# ---------------------------------------------------------------------------
# App configuration helpers
# ---------------------------------------------------------------------------
def now_utc() -> datetime:
    return datetime.now()


def normalize_database_url(url: str) -> str:
    if url.startswith("mysql://"):
        return "mysql+pymysql://" + url.removeprefix("mysql://")
    return url


def is_mysql(url: str) -> bool:
    return url.startswith("mysql")


def ensure_mysql_database(database_url: str) -> None:
    """Create the MySQL database if it is missing. No-op for SQLite."""
    if not is_mysql(database_url):
        return

    import pymysql  # imported lazily so SQLite users do not need it

    parsed = urlparse(database_url)
    database_name = parsed.path.strip("/")
    if not database_name:
        raise RuntimeError("DATABASE_URL must include a database name.")

    connection = pymysql.connect(
        host=parsed.hostname or "localhost",
        port=parsed.port or 3306,
        user=parsed.username or "root",
        password=parsed.password or "",
        autocommit=True,
    )
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                f"CREATE DATABASE IF NOT EXISTS `{database_name}` "
                "CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci"
            )
    finally:
        connection.close()


def resolve_database_url() -> str:
    """Default to a zero-config SQLite file so `python app.py` just runs.

    Set DATABASE_URL (e.g. mysql://root:1234@localhost:3306/usls_gs_demo) to use MySQL.
    """
    configured = os.getenv("DATABASE_URL")
    if configured:
        return normalize_database_url(configured)
    sqlite_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "usls_gs_demo.sqlite3")
    return f"sqlite:///{sqlite_path}"


def demo_mode_enabled() -> bool:
    """The single switch for every presenter convenience (DEMO_MODE, default ON).

    ON: the sign-in page offers an expandable "Demo accounts" panel, the demo
    endpoints answer, and a demo persona's prerequisites are repaired at login.
    OFF: the sign-in page is a plain email + password form, every demo endpoint
    returns 404, and no default password is ever sent to the browser.
    Read on every call so the switch can be flipped without touching code.
    """
    return os.getenv("DEMO_MODE", "1").strip().lower() not in {"0", "false", "no", "off"}


def demo_password_hint() -> str:
    """The shared default password, but only while DEMO_MODE is on."""
    return SIM_STUDENT_PASSWORD if demo_mode_enabled() else ""


def resolve_secret_key(environ=None) -> str:
    """SECRET_KEY from the environment; otherwise a public default in demo mode
    only. With DEMO_MODE off a missing key becomes a random per-process key, so
    a session cookie can never be forged with a value published in the source."""
    environ = os.environ if environ is None else environ
    configured = environ.get("SECRET_KEY")
    if configured:
        return configured
    if str(environ.get("DEMO_MODE", "1")).strip().lower() not in {"0", "false", "no", "off"}:
        return "demo-only-secret"
    return os.urandom(32).hex()


def create_app() -> Flask:
    database_url = resolve_database_url()
    ensure_mysql_database(database_url)

    # static_folder disabled: our catch-all route serves both the built assets
    # and the SPA fallback, so Flask's greedy static route does not shadow client routes.
    app = Flask(__name__, static_folder=None)
    app.config["SECRET_KEY"] = resolve_secret_key()
    # The session cookie is never readable by page scripts and is not sent on
    # cross-site requests. Set SESSION_COOKIE_SECURE=1 when serving over HTTPS.
    app.config["SESSION_COOKIE_HTTPONLY"] = True
    app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
    app.config["SESSION_COOKIE_SECURE"] = os.getenv("SESSION_COOKIE_SECURE", "0").strip().lower() in {"1", "true", "yes", "on"}
    app.config["SQLALCHEMY_DATABASE_URI"] = database_url
    app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False
    db.init_app(app)

    register_json_error_handling(app)
    register_routes(app)
    return app


HTTP_ERROR_MESSAGES = {
    400: "The request could not be understood. Check what you entered and try again.",
    401: "Sign in to continue.",
    403: "You do not have permission to do that.",
    404: "We could not find what you asked for.",
    405: "That action is not available here.",
    413: "The file or request is too large.",
    415: "The request was sent in a format the server cannot read.",
    429: "Too many requests. Wait a moment and try again.",
    500: "Something went wrong on the server. Nothing was saved; try again or contact the Graduate School office.",
}


def register_json_error_handling(app: Flask) -> None:
    """Every failure under /api/ answers with JSON ``{"error": "..."}`` and a sensible status.

    The screens show ``error`` as-is, so they never see an HTML page or a Werkzeug sentence.
    """
    from werkzeug.exceptions import BadRequest, HTTPException

    def is_api_request() -> bool:
        return request.path.startswith("/api/")

    @app.before_request
    def reject_non_object_json_bodies():
        # Handlers read the body as a dict; a list or a bare value used to end in a 500.
        if (
            is_api_request()
            and request.method in {"POST", "PUT", "PATCH", "DELETE"}
            and request.is_json
        ):
            body = request.get_json(silent=True)
            if body is not None and not isinstance(body, dict):
                return jsonify({"error": "Send the request as a JSON object."}), 400
        return None

    @app.errorhandler(HTTPException)
    def http_error(exc: HTTPException):
        if not is_api_request():
            return exc
        code = exc.code or 500
        if code >= 500:
            db.session.rollback()
            app.logger.error("API error %s on %s %s", code, request.method, request.path)
        message = HTTP_ERROR_MESSAGES.get(code, exc.name)
        if isinstance(exc, BadRequest) and getattr(exc, "args", None) and type(exc).__name__ == "BadRequestKeyError":
            message = f"A required field is missing: {exc.args[0]}."
        elif exc.description and exc.description != type(exc).description and code < 500:
            message = exc.description  # a message written for this case by abort(code, "...")
        return jsonify({"error": message}), code

    @app.errorhandler(ValueError)
    @app.errorhandler(TypeError)
    def unreadable_number(exc: Exception):
        # int("abc") and int(None) on user input are the caller's mistake, not a server fault.
        text_value = str(exc)
        if is_api_request() and (
            text_value.startswith("invalid literal for int()")
            or text_value.startswith("int() argument must be")
            or text_value.startswith("could not convert string to float")
        ):
            return jsonify({"error": "A number was expected but something else was sent."}), 400
        raise exc


# ---------------------------------------------------------------------------
# Models
# ---------------------------------------------------------------------------
# The schema is intentionally compact for the MVP. It stores monitoring signals
# and workflow outcomes, not official registrar/accounting records.
class Program(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    code = db.Column(db.String(30), unique=True, nullable=False)
    name = db.Column(db.String(160), nullable=False)
    college = db.Column(db.String(120), nullable=False)
    has_practicum = db.Column(db.Boolean, default=False)

    courses = db.relationship("Course", backref="program", lazy=True)
    students = db.relationship("Student", backref="program", lazy=True)


# Central student lifecycle record. Related tables hang off this record so the
# detail page can reconstruct coursework, documents, tasks, schedules, and logs.
class Student(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_number = db.Column(db.String(40), unique=True, nullable=False)
    first_name = db.Column(db.String(80), nullable=False)
    last_name = db.Column(db.String(80), nullable=False)
    email = db.Column(db.String(160), nullable=False)
    program_id = db.Column(db.Integer, db.ForeignKey("program.id"), nullable=False)
    entry_year = db.Column(db.Integer, nullable=False)
    # Preserve the two distinct source columns from the AC monitoring workbook.
    # entry_year remains the numeric value used by residency calculations.
    academic_year_entry = db.Column(db.String(20), nullable=False, default="")
    year_level = db.Column(db.String(20), nullable=False, default="")
    current_stage = db.Column(db.String(60), nullable=False, default="Admission")
    standing = db.Column(db.String(60), nullable=False, default="Active")
    # Current-term enrollment tag (per AC notes): Enrolled / LOA / AWOL / Completed.
    enrollment_tag = db.Column(db.String(20), nullable=False, default="Enrolled")
    comprehensive_exam_status = db.Column(db.String(30), nullable=False, default="Not Taken")
    risk_level = db.Column(db.String(20), nullable=False, default="Not Yet Assessed")
    adviser_name = db.Column(db.String(120))
    monitoring_new_student = db.Column(db.Boolean, nullable=False, default=False)
    monitoring_imported_at = db.Column(db.DateTime)
    monitoring_upload_id = db.Column(db.Integer, db.ForeignKey("monitoring_sheet_upload.id"))
    created_at = db.Column(db.DateTime, default=now_utc)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc)

    enrollments = db.relationship("TermEnrollment", backref="student", lazy=True, cascade="all, delete-orphan")
    course_records = db.relationship("CourseRecord", backref="student", lazy=True, cascade="all, delete-orphan")
    research_cases = db.relationship("ResearchCase", backref="student", lazy=True, cascade="all, delete-orphan")
    document_checks = db.relationship("DocumentCheck", backref="student", lazy=True, cascade="all, delete-orphan")
    tasks = db.relationship("Task", backref="student", lazy=True, cascade="all, delete-orphan")
    logs = db.relationship("TransactionLog", backref="student", lazy=True, cascade="all, delete-orphan")
    practicum_records = db.relationship("PracticumRecord", backref="student", lazy=True, cascade="all, delete-orphan")
    withdrawal_applications = db.relationship("WithdrawalApplication", backref="student", lazy=True, cascade="all, delete-orphan")
    graduation_endorsements = db.relationship("GraduationEndorsement", backref="student", lazy=True, cascade="all, delete-orphan")
    workflow_messages = db.relationship("WorkflowMessage", backref="student", lazy=True, cascade="all, delete-orphan")

    @property
    def name(self) -> str:
        return f"{self.first_name} {self.last_name}"


class UserAccount(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(160), unique=True, nullable=False)
    full_name = db.Column(db.String(160), nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)
    role = db.Column(db.String(40), nullable=False)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"))
    faculty_id = db.Column(db.Integer, db.ForeignKey("faculty.id"))
    active = db.Column(db.Boolean, default=True)
    # True for an account whose initial password was generated for it: the holder must
    # choose their own password at first sign-in before anything else works.
    must_change_password = db.Column(db.Boolean, nullable=False, default=False)
    created_at = db.Column(db.DateTime, default=now_utc)

    student = db.relationship("Student")
    faculty = db.relationship("Faculty")


class PolicyDocument(db.Model):
    """A staff-managed PDF included in the Policy Assistant's RAG corpus."""
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(220), nullable=False)
    description = db.Column(db.Text, nullable=False, default="")
    original_name = db.Column(db.String(255), nullable=False)
    stored_name = db.Column(db.String(255), unique=True, nullable=False)
    mime_type = db.Column(db.String(100), nullable=False, default="application/pdf")
    file_size = db.Column(db.Integer, nullable=False, default=0)
    page_count = db.Column(db.Integer, nullable=False, default=0)
    chunk_count = db.Column(db.Integer, nullable=False, default=0)
    uploaded_by_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"), nullable=False)
    created_at = db.Column(db.DateTime, default=now_utc, nullable=False)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc, nullable=False)

    # Library management: what kind of document it is, when it takes effect, and
    # whether it is validated. "draft" documents are searched but every answer
    # that cites one says it is pending validation; "archived" ones are kept for
    # the record but not searched.
    category = db.Column(db.String(40), nullable=False, default="Other")
    effective_date = db.Column(db.Date)
    status = db.Column(db.String(20), nullable=False, default="active")
    validation_note = db.Column(db.Text)

    uploaded_by = db.relationship("UserAccount")
    versions = db.relationship(
        "PolicyDocumentVersion",
        back_populates="document",
        order_by="PolicyDocumentVersion.version_number",
        cascade="all, delete-orphan",
    )


class PolicyDocumentVersion(db.Model):
    """One uploaded file of a policy document. The newest row is the current version."""
    id = db.Column(db.Integer, primary_key=True)
    document_id = db.Column(db.Integer, db.ForeignKey("policy_document.id"), nullable=False, index=True)
    version_number = db.Column(db.Integer, nullable=False, default=1)
    original_name = db.Column(db.String(255), nullable=False)
    stored_name = db.Column(db.String(255), unique=True, nullable=False)
    mime_type = db.Column(db.String(100), nullable=False, default="application/pdf")
    file_size = db.Column(db.Integer, nullable=False, default=0)
    page_count = db.Column(db.Integer, nullable=False, default=0)
    chunk_count = db.Column(db.Integer, nullable=False, default=0)
    note = db.Column(db.Text)
    uploaded_by_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"), nullable=False)
    created_at = db.Column(db.DateTime, default=now_utc, nullable=False)

    document = db.relationship("PolicyDocument", back_populates="versions")
    uploaded_by = db.relationship("UserAccount")


class BusinessRule(db.Model):
    """One business rule the workflows read, with the policy it comes from.

    Seeded from ``business_rules_catalog.py`` by ``ensure_business_rules()``;
    afterwards the row is the source of truth and Graduate School staff edit it.
    """
    id = db.Column(db.Integer, primary_key=True)
    key = db.Column(db.String(120), unique=True, nullable=False)
    process = db.Column(db.String(40), nullable=False)
    title = db.Column(db.String(220), nullable=False)
    description = db.Column(db.Text, nullable=False, default="")
    value = db.Column(db.String(500), nullable=False)
    value_type = db.Column(db.String(12), nullable=False, default="int")
    unit = db.Column(db.String(30))
    source_title = db.Column(db.String(220), nullable=False, default="")
    source_section = db.Column(db.String(220))
    source_page = db.Column(db.String(40))
    policy_document_id = db.Column(db.Integer, db.ForeignKey("policy_document.id"))
    enforced = db.Column(db.Boolean, nullable=False, default=True)
    not_enforced_reason = db.Column(db.Text)
    status = db.Column(db.String(20), nullable=False, default="active")
    effective_date = db.Column(db.Date)
    updated_by_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"))
    updated_at = db.Column(db.DateTime, default=now_utc, nullable=False)

    policy_document = db.relationship("PolicyDocument")
    updated_by = db.relationship("UserAccount")


class BusinessRuleRevision(db.Model):
    """History of every edit to a business rule (who, when, why)."""
    id = db.Column(db.Integer, primary_key=True)
    rule_id = db.Column(db.Integer, db.ForeignKey("business_rule.id"), nullable=False)
    old_value = db.Column(db.String(500))
    new_value = db.Column(db.String(500))
    reason = db.Column(db.Text, nullable=False, default="")
    changed_by_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"))
    changed_at = db.Column(db.DateTime, default=now_utc, nullable=False)

    rule = db.relationship("BusinessRule", backref="revisions")
    changed_by = db.relationship("UserAccount")


class AcademicTerm(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    label = db.Column(db.String(40), unique=True, nullable=False)
    start_date = db.Column(db.Date, nullable=False)
    end_date = db.Column(db.Date, nullable=False)
    is_active_planning_term = db.Column(db.Boolean, default=False)
    planning_window_open = db.Column(db.Date)
    planning_window_close = db.Column(db.Date)
    grade_submission_deadline = db.Column(db.Date)
    status = db.Column(db.String(20))


class Course(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    program_id = db.Column(db.Integer, db.ForeignKey("program.id"), nullable=False)
    code = db.Column(db.String(40), unique=True, nullable=False)
    title = db.Column(db.String(160), nullable=False)
    units = db.Column(db.Integer, default=3)
    recommended_term = db.Column(db.String(40), default="Year 1")
    category = db.Column(db.String(40), default="Core")  # Basic / Major / Cognate (from monitoring sheet groups)


class CourseOfferingPlan(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    program_id = db.Column(db.Integer, db.ForeignKey("program.id"), nullable=False)
    term_label = db.Column(db.String(60), nullable=False)
    status = db.Column(db.String(40), nullable=False, default="Draft")
    notes = db.Column(db.String(260))
    created_at = db.Column(db.DateTime, default=now_utc)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc)
    submitted_at = db.Column(db.DateTime)
    approved_at = db.Column(db.DateTime)
    approved_by = db.Column(db.String(120))  # the account that approved (by role, not hardcoded)
    published_at = db.Column(db.DateTime)
    target_term_id = db.Column(db.Integer, db.ForeignKey("academic_term.id"))
    reference_term_id = db.Column(db.Integer, db.ForeignKey("academic_term.id"))

    program = db.relationship("Program")
    target_term = db.relationship("AcademicTerm", foreign_keys=[target_term_id])
    reference_term = db.relationship("AcademicTerm", foreign_keys=[reference_term_id])
    offerings = db.relationship("CourseOffering", backref="plan", lazy=True, cascade="all, delete-orphan")


class CourseOffering(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    plan_id = db.Column(db.Integer, db.ForeignKey("course_offering_plan.id"), nullable=False)
    course_id = db.Column(db.Integer, db.ForeignKey("course.id"), nullable=False)
    demand_count = db.Column(db.Integer, default=0)
    section_count = db.Column(db.Integer, default=0)
    availability_count = db.Column(db.Integer, default=0)
    status = db.Column(db.String(40), nullable=False, default="Suggested")
    notes = db.Column(db.String(220))
    assigned_faculty_id = db.Column(db.Integer, db.ForeignKey("faculty.id"))
    assignment_status = db.Column(db.String(40), nullable=False, default="Unassigned")

    course = db.relationship("Course")
    assigned_faculty = db.relationship("Faculty", foreign_keys=[assigned_faculty_id])


class CurriculumOffering(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    program_id = db.Column(db.Integer, db.ForeignKey("program.id"), nullable=False)
    academic_year = db.Column(db.String(20), nullable=False)
    semester = db.Column(db.String(20), nullable=False)
    course_id = db.Column(db.Integer, db.ForeignKey("course.id"), nullable=False)
    added_by = db.Column(db.String(160))
    # Course Offering Setup (Sir Eddie, 2026-07-21): each offered subject carries the
    # assigned faculty and the schedule that students are then tagged/enrolled into.
    assigned_faculty_id = db.Column(db.Integer, db.ForeignKey("faculty.id"))
    schedule = db.Column(db.String(160))
    section = db.Column(db.String(40))
    created_at = db.Column(db.DateTime, default=now_utc)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc)

    program = db.relationship("Program")
    course = db.relationship("Course")
    assigned_faculty = db.relationship("Faculty", foreign_keys=[assigned_faculty_id])


# Term-level enrollment signal copied from an institutional source such as AIMS.
class TermEnrollment(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"), nullable=False)
    term_id = db.Column(db.Integer, db.ForeignKey("academic_term.id"), nullable=False)
    status = db.Column(db.String(40), nullable=False)
    source_reference = db.Column(db.String(160))
    confirmed_at = db.Column(db.DateTime, default=now_utc)

    term = db.relationship("AcademicTerm")


class SubjectEnrollment(db.Model):
    """Durable student-to-subject enrollment for one academic semester.

    CourseRecord remains the monitoring/profile projection used throughout the
    existing app. This table preserves the semester-level enrollment history so
    adding a class in a later semester never erases the earlier transaction.
    """

    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"), nullable=False)
    course_id = db.Column(db.Integer, db.ForeignKey("course.id"), nullable=False)
    term_id = db.Column(db.Integer, db.ForeignKey("academic_term.id"), nullable=False)
    status = db.Column(db.String(40), nullable=False, default="Enrolled")
    source_reference = db.Column(db.String(160))
    conflict_override = db.Column(db.Text)
    status_note = db.Column(db.Text)
    status_changed_at = db.Column(db.DateTime)
    enrolled_at = db.Column(db.DateTime, default=now_utc, nullable=False)
    cancelled_at = db.Column(db.DateTime)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc)

    student = db.relationship("Student")
    course = db.relationship("Course")
    term = db.relationship("AcademicTerm")

    __table_args__ = (
        db.UniqueConstraint(
            "student_id",
            "course_id",
            "term_id",
            name="uq_subject_enrollment_student_course_term",
        ),
    )


class AwolCase(db.Model):
    id = db.Column(db.Integer, primary_key=True)
