# Research adviser appointment (protocol: Designation of the Research Adviser). One row per
# nomination; the Accepted, not-ended row is the student's adviser everywhere.
ADVISER_STATUS_APPLIED = "Applied"            # Form 3 submitted by the student (or a change request)
ADVISER_STATUS_NOTED = "Noted by AC"          # the Academic Coordinator noted the application
ADVISER_STATUS_DELIBERATION = "Under deliberation"  # the Research Coordinator sent it to the Dean
ADVISER_STATUS_APPOINTED = "Appointed"        # approved; Form 3.1 issued, waiting for the adviser
ADVISER_STATUS_ACCEPTED = "Accepted"          # the adviser accepted Form 3.1
ADVISER_STATUS_DECLINED = "Declined"          # the nominated adviser declined
ADVISER_STATUS_NOT_APPROVED = "Not approved"  # the Dean did not approve; the student may nominate again
ADVISER_STATUS_WITHDRAWN = "Withdrawn"        # the student withdrew the application
ADVISER_STATUS_ENDED = "Ended"                # replaced by a change of adviser
ADVISER_OPEN_STATUSES = (
    ADVISER_STATUS_APPLIED, ADVISER_STATUS_NOTED, ADVISER_STATUS_DELIBERATION, ADVISER_STATUS_APPOINTED,
)


class AdviserAppointment(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"), nullable=False, index=True)
    faculty_id = db.Column(db.Integer, db.ForeignKey("faculty.id"), nullable=False, index=True)
    kind = db.Column(db.String(20), nullable=False, default="Initial")  # Initial | Change | Recorded
    status = db.Column(db.String(30), nullable=False, default=ADVISER_STATUS_APPLIED)
    replaces_id = db.Column(db.Integer)  # the appointment a change of adviser replaces
    reason = db.Column(db.Text)  # why the student asks for a change (Form 3.1.1)
    student_note = db.Column(db.Text)
    applied_at = db.Column(db.DateTime, default=now_utc)
    ac_note = db.Column(db.Text)
    ac_noted_by = db.Column(db.String(160))
    ac_noted_at = db.Column(db.DateTime)
    forwarded_by = db.Column(db.String(160))
    forwarded_at = db.Column(db.DateTime)
    decided_by = db.Column(db.String(160))
    decided_at = db.Column(db.DateTime)
    decision_note = db.Column(db.Text)
    associate_dean_name = db.Column(db.String(160))
    cap_exception = db.Column(db.Boolean, default=False)
    form31_issued_on = db.Column(db.Date)
    adviser_response = db.Column(db.String(20), nullable=False, default="Pending")  # Pending | Accepted | Declined
    adviser_responded_at = db.Column(db.DateTime)
    adviser_response_reason = db.Column(db.Text)
    current_adviser_consent = db.Column(db.String(20))  # change only: Pending | Consented | Declined
    current_adviser_consent_at = db.Column(db.DateTime)
    current_adviser_consent_reason = db.Column(db.Text)
    contract_due_on = db.Column(db.Date)  # Form 3.2 / 3.3 due date (5 days from Form 3.1)
    contract_submitted_at = db.Column(db.DateTime)
    contract_note = db.Column(db.Text)
    contract_received_at = db.Column(db.DateTime)
    contract_received_by = db.Column(db.String(160))
    ended_at = db.Column(db.DateTime)
    end_reason = db.Column(db.Text)
    source = db.Column(db.String(80))
    created_at = db.Column(db.DateTime, default=now_utc)
    updated_at = db.Column(db.DateTime, default=now_utc, onupdate=now_utc)

    student = db.relationship("Student")
    faculty = db.relationship("Faculty")


# A panel seat offered to a faculty member. Keyed by student + faculty + gate (not by the
# PanelAssignment row, which is re-created whenever a panel is re-matched).
class PanelInvitation(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"), nullable=False, index=True)
    faculty_id = db.Column(db.Integer, db.ForeignKey("faculty.id"), nullable=False, index=True)
    gate = db.Column(db.String(80), nullable=False)
    panel_role = db.Column(db.String(60))
    status = db.Column(db.String(20), nullable=False, default="Invited")  # Invited | Accepted | Declined
    invited_at = db.Column(db.DateTime, default=now_utc)
    responded_at = db.Column(db.DateTime)
    reason = db.Column(db.Text)

    student = db.relationship("Student")
    faculty = db.relationship("Faculty")

    __table_args__ = (
        db.UniqueConstraint("student_id", "faculty_id", "gate", name="uq_panel_invitation_seat"),
    )


# In-app notification. `dedupe_key` makes every generator idempotent per recipient.
class Notification(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    account_id = db.Column(db.Integer, db.ForeignKey("user_account.id"), nullable=False, index=True)
    kind = db.Column(db.String(60), nullable=False)
    title = db.Column(db.String(180), nullable=False)
    body = db.Column(db.Text)
    link = db.Column(db.String(200))
    related_type = db.Column(db.String(40))
    related_id = db.Column(db.Integer)
    due_on = db.Column(db.Date)
    dedupe_key = db.Column(db.String(160), nullable=False)
    created_at = db.Column(db.DateTime, default=now_utc)
    read_at = db.Column(db.DateTime)

    __table_args__ = (
        db.UniqueConstraint("account_id", "dedupe_key", name="uq_notification_dedupe"),
    )


# Secret-token link to a person's private .ics calendar feed; works without a session.
class CalendarToken(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    account_id = db.Column(db.Integer, db.ForeignKey("user_account.id"), nullable=False, index=True)
    token = db.Column(db.String(80), nullable=False, unique=True)
    created_at = db.Column(db.DateTime, default=now_utc)
    revoked_at = db.Column(db.DateTime)
    last_used_at = db.Column(db.DateTime)


# Work queue item. Tasks represent the next owner and next action after a transaction.
class Task(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"), nullable=False)
    title = db.Column(db.String(180), nullable=False)
    owner_role = db.Column(db.String(80), nullable=False)
    due_at = db.Column(db.Date, nullable=False)
    status = db.Column(db.String(40), nullable=False, default="Pending")
    priority = db.Column(db.Integer, default=10)


# Append-style activity record for transactions and accountability demos.
class TransactionLog(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    transaction_slug = db.Column(db.String(80), nullable=False)
    student_id = db.Column(db.Integer, db.ForeignKey("student.id"))
    workflow_request_id = db.Column(db.Integer)
    actor_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"))
    action_type = db.Column(db.String(40))
    visibility = db.Column(db.String(30), nullable=False, default="student_visible")
    actor_role = db.Column(db.String(80), nullable=False)
    source_reference = db.Column(db.String(160))
    result = db.Column(db.String(160), nullable=False)
    next_owner = db.Column(db.String(80))
    notes = db.Column(db.Text)
    previous_status = db.Column(db.String(100))
    new_status = db.Column(db.String(100))
    created_at = db.Column(db.DateTime, default=now_utc)
    # Daily change report: whether this change has been mirrored into AIMS.
    reflected_in_aims = db.Column(db.Boolean, nullable=False, default=False)
    reflected_at = db.Column(db.DateTime)
    reflected_by_user_id = db.Column(db.Integer, db.ForeignKey("user_account.id"))


# ---------------------------------------------------------------------------
# Serializers
# ---------------------------------------------------------------------------
# These helpers shape SQLAlchemy objects into stable JSON contracts for React.
# Keeping them separate from routes makes the API response shape easy to review.
def iso(value) -> str | None:
    if value is None:
        return None
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return str(value)


def program_dict(program: Program) -> dict:
    return {
        "id": program.id,
        "code": program.code,
        "name": program.name,
        "college": program.college,
        "has_practicum": program_allows_practicum(program),
    }


PRACTICUM_MSGC_CODE = "MSGC"
PRACTICUM_PSYCHOLOGY_NAME_TOKEN = "psychology"
PRACTICUM_SCOPE_LABEL = (
    "Psychology and Master of Science in Guidance and Counseling (MSGC) students only"
)


def program_allows_practicum(program: Program | None) -> bool:
    """Return the confirmed Graduate School practicum program scope."""
    if not program:
        return False
    code = (program.code or "").strip().upper()
    name = (program.name or "").strip().lower()
    return code == PRACTICUM_MSGC_CODE or PRACTICUM_PSYCHOLOGY_NAME_TOKEN in name


def practicum_program_scope() -> dict:
    return {
        "label": PRACTICUM_SCOPE_LABEL,
        "description": (
            "Practicum is restricted to students enrolled in a Psychology "
            "program or the Master of Science in Guidance and Counseling (MSGC)."
        ),
        "allowed_program_codes": ["MAPSY", "DPSY", PRACTICUM_MSGC_CODE],
    }


def practicum_program_filter():
    """SQL predicate matching the same policy used by route authorization."""
    return or_(
        func.upper(Program.code) == PRACTICUM_MSGC_CODE,
        func.lower(Program.name).contains(PRACTICUM_PSYCHOLOGY_NAME_TOKEN),
    )


def scoped_practicum_records_query():
    return (
        PracticumRecord.query
        .join(Student, Student.id == PracticumRecord.student_id)
        .join(Program, Program.id == Student.program_id)
        .filter(practicum_program_filter())
    )


def ensure_practicum_program_policy() -> int:
    """Normalize legacy program metadata to the confirmed practicum scope."""
    changed = 0
    legacy_guidance = Program.query.filter(func.upper(Program.code) == "MAGC").first()
    msgc = Program.query.filter(func.upper(Program.code) == PRACTICUM_MSGC_CODE).first()
    if legacy_guidance and msgc and legacy_guidance.id != msgc.id:
        msgc_has_records = bool(
            Student.query.filter_by(program_id=msgc.id).first()
            or Course.query.filter_by(program_id=msgc.id).first()
        )
        if not msgc_has_records:
            db.session.delete(msgc)
            db.session.flush()
            msgc = None
            changed += 1
    if legacy_guidance and not msgc:
        legacy_guidance.code = PRACTICUM_MSGC_CODE
        legacy_guidance.name = "Master of Science in Guidance and Counseling"
        msgc = legacy_guidance
        changed += 1
        for course in Course.query.filter_by(program_id=legacy_guidance.id).all():
            if (course.code or "").upper().startswith("MAGC"):
                replacement = f"{PRACTICUM_MSGC_CODE}{course.code[4:]}"
                duplicate = Course.query.filter(
                    Course.program_id == legacy_guidance.id,
                    func.upper(Course.code) == replacement.upper(),
                    Course.id != course.id,
                ).first()
                if not duplicate:
                    course.code = replacement
                    changed += 1
    elif msgc:
        expected_name = "Master of Science in Guidance and Counseling"
        if msgc.name != expected_name:
            msgc.name = expected_name
            changed += 1

    for program in Program.query.all():
        allowed = program_allows_practicum(program)
        if bool(program.has_practicum) != allowed:
            program.has_practicum = allowed
            changed += 1
    return changed


def term_ordinal(term: AcademicTerm) -> int | None:
    """A sortable integer for a semester (start-year*2 + semester index) so we can
    tell how far a term is from the active one."""
    ay, sem = split_academic_term_label(term.label)
    if not ay:
        return None
    try:
        start_year = int(ay.split("-")[0])
    except (ValueError, IndexError):
        return None
    return start_year * 2 + (1 if ("2nd" in sem or "Second" in sem) else 0)


def term_relative_label(term: AcademicTerm, active: AcademicTerm | None) -> str:
    """'Current' / 'Next' / 'Previous' / '+2' / '-3' relative to the active semester."""
    if not active:
        return ""
    if term.id == active.id:
        return "Current"
    a, b = term_ordinal(term), term_ordinal(active)
    if a is None or b is None:
        return ""
    diff = a - b
    if diff == 1:
        return "Next"
    if diff == -1:
        return "Previous"
    return f"+{diff}" if diff > 0 else f"{diff}"


def term_dict(term: AcademicTerm, active: AcademicTerm | None = None) -> dict:
    active = active if active is not None else get_active_term()
    return {
        "id": term.id,
        "label": term.label,
        "start_date": iso(term.start_date),
        "end_date": iso(term.end_date),
        "planning_window_open": iso(term.planning_window_open),
        "planning_window_close": iso(term.planning_window_close),
        "status": term.status,
        "is_active_planning_term": bool(term.is_active_planning_term),
        "relative_label": term_relative_label(term, active),
    }


def term_date_problem(term: AcademicTerm, exclude_id: int | None = None) -> tuple[int, str] | None:
    """Return (status, message) when a semester's dates cannot be saved, else None.

    Enrollment, the withdrawal window, residency and reports all read term start dates, so two
    semesters may never overlap and each must start before it ends.
    """
    if not term.start_date or not term.end_date:
        return 400, "Start and end dates are required."
    if term.start_date >= term.end_date:
        return 400, "The semester must start before it ends."
    if term.planning_window_open and term.planning_window_close and term.planning_window_open > term.planning_window_close:
        return 400, "The planning window must open before it closes."
    query = AcademicTerm.query.filter(
        AcademicTerm.start_date <= term.end_date,
        AcademicTerm.end_date >= term.start_date,
    )
    if exclude_id is not None:
        query = query.filter(AcademicTerm.id != exclude_id)
    with db.session.no_autoflush:
        clash = query.first()
    if clash:
        return 409, (
            f"These dates overlap {clash.label} ({iso(clash.start_date)} to {iso(clash.end_date)}). "
            "Semesters cannot overlap."
        )
    return None


def get_active_term() -> AcademicTerm | None:
    active = AcademicTerm.query.filter_by(is_active_planning_term=True).first()
    if active:
        return active
    # Date-aware "current semester": the one in session, else the next upcoming, else latest.
    today = date.today()
    current = (
        AcademicTerm.query.filter(AcademicTerm.start_date <= today, AcademicTerm.end_date >= today)
        .order_by(AcademicTerm.start_date.desc())
        .first()
    )
    if current:
        return current
    upcoming = (
        AcademicTerm.query.filter(AcademicTerm.start_date > today)
        .order_by(AcademicTerm.start_date.asc())
        .first()
    )
    return upcoming or AcademicTerm.query.order_by(AcademicTerm.start_date.desc()).first()


def visible_terms() -> list[AcademicTerm]:
    """The semesters worth showing in dropdowns: the one immediately before the
    active semester, the active semester itself, and one semester ahead for
    planning the next term. Older/future semesters stay in the database (history
    and references are intact) but are hidden from the pickers to keep them tidy."""
    terms = AcademicTerm.query.order_by(AcademicTerm.start_date.asc()).all()
    active = get_active_term()
    if not active or not terms:
        return terms
    idx = next((i for i, t in enumerate(terms) if t.id == active.id), None)
    if idx is None:
        return terms
    lo = max(0, idx - 1)
    hi = min(len(terms), idx + 2)  # active + one planning semester ahead
    return terms[lo:hi]


def course_audit_subject_items() -> list[dict]:
    """Subjects that currently have a class roster."""
    counts = dict(db.session.query(CourseRecord.course_id, func.count(CourseRecord.id)).group_by(CourseRecord.course_id).all())
    return [
        {"id": course.id, "code": course.code, "title": course.title, "program_id": course.program_id, "enrolled": counts[course.id]}
        for course in Course.query.order_by(Course.code).all() if counts.get(course.id)
    ]


# Academic calendar is semester-based: two semesters per academic year (not trimester).
SEMESTER_NAMES = ["1st Semester", "2nd Semester"]


def academic_semester_label(start_year: int, sem_index: int) -> str:
    return f"AY {start_year}-{start_year + 1} {SEMESTER_NAMES[sem_index]}"


def generate_semester_calendar(from_year: int = 2023, to_year: int = 2030) -> list[tuple[str, date]]:
    """(label, start_date) for every semester in the range — 1st Sem in Aug, 2nd in Jan."""
    rows: list[tuple[str, date]] = []
    for year in range(from_year, to_year + 1):
        rows.append((academic_semester_label(year, 0), date(year, 8, 1)))
        rows.append((academic_semester_label(year, 1), date(year + 1, 1, 10)))
    return rows


def upcoming_semester_labels(count: int = 5, reference: date | None = None) -> list[str]:
    """The current and next few semesters (by label), for student/staff dropdowns."""
    reference = reference or date.today()
    terms = AcademicTerm.query.order_by(AcademicTerm.start_date.asc()).all()
    upcoming = [t for t in terms if (t.end_date or t.start_date) >= reference]
    chosen = (upcoming or terms[-count:])[:count]
    return [t.label for t in chosen]


def future_semester_labels(count: int = 5, reference: date | None = None) -> list[str]:
    """Semesters that have not begun yet, used for future-effective requests."""
    reference = reference or date.today()
    terms = (
        AcademicTerm.query.filter(AcademicTerm.start_date > reference)
        .order_by(AcademicTerm.start_date.asc())
        .limit(count)
        .all()
    )
    return [term.label for term in terms]


def split_academic_term_label(label: str) -> tuple[str, str]:
    ay_match = re.search(r"(\d{4}\s*-\s*\d{4})", label or "")
    sem_match = re.search(r"((?:1st|2nd|3rd|First|Second|Third)\s*Semester|Term\s*\d+)", label or "", flags=re.IGNORECASE)
    academic_year = ay_match.group(1).replace(" ", "") if ay_match else ""
    semester = ""
    if sem_match:
        matched = re.sub(r"\s+", " ", sem_match.group(1)).strip()
        lowered = matched.lower()
        if lowered.startswith(("1st", "first")):
            semester = "1st Semester"
        elif lowered.startswith(("2nd", "second")):
            semester = "2nd Semester"
        elif lowered.startswith(("3rd", "third")):
            semester = "3rd Semester"
        else:
            semester = matched.title()
    return academic_year, semester


def normalize_graduation_school_year(value: str | None) -> str:
    """Return the canonical school-year value stored by the graduation workflow."""
    academic_year, _ = split_academic_term_label(value or "")
    return f"AY {academic_year}" if academic_year else ""


def graduation_school_year_options() -> list[str]:
    """School years configured by the semester calendar, with the active year first."""
    configured: list[str] = []
    for term in AcademicTerm.query.order_by(AcademicTerm.start_date.asc()).all():
        school_year = normalize_graduation_school_year(term.label)
        if school_year and school_year not in configured:
            configured.append(school_year)

    active = get_active_term()
    active_year = normalize_graduation_school_year(active.label) if active else ""
    if active_year and active_year in configured:
        active_index = configured.index(active_year)
        future_years = configured[active_index + 1:]
        previous_years = list(reversed(configured[:active_index]))
        configured = [active_year, *future_years, *previous_years]
    if configured:
        return configured

    # New/test databases may not have an academic calendar yet. Keep the form
    # usable until staff configure terms, while still requiring an AY value.
    today = date.today()
    start_year = today.year if today.month >= 6 else today.year - 1
    return [f"AY {start_year}-{start_year + 1}"]


def default_graduation_school_year() -> str:
    active = get_active_term()
    active_year = normalize_graduation_school_year(active.label) if active else ""
    options = graduation_school_year_options()
    return active_year or (options[0] if options else "")


def validate_graduation_school_year(value: str | None) -> str:
    school_year = normalize_graduation_school_year(value)
    if not school_year:
        raise ValueError("Choose a graduation school year from the list.")
    configured_years = graduation_school_year_options()
    if AcademicTerm.query.first() and school_year not in configured_years:
        raise ValueError("Choose a graduation school year configured in the academic calendar.")
    active_year = default_graduation_school_year()
    if active_year and school_year != active_year:
        raise ValueError(f"The graduation review window is open only for {active_year}.")
    return school_year


