class LoginThrottle:
    """Per-process brake on repeated failed sign-ins.

    An email (known or not, so lockout reveals nothing) is locked for
    ``lockout_seconds`` after ``max_failures`` failures inside ``window_seconds``;
    one client address gets a larger allowance. State lives in memory, so it
    resets on restart and is per worker process.
    """

    def __init__(self, clock=None):
        from time import monotonic

        self.max_failures = int(os.getenv("LOGIN_MAX_FAILURES", "5"))
        self.ip_max_failures = int(os.getenv("LOGIN_IP_MAX_FAILURES", "40"))
        self.window_seconds = int(os.getenv("LOGIN_FAILURE_WINDOW_SECONDS", "900"))
        self.lockout_seconds = int(os.getenv("LOGIN_LOCKOUT_SECONDS", "300"))
        self.clock = clock or monotonic
        self._lock = threading.Lock()
        self._failures: dict[tuple[str, str], list[float]] = {}
        self._locked_until: dict[tuple[str, str], float] = {}

    def reset(self) -> None:
        with self._lock:
            self._failures.clear()
            self._locked_until.clear()

    @staticmethod
    def _keys(email: str, ip: str) -> list[tuple[tuple[str, str], int]]:
        return [(("email", (email or "")[:254].lower()), 0), (("ip", ip or ""), 1)]

    def retry_after(self, email: str, ip: str) -> int:
        """Seconds until sign-in may be tried again; 0 when not locked."""
        now = self.clock()
        with self._lock:
            waits = [self._locked_until.get(key, 0) - now for key, _ in self._keys(email, ip)]
        return max(0, int(max(waits) + 0.999)) if max(waits) > 0 else 0

    def record_failure(self, email: str, ip: str) -> None:
        now = self.clock()
        with self._lock:
            if len(self._failures) > 20000:  # bound memory under a spray of made-up emails
                self._failures = {k: v for k, v in self._failures.items() if v and now - v[-1] < self.window_seconds}
                self._locked_until = {k: v for k, v in self._locked_until.items() if v > now}
            for key, kind in self._keys(email, ip):
                recent = [t for t in self._failures.get(key, []) if now - t < self.window_seconds]
                recent.append(now)
                self._failures[key] = recent
                if len(recent) >= (self.ip_max_failures if kind else self.max_failures):
                    self._locked_until[key] = now + self.lockout_seconds
                    self._failures[key] = []

    def record_success(self, email: str) -> None:
        with self._lock:
            key = ("email", (email or "")[:254].lower())
            self._failures.pop(key, None)
            self._locked_until.pop(key, None)


LOGIN_THROTTLE = LoginThrottle()
# Checked when the email is unknown, so a miss costs as much as a wrong password.
UNKNOWN_ACCOUNT_PASSWORD_HASH = generate_password_hash(os.urandom(16).hex())

# Sessions that were signed out on purpose. The cookie is a signed value the
# browser holds, so clearing it there alone would not stop a copy of it; every
# login gets a random "sid" and logout remembers it here (bounded, per process).
REVOKED_SESSION_IDS: "OrderedDict[str, None]" = OrderedDict()
REVOKED_SESSION_LIMIT = 5000


def revoke_session_id(sid: str | None) -> None:
    if not sid:
        return
    REVOKED_SESSION_IDS[sid] = None
    while len(REVOKED_SESSION_IDS) > REVOKED_SESSION_LIMIT:
        REVOKED_SESSION_IDS.popitem(last=False)


def current_account() -> UserAccount | None:
    account_id = session.get("account_id")
    if not account_id:
        return None
    if session.get("sid") in REVOKED_SESSION_IDS:
        session.clear()
        return None
    account = db.session.get(UserAccount, account_id)
    if not account or not account.active:
        session.clear()
        return None
    return account


def faculty_can_access_research_evidence(faculty_id: int, evidence: ResearchEvidenceFile) -> bool:
    faculty = Faculty.query.get(faculty_id)
    if not faculty or not evidence or not evidence.document_check:
        return False
    if faculty_is_adviser_for_student(faculty.id, evidence.student_id):
        return True
    return bool(
        PanelAssignment.query.filter_by(
            faculty_id=faculty.id,
            student_id=evidence.student_id,
            gate=evidence.document_check.gate,
        ).first()
    )


# Records the roles each protected endpoint was actually registered with, so the
# access-control KPI can compare the running configuration against an
# independently declared specification instead of restating the same rule.
API_ROLE_REGISTRY: dict[str, frozenset] = {}


def require_api_login(*roles):
    # Pass one or more roles; empty means "any signed-in account".
    allowed = {r for r in roles if r}

    def decorator(fn):
        API_ROLE_REGISTRY[fn.__name__] = frozenset(allowed)

        @wraps(fn)
        def wrapper(*args, **kwargs):
            account = current_account()
            if not account:
                return jsonify({"error": "Please sign in to continue."}), 401
            # Admin is a superuser: it passes every role gate so it can review
            # all staff-side screens. (Ownership visibility is tightened later.)
            if allowed and account.role not in allowed and account.role != "admin":
                return jsonify({"error": "This account cannot access that area."}), 403
            if account.must_change_password:
                return jsonify({
                    "error": "Choose your own password before you continue.",
                    "must_change_password": True,
                }), 403
            return fn(*args, **kwargs)

        return wrapper

    return decorator


def require_workflow_actor(*roles) -> UserAccount:
    """Enforce the configured owner for a workflow transition."""
    account = current_account()
    if not account or account.role not in roles:
        expected = " or ".join(ROLE_LABELS[role] for role in roles)
        raise ValueError(f"This step must be completed by {expected}.")
    return account


def workflow_actor_label(account: UserAccount) -> str:
    return f"{ROLE_LABELS.get(account.role, account.role)} · {account.full_name}"


# ---------------------------------------------------------------------------
# Module 5 — Prescriptive decision support (rule-based, computed in the backend)
# ---------------------------------------------------------------------------
# These indicators + recommendations are the SOURCE OF TRUTH. They are computed
# deterministically from recorded transactions, never by the assistant/LLM.
STALL_WARN_DAYS = 120
STALL_HIGH_DAYS = 210

def student_indicators(student: Student) -> dict:
    """Computed indicators for one student (Table 13 in the proposal)."""
    audit = compute_course_audit(student)
    open_tasks = Task.query.filter(
        Task.student_id == student.id, Task.status.in_(["Pending", "Overdue"])
    ).order_by(Task.due_at.asc()).all()
    overdue = [t for t in open_tasks if t.due_at < date.today()]
    max_overdue_days = max(((date.today() - t.due_at).days for t in overdue), default=0)
    upcoming = [t for t in open_tasks if t.due_at >= date.today()]
    next_due_days = min(((t.due_at - date.today()).days for t in upcoming), default=None)
    next_upcoming_title = (
        sorted(upcoming, key=lambda t: t.due_at)[0].title if upcoming else None
    )
    case = (
        ResearchCase.query.filter_by(student_id=student.id).order_by(ResearchCase.opened_at.desc()).first()
    )
    current_milestone = research_milestone_payload(student, case.current_gate) if case and case.current_gate in RESEARCH_MILESTONES else None
    missing_docs = current_milestone["student_missing_count"] if current_milestone else 0
    sched = (
        ScheduleRequest.query.filter_by(student_id=student.id).order_by(ScheduleRequest.created_at.desc()).first()
    )
    last_log = (
        TransactionLog.query.filter_by(student_id=student.id).order_by(TransactionLog.created_at.desc()).first()
    )
    anchor = student.updated_at or student.created_at or now_utc()
    days_in_stage = max((now_utc() - anchor).days, 0)
    next_owner = (last_log.next_owner if last_log else None) or (open_tasks[0].owner_role if open_tasks else None)
    return {
        "stage": student.current_stage,
        "standing": student.standing,
        "risk": student.risk_level,
        "completion_rate": audit["completion_rate"],
        "missing_subjects": audit["missing_count"],
        "open_tasks": len(open_tasks),
        "overdue_tasks": len(overdue),
        "max_overdue_days": max_overdue_days,
        "research_gate": case.current_gate if case else None,
        "research_status": case.status if case else None,
        "missing_documents": missing_docs,
        "schedule_status": sched.status if sched else None,
        "days_in_stage": days_in_stage,
        "next_owner": next_owner,
    }


# Priority score = weighted urgency, so same-severity items can be ranked.
# Severity is DERIVED from the score, so the badge and the score never disagree.
SCORE_HIGH = 67
SCORE_MEDIUM = 34
SCORE_CRITICAL = 85


def band_from_score(score: int) -> str:
    if score >= SCORE_CRITICAL:
        return "critical"
    if score >= SCORE_HIGH:
        return "high"
    if score >= SCORE_MEDIUM:
        return "medium"
    return "low"


def _make_rec(code, base_score, trigger, recommendation, owner, bonus=0):
    score = max(1, min(100, int(base_score + bonus)))
    return {
        "code": code,
        "score": score,
        "severity": band_from_score(score),
        "trigger": trigger,
        "recommendation": recommendation,
        "owner": normalize_owner_label(owner) or STAFF_OWNER,
    }


def student_recommendations(student: Student) -> dict:
    """Turn indicators into prescriptive, scored, owner-assigned next actions."""
    ind = student_indicators(student)
    owner = normalize_owner_label(ind["next_owner"]) or STAFF_OWNER
    recs: list[dict] = []

    if ind["overdue_tasks"] > 0:
        d = ind["max_overdue_days"]
        recs.append(_make_rec(
            "overdue", 68, f"{ind['overdue_tasks']} task(s) overdue — oldest is {d} day(s) past due",
            f"Escalate the overdue task(s) to {owner} and confirm the next step ({d} day(s) late).",
            owner, bonus=min(d * 2, 32)))
    if ind["missing_documents"] > 0 and ind["research_gate"]:
        n = ind["missing_documents"]
        recs.append(_make_rec(
            "evidence", 42, f"{n} required document(s) missing at {ind['research_gate']}",
            f"Return to the student to submit the {n} missing item(s) for {ind['research_gate']}.",
            "Student", bonus=min(n * 4, 24)))
    if ind["missing_subjects"] > 0 and ind["stage"] not in ("Admission", "LOA", "Completed"):
        n = ind["missing_subjects"]
        recs.append(_make_rec(
            "coursework", 36, f"{n} subject(s) missing or incomplete in the course audit",
            f"Resolve the {n} outstanding subject(s) with the Academic Coordinator.",
            "Academic Coordinator", bonus=min(n * 2, 18)))
    if ind["schedule_status"] in PENDING_DEFENSE_STATUSES:
        recs.append(_make_rec(
            "schedule", 46, "Defense schedule has no confirmed panel availability",
            "Collect panel and adviser availability, then re-confirm the defense date.",
            "Research Coordinator"))
    if ind["standing"] == "On Leave":
        recs.append(_make_rec(
            "residency", 40, "Student is on Leave of Absence",
            "Check the LOA expiry and prepare the readmission follow-up.", STAFF_OWNER))
    if ind["days_in_stage"] >= STALL_WARN_DAYS and ind["stage"] != "Completed":
        d = ind["days_in_stage"]
        recs.append(_make_rec(
            "stalled", 48, f"No recorded update in {d} days at the {ind['stage']} stage",
            f"Follow up — the case has been inactive for {d} days at {ind['stage']}.",
            owner, bonus=min(d // 8, 40)))

    recs.sort(key=lambda r: -r["score"])
    return {"indicators": ind, "recommendations": recs}


def student_portal_recommendations(student: Student) -> list[dict]:
    payload = student_recommendations(student)
    indicators = payload["indicators"]
    milestone = RESEARCH_MILESTONES.get(indicators.get("research_gate") or "", {})
    rows = []
    for rec in payload["recommendations"]:
        item = dict(rec)
        if rec["code"] == "evidence":
            count = indicators["missing_documents"]
            item["recommendation"] = f"Upload the {count} missing file(s) for {milestone.get('label', indicators['research_gate'])}."
            item["owner"] = "You"
        elif rec["code"] == "coursework":
            item["recommendation"] = f"Contact the Academic Coordinator about your {indicators['missing_subjects']} outstanding subject(s)."
        elif rec["code"] == "schedule":
            item["recommendation"] = "Wait for the Research Coordinator to confirm a time shared by your adviser and panel."
        elif rec["code"] == "stalled":
            item["recommendation"] = "Contact the office shown below to confirm the next action on your record."
        rows.append(item)
    return rows


def student_delay_assessment(student: Student) -> dict:
    """Return a progress status; every alert must explain a possible delay."""
    term = get_active_term()
    indicators = student_indicators(student)
    delayed: list[str] = []
    at_risk: list[str] = []
    current_year = student_current_course_year(student, term) or 1
    records = {
        record.course_id: record
        for record in CourseRecord.query.filter_by(student_id=student.id).all()
    }

    for course in monitoring_curriculum_courses(student.program):
        record = records.get(course.id)
        status = record.status if record else "Missing"
        if student.program.code in AUTHORITATIVE_CURRICULA:
            year_match = re.search(r"year\s*(\d+)", course.recommended_term or "", re.IGNORECASE)
            required_for_sequence = course.category != "Cognate" or course.code == "MBA218"
            if (
                year_match and int(year_match.group(1)) < current_year
                and required_for_sequence and status not in {"Completed", "Current", "Enrolled"}
            ):
                delayed.append(f"{course.code} remains unfinished past its suggested course year")

    if student.standing == "AWOL" or student.enrollment_tag == "AWOL":
        delayed.append("AWOL status has interrupted enrollment")
    if indicators["days_in_stage"] >= STALL_HIGH_DAYS and student.current_stage != "Completed":
        delayed.append(f"no progress update has been recorded for {indicators['days_in_stage']} days")
    elif indicators["days_in_stage"] >= STALL_WARN_DAYS and student.current_stage != "Completed":
        at_risk.append(f"no progress update has been recorded for {indicators['days_in_stage']} days")
    if indicators["overdue_tasks"]:
        at_risk.append(f"{indicators['overdue_tasks']} overdue action(s) may delay progress")
    if indicators["missing_documents"]:
        at_risk.append(f"{indicators['missing_documents']} required document(s) may delay the current milestone")
    if term and student.program.code in AUTHORITATIVE_CURRICULA:
        next_ids = {row["id"] for row in student_semester_subjects(student, term)["next_subjects"]}
        plan = (
            CourseOfferingPlan.query.filter_by(program_id=student.program_id, term_label=term.label)
            .filter(CourseOfferingPlan.status.in_(["Approved", "Published"]))
            .order_by(CourseOfferingPlan.updated_at.desc())
            .first()
        )
        if plan:
            unavailable = {item.course_id for item in plan.offerings if item.status == "Not Offered"}
            for course_id in sorted(next_ids & unavailable):
                course = db.session.get(Course, course_id)
                if course:
                    at_risk.append(f"{course.code} is needed next but is not offered for {term.label}")

    delayed = list(dict.fromkeys(delayed))
    at_risk = list(dict.fromkeys(at_risk))
    if delayed:
        return {"level": "Delayed", "score": 80, "reason": delayed[0], "causes": delayed + at_risk}
    if at_risk:
        return {"level": "At Risk of Delay", "score": 50, "reason": at_risk[0], "causes": at_risk}
    return {"level": "On Track", "score": 0, "reason": "No recorded delay indicators", "causes": []}


def student_priority(student: Student) -> dict:
    """A student's overall priority = the highest-scoring recommendation. Keeps the
    student record consistent with the Decision Support queue."""
    # Checklist items 11/74: a newly admitted student has not accumulated the signals
    # the risk model needs, so it remains "Not Yet Assessed" until verified
    # indicators exist.
    has_coursework = CourseRecord.query.filter(
        CourseRecord.student_id == student.id,
        CourseRecord.status.in_(["Completed", "Failed", "Current", "Enrolled"]),
    ).first()
    if student.current_stage == "Admission" and not has_coursework:
        return {"level": "Not Yet Assessed", "score": 0, "reason": "Newly admitted — not yet assessed for risk (insufficient data)"}
    return student_delay_assessment(student)


def recompute_risk(student: Student) -> None:
    """Persist the derived priority into risk_level so every view agrees."""
    student.risk_level = student_priority(student)["level"]


def normalize_owner_role_vocabulary() -> int:
    """Rewrite the old "GS Staff" owner spelling to the one canonical label on existing rows.

    Guarded and idempotent: only touches rows that still carry a legacy spelling and tolerates a
    database where the tables do not exist yet.
    """
    tables = set(inspect(db.engine).get_table_names())
    changed = 0
    for table, column in (("task", "owner_role"), ("transaction_log", "next_owner")):
        if table not in tables:
            continue
        for legacy in LEGACY_STAFF_OWNER_SPELLINGS:
            result = db.session.execute(
                text(f"UPDATE {table} SET {column} = :new WHERE {column} = :old"),
                {"new": STAFF_OWNER, "old": legacy},
            )
            changed += result.rowcount or 0
    if changed:
        db.session.commit()
    return changed


def normalize_stage_vocabulary() -> int:
    """Move students left in the retired stage "Research" to the real stage "Writing"."""
    if "student" not in set(inspect(db.engine).get_table_names()):
        return 0
    result = db.session.execute(
        text("UPDATE student SET current_stage = 'Writing' WHERE current_stage = 'Research'")
    )
    if result.rowcount:
        db.session.commit()
    return result.rowcount or 0


def ensure_delay_status_consistency() -> int:
    changed = 0
    for student in Student.query.all():
        expected = student_priority(student)["level"]
        if student.risk_level != expected:
            student.risk_level = expected
            changed += 1
    if changed:
        db.session.commit()
    return changed


# Risk depends on the clock (overdue tasks, days in a stage), so the stored ``risk_level`` would go
# stale on a server that stays up. Every screen that counts or filters by risk calls
# refresh_risk_levels() first; it recomputes through student_priority() (the one definition) at most
# once per RISK_REFRESH_SECONDS and whenever the day changes.
RISK_REFRESH_SECONDS = max(int(os.getenv("USLS_RISK_REFRESH_SECONDS", "60") or 60), 0)
_RISK_REFRESH_STATE: dict = {"at": None, "day": None}


def refresh_risk_levels(force: bool = False) -> int:
    """Bring every student's stored risk level up to date; returns how many changed."""
    import time as _time

    now = _time.monotonic()
    today = date.today()
    last = _RISK_REFRESH_STATE["at"]
    if (
        not force
        and last is not None
        and _RISK_REFRESH_STATE["day"] == today
        and now - last < RISK_REFRESH_SECONDS
    ):
        return 0
    changed = ensure_delay_status_consistency()
    _RISK_REFRESH_STATE.update(at=now, day=today)
    return changed


def _portfolio_row(rec, student):
    row = dict(rec)
    row.update({
        "student_id": student.id,
        "student_name": student.name,
        "student_number": student.student_number,
        "program_code": student.program.code,
        "stage": student.current_stage,
    })
    return row


def portfolio_recommendations(limit: int = 150) -> dict:
    """Action queue across the population, each item scored and specific (cheap queries)."""
    today = date.today()
    rows: list[dict] = []

    for t in (
        Task.query.filter(Task.status.in_(["Pending", "Overdue"]), Task.due_at < today)
        .order_by(Task.due_at.asc())
        .all()
    ):
        if not t.student:
            continue
        d = (today - t.due_at).days
        rows.append(_portfolio_row(_make_rec(
            "overdue", 68, f"“{t.title}” is {d} day(s) overdue (due {t.due_at.isoformat()})",
            f"Escalate “{t.title}” to {t.owner_role} — {d} day(s) past due.",
            t.owner_role, bonus=min(d * 2, 32)), t.student))

    cutoff = now_utc() - timedelta(days=STALL_WARN_DAYS)
    for s in (
        Student.query.filter(
            Student.standing == "Active",
            Student.current_stage != "Completed",
            Student.updated_at < cutoff,
        )
        .order_by(Student.updated_at.asc())
        .all()
    ):
        d = max((now_utc() - (s.updated_at or s.created_at)).days, 0)
        owner = "Research Coordinator" if s.current_stage in (
            "Proposal Development", "Proposal Defense", "Data Collection", "Writing", "Final Defense"
        ) else "Academic Coordinator" if s.current_stage == "Coursework" else STAFF_OWNER
        rows.append(_portfolio_row(_make_rec(
            "stalled", 48, f"No recorded update in {d} days at {s.current_stage}",
            f"Follow up — inactive for {d} days at {s.current_stage}.",
            owner, bonus=min(d // 8, 40)), s))

    for sc in (
        ScheduleRequest.query.filter(ScheduleRequest.status.in_(PENDING_DEFENSE_STATUSES))
        .order_by(ScheduleRequest.created_at.desc())
        .all()
    ):
        if sc.student:
            rows.append(_portfolio_row(_make_rec(
                "schedule", 46, "Defense schedule has no confirmed panel availability",
                "Collect panel and adviser availability, then re-confirm the defense date.",
                "Research Coordinator"), sc.student))

    for sid, n in (
        db.session.query(DocumentCheck.student_id, func.count(DocumentCheck.id))
        .filter(DocumentCheck.status == "Missing")
        .group_by(DocumentCheck.student_id)
        .all()
    ):
        s = Student.query.get(sid)
        if s and s.standing == "Active":
            rows.append(_portfolio_row(_make_rec(
                "evidence", 42, f"{n} required document(s) missing",
                f"Request the {n} missing required document(s) from the student.",
                "Student", bonus=min(n * 4, 24)), s))

    seen = {(r["student_id"], r["code"]) for r in rows}
    for s in Student.query.filter(on_leave_clause()).all():
        if (s.id, "residency") not in seen:
            rows.append(_portfolio_row(_make_rec(
                "residency", 40, "Student is on Leave of Absence",
                "Check the LOA expiry and prepare the readmission follow-up.", STAFF_OWNER), s))

    rows.sort(key=lambda r: -r["score"])
    # The summary counts EVERY flagged item; only the list that is sent to the screen is cut to
    # ``limit`` rows, so the headline numbers never depend on the cut.
    all_rows = rows
    rows = rows[:limit]

    by_severity: dict[str, int] = {}
    by_owner: dict[str, int] = {}
    for r in all_rows:
        by_severity[r["severity"]] = by_severity.get(r["severity"], 0) + 1
        by_owner[r["owner"]] = by_owner.get(r["owner"], 0) + 1

    return {
        "items": rows,
        "summary": {
            "total": len(all_rows),
            "shown": len(rows),
            "students_flagged": len({r["student_id"] for r in all_rows}),
            "by_severity": [
                {"severity": sev, "count": by_severity.get(sev, 0)}
                for sev in ["high", "medium", "low"]
                if by_severity.get(sev, 0) > 0
            ],
            "by_owner": [{"owner": o, "count": n} for o, n in sorted(by_owner.items(), key=lambda x: -x[1])],
        },
    }


