def _gemini_generate(prompt: str) -> str:
    """Make one bounded, stateless Gemini request without a heavyweight SDK."""
    api_key = os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_AI_STUDIO_API_KEY")
    if not api_key:
        raise RuntimeError("Google AI Studio is not configured.")
    model_name = os.getenv("GEMINI_MODEL", "gemini-2.5-flash").removeprefix("models/")
    if not re.fullmatch(r"[A-Za-z0-9._-]+", model_name):
        raise RuntimeError("The configured Gemini model name is invalid.")
    endpoint = (
        "https://generativelanguage.googleapis.com/v1beta/models/"
        f"{model_name}:generateContent"
    )
    body = json.dumps({
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {
            "maxOutputTokens": int(os.getenv("RAG_MAX_OUTPUT_TOKENS", "500")),
        },
    }).encode("utf-8")
    request_item = Request(
        endpoint,
        data=body,
        headers={
            "Content-Type": "application/json",
            "x-goog-api-key": api_key,
        },
        method="POST",
    )
    timeout = max(3.0, float(os.getenv("RAG_REQUEST_TIMEOUT_SECONDS", "18")))
    try:
        with urlopen(request_item, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        raise RuntimeError(f"Gemini returned HTTP {exc.code}.") from exc
    except (URLError, TimeoutError) as exc:
        raise RuntimeError("Gemini did not respond before the timeout.") from exc
    candidates = payload.get("candidates") or []
    if not candidates:
        raise RuntimeError("Gemini returned no answer.")
    parts = ((candidates[0].get("content") or {}).get("parts") or [])
    answer = "".join(str(part.get("text") or "") for part in parts).strip()
    if not answer:
        raise RuntimeError("Gemini returned an empty answer.")
    return answer


def _normalized_embedding(values: list) -> list[float]:
    vector = [float(value) for value in values]
    if not vector or not all(math.isfinite(value) for value in vector):
        raise RuntimeError("The embedding service returned an invalid vector.")
    magnitude = math.sqrt(sum(value * value for value in vector))
    if magnitude <= 0:
        raise RuntimeError("The embedding service returned an empty vector.")
    return [value / magnitude for value in vector]


def _gemini_embed_texts(texts: list[str], purpose: str, timeout: float | None = None) -> list[list[float]]:
    """Generate bounded semantic vectors with Gemini's current embedding model."""
    if not texts:
        return []
    api_key = os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_AI_STUDIO_API_KEY")
    if not api_key:
        raise RuntimeError("Google AI Studio is not configured for vector retrieval.")
    model_name = os.getenv("GEMINI_EMBEDDING_MODEL", "gemini-embedding-2").removeprefix("models/")
    if not re.fullmatch(r"[A-Za-z0-9._-]+", model_name):
        raise RuntimeError("The configured Gemini embedding model name is invalid.")
    dimensions = max(128, min(3072, int(os.getenv("RAG_EMBEDDING_DIMENSIONS", "768"))))
    batch_size = max(1, min(50, int(os.getenv("RAG_EMBEDDING_BATCH_SIZE", "20"))))
    instruction = {
        "document": "Represent this USLS Graduate School policy passage for semantic document retrieval.",
        "query": "Retrieve USLS Graduate School policy passages that answer this question.",
    }.get(purpose, "Represent this text for semantic similarity.")
    endpoint = (
        "https://generativelanguage.googleapis.com/v1beta/models/"
        f"{model_name}:batchEmbedContents"
    )
    vectors: list[list[float]] = []
    timeout = timeout or max(5.0, float(os.getenv("RAG_EMBEDDING_TIMEOUT_SECONDS", "45")))
    for start in range(0, len(texts), batch_size):
        batch = texts[start:start + batch_size]
        body = json.dumps({
            "requests": [
                {
                    "model": f"models/{model_name}",
                    "content": {
                        "parts": [{"text": f"{instruction}\n\n{text[:12000]}"}],
                    },
                    "outputDimensionality": dimensions,
                }
                for text in batch
            ],
        }).encode("utf-8")
        request_item = Request(
            endpoint,
            data=body,
            headers={
                "Content-Type": "application/json",
                "x-goog-api-key": api_key,
            },
            method="POST",
        )
        try:
            with urlopen(request_item, timeout=timeout) as response:
                payload = json.loads(response.read().decode("utf-8"))
        except HTTPError as exc:
            raise RuntimeError(f"Gemini embeddings returned HTTP {exc.code}.") from exc
        except (URLError, TimeoutError) as exc:
            raise RuntimeError("Gemini embeddings did not respond before the timeout.") from exc
        embeddings = payload.get("embeddings") or []
        if len(embeddings) != len(batch):
            raise RuntimeError("Gemini embeddings returned an incomplete batch.")
        vectors.extend(
            _normalized_embedding(item.get("values") or [])
            for item in embeddings
        )
    return vectors


def _rag_vector_signature() -> dict:
    return {
        "model": os.getenv("GEMINI_EMBEDDING_MODEL", "gemini-embedding-2").removeprefix("models/"),
        "dimensions": max(128, min(3072, int(os.getenv("RAG_EMBEDDING_DIMENSIONS", "768")))),
        "prompt_version": 2,
    }


def _rag_chunk_vector_key(chunk: dict) -> str:
    """Vectors are cached by passage content, so a new upload only embeds its own passages."""
    return hashlib.sha1(
        f"{chunk.get('title', '')}\n{chunk.get('source', '')}\n{chunk.get('text', '')}".encode("utf-8")
    ).hexdigest()


def _rag_vector_store() -> dict[str, list[float]]:
    signature = _rag_vector_signature()
    path = Path(RAG_INDEX_DIR) / "vectors_v2.json"
    state = _RAG_VECTOR_STATE
    if state["path"] != str(path) or state["signature"] != signature:
        vectors: dict[str, list[float]] = {}
        if path.exists():
            try:
                stored = json.loads(path.read_text(encoding="utf-8"))
                if stored.get("signature") == signature and isinstance(stored.get("vectors"), dict):
                    vectors = {
                        key: value for key, value in stored["vectors"].items()
                        if isinstance(value, list) and value
                    }
            except Exception:  # noqa: BLE001
                vectors = {}
        state.update(path=str(path), signature=signature, vectors=vectors)
    return state["vectors"]


def _rag_save_vector_store() -> None:
    state = _RAG_VECTOR_STATE
    if not state["path"]:
        return
    path = Path(state["path"])
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary_path = path.with_suffix(".json.tmp")
        temporary_path.write_text(
            json.dumps({"signature": state["signature"], "vectors": state["vectors"]}, ensure_ascii=False, separators=(",", ":")),
            encoding="utf-8",
        )
        temporary_path.replace(path)
    except OSError:
        pass


def _rag_embedding_cooldown() -> float:
    return max(0.0, float(os.getenv("RAG_EMBED_COOLDOWN_SECONDS", "60")))


def _rag_embedding_failed() -> None:
    """After a failed embedding call, go straight to keyword search for a while."""
    global _RAG_EMBED_COOLDOWN_UNTIL
    _RAG_EMBED_COOLDOWN_UNTIL = _monotonic() + _rag_embedding_cooldown()


def _ensure_rag_vectors(
    chunks: list[dict],
    *,
    inline_limit: int | None = None,
    timeout: float | None = None,
) -> dict[str, list[float]]:
    """Return a vector per chunk id, embedding only passages not seen before.

    With ``inline_limit`` set (the request path) a large backlog is handed to a
    background thread instead of making the user's question wait for it.
    """
    acquired = _RAG_VECTOR_LOCK.acquire(blocking=inline_limit is None)
    if not acquired:
        raise RuntimeError("The semantic index is being prepared by another request.")
    try:
        store = _rag_vector_store()
        keys = {chunk["id"]: _rag_chunk_vector_key(chunk) for chunk in chunks}
        missing: list[dict] = []
        queued: set[str] = set()
        for chunk in chunks:
            key = keys[chunk["id"]]
            if key not in store and key not in queued:
                queued.add(key)
                missing.append(chunk)
        if missing:
            if _monotonic() < _RAG_EMBED_COOLDOWN_UNTIL:
                raise RuntimeError("The embedding service failed recently; using keyword search for now.")
            if inline_limit is not None and len(missing) > inline_limit:
                _start_background_embedding()
                raise RuntimeError("The semantic index is still being prepared.")
            try:
                for start in range(0, len(missing), 100):
                    batch = missing[start:start + 100]
                    embedded = _gemini_embed_texts(
                        [
                            f"Title: {chunk['title']}\nSource: {chunk['source']}\nPassage: {chunk['text']}"
                            for chunk in batch
                        ],
                        "document",
                        timeout=timeout,
                    )
                    if len(embedded) != len(batch):
                        raise RuntimeError("The embedding service returned an incomplete batch.")
                    for chunk, vector in zip(batch, embedded, strict=True):
                        store[keys[chunk["id"]]] = [round(value, 8) for value in vector]
            except Exception:
                _rag_embedding_failed()
                raise
            finally:
                _rag_save_vector_store()
        return {chunk["id"]: store[keys[chunk["id"]]] for chunk in chunks}
    finally:
        _RAG_VECTOR_LOCK.release()


def _start_background_embedding() -> None:
    global _RAG_BACKGROUND_THREAD
    if os.getenv("RAG_BACKGROUND_EMBED", "1").strip().lower() in {"0", "false", "no"}:
        return
    if not (os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_AI_STUDIO_API_KEY")):
        return
    if _RAG_BACKGROUND_THREAD is not None and _RAG_BACKGROUND_THREAD.is_alive():
        return
    _RAG_BACKGROUND_THREAD = threading.Thread(target=prewarm_document_rag, name="rag-embed", daemon=True)
    _RAG_BACKGROUND_THREAD.start()


def _load_rag_vector_index(chunks: list[dict]) -> dict[str, list[float]]:
    """Vectors for the current corpus; small changes are embedded on the spot."""
    return _ensure_rag_vectors(
        chunks,
        inline_limit=max(1, int(os.getenv("RAG_INLINE_EMBED_LIMIT", "40"))),
        timeout=max(3.0, float(os.getenv("RAG_INLINE_EMBED_TIMEOUT_SECONDS", "12"))),
    )


def _embed_rag_query(question: str) -> list[float]:
    if _monotonic() < _RAG_EMBED_COOLDOWN_UNTIL:
        raise RuntimeError("The embedding service failed recently; using keyword search for now.")
    try:
        return _gemini_embed_texts(
            [question], "query",
            timeout=max(3.0, float(os.getenv("RAG_INLINE_EMBED_TIMEOUT_SECONDS", "12"))),
        )[0]
    except Exception:
        _rag_embedding_failed()
        raise


# --- keyword retrieval --------------------------------------------------------
_RAG_EXTRA_STOPWORDS = set(
    "explain describe tell give list state please answer again need needs want wants many much may might would "
    "could about there their them they have has had been being also any some such than then into from does did "
    "doing where why whom whose very just more most other own same".split()
)


def _rag_stem(word: str) -> str:
    if len(word) > 4 and word.endswith("ies"):
        return word[:-3] + "y"
    if len(word) > 5 and word.endswith("ing"):
        return word[:-3]
    if len(word) > 4 and word.endswith(("ed", "es")):
        return word[:-2]
    if len(word) > 3 and word.endswith("s") and not word.endswith("ss"):
        return word[:-1]
    return word


def _rag_terms(text: str) -> list[str]:
    terms = []
    for word in re.findall(r"[a-z0-9]+(?:\.[0-9]+)?", (text or "").lower()):
        if word in _STOPWORDS or word in _RAG_EXTRA_STOPWORDS:
            continue
        if len(word) <= 2 and not any(ch.isdigit() for ch in word):
            continue
        stem = _rag_stem(word)
        if stem not in _STOPWORDS and stem not in _RAG_EXTRA_STOPWORDS:
            terms.append(stem)
    return terms


def _rag_chunk_terms(chunk: dict) -> list[str]:
    key = hash(chunk.get("text") or "")
    cached = _RAG_TERMS_CACHE.get(key)
    if cached is None:
        cached = _rag_terms(chunk.get("text") or "")
        _RAG_TERMS_CACHE[key] = cached
    return cached


def _rag_query_idf(query_terms: set[str], chunk_term_sets: list[set[str]]) -> dict[str, float]:
    document_frequency = Counter(term for terms in chunk_term_sets for term in terms if term in query_terms)
    corpus_size = max(1, len(chunk_term_sets))
    return {
        term: math.log((corpus_size + 1) / (document_frequency.get(term, 0) + 1)) + 1
        for term in query_terms
    }


def _retrieve_rag_document_chunks_lexically(
    question: str,
    chunks: list[dict],
    limit: int,
) -> list[dict]:
    query_sequence = _rag_terms(question)
    query_terms = set(query_sequence)
    if not query_terms or not chunks:
        return []
    chunk_term_lists = [_rag_chunk_terms(chunk) for chunk in chunks]
    chunk_term_sets = [set(terms) for terms in chunk_term_lists]
    idf = _rag_query_idf(query_terms, chunk_term_sets)
    total_idf = sum(idf.values()) or 1.0
    query_phrases = {
        " ".join(query_sequence[index:index + size])
        for size in (2, 3)
        for index in range(len(query_sequence) - size + 1)
    }
    # Handbook wording hints: they nudge, they never outvote a real term match.
    raw_terms = set(_tokenize(question))
    topic_anchors = []
    if "load" in raw_terms:
        topic_anchors.append("academic load")
    if "inc" in raw_terms or "incomplete" in raw_terms:
        topic_anchors.extend(["incomplete grades", "removal of the inc"])
    if "residence" in raw_terms and "maximum" in raw_terms:
        topic_anchors.append("maximum residence")
    if "comprehensive" in raw_terms:
        topic_anchors.append("comprehensive exam")
    if {"repeat", "retake", "failed", "failure"} & raw_terms and {"subject", "course", "class"} & raw_terms:
        topic_anchors.append("retention policy")
    if "withdraw" in raw_terms or "withdrawal" in raw_terms:
        topic_anchors.append("withdrawal of subject")
    if "leave" in raw_terms and "absence" in raw_terms:
        topic_anchors.append("leave of absence")
    if {"graduate", "graduation"} & raw_terms and {"requirement", "requirements", "completed", "complete"} & raw_terms:
        topic_anchors.append("graduation requirements")
    question_lower = (question or "").lower()
    document_words = ("handbook", "research protocol", "operations manual", "memo")

    scored = []
    for chunk, terms, term_set in zip(chunks, chunk_term_lists, chunk_term_sets, strict=True):
        title_terms = set(_rag_terms(chunk.get("title", "")))
        counts = Counter(terms)
        score = 0.0
        matched_idf = 0.0
        for term in query_terms:
            in_title = term in title_terms
            if counts.get(term) or in_title:
                matched_idf += idf[term]
            score += (min(counts.get(term, 0), 3) + (3 if in_title else 0)) * idf[term]
        if not score:
            continue
        normalized_text = " ".join(terms)
        score += sum(8 for phrase in query_phrases if phrase in normalized_text)
        raw_text = " ".join((chunk.get("text") or "").lower().split())
        score += sum(12 for anchor in topic_anchors if anchor in raw_text)
        label = f"{chunk.get('title', '')} {chunk.get('source', '')} {chunk.get('category', '')}".lower()
        for phrase in document_words:
            if phrase in question_lower and phrase in label:
                score += 50
        if chunk.get("kind") == "managed":
            score *= 1.1  # a staff upload is the newer, approved word
        coverage = matched_idf / total_idf
        matched = sum(1 for term in query_terms if counts.get(term) or term in title_terms)
        relevant = coverage >= 0.4 and matched >= min(2, len(query_terms))
        scored.append((score, chunk, coverage, relevant))
    scored.sort(key=lambda item: (-item[0], (item[1].get("status") or "active") != "active", item[1].get("id", "")))
    return [
        {**chunk, "_retrieval": "lexical-fallback", "_score": round(score, 4), "_coverage": round(coverage, 3), "_relevant": relevant}
        for score, chunk, coverage, relevant in scored[:limit]
    ]


def _retrieve_rag_document_chunks(
    question: str,
    chunks: list[dict],
    limit: int | None = None,
) -> list[dict]:
    limit = limit or max(1, int(os.getenv("RAG_TOP_K", "3")))
    try:
        vectors = _load_rag_vector_index(chunks)
        query_vector = _embed_rag_query(question)
        scored = [
            (
                sum(a * b for a, b in zip(query_vector, vectors[chunk["id"]])),
                chunk,
            )
            for chunk in chunks
            if chunk["id"] in vectors
        ]
        scored.sort(key=lambda item: (-item[0], item[1].get("id", "")))
        if scored:
            top = [
                {**chunk, "_retrieval": "vector", "_score": round(score, 6)}
                for score, chunk in scored[:limit]
            ]
            # Exact wording still matters: a passage that contains nearly every
            # term of the question is never left out because of the embedding.
            lexical = _retrieve_rag_document_chunks_lexically(question, chunks, 1)
            if lexical and lexical[0]["_coverage"] >= 0.75 and lexical[0]["id"] not in {item["id"] for item in top}:
                top = [{**lexical[0], "_retrieval": "lexical-boost"}] + top[: limit - 1]
            return top
    except Exception:  # noqa: BLE001
        # Keep policy guidance available during an embedding outage. Generation
        # still receives retrieved source text and remains citation-grounded.
        pass
    return _retrieve_rag_document_chunks_lexically(question, chunks, limit)


def prewarm_document_rag() -> None:
    """Prepare persisted document chunks and semantic vectors in the background."""
    try:
        def build():
            chunks = _load_rag_document_index()
            return chunks, _ensure_rag_vectors(chunks)

        chunks, vectors = _in_app_context(build)
        print(
            f"Policy Assistant vector index is ready "
            f"({len(chunks)} chunks, {len(vectors)} vectors)."
        )
    except Exception as exc:  # noqa: BLE001
        print(f"Policy Assistant document index prewarm skipped: {exc}")


def _case_context_for_rag(student: Student | None, payload: dict | None, snippets: list[dict]) -> str:
    context = []
    if student and payload:
        context.append("Student context: " + _status_sentence(student, payload["indicators"]))
        if payload["recommendations"]:
            context.append(
                "Open recommendations: "
                + "; ".join(f"{r['recommendation']} ({r['owner']})" for r in payload["recommendations"][:3])
            )
    if snippets:
        context.append(
            "Known policy snippets: "
            + " ".join(f"{s['title']}: {s['text']}" for s in snippets)
        )
    return "\n".join(context)


def _policy_citation(chunk: dict) -> dict:
    status = chunk.get("status") or "active"
    return {
        "id": chunk["id"],
        "title": chunk["title"],
        "source": chunk["source"],
        "text": chunk["text"][:700],
        "retrieval": chunk.get("_retrieval", "vector"),
        "similarity": chunk.get("_score"),
        "status": status,
        "category": chunk.get("category"),
        "document_id": chunk.get("document_id"),
        "kind": chunk.get("kind"),
        "warning": POLICY_DRAFT_WARNING if status == "draft" else None,
    }


def _finalize_document_answer(answer: str, chunks: list[dict]) -> str:
    """Make every answer name its source document and flag draft documents."""
    answer = (answer or "").strip()
    if chunks and not any(chunk["title"].lower() in answer.lower() for chunk in chunks):
        labels = []
        for chunk in chunks[:2]:
            if chunk["source"] not in labels:
                labels.append(chunk["source"])
        answer += "\n\nSource: " + "; ".join(labels)
    drafts = [chunk for chunk in chunks if (chunk.get("status") or "active") == "draft"]
    if drafts and POLICY_DRAFT_WARNING not in answer:
        titles = []
        for chunk in drafts:
            if chunk["title"] not in titles:
                titles.append(chunk["title"])
        answer += f"\n\n{POLICY_DRAFT_WARNING}: {', '.join(titles)}."
    return answer


def call_document_rag(question: str, snippets: list[dict], payload: dict | None, student: Student | None) -> tuple[str, list[dict]]:
    document_chunks = _load_rag_document_index()
    retrieved_chunks = _retrieve_rag_document_chunks(question, document_chunks)
    if not retrieved_chunks:
        raise PolicyPassageNotFound("No matching policy passage was found.")
    case_context = _case_context_for_rag(student, payload, snippets)
    prompt = (
        "Answer as the USLS Graduate School assistant. Use the retrieved policy document excerpts (handbook, "
        "research protocol, memos, manuals) as the primary source; when two excerpts disagree, prefer the one "
        "marked as the newer or staff-uploaded document and say so. Name the source document title and page or "
        "section you rely on. If an excerpt is marked DRAFT, say the rule is a draft pending Graduate School "
        "validation. If student context is provided, use it only for that student's live "
        "status and do not invent approvals, decisions, or missing records. Answer the question directly in no "
        "more than 120 words. Include only the rules needed to answer it; do not paste long source passages. "
        "If the documents do not answer the question, say what is missing.\n\n"
    )
    if case_context:
        prompt += case_context + "\n\n"
    prompt += "Retrieved document excerpts:\n"
    prompt += "\n\n".join(
        f"[{chunk['source']}"
        + (" — DRAFT, pending Graduate School validation" if (chunk.get("status") or "active") == "draft" else "")
        + (" — staff-uploaded" if chunk.get("kind") == "managed" else "")
        + f"]\n{chunk['text']}"
        for chunk in retrieved_chunks
    )
    prompt += f"\n\nQuestion: {question}"
    response = _finalize_document_answer(_gemini_generate(prompt), retrieved_chunks)
    return response, [_policy_citation(chunk) for chunk in retrieved_chunks]


def _merge_rag_source_chunks(source_chunk: dict, document_chunks: list[dict]) -> str:
    """Reconstruct a page or section so it does not end at a chunk boundary."""
    matching = [
        chunk for chunk in document_chunks
        if chunk.get("title") == source_chunk.get("title")
        and chunk.get("source") == source_chunk.get("source")
    ]
    merged_words: list[str] = []
    for chunk in matching:
        words = (chunk.get("text") or "").split()
        if not words:
            continue
        overlap = 0
        for size in range(min(80, len(merged_words), len(words)), 0, -1):
            if merged_words[-size:] == words[:size]:
                overlap = size
                break
        merged_words.extend(words[overlap:])
    return " ".join(merged_words).strip()


def _local_rag_focus_phrases(question: str) -> list[str]:
    lowered = (question or "").lower()
    phrases: list[str] = []
    if ("inc" in lowered or "incomplete" in lowered) and any(
        word in lowered for word in ("remove", "deadline", "happen", "long")
    ):
        phrases.extend(["removal of the", "removal of"])
    elif "inc" in lowered or "incomplete" in lowered:
        phrases.append("incomplete grades")
    if "withdraw" in lowered:
        phrases.append("withdrawal of subject")
    if "leave of absence" in lowered:
        phrases.extend(["leave may be approved", "leave of absence"])
    if "load" in lowered:
        phrases.append("academic load")
    if "maximum" in lowered and "residence" in lowered:
        phrases.append("maximum residence")
    if "comprehensive" in lowered:
        phrases.extend(["eligibility", "minimum score", "comprehensive examination"])
    if (
        any(term in lowered for term in ("repeat", "retake", "failed", "failure"))
        and any(term in lowered for term in ("subject", "course", "class"))
    ):
        phrases.append("retention policy")
    if "thesis" in lowered or "dissertation" in lowered or "project paper" in lowered:
        phrases.extend(["thesis/project paper writing", "dissertation writing"])
    if ("graduate" in lowered or "graduation" in lowered) and "require" in lowered:
        phrases.append("graduation requirements")
    return phrases


def _focused_local_rag_excerpt(text: str, question: str, max_chars: int) -> str:
    """Return a short passage around the part that answers the question."""
    excerpt = " ".join((text or "").split()).strip()
    excerpt = re.sub(
        r"^(?:\d+\s+)?Graduate Programs Student Handbook 2022-2023\s+\d*\s*",
        "",
        excerpt,
        flags=re.IGNORECASE,
    )
    if not excerpt:
        return ""

    lowered = excerpt.lower()
    positions = []
    for phrase in _local_rag_focus_phrases(question):
        position = lowered.find(phrase)
        if position >= 0:
            positions.append(position)
    focus = positions[0] if positions else 0

    sentence_start = max(
        excerpt.rfind(". ", max(0, focus - 320), focus),
        excerpt.rfind("? ", max(0, focus - 320), focus),
        excerpt.rfind("! ", max(0, focus - 320), focus),
    )
    start = sentence_start + 2 if sentence_start >= 0 else max(0, focus - 120)
    candidate = excerpt[start:].strip()
    if len(candidate) <= max_chars:
        return candidate

    boundary = max(
        candidate.rfind(". ", 0, max_chars),
        candidate.rfind("? ", 0, max_chars),
        candidate.rfind("! ", 0, max_chars),
    )
    if boundary >= min(220, max_chars // 2):
        return candidate[:boundary + 1].strip()
    return candidate[:max_chars].rsplit(" ", 1)[0].rstrip(" ,;:") + "…"


def _targeted_local_rag_answer(question: str, page_texts: list[str]) -> str | None:
    """Select complete rule sentences for common multi-part handbook questions."""
    sentences = []
    for text in page_texts:
        normalized = " ".join((text or "").split()).strip()
        sentences.extend(re.split(r"(?<=[.!?])\s+", normalized))

    def pick(*required_groups: tuple[str, ...]) -> list[str]:
        picked = []
        for required in required_groups:
            match = next(
                (
                    sentence.strip()
                    for sentence in sentences
                    if all(term in sentence.lower() for term in required)
                ),
                None,
            )
            if match and match not in picked:
                picked.append(match)
        return picked

    lowered = (question or "").lower()
    selected: list[str] = []
    if "academic load" in lowered or (
        "part-time" in lowered and "full-time" in lowered and "load" in lowered
    ):
        selected = pick(
            ("normal load", "part-time", "full-time"),
        )
        if selected:
            start = selected[0].lower().find("the normal load")
            if start >= 0:
                selected[0] = selected[0][start:]
    elif "withdraw" in lowered:
        selected = pick(
            ("may withdraw subjects until",),
            ("ten percent", "twenty percent"),
            ("withdraw all subjects", "full enrolment fees"),
        )
        if selected:
            start = selected[0].lower().find("the student may withdraw")
            if start >= 0:
                selected[0] = selected[0][start:]
    elif "leave of absence" in lowered and "return" in lowered:
        selected = pick(
            ("leave may be approved",),
            ("student returning from a leave of absence",),
        )
    elif ("inc" in lowered or "incomplete" in lowered) and any(
        word in lowered for word in ("remove", "deadline", "happen", "long")
    ):
        selected = pick(
            ("removal of the", "one (1) academic year"),
            ("fails to comply", "automatically get"),
        )
    elif "maximum" in lowered and "residence" in lowered:
        selected = pick(
            ("master", "maximum of seven"),
            ("doctoral program", "maximum of nine"),
        )
        if selected:
            start = selected[0].lower().find("a master")
            if start >= 0:
                selected[0] = selected[0][start:]
    elif "comprehensive" in lowered and ("retake" in lowered or "how many times" in lowered):
        selected = pick(
            ("allowed to take 2 retakes",),
            ("fails in the second retake", "refresher course"),
            ("failure", "fourth time", "disqualification"),
        )
    elif "comprehensive" in lowered and any(
        word in lowered for word in ("eligib", "requirement", "qualif", "apply", "file ")
    ):
        selected = pick(
            ("master", "passed all academic requirements", "may file"),
            ("doctorate students", "passed all academic requirements", "may likewise file"),
            ("minimum score", "7.00 points"),
            ("70% or higher", "passed"),
            ("allowed to take 2 retakes",),
            ("fails in the second retake", "refresher course"),
            ("failure", "fourth time", "disqualification"),
        )
        if selected:
            start = selected[0].lower().find("students who have passed")
            if start >= 0:
                selected[0] = "Master’s " + selected[0][start:]
        if len(selected) >= 3:
            start = selected[2].lower().find("students must get")
            if start >= 0:
                selected[2] = selected[2][start:]
    elif "thesis" in lowered or "dissertation" in lowered or "project paper" in lowered:
        selected = pick(
            ("thesis/project paper writing", "two (2) years"),
            ("dissertation writing", "three (3) years"),
        )
    elif "good standing" in lowered or (
        "master" in lowered and "doctoral" in lowered and "average" in lowered
    ):
        selected = pick(
            ("remain in good standing", "2.0 or better", "1.75 or better"),
            ("passing grades", "graduate credit"),
        )
        if selected:
            start = selected[0].lower().find("to remain in good standing")
            if start >= 0:
                selected[0] = selected[0][start:]
    elif (
        any(term in lowered for term in ("repeat", "retake", "failed", "failure"))
        and any(term in lowered for term in ("subject", "course", "class"))
    ):
        selected = pick(
            ("gets 5.0", "automatically dropped"),
            ("failure in any subject", "no re-admission"),
        )

    return " ".join(selected) if selected else None


_ANSWER_ABBREVIATIONS = ("no.", "dr.", "mr.", "mrs.", "ms.", "prof.", "e.g.", "i.e.", "vs.", "sec.", "art.", "fig.", "approx.")


def _split_policy_sentences(text: str) -> list[str]:
    normalized = " ".join((text or "").split())
    # A numbered heading such as "3.11 GRADUATION REQUIREMENTS" starts a new sentence.
    normalized = re.sub(r"(?<![.!?:;])\s+(?=\d{1,2}(?:\.\d{1,2})+\s+[A-Z]{3,})", ". ", normalized)
    pieces = re.split(r"(?<=[.!?])\s+(?=[\"“(•\-]?[A-Z0-9])", normalized)
    merged: list[str] = []
    for piece in pieces:
        if merged and merged[-1].lower().endswith(_ANSWER_ABBREVIATIONS):
            merged[-1] = f"{merged[-1]} {piece}"
        else:
            merged.append(piece)
    sentences: list[str] = []
    for piece in merged:
        piece = piece.strip()
        if not piece:
            continue
        if len(piece.split()) > 70:  # run-on PDF text: fall back to clause boundaries
            sentences.extend(part.strip() for part in re.split(r"(?<=[;:])\s+", piece) if part.strip())
        else:
            sentences.append(piece)
    return sentences


_NUMBER_WORDS = {
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "twelve", "twenty",
    "thirty", "fifty", "hundred", "half", "once", "twice",
}
_QUANTITY_QUESTION = re.compile(
    r"\b(how many|how much|how long|how often|maximum|minimum|at most|at least|limit|deadline|within|units?|"
    r"years?|days?|weeks?|months?|semesters?|percent|fee|fees|cost|score|grade)\b",
    re.IGNORECASE,
)


def _select_answer_sentences(question: str, page_text: str, idf: dict[str, float], max_chars: int) -> tuple[str, float]:
    """Pick the few sentences of a page or section that answer the question."""
    sentences = _split_policy_sentences(page_text)
    if not sentences:
        return "", 0.0
    query_sequence = _rag_terms(question)
    query_terms = set(query_sequence)
    phrases = {
        " ".join(query_sequence[index:index + size])
        for size in (2, 3)
        for index in range(len(query_sequence) - size + 1)
    }
    asks_quantity = bool(_QUANTITY_QUESTION.search(question or ""))
    scores = []
    for sentence in sentences:
        terms = _rag_terms(sentence)
        term_set = set(terms)
        score = sum(idf.get(term, 1.0) for term in query_terms if term in term_set)
        if score:
            normalized = " ".join(terms)
            score += sum(3 for phrase in phrases if phrase in normalized)
            if asks_quantity and (re.search(r"\d", sentence) or term_set & _NUMBER_WORDS):
                score += 2
        scores.append(score)
    best = max(scores)
    if best <= 0:
        return "", 0.0

    best_index = scores.index(best)
    chosen = {best_index}
    lead = sentences[best_index - 1] if best_index > 0 else ""
    follow = sentences[best_index + 1] if best_index + 1 < len(sentences) else ""
    if lead.rstrip().endswith(":") or re.match(r"^(and|or|but|which|however|provided|unless)\b", sentences[best_index], re.I):
        chosen.add(best_index - 1)
    if follow and re.match(r"^(however|but|otherwise|except|unless|provided|in case|if not|exceptions?)\b", follow, re.I):
        chosen.add(best_index + 1)
    if sentences[best_index].rstrip().endswith(":") or re.search(
        r"(following|below|as follows|listed)\W*$", sentences[best_index], re.IGNORECASE
    ):
        chosen.update(range(best_index + 1, min(len(sentences), best_index + 4)))  # the list that follows
    for index, score in sorted(enumerate(scores), key=lambda item: -item[1]):
        if len(chosen) >= 3:
            break
        if index not in chosen and score >= 0.6 * best:
            chosen.add(index)

    selected: list[str] = []
    used = 0
    for index in sorted(chosen):
        sentence = sentences[index]
        if selected and used + len(sentence) > max_chars:
            break
        selected.append(sentence)
        used += len(sentence) + 1
    text = " ".join(selected)
    if len(text) > max_chars:
        text = text[:max_chars].rsplit(" ", 1)[0].rstrip(" ,;:") + "…"
    return text, best


def _local_answer_location(chunk: dict) -> str:
    title = chunk.get("title") or ""
    source = chunk.get("source") or ""
    return source[len(title):].lstrip(", ") if source.startswith(title) else source


def call_local_document_rag(question: str) -> tuple[str, list[dict]]:
    """Answer from the policy library without an AI service: cited, extractive, short."""
    document_chunks = _load_rag_document_index()
    retrieved_chunks = _retrieve_rag_document_chunks_lexically(
        question,
        document_chunks,
        max(8, int(os.getenv("RAG_TOP_K", "3"))),
    )
    relevant = [chunk for chunk in retrieved_chunks if chunk.get("_relevant")]
    if not relevant:
        raise PolicyPassageNotFound("No matching policy passage was found.")

    # Keep the response strictly extractive: sentences are copied from the
    # strongest passage (and a second one only when it is nearly as strong), so
    # an answer can never blend in a loosely matching rule.
    top = relevant[0]
    selected_chunks = [top]
    for other in relevant[1:]:
        if len(selected_chunks) >= 2:
            break
        if other["source"] != top["source"] and other["_score"] >= 0.6 * top["_score"]:
            selected_chunks.append(other)

    page_texts = [_merge_rag_source_chunks(chunk, document_chunks) for chunk in selected_chunks]
    total_limit = max(500, int(os.getenv("LOCAL_RAG_MAX_ANSWER_CHARS", "1050")))
    targeted_answer = _targeted_local_rag_answer(question, page_texts)
    paragraphs: list[str] = []
    cited = list(selected_chunks)
    if targeted_answer:
        paragraphs.append(f"According to {top['title']}, {_local_answer_location(top)}: {targeted_answer}")
    else:
        idf = _rag_query_idf(
            set(_rag_terms(question)),
            [set(_rag_chunk_terms(chunk)) for chunk in document_chunks],
        )
        cited = []
        first_score = 0.0
        for chunk, page_text in zip(selected_chunks, page_texts, strict=True):
            text, score = _select_answer_sentences(question, page_text, idf, total_limit // len(selected_chunks))
            if not text:
                text = _focused_local_rag_excerpt(page_text, question, total_limit // len(selected_chunks))
                score = 0.0
            if not text:
                continue
            if cited and score < 0.6 * first_score:
                continue  # the second passage adds nothing that answers the question
            if not cited:
                first_score = score
            cited.append(chunk)
            paragraphs.append(f"According to {chunk['title']}, {_local_answer_location(chunk)}: {text}")
    if not paragraphs:
        raise PolicyPassageNotFound("No readable policy passage was found.")
    answer = _finalize_document_answer("\n\n".join(paragraphs), cited)
    citations = [{**_policy_citation(chunk), "retrieval": "lexical"} for chunk in cited]
    return answer, citations


def _assistant_asks_portfolio(question: str) -> bool:
    lowered = (question or "").lower()
    return any(
        phrase in lowered
        for phrase in [
            "delayed", "overdue", "at risk", "risk", "stalled", "which students",
            "attention", "bottleneck", "escalate", "behind",
        ]
    )


def _assistant_intent(question: str) -> str:
    lowered = " ".join((question or "").lower().split())
    if (
        any(term in lowered for term in ["how many", "number of", "count"])
        and any(term in lowered for term in ["graduate", "graduation"])
        and any(term in lowered for term in ["next semester", "next term", "would", "could", "eligible", "ideally"])
    ):
        return "graduation_forecast"
    if (
        "earliest" in lowered
        and any(term in lowered for term in ["entry", "enrolled", "academic record", "student record"])
    ) or any(phrase in lowered for phrase in ["oldest student", "earliest student", "longest enrolled"]):
        return "earliest_academic_entry"
    if any(
        phrase in lowered
        for phrase in [
            "preventing this student", "prevent this student", "blocking this student",
            "holding this student back", "why is this student stuck",
            "why can't this student progress", "why cannot this student progress",
            "not progressing", "cannot advance", "can't advance", "move forward",
            "progress blockers",
        ]
    ):
        return "student_progress_blockers"
    if (
        any(term in lowered for term in ["graduate", "graduation", "finish the program", "complete the program"])
        and any(term in lowered for term in ["when", "date", "how long", "expected", "estimate", "ready"])
    ):
        return "student_graduation"
    if (
        any(term in lowered for term in ["course audit", "coursework", "subject", "subjects", "proposal development"])
        and any(term in lowered for term in ["eligible", "clear", "cleared", "move", "ready", "proposal development"])
    ):
        return "coursework_eligibility"
    if _assistant_asks_portfolio(question):
        return "student_attention"
    if any(term in lowered for term in ["status", "pending", "where", "next", "owner", "summary", "doing", "standing"]):
        return "student_status"
    if any(
        term in lowered
        for term in [
            "loa", "leave", "residency", "readmission", "eligible", "require",
            "requirement", "form", "ethics", "panel", "schedule", "completion",
            "graduat", "withdraw", "practicum", "policy", "rule", "handbook", "manual",
        ]
    ):
        return "policy"
    return "unknown"


def _classify_assistant_intent_with_gemini(question: str, has_student: bool) -> str | None:
    """Use Gemini only to classify an ambiguous question, never to query records."""
    allowed = {
        "earliest_academic_entry", "graduation_forecast", "student_progress_blockers",
        "student_graduation", "coursework_eligibility", "student_attention",
        "student_status", "policy", "unknown",
    }
    prompt = (
        "Classify this Graduate School assistant question into exactly one label and return only the label:\n"
        + "\n".join(sorted(allowed))
        + f"\nA student record is {'selected' if has_student else 'not selected'}."
        + f"\nQuestion: {question}"
    )
    try:
        label = _gemini_generate(prompt).strip().lower()
    except Exception:
        return None
    return label if label in allowed else None


def _progress_blocker_report(student: Student, payload: dict) -> dict:
    indicators = payload["indicators"]
    audit = compute_course_audit(student)
    exam = comprehensive_exam_eligibility(student)
    findings: list[dict] = []

    def add_finding(code: str, title: str, detail: str, action: str, owner: str, severity: str = "medium") -> None:
        if any(item["code"] == code for item in findings):
            return
        findings.append({
            "code": code, "title": title, "detail": detail, "action": action,
            "owner": owner, "severity": severity,
        })

    if student.standing != "Active":
        add_finding(
            "standing", f"Standing is {student.standing}",
            "The student is not currently recorded with Active standing.",
            "Resolve the standing workflow before advancing the academic stage.",
            "GS Staff", "high",
        )
    if indicators["missing_subjects"] > 0:
        add_finding(
            "coursework", "Coursework is incomplete",
            f"{indicators['missing_subjects']} required subject(s) are missing or incomplete.",
            "Resolve the course audit with the Academic Coordinator.",
            "Academic Coordinator", "high",
        )
    elif student.current_stage in {"Admission", "Coursework", "Comprehensive Exam"}:
        if not exam["eligible"]:
            add_finding(
                "exam_eligibility", "Comprehensive Exam eligibility is not cleared",
                (
                    f"{exam['completed_units']} of {exam['required_units']} qualifying units are recorded; "
                    f"{exam['missing_subjects']} subject(s) remain."
                ),
                "Verify the comprehensive-exam eligibility audit.",
                "Academic Coordinator", "high",
            )
        elif not exam["passed"]:
            add_finding(
                "comprehensive_exam", f"Comprehensive Exam is {exam['exam_status']}",
                "Coursework is complete, but a passing Comprehensive Exam result is required before research progression.",
                "Complete or record the authorized Comprehensive Exam result.",
                "Academic Coordinator",
                "high" if str(exam["exam_status"]).lower() == "failed" else "medium",
            )
        else:
            add_finding(
                "stage_handoff", "Academic stage has not advanced",
                (
                    f"Coursework and the Comprehensive Exam are cleared, but the record remains at "
                    f"{student.current_stage}."
                ),
                "Verify the authorized handoff to Proposal Development.",
                "Academic Coordinator", "medium",
            )

    for recommendation in payload["recommendations"]:
        if recommendation["code"] == "coursework":
            continue
        add_finding(
            recommendation["code"], recommendation["trigger"], recommendation["trigger"],
            recommendation["recommendation"], recommendation["owner"], recommendation["severity"],
        )

    return {
        "type": "grounded_record",
        "heading": "Progress review",
        "summary": (
            f"{len(findings)} recorded blocker(s) need attention."
            if findings else "No recorded blocker was found in the available workflow data."
        ),
        "facts": [
            {"label": "Stage", "value": student.current_stage},
            {"label": "Standing", "value": student.standing},
            {"label": "Coursework", "value": f"{audit['completion_rate']}% complete"},
            {"label": "Comprehensive Exam", "value": exam["exam_status"]},
        ],
        "findings": findings,
    }


def _graduation_report(student: Student) -> dict:
    eligibility = graduation_eligibility(student)
    endorsement = latest_graduation_endorsement(student.id)
    findings: list[dict] = []
    for item in eligibility["checklist"]:
        if item["passed"] is True:
            continue
        findings.append({
            "code": item["key"],
            "title": item["label"],
            "detail": f"Required: {item['required']}. Recorded: {item['actual']}.",
            "action": item.get("note") or eligibility["next_action"],
            "owner": eligibility["next_owner"],
            "severity": "medium" if item["passed"] is None else "high",
        })
    if not findings and not eligibility["eligible"]:
        findings.append({
            "code": "graduation_review",
            "title": "Graduation readiness is not cleared",
            "detail": "The available graduation checks are not all complete.",
            "action": eligibility["next_action"],
            "owner": eligibility["next_owner"],
            "severity": "medium",
        })
    batch_name = endorsement.batch_name if endorsement and endorsement.batch_name else "Not assigned"
    return {
        "type": "grounded_record",
        "heading": "Graduation readiness",
        "summary": (
            "The database does not store an exact graduation or ceremony date. "
            f"The student is currently {eligibility['status'].lower()} for graduation endorsement."
        ),
        "facts": [
            {"label": "Readiness", "value": eligibility["status"]},
            {"label": "Coursework", "value": eligibility["coursework_status"]},
            {"label": "Research", "value": eligibility["research_status"]},
            {"label": "Practicum", "value": eligibility["practicum_status"]},
            {"label": "Graduation batch", "value": batch_name},
        ],
        "findings": findings,
        "next_action": eligibility["next_action"],
        "next_owner": eligibility["next_owner"],
        "exact_date_known": False,
    }


def _graduation_forecast_report() -> dict:
    active_term = get_active_term()
    next_term = None
    if active_term:
        next_term = (
            AcademicTerm.query
            .filter(AcademicTerm.start_date > active_term.start_date)
            .order_by(AcademicTerm.start_date.asc())
            .first()
        )
    if not next_term:
        next_term = (
            AcademicTerm.query
            .filter(AcademicTerm.start_date > date.today())
            .order_by(AcademicTerm.start_date.asc())
            .first()
        )
    students = (
        Student.query
        .filter(Student.standing == "Active", Student.current_stage != "Completed")
        .order_by(Student.last_name.asc(), Student.first_name.asc())
        .all()
    )
    eligible_students = []
    needs_verification_students = []
    blocked_students = []
    requirement_counts: Counter = Counter()
    requirement_owners: dict[str, Counter] = {}
    for student in students:
        eligibility = graduation_eligibility(student)
        if eligibility["eligible"]:
            eligible_students.append(student)
            continue
        for item in eligibility["checklist"]:
            if item["passed"] is not True:
                requirement_counts[item["label"]] += 1
                requirement_owners.setdefault(item["label"], Counter())[eligibility["next_owner"]] += 1
        if eligibility["needs_verification"]:
            needs_verification_students.append(student)
        else:
            blocked_students.append(student)

    term_label = next_term.label if next_term else "the next configured semester"
    findings = [
        {
            "code": re.sub(r"[^a-z0-9]+", "_", label.lower()).strip("_"),
            "title": label,
            "detail": f"{count} assessed student(s) do not yet have this requirement verified as complete.",
            "action": "Resolve or verify this requirement before graduation endorsement.",
            "owner": (
                requirement_owners[label].most_common(1)[0][0]
                if requirement_owners.get(label) else "Graduate School Staff"
            ),
            "severity": "high" if count >= max(1, len(students) // 2) else "medium",
        }
        for label, count in requirement_counts.most_common(5)
    ]
    return {
        "type": "grounded_record",
        "heading": "Next-semester graduation forecast",
        "summary": (
            f"{len(eligible_students)} of {len(students)} active, not-yet-completed student(s) "
            f"currently pass every graduation eligibility check and are the ideal candidates for {term_label}. "
            "This is a readiness forecast from current records, not a guaranteed graduation date."
        ),
        "facts": [
            {"label": "Target semester", "value": term_label},
            {"label": "Students assessed", "value": str(len(students))},
            {"label": "Eligible now", "value": str(len(eligible_students))},
            {"label": "Needs verification", "value": str(len(needs_verification_students))},
            {"label": "Blocked", "value": str(len(blocked_students))},
        ],
        "findings": findings,
        "eligible_student_ids": [student.id for student in eligible_students],
        "eligible_student_names": [student.name for student in eligible_students],
        "assumption": (
            "Counts active students who are not already completed and who currently pass coursework, "
            "research, practicum, and completion-evidence checks."
        ),
    }


def _earliest_academic_entry_report() -> dict:
    earliest = (
        Student.query
        .order_by(Student.entry_year.asc(), Student.created_at.asc(), Student.id.asc())
        .first()
    )
    if not earliest:
        return {
            "type": "grounded_record", "heading": "Earliest academic entry",
            "summary": "There are no student records available.", "facts": [], "findings": [],
        }
    return {
        "type": "grounded_record",
        "heading": "Earliest academic entry",
        "summary": (
            "Student birth dates are not stored, so this does not identify the oldest person by age. "
            f"The earliest academic entry on record is {earliest.name}, with entry year {earliest.entry_year}."
        ),
        "facts": [
            {"label": "Student", "value": earliest.name},
            {"label": "Student number", "value": earliest.student_number},
            {"label": "Program", "value": earliest.program.code},
            {"label": "Entry year", "value": str(earliest.entry_year)},
            {"label": "Academic year entry", "value": earliest.academic_year_entry or "Not recorded"},
        ],
        "findings": [],
        "student": student_brief(earliest),
    }


def _grounded_report_text(report: dict) -> str:
    lines = [report["summary"]]
    if report.get("facts"):
        lines.extend(["", *[f"{item['label']}: {item['value']}" for item in report["facts"]]])
    if report.get("findings"):
        lines.extend(["", "Recorded blockers or requirements:"])
        for index, item in enumerate(report["findings"], start=1):
            lines.append(f"{index}. {item['title']}: {item['detail']}")
            lines.append(f"   Next action: {item['action']} [{item['owner']}]")
    elif report.get("next_action"):
        lines.extend(["", f"Next action: {report['next_action']} [{report['next_owner']}]"])
    return "\n".join(lines)


def _database_report_for_intent(intent: str, student: Student | None, payload: dict | None) -> dict | None:
    if intent == "earliest_academic_entry":
        return _earliest_academic_entry_report()
    if intent == "graduation_forecast":
        return _graduation_forecast_report()
    if intent in {"student_progress_blockers", "student_graduation"} and not student:
        return {
            "type": "grounded_record", "heading": "Select a student",
            "summary": "Select a student record before asking this question.",
            "facts": [], "findings": [],
        }
    if intent == "student_progress_blockers" and student and payload:
        return _progress_blocker_report(student, payload)
    if intent == "student_graduation" and student:
        return _graduation_report(student)
    return None


def _assistant_source(mode: str, intent_ai_used: bool = False) -> dict:
    sources = {
        "database-rules": (
            "Live record · Verified rules",
            "Calculated from authorized database records and deterministic workflow rules.", False,
        ),
        "policy-retrieval": (
            "Policy library · Keyword retrieval",
            "Retrieved from the curated local policy library without AI generation.", False,
        ),
        "document-rag": (
            "Policy documents · Gemini",
            "Generated by Gemini from retrieved policy document excerpts (handbook, protocol, uploads).", True,
        ),
        "document-rag-cache": (
            "Policy documents · Gemini (cached)",
            "Previously generated by Gemini from retrieved policy document excerpts.", True,
        ),
        "document-rag-local": (
            "Policy documents · Local retrieval",
            "Extracted directly from matching policy document passages without AI generation.", False,
        ),
        "role-guarded": (
            "Policy library · Role limits",
            "This role can ask policy questions; student records are not available in this chat.", False,
        ),
        "offline-fallback": (
            "Policy fallback · Verified rules",
            "The AI provider was unavailable, so deterministic local guidance was used.", False,
        ),
        "validation": (
            "Safety guidance",
            "A local safety rule handled this request; no AI or record change was used.", False,
        ),
    }
    label, detail, ai_used = sources.get(
        mode, ("Local assistant", "Answered by the local advisory assistant.", False)
    )
    if intent_ai_used and mode == "database-rules":
        label = "Live record · Gemini interpreted"
        detail = "Gemini classified the question only; verified database rules produced the answer."
        ai_used = True
    return {"label": label, "detail": detail, "ai_used": ai_used}


def _attention_report(portfolio: dict, display_limit: int = 5) -> dict:
    summary = portfolio.get("summary", {})
    severity_counts = {
        item["severity"]: item["count"] for item in summary.get("by_severity", [])
    }
    grouped: dict[int, dict] = {}
    for item in portfolio.get("items", []):
        student_id = item["student_id"]
        if student_id not in grouped:
            grouped[student_id] = {
                "id": student_id, "name": item["student_name"],
                "student_number": item["student_number"], "program_code": item["program_code"],
                "stage": item["stage"], "severity": item["severity"], "issues": [],
            }
        grouped[student_id]["issues"].append({
            "severity": item["severity"], "trigger": item["trigger"],
            "recommendation": item["recommendation"], "owner": item["owner"],
        })
    students = list(grouped.values())[:display_limit]
    return {
        "type": "student_attention",
        "summary": {
            "students": summary.get("students_flagged", len(grouped)),
            "follow_ups": summary.get("total", 0),
            "high": severity_counts.get("high", 0),
            "medium": severity_counts.get("medium", 0),
            "low": severity_counts.get("low", 0),
        },
        "shown_students": len(students),
        "students": students,
    }


def _attention_report_text(report: dict) -> str:
    summary = report["summary"]
    severity_parts = [
        f"{summary[level]} {level}" for level in ("high", "medium", "low") if summary[level]
    ]
    lines = [
        (
            f"{summary['students']} students currently need attention across "
            f"{summary['follow_ups']} follow-up item(s) ({', '.join(severity_parts)})."
        ),
        "",
        f"Top {report['shown_students']} priority student(s):",
    ]
    for index, student in enumerate(report["students"], start=1):
        lines.append(f"{index}. {student['name']} ({student['program_code']} - {student['stage']})")
        for issue in student["issues"]:
            lines.extend([
                f"   Issue: {issue['trigger']}",
                f"   Action: {issue['recommendation']}",
                f"   Owner: {issue['owner']}",
            ])
    return "\n".join(lines)


def local_grounded_answer(
    question: str,
    student: Student | None,
    payload: dict | None,
    snippets: list[dict],
    attention_portfolio: dict | None = None,
    database_report: dict | None = None,
) -> str:
    """Offline, deterministic responder. Grounds answers in computed indicators + retrieved policy.
    Stands in for Google AI Studio so the feature is demonstrable without an API key."""
    q = (question or "").lower()
    out: list[str] = []
    ind = payload["indicators"] if payload else None
    recs = payload["recommendations"] if payload else []
    intent = _assistant_intent(question)
    database_report = database_report or _database_report_for_intent(intent, student, payload)

    if database_report:
        return _grounded_report_text(database_report)

    asks_status = any(w in q for w in ["status", "pending", "where", "next", "owner", "summary", "doing", "standing"])
    asks_policy = any(w in q for w in ["loa", "leave", "residency", "readmission", "eligible", "require", "requirement",
                                       "form", "ethics", "panel", "schedule", "completion", "graduat", "withdraw", "practicum", "policy", "rule"])
    asks_coursework_eligibility = student and any(
        w in q for w in ["course audit", "coursework", "subject", "subjects", "proposal development"]
    ) and any(w in q for w in ["eligible", "clear", "cleared", "move", "ready", "proposal development"])
    asks_portfolio = _assistant_asks_portfolio(question)
    asks_oldest_record = (
        any(phrase in q for phrase in ["oldest student", "earliest student", "longest enrolled"])
        and any(word in q for word in ["record", "student", "enrolled"])
    )

    if asks_oldest_record:
        earliest = (
            Student.query
            .order_by(Student.entry_year.asc(), Student.created_at.asc(), Student.id.asc())
            .first()
        )
        if earliest:
            out.append(
                "Student birth dates are not stored, so I cannot determine who is oldest by age. "
                f"The earliest academic entry on record is {earliest.name} "
                f"({earliest.student_number}, {earliest.program.code}), with entry year {earliest.entry_year}."
            )
        else:
            out.append("There are no student records available.")

    elif asks_coursework_eligibility:
        out.append(_status_sentence(student, ind))
        if ind["missing_subjects"] == 0:
            out.append(
                "Course-audit eligibility: cleared. All required subjects are marked completed, so the backend rule "
                "can advance an Admission or Coursework student to Proposal Development."
            )
        else:
            out.append(
                f"Course-audit eligibility: not cleared yet. {ind['missing_subjects']} required subject(s) are "
                "missing or incomplete, so the Academic Coordinator should resolve the audit before proposal development."
            )
        if recs:
            out.append("Recommended next step: " + recs[0]["recommendation"] + f" ({recs[0]['owner']}).")

    elif student and (asks_status or (not asks_policy and not asks_portfolio)):
        out.append(_status_sentence(student, ind))
        if ind["overdue_tasks"]:
            out.append(f"There {'is' if ind['overdue_tasks'] == 1 else 'are'} {ind['overdue_tasks']} overdue task(s).")
        if ind["missing_documents"] and ind["research_gate"]:
            out.append(f"{ind['missing_documents']} required document(s) are still missing at {ind['research_gate']}.")
        out.append(f"The next action is owned by {ind['next_owner'] or 'GS Staff'}.")
        if recs:
            out.append("Recommended next steps: " + "; ".join(f"{r['recommendation']} ({r['owner']})" for r in recs[:3]))
        else:
            out.append("No outstanding follow-ups are flagged for this student.")

    elif asks_portfolio:
        port = attention_portfolio or portfolio_recommendations()
        out.append(_attention_report_text(_attention_report(port)))

    else:
        if snippets:
            top = snippets[0]
            out.append(f"{top['title']}: {top['text']}")
        if student and ind:
            out.append("For this student — " + _status_sentence(student, ind))
            if recs:
                out.append("Suggested action: " + recs[0]["recommendation"] + f" ({recs[0]['owner']}).")
        if not snippets and not student:
            out.append("I could not find a matching policy. Try mentioning a stage, form, or topic "
                       "(e.g. LOA, Form 4, panel, ethics, completion).")

    return " ".join(out).strip()


def call_google_ai_studio(question: str, snippets: list[dict], payload: dict | None, api_key: str) -> str:
    """Real provider integration point (Google AI Studio / Gemini).

    Intentionally a thin stub: in the demo no key is set, so this is never called.
    When GOOGLE_AI_STUDIO_API_KEY is provided, build the grounded prompt from
    `snippets` + `payload` and POST to the AI Studio endpoint here, then return the text.
    """
    raise NotImplementedError("Google AI Studio not connected in this build.")


def assistant_validation_message(question: str) -> str | None:
    normalized = (question or "").strip()
    if len(normalized) > ASSISTANT_MAX_QUESTION_LENGTH:
        return (
            f"That message is too long for the Policy Assistant. Please shorten it to "
            f"{ASSISTANT_MAX_QUESTION_LENGTH} characters or fewer and ask one question at a time."
        )
    if any(ord(character) < 32 and character not in "\n\r\t" for character in normalized):
        return "I could not safely read that message. Please remove control characters and try again."
    unsupported_patterns = [
        r"\b(?:drop|truncate|delete|erase)\s+(?:the\s+)?(?:database|table|records?|students?)\b",
        r"\b(?:insert|alter|update)\s+(?:the\s+)?(?:database|table)\b",
        r"\b(?:run|execute)\s+(?:this\s+)?(?:sql|shell|command|script|code)\b",
        r"\b(?:ignore|bypass|override)\s+(?:all\s+)?(?:previous\s+)?(?:instructions?|permissions?|security)\b",
        r"\b(?:show|reveal|print|give me)\b.{0,50}\b(?:api key|password|secret|system prompt|environment variables?)\b",
    ]
    if any(re.search(pattern, normalized, flags=re.IGNORECASE) for pattern in unsupported_patterns):
        return (
            "I can explain Graduate School policy and summarize authorized read-only records, "
            "but I cannot execute commands, change or delete database records, bypass permissions, "
            "or reveal protected system information."
        )
    if re.search(
        r"\b(?:query the database|database query|select \* from|consolidate all students)\b",
        normalized,
        flags=re.IGNORECASE,
    ):
        return (
            "The Policy Assistant cannot run arbitrary database queries. Use an approved read-only "
            "report or filter in the relevant workspace; database changes require an authorized workflow."
        )
    return None


def assistant_validation_response(
    message: str,
    student: Student | None = None,
    payload: dict | None = None,
) -> dict:
    return {
        "answer": message,
        "mode": "validation",
        "source": _assistant_source("validation"),
        "citations": [],
        "grounded": payload["indicators"] if payload else None,
        "recommendations": payload["recommendations"] if payload else [],
        "student": student_brief(student) if student else None,
    }


ASSISTANT_DATABASE_INTENTS = {
    "earliest_academic_entry", "graduation_forecast", "student_progress_blockers",
    "student_graduation", "coursework_eligibility", "student_attention", "student_status",
}
ASSISTANT_STUDENT_BOUND_INTENTS = {
    "student_progress_blockers", "student_graduation", "coursework_eligibility", "student_status",
}
ASSISTANT_POLICY_DOMAIN_TERMS = [
    "research", "adviser", "advisor", "thesis", "dissertation",
    "subject", "course", "class", "grade", "exam", "retake", "repeat",
    "form", "defense", "panel", "ethics", "residency", "leave of absence",
    "loa", "readmission", "withdrawal", "graduation", "completion",
]


def _policy_library_has_relevant_passage(question: str) -> bool:
    try:
        chunks = _load_rag_document_index()
        return any(
            chunk.get("_relevant")
            for chunk in _retrieve_rag_document_chunks_lexically(question, chunks, 3)
        )
    except Exception:  # noqa: BLE001
        return False


def assistant_requires_document_rag(
    question: str,
    student: Student | None,
    snippets: list[dict],
    intent: str | None = None,
) -> bool:
    """The document library is the primary source for every policy question.

    Curated snippets never answer first: a policy question goes to the complete
    library (built-in documents plus staff uploads) and the snippets are only a
    fallback when no passage is relevant. Questions about a live student
    record, or about the portfolio, are answered from the database instead.
    """
    lowered = " ".join((question or "").lower().split())
    intent = intent or _assistant_intent(question)
    if intent in ASSISTANT_DATABASE_INTENTS:
        return False
    if intent == "policy":
        return True
    # "unknown" intent: a question that uses policy vocabulary or matches the
    # library is still a policy question (an uploaded rule may use any words).
    if any(term in lowered for term in ASSISTANT_POLICY_DOMAIN_TERMS):
        return True
    return _policy_library_has_relevant_passage(question)


def student_requires_document_rag(
    question: str,
    student: Student,
    snippets: list[dict],
) -> bool:
    """Route student policy questions to the uploaded document library."""
    if assistant_requires_document_rag(question, student, snippets):
        return True
    lowered = " ".join((question or "").lower().split())
    own_record_phrases = [
        "my record", "my status", "my progress", "my standing", "my next step",
        "what should i do next", "where am i", "what is pending for me",
        "am i eligible", "am i ready", "my requirements", "my documents",
    ]
    return not any(phrase in lowered for phrase in own_record_phrases) and not _student_asks_current_enrollment(question)


def _student_asks_current_enrollment(question: str) -> bool:
    lowered = " ".join((question or "").lower().split())
    return any(
        phrase in lowered
        for phrase in [
            "currently enrolled", "am i enrolled", "my enrolled subjects",
            "my current subjects", "subjects i am taking", "courses i am taking",
        ]
    )


def _student_enrollment_answer(student: Student) -> str:
    snapshot = student_enrollment_snapshot(student)
    term = snapshot.get("term") or {}
    active = [
        item for item in snapshot.get("enrollments", [])
        if item.get("term_id") == term.get("id")
        and item.get("status") in ACTIVE_SUBJECT_ENROLLMENT_STATUSES
    ]
    if not term:
        return "There is no active academic term configured, so I cannot verify current enrollment."
    if not active:
        return f"Your record shows no active subject enrollments for {term.get('label', 'the current term')}."
    subjects = "; ".join(
        f"{item.get('course_code')} — {item.get('course_title')} ({item.get('course_units')} units)"
        for item in active
    )
    return f"Your active subjects for {term.get('label', 'the current term')} are: {subjects}."


def _student_policy_fallback(snippets: list[dict]) -> str:
    if snippets:
        return f"{snippets[0]['title']}: {snippets[0]['text']}"
    return (
        "I could not find a sufficiently relevant rule in the uploaded policy documents. "
        "Please name the process, form, subject, examination, or defense type you mean."
    )


def _rag_cache_get(key: tuple) -> tuple[str, list[dict]] | None:
    with _RAG_RESPONSE_CACHE_LOCK:
        value = _RAG_RESPONSE_CACHE.get(key)
        if value is not None:
            _RAG_RESPONSE_CACHE.move_to_end(key)
        return value


def _rag_cache_set(key: tuple, value: tuple[str, list[dict]]) -> None:
    with _RAG_RESPONSE_CACHE_LOCK:
        _RAG_RESPONSE_CACHE[key] = value
        _RAG_RESPONSE_CACHE.move_to_end(key)
        while len(_RAG_RESPONSE_CACHE) > max(1, int(os.getenv("RAG_RESPONSE_CACHE_SIZE", "128"))):
            _RAG_RESPONSE_CACHE.popitem(last=False)


def assistant_role_guarded_response(role: str) -> dict:
    label = ROLE_LABELS.get(role, "your role")
    return {
        "answer": (
            f"As {label} you can ask me about Graduate School policy, procedures, forms, and deadlines, and I "
            "answer from the policy document library with the source shown. Student records, rosters, and "
            "monitoring lists are not available in this chat; use the screens in your own portal for those."
        ),
        "structured": None,
        "mode": "role-guarded",
        "source": _assistant_source("validation"),
        "citations": [],
        "grounded": None,
        "recommendations": [],
        "student": None,
        "scope": "policy-only",
        "read_only": True,
    }


def generate_answer(question: str, student_id: int | None = None, policy_only: bool = False, role: str = "") -> dict:
    # Policy-only callers (Dean, coordinators, faculty) never get student data.
    student = Student.query.get(student_id) if student_id and not policy_only else None
    payload = student_recommendations(student) if student else None
    validation_message = assistant_validation_message(question)
    if validation_message:
        return assistant_validation_response(validation_message, student, payload)
    # The assistant is advisory only: it retrieves policy passages and explains
    # backend-computed facts. It never changes records or approves decisions.
    api_key = os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_AI_STUDIO_API_KEY")
    intent = _assistant_intent(question)
    intent_ai_used = False
    if intent == "unknown" and not assistant_requires_document_rag(question, student, [], intent) and api_key:
        classified_intent = _classify_assistant_intent_with_gemini(question, bool(student))
        if classified_intent and classified_intent != "unknown":
            intent = classified_intent
            intent_ai_used = True

    if not student and intent in ASSISTANT_STUDENT_BOUND_INTENTS:
        # "What grade keeps a master's student in good standing?" names no student:
        # it is a policy question, not a request for a record.
        intent = "unknown"
    database_intents = ASSISTANT_DATABASE_INTENTS
    if policy_only and intent in database_intents:
        return assistant_role_guarded_response(role)
    snippets = retrieve_policy(question, k=3) if intent in {"policy", "unknown"} else []
    mode = "database-rules" if intent in database_intents else "policy-retrieval"
    rag_citations = []
    attention_portfolio = portfolio_recommendations() if intent == "student_attention" else None
    database_report = _database_report_for_intent(intent, student, payload)
    if assistant_requires_document_rag(question, student, snippets, intent):
        try:
            if not api_key:
                raise RuntimeError("Gemini is not configured.")
            cache_key = ("general-policy", " ".join(question.lower().split()))
            cached = _rag_cache_get(cache_key) if not student else None
            if cached:
                answer, rag_citations = cached
                mode = "document-rag-cache"
            else:
                answer, rag_citations = call_document_rag(question, snippets, payload, student)
                mode = "document-rag"
                if not student:
                    _rag_cache_set(cache_key, (answer, rag_citations))
        except Exception:
            try:
                answer, rag_citations = call_local_document_rag(question)
                mode = "document-rag-local"
            except PolicyPassageNotFound:
                # No passage in the library is relevant: only now do the curated snippets answer.
                answer = local_grounded_answer(
                    question, student, payload, snippets, attention_portfolio, database_report
                )
                mode = "policy-retrieval"
            except Exception:
                answer = local_grounded_answer(
                    question, student, payload, snippets, attention_portfolio, database_report
                )
                mode = "offline-fallback"
    else:
        answer = local_grounded_answer(
            question, student, payload, snippets, attention_portfolio, database_report
        )

    policy_citations = [{"id": s["id"], "title": s["title"], "source": s["source"], "text": s["text"]} for s in snippets]
    structured = None
    if mode not in {"document-rag", "document-rag-cache", "document-rag-local"}:
        structured = database_report or (
            _attention_report(attention_portfolio) if attention_portfolio else None
        )
    return {
        "answer": answer,
        "structured": structured,
        "mode": mode,
        "source": _assistant_source(mode, intent_ai_used),
        "citations": rag_citations or (
            policy_citations if mode != "database-rules" else []
        ),
        "grounded": payload["indicators"] if payload else None,
        "recommendations": payload["recommendations"] if payload else [],
        "student": student_brief(student) if student else None,
    }


def generate_student_answer(question: str, student: Student) -> dict:
    """Handbook and own-record assistant with no staff or cross-student access."""
    validation_message = assistant_validation_message(question)
    if validation_message:
        payload = student_recommendations(student)
        response = assistant_validation_response(validation_message, student, payload)
        response.update({"mode": "student-guarded", "scope": "own-record-only", "read_only": True})
        return response
    lowered = (question or "").lower()
    restricted_terms = {
        "which students", "other student", "other students", "another student",
        "another student's", "someone else's", "classmate", "all students",
        "student roster", "class list", "faculty load", "faculty workload",
        "faculty assignment", "faculty ranking", "faculty email",
        "dean queue", "approval queue", "decision queue", "staff notes",
        "internal notes", "audit log", "transaction log", "admin records",
        "database", "course adjustment rationale",
    }
    if any(term in lowered for term in restricted_terms):
        return {
            "answer": (
                "I can help with the Graduate School handbook, student procedures, and your own record. "
                "I cannot access other students, staff-only notes, faculty selection data, or approval queues."
            ),
            "mode": "student-guarded",
            "citations": [],
            "grounded": student_indicators(student),
            "recommendations": student_portal_recommendations(student),
            "student": student_brief(student),
            "scope": "own-record-only",
            "read_only": True,
        }
    record_change_patterns = [
        r"\b(?:approve|reject)\s+(?:my|this)\s+(?:application|request|loa|readmission|withdrawal)\b",
        r"\b(?:change|edit|update|raise|replace)\s+my\s+(?:grade|status|standing|record)\b",
        r"\b(?:mark|tag)\s+me\s+(?:as\s+)?(?:enrolled|completed|passed|graduated)\b",
        r"\b(?:drop|remove|withdraw)\s+me\s+(?:from\s+)?(?:this\s+)?(?:subject|class|course)\b",
    ]
    if any(re.search(pattern, question, flags=re.IGNORECASE) for pattern in record_change_patterns):
        return {
            "answer": (
                "I can explain the applicable process and show your own recorded status, but I cannot "
                "change grades, enrollment, standing, or approval decisions. Please use the appropriate "
                "student request form or contact the Graduate School or Academic Coordinator."
            ),
            "mode": "student-guarded",
            "citations": [],
            "grounded": student_indicators(student),
            "recommendations": student_portal_recommendations(student),
            "student": student_brief(student),
            "scope": "own-record-only",
            "read_only": True,
        }
    payload = student_recommendations(student)
    snippets = retrieve_policy(question, k=3)
    api_key = os.getenv("GOOGLE_API_KEY") or os.getenv("GOOGLE_AI_STUDIO_API_KEY")
    mode = "student-fast"
    rag_citations = []
    if _student_asks_current_enrollment(question):
        answer = _student_enrollment_answer(student)
        mode = "student-records"
    elif student_requires_document_rag(question, student, snippets):
        try:
            if not api_key:
                raise RuntimeError("Gemini is not configured.")
            answer, rag_citations = call_document_rag(
                question,
                snippets,
                payload,
                student,
            )
            mode = "student-document-rag"
        except Exception:
            try:
                answer, rag_citations = call_local_document_rag(question)
                mode = "student-document-rag-local"
            except Exception:
                answer = _student_policy_fallback(snippets)
                mode = "student-policy-fallback"
    else:
        answer = local_grounded_answer(question, student, payload, snippets)
    return {
        "answer": answer,
        "mode": mode,
        "citations": rag_citations or (
            [
                {"id": item["id"], "title": item["title"], "source": item["source"], "text": item["text"]}
                for item in snippets
            ]
            if mode == "student-policy-fallback"
            else []
        ),
        "grounded": {**payload["indicators"], "progress_status": student_priority(student)},
        "recommendations": student_portal_recommendations(student),
        "student": student_brief(student),
        "scope": "own-record-only",
        "read_only": True,
    }


# ---------------------------------------------------------------------------
# Routes (JSON API + SPA hosting)
# ---------------------------------------------------------------------------
def register_routes(app: Flask) -> None:
    # Lightweight smoke-check endpoint for setup/demo verification.
    @app.route("/api/health")
    def health():
        return jsonify({"status": "ok", "students": Student.query.count()})

    def demo_mode_off_response():
        return jsonify({"error": "Not found."}), 404

    def no_store(response):
        response.headers["Cache-Control"] = "no-store"
        return response

    @app.route("/api/auth/config")
    def auth_config():
        """Tell the sign-in page whether to offer the demo panel. Public, no secrets."""
        return no_store(jsonify({"demo_mode": demo_mode_enabled()}))

    @app.route("/api/auth/demo-accounts")
    def auth_demo_accounts():
        """Ready-made staff/faculty/dean/student logins for the presenter's
        expandable "Demo accounts" panel. Demo mode only; an account whose
        password has been changed is never listed."""
        if not demo_mode_enabled():
            return demo_mode_off_response()
        return no_store(jsonify({"items": demo_accounts_payload()}))

    @app.route("/api/auth/demo-students")
    def auth_demo_students():
        """Expose only the purpose-built quick-login demo identities (demo mode only)."""
        if not demo_mode_enabled():
            return demo_mode_off_response()
        return no_store(jsonify({"items": workflow_demo_students_payload()}))

    @app.route("/api/auth/demo-students/<demo_key>/reset", methods=["POST"])
    def auth_demo_student_reset(demo_key: str):
        """Reset a whitelisted demo student before authentication (demo mode only)."""
        if not demo_mode_enabled():
            return demo_mode_off_response()
        config = WORKFLOW_DEMO_STUDENTS.get(demo_key)
        if not config:
            return jsonify({"error": "Demo student not found."}), 404
        student = Student.query.filter_by(student_number=config["student_number"]).first()
        if not student:
            return jsonify({"error": "Demo student is not available. Reseed the demo database."}), 404
        try:
            result = reset_workflow_demo_case(config["workflow"], student)
            account = ensure_student_account(student, config["email"], SIM_STUDENT_PASSWORD)
            account.password_hash = generate_password_hash(SIM_STUDENT_PASSWORD)
            db.session.commit()
        except Exception as exc:  # noqa: BLE001
            db.session.rollback()
            return jsonify({"error": str(exc)}), 400
        for stored_name in result.pop("stored_names"):
            (REQUEST_UPLOAD_ROOT / stored_name).unlink(missing_ok=True)
        for stored_name in result.pop("research_stored_names", []):
            (UPLOAD_ROOT / stored_name).unlink(missing_ok=True)
        workflow_title = config.get("title") or config["workflow"].title()
        return jsonify({
            "ok": True,
            **result,
            "item": next(
                (item for item in workflow_demo_students_payload() if item["key"] == demo_key),
                None,
            ),
            "message": (
                f"Reset {student.name}'s {workflow_title} demo. "
                "All prerequisite stages are complete and the student is ready to begin again."
            ),
        })

    @app.route("/api/auth/me")
    def auth_me():
        account = current_account()
        return no_store(jsonify({"user": account_dict(account) if account else None}))

    @app.route("/api/auth/login", methods=["POST"])
    def auth_login():
        body = request.get_json(silent=True) or {}
        email = str(body.get("email") or "").strip().lower()
        password = str(body.get("password") or "")
        # The role a user gets is the role stored on the account. A "role" field
        # sent by an older client is ignored: it can never widen or change access.
        if not email or not password:
            return no_store(jsonify({"error": "Enter your email and password."})), 400
        client_ip = request.remote_addr or ""
        wait = LOGIN_THROTTLE.retry_after(email, client_ip)
        if wait:
            response = jsonify({
                "error": f"Too many failed sign-in attempts. Try again in {max(1, (wait + 59) // 60)} minute(s).",
            })
            response.headers["Retry-After"] = str(wait)
            return no_store(response), 429
        account = UserAccount.query.filter_by(email=email, active=True).first()
        # Always verify a hash so an unknown email costs the same as a wrong password.
        password_ok = check_password_hash(
            account.password_hash if account else UNKNOWN_ACCOUNT_PASSWORD_HASH, password
        )
        if not account or not password_ok:
            LOGIN_THROTTLE.record_failure(email, client_ip)
            return no_store(jsonify({"error": "Incorrect email or password."})), 401
        LOGIN_THROTTLE.record_success(email)
        if demo_mode_enabled():
            _, demo_config = workflow_demo_config_for_student(account.student)
            if demo_config:
                try:
                    # Logging in repairs prerequisite source data but deliberately keeps
                    # the current workflow progress. The adjacent Reset button clears it.
                    ensure_workflow_demo_student_baseline(account.student, demo_config["workflow"])
                    db.session.commit()
                except Exception as exc:  # noqa: BLE001
                    db.session.rollback()
                    return jsonify({"error": f"Could not prepare the demo account: {exc}"}), 400
        try:
            # Start leaves that begin today and flag leaves that are ending (idempotent).
            sync_leave_cases(commit=True)
        except Exception:  # noqa: BLE001 - signing in must never fail because of this
            db.session.rollback()
            app.logger.exception("Leave date sweep failed at sign-in")
        session.clear()  # a fresh session on every sign-in (no session fixation)
        session["account_id"] = account.id
        session["role"] = account.role
        session["student_id"] = account.student_id
        session["sid"] = uuid4().hex
        return no_store(jsonify({"user": account_dict(account)}))

    @app.route("/api/auth/logout", methods=["POST"])
    def auth_logout():
        revoke_session_id(session.get("sid"))
        session.clear()
        return no_store(jsonify({"ok": True}))

    @app.route("/api/auth/change-password", methods=["POST"])
    def auth_change_password():
        """Let a signed-in account choose its own password. Required at first sign-in for an
        account created with a generated initial password."""
        account = current_account()
        if not account:
            return no_store(jsonify({"error": "Please sign in to continue."})), 401
        body = request.get_json(silent=True) or {}
        current_password = str(body.get("current_password") or "")
        new_password = str(body.get("new_password") or "")
        client_ip = request.remote_addr or ""
        wait = LOGIN_THROTTLE.retry_after(account.email, client_ip)
        if wait:
            return no_store(jsonify({
                "error": f"Too many failed attempts. Try again in {max(1, (wait + 59) // 60)} minute(s).",
            })), 429
        if not check_password_hash(account.password_hash, current_password):
            LOGIN_THROTTLE.record_failure(account.email, client_ip)
            return no_store(jsonify({"error": "The current password is not correct."})), 400
        if len(new_password) < 10:
            return no_store(jsonify({"error": "Choose a password of at least 10 characters."})), 400
        if new_password == current_password:
            return no_store(jsonify({"error": "Choose a password different from the current one."})), 400
        if new_password == SIM_STUDENT_PASSWORD or new_password.lower() == account.email.lower():
            return no_store(jsonify({"error": "That password is too easy to guess. Choose another."})), 400
        account.password_hash = generate_password_hash(new_password)
        account.must_change_password = False
        db.session.commit()
        LOGIN_THROTTLE.record_success(account.email)
        return no_store(jsonify({"ok": True, "user": account_dict(account)}))

    # Shared reference data used to render filters, dropdowns, and workflow cards.
