    @app.route("/api/student-portal/leave-cases/<int:case_id>/<action>", methods=["POST"])
    @require_api_login("student")
    def student_leave_case_action(case_id: int, action: str):
        """Withdraw a pending request, or cancel an approved leave that has not started."""
        account = current_account()
        case = db.session.get(LeaveCase, case_id)
        if not case or case.student_id != account.student_id:
            return jsonify({"error": "That request was not found."}), 404
        if action not in {"withdraw", "cancel"}:
            return jsonify({"error": "That action is not available to students."}), 400
        data = request.get_json(silent=True) or {}
        try:
            outcome = leave_case_apply(case, action, account, comment=(data.get("comment") or ""))
            db.session.commit()
        except LeaveError as exc:
            db.session.rollback()
            return jsonify({"error": str(exc)}), exc.status
        return jsonify({"ok": True, "message": outcome["message"], "case": leave_case_dict(case, role="student")})

    @app.route("/api/student-portal/requests/awol-return", methods=["POST"])
    @require_api_login("student")
    def student_awol_return_request():
        data = request_payload()
        account = current_account()
        student = Student.query.get_or_404(account.student_id)
        if student.enrollment_tag != "AWOL" and student.standing != "AWOL":
            return jsonify({"error": "A return-from-AWOL request can be filed only while your record is marked AWOL."}), 409
        target_return_term = (data.get("target_return_term") or "").strip()
        last_enrolled_term = (data.get("last_enrolled_term") or "").strip()
        return_intent = (data.get("return_intent") or "").strip()
        return_reason = (data.get("return_reason") or "").strip()
        target_term = AcademicTerm.query.filter_by(label=target_return_term).first()
        last_term = AcademicTerm.query.filter_by(label=last_enrolled_term).first()
        if not target_term or target_term.start_date <= date.today():
            return jsonify({"error": "Choose a valid future semester when you intend to return."}), 400
        if last_enrolled_term and not last_term:
            return jsonify({"error": "Choose a valid last enrolled semester."}), 400
        if not return_intent:
            return jsonify({"error": "Enter your written intention to resume enrollment."}), 400
        if not return_reason:
            return jsonify({"error": "Explain why you are requesting to return."}), 400
        item = latest_awol_case(student.id)
        if item and item.status not in {"AWOL Declared", "Return Denied", "Returned for Revision", "Return Submitted"}:
            return jsonify({"error": "Your current AWOL return case cannot be resubmitted at this stage."}), 409
        if not item:
            item = AwolCase(
                student_id=student.id,
                status="AWOL Declared",
                awol_effective_date=date.today(),
                last_enrolled_term=last_enrolled_term or None,
            )
            db.session.add(item)
            db.session.flush()
        review = awol_policy_review(student, {
            "workflow_action": "return_from_awol",
            "application_reference": "Structured portal return declaration",
        })
        item.status = "Return Submitted"
        item.return_requested_at = now_utc()
        item.target_return_term = target_return_term
        item.last_enrolled_term = last_enrolled_term or item.last_enrolled_term
        item.intent_attachment_id = None
        item.return_intent = return_intent
        item.return_reason = return_reason
        item.years_in_program = review["limits"]["years_in_program"]
        item.normal_residence_years = review["limits"]["normal_years"]
        item.absolute_residence_years = review["limits"]["absolute_years"]
        item.policy_classification = review["classification"]
        item.refresher_required = review["refresher_required"]
        item.full_reenrollment_required = review["full_reenrollment_required"]
        item.dean_decision = "Not Submitted"
        item.updated_at = now_utc()
        add_task(student.id, "Review structured return declaration from AWOL", "GS Staff", 3, 65)
        add_log(
            "awol", student.id, "Student", "Structured portal return declaration",
            "AWOL return declaration submitted", "GS Staff",
            (
                f"Target return semester: {target_return_term}.\n"
                f"Last enrolled semester: {last_enrolled_term or 'Not recorded'}.\n"
                f"Written intention: {return_intent}\n"
                f"Reason for return: {return_reason}\n"
                f"Policy classification: {item.policy_classification}."
            ),
            previous_status="AWOL Declared", new_status="Return Submitted",
        )
        db.session.commit()
        return jsonify({"ok": True, "message": "Submitted. Graduate School staff will review your structured return declaration and route it to the Dean."})

    @app.route("/api/student-portal/requests/practicum", methods=["POST"])
    @require_api_login("student")
    def student_practicum_request():
        data = request_payload()
        account = current_account()
        student = Student.query.get_or_404(account.student_id)
        if not program_allows_practicum(student.program):
            return jsonify({
                "error": (
                    "Practicum is available only to Psychology and Master of "
                    "Science in Guidance and Counseling (MSGC) students."
                )
            }), 403

        record = latest_practicum_record(student.id)
        eligibility = practicum_eligibility(student)
        if not record and not eligibility["eligible"]:
            return jsonify({
                "error": "Your practicum eligibility check is not complete. The MOA stage will unlock after the current requirements are verified."
            }), 409
        stage = practicum_student_submission_stage(record)
        if stage == "locked":
            return jsonify({"error": "This practicum stage is awaiting reviewer action. Your submitted information remains saved and read-only."}), 400

        previous_status = record.status if record else "Not Submitted"
        previous_certificate_attachment_id = record.certificate_attachment_id if record else None
        student_remark = (data.get("remarks") or "").strip()
        if stage == "moa":
            moa_attachment = request_attachment_from_payload(student, "practicum", data)
            if not moa_attachment:
                return jsonify({"error": "Upload the practicum MOA PDF before submitting this stage."}), 400
            practicum_site = (data.get("practicum_site") or "").strip()
            if not practicum_site:
                return jsonify({"error": "Enter the practicum site or company for the MOA stage."}), 400
            if not record:
                record = PracticumRecord(student_id=student.id)
                db.session.add(record)
            record.practicum_site = practicum_site
            record.supervisor_name = (data.get("supervisor_name") or record.supervisor_name or "").strip()
            record.required_hours = record.required_hours or practicum_required_hours()
            record.moa_attachment_id = moa_attachment.id
            record.moa_uploaded = True
            record.moa_status = "Uploaded"
            if student_remark:
                record.remarks = student_remark
            record.status = "MOA Submitted"
            record.updated_at = now_utc()
            db.session.flush()
            bind_workflow_attachment(moa_attachment, record, "MOA Submission", account)
            add_task(student.id, "Record and forward practicum MOA", "Graduate School Staff", 3, 45)
            next_owner = "Graduate School Staff"
            message = "MOA submitted. Graduate School staff will record and forward it to the Academic Coordinator."
        else:
            certificate_id = safe_int(data.get("certificate_attachment_id"), 0)
            certificate = StudentRequestAttachment.query.filter_by(
                id=certificate_id,
                student_id=student.id,
                request_type="practicum",
            ).first()
            if not certificate:
                return jsonify({"error": "Upload the practicum completion documents PDF before submitting this stage."}), 400
            if (
                previous_status in {"Hours Incomplete", "Additional Certificates Requested"}
                and previous_certificate_attachment_id
                and certificate.id == previous_certificate_attachment_id
            ):
                return jsonify({"error": "Upload the requested additional practicum PDF before resubmitting this stage."}), 400
            if record.certificate_attachment and record.certificate_attachment.id != certificate.id:
                bind_workflow_attachment(
                    record.certificate_attachment,
                    record,
                    "Practicum Document Submission",
                )
            record.certificate_attachment_id = certificate.id
            record.completed_hours = max(safe_int(data.get("completed_hours"), record.completed_hours or 0), 0)
            record.document_status = "Pending Review"
            if student_remark:
                record.remarks = student_remark
            record.updated_at = now_utc()
            if record.completed_hours < record.required_hours:
                record.status = "Hours Incomplete"
                message = "Documents submitted. Graduate School staff will record and forward them to the Academic Coordinator."
            else:
                record.status = "Documents Submitted"
                message = "Documents and hours submitted. Graduate School staff will record and forward them to the Academic Coordinator."
            add_task(student.id, "Record and forward practicum documents", "Graduate School Staff", 3, 45)
            next_owner = "Graduate School Staff"
            bind_workflow_attachment(certificate, record, "Practicum Document Submission", account)
            record.certificate_count = detected_practicum_certificate_count(record)

        resolve_student_returns("practicum", student.id)

        if student_remark:
            workflow_message_record(
                "practicum",
                student,
                account,
                next_owner,
                "Student submission remark",
                student_remark,
                "submission",
                previous_status,
                record.status,
                visibility="student_visible",
                status="Sent",
            )

        source_attachment = record.certificate_attachment if stage == "completion" else record.moa_attachment
        add_log(
            "practicum",
            student.id,
            "Student",
            source_attachment.original_name if source_attachment else "Student portal",
            f"Practicum submission recorded: {record.status}",
            next_owner,
            practicum_notes(record),
            previous_status=previous_status,
            new_status=record.status,
        )
        recompute_risk(student)
        db.session.commit()
        return jsonify({"ok": True, "message": message})

    @app.route("/api/student-portal/requests/withdrawal", methods=["POST"])
    @require_api_login("student")
    def student_withdrawal_request():
        data = request_payload()
        account = current_account()
        student = Student.query.get_or_404(account.student_id)
        current = latest_withdrawal_application(student.id)
        if current and current.status not in WITHDRAWAL_TERMINAL_STATUSES:
            return jsonify({"error": "You already have an active withdrawal request. Follow its current status instead of creating another request."}), 400
        # Withdrawal is a structured portal request. A PDF is not required.
        # Preserve support for legacy/optional attachments sent by older clients,
        # but do not make them part of the current submission contract.
        attachment = request_attachment_from_payload(student, "withdrawal", data)
        if not (data.get("reason") or (current.reason if current else "")):
            return jsonify({"error": "Enter the reason for withdrawal before submitting."}), 400
        subject_enrollment_id = safe_int(
            data.get("subject_enrollment_id") or (current.subject_enrollment_id if current else None),
            0,
        )
        subject_enrollment = SubjectEnrollment.query.filter_by(
            id=subject_enrollment_id,
            student_id=student.id,
        ).first()
        if not subject_enrollment:
            return jsonify({"error": "Choose one of your enrolled subjects to withdraw from."}), 400
        if subject_enrollment.status not in ACTIVE_SUBJECT_ENROLLMENT_STATUSES:
            return jsonify({"error": "Only an active enrolled subject can be withdrawn. Refresh and choose another subject."}), 400
        withdrawal_window = subject_withdrawal_window(subject_enrollment)
        if not withdrawal_window["eligible"]:
            return jsonify({"error": withdrawal_window_closed_message(withdrawal_window)}), 409

        previous_status = current.status if current else "Not Submitted"
        application = current if current and current.status in {"Returned", "Returned for Clarification"} else WithdrawalApplication(student_id=student.id)
        if not application.id:
            db.session.add(application)
        application.reason = (data.get("reason") or application.reason or "").strip()
        application.subject_enrollment_id = subject_enrollment.id
        application.withdrawal_scope = "Subject"
        application.effective_term = subject_enrollment.term.label
        if attachment:
            application.request_attachment_id = attachment.id
        application.fee_status = "Not Applicable"
        application.requirement_status = "Not Applicable"
        application.dean_decision = "Pending"
        application.registrar_status = "Pending"
        application.registrar_reference = None
        application.registrar_report_generated_at = None
        application.registrar_sent_at = None
        application.registrar_confirmed_at = None
        application.effective_date = date.today()
        application.status = "Submitted to GS Staff"
        application.decided_at = None
        application.completed_at = None
        application.updated_at = now_utc()
        db.session.flush()
        if attachment:
            bind_workflow_attachment(attachment, application, "Withdrawal Application", account)
        resolve_student_returns("withdrawal", student.id)
        add_task(student.id, "Record and forward withdrawal request", "Graduate School Staff", 3, 60)
        add_log(
            "withdrawal",
            student.id,
            "Student",
            attachment.original_name if attachment else "Structured student portal request",
            "Withdrawal request submitted",
            "Graduate School Staff",
            f"Subject: {subject_enrollment.course.code if subject_enrollment.course else subject_enrollment.course_id}; "
            f"semester: {application.effective_term}. Reason: {application.reason or 'Not provided'}. "
            f"Eligibility: {withdrawal_window['status']} (deadline {withdrawal_window['deadline']}). "
            f"Fee consequence: {withdrawal_window['fee_consequence']} "
            "No PDF attachment is required.",
            previous_status=previous_status,
            new_status=application.status,
        )
        db.session.commit()
        return jsonify({
            "ok": True,
            "message": (
                f"Submitted within the withdrawal window ({withdrawal_window['status'].lower()}). "
                "Graduate School staff will record and forward your subject request to the Dean. "
                + (
                    f"A charge of {withdrawal_window['fee_percent']}% of the term's total due applies "
                    f"({withdrawal_window['rule_source']}); the Business Office settles it."
                    if withdrawal_window.get("fee_percent") is not None
                    else "The Business Office confirms any charge."
                )
            ),
        })

    @app.route("/api/withdrawal/<int:application_id>/registrar-report")
    @require_api_login("staff", "academic_coordinator")
    def withdrawal_registrar_report(application_id: int):
        """Generate the focused Registrar handoff for one approved subject withdrawal."""
        application = WithdrawalApplication.query.get_or_404(application_id)
        if application.dean_decision != "Approved":
            return jsonify({"error": "The Dean must approve this subject withdrawal before a Registrar report is generated."}), 400
        enrollment = application.subject_enrollment
        if not enrollment or not enrollment.course or not enrollment.term:
            return jsonify({"error": "This case has no valid subject enrollment attached."}), 400
        if (
            application.status not in {
                "Subject Tagged - Registrar Preparation",
                "Exported - Ready to Send",
                "Sent to Registrar",
            }
            or enrollment.status != "Withdrawn"
        ):
            return jsonify({
                "error": (
                    "Graduate School Staff must tag the student as Withdrawn "
                    "from the selected subject before generating a Registrar report."
                )
            }), 409
        first_generation = not application.registrar_report_generated_at
        application.registrar_report_generated_at = application.registrar_report_generated_at or now_utc()
        if first_generation:
            add_log(
                "withdrawal",
                application.student_id,
                workflow_actor_label(current_account()),
                "Registrar report",
                f"Registrar subject-withdrawal report generated for {enrollment.course.code}",
                "Graduate School Staff",
                withdrawal_notes(application),
                previous_status=application.status,
                new_status=application.status,
                visibility="internal",
            )
        db.session.commit()

        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(["USLS Graduate School Subject Withdrawal Report"])
        writer.writerow(["Application ID", application.id])
        writer.writerow(["Student", application.student.name])
        writer.writerow(["Student ID", application.student.student_number])
        writer.writerow(["Program", application.student.program.code])
        writer.writerow(["Subject", f"{enrollment.course.code} - {enrollment.course.title}"])
        writer.writerow(["Semester", enrollment.term.label])
        writer.writerow(["Current enrollment status", enrollment.status])
        writer.writerow(["Dean decision", application.dean_decision])
        writer.writerow(["Reason", application.reason or ""])
        writer.writerow(["Generated at", application.registrar_report_generated_at.isoformat()])
        filename = f"subject-withdrawal-{application.student.student_number}-{enrollment.course.code}.csv"
        return Response(
            output.getvalue(),
            mimetype="text/csv",
            headers={"Content-Disposition": f'attachment; filename="{filename}"'},
        )

    @app.route("/api/withdrawal/approved.xlsx", methods=["POST"])
    @require_api_login("staff")
    def withdrawal_approved_workbook():
        """Export Dean-approved subject withdrawals as one Registrar Excel list."""
        data = request.get_json(silent=True) or {}
        try:
            application_ids = [int(value) for value in (data.get("application_ids") or [])]
        except (TypeError, ValueError):
            return jsonify({"error": "Withdrawal application IDs must be whole numbers."}), 400
        applications = approved_withdrawal_applications(application_ids or None)
        if application_ids and len(applications) != len(set(application_ids)):
            return jsonify({
                "error": (
                    "Every selected request must be Dean-approved, tagged as "
                    "Withdrawn from its selected subject, and awaiting Registrar preparation."
                )
            }), 409
        if not applications:
            return jsonify({
                "error": (
                    "No Dean-approved subject withdrawals have been tagged and "
                    "made ready for Excel export."
                )
            }), 400
        untagged = [
            application.student.name
            for application in applications
            if (
                not application.subject_enrollment
                or application.subject_enrollment.status != "Withdrawn"
            )
        ]
        if untagged:
            return jsonify({
                "error": (
                    "Tag each selected student as Withdrawn from the approved "
                    "subject before exporting: " + ", ".join(untagged)
                )
            }), 409

        exported_at = now_utc()
        actor = workflow_actor_label(current_account())
        for application in applications:
            previous_status = application.status
            application.status = "Exported - Ready to Send"
            application.registrar_status = "Exported - Ready to Send"
            application.registrar_report_generated_at = exported_at
            application.updated_at = exported_at
