    @app.route("/api/monitoring/class-list")
    @require_api_login("staff", "academic_coordinator")
    def monitoring_class_list():
        """Enrollment-built class roster shown beside the read-only monitoring grid."""
        program_id = request.args.get("program_id", type=int)
        term_id = request.args.get("term_id", type=int)
        course_id = request.args.get("course_id", type=int)
        view = (request.args.get("view") or "").strip().lower()
        program = Program.query.get(program_id) if program_id else Program.query.order_by(Program.code).first()
        if not program:
            return jsonify({"error": "No program found."}), 404
        term = AcademicTerm.query.get(term_id) if term_id else get_active_term()
        if not term:
            return jsonify({"error": "No academic semester is available."}), 404

        offerings = curriculum_offerings_for_term(program, term)
        selected = next((item for item in offerings if item.course_id == course_id), None)
        if not selected and offerings:
            selected = offerings[0]

        offering_rows = []
        for offering in offerings:
            status_counts = dict(
                db.session.query(SubjectEnrollment.status, func.count(SubjectEnrollment.id))
                .filter(
                    SubjectEnrollment.term_id == term.id,
                    SubjectEnrollment.course_id == offering.course_id,
                    SubjectEnrollment.status != "Cancelled",
                )
                .group_by(SubjectEnrollment.status)
                .all()
            )
            offering_rows.append({
                **curriculum_offering_dict(offering),
                "faculty_id": offering.assigned_faculty_id,
                "faculty_name": offering.assigned_faculty.name if offering.assigned_faculty else None,
                "schedule": offering.schedule or "",
                "section": offering.section or "",
                "class_size": sum(status_counts.values()),
                "active_count": sum(
                    count for status, count in status_counts.items()
                    if status in ACTIVE_SUBJECT_ENROLLMENT_STATUSES
                ),
                "status_counts": status_counts,
            })

        offered_course_ids = [item.course_id for item in offerings]
        all_roster = []
        if offered_course_ids:
            all_roster = (
                SubjectEnrollment.query.join(
                    Student,
                    Student.id == SubjectEnrollment.student_id,
                )
                .filter(
                    SubjectEnrollment.term_id == term.id,
                    SubjectEnrollment.course_id.in_(offered_course_ids),
                    SubjectEnrollment.status != "Cancelled",
                    Student.program_id == program.id,
                )
                .order_by(
                    SubjectEnrollment.course_id,
                    Student.last_name,
                    Student.first_name,
                )
                .all()
            )
        roster_by_course: dict[int, list[SubjectEnrollment]] = {}
        for item in all_roster:
            roster_by_course.setdefault(item.course_id, []).append(item)
        roster = roster_by_course.get(selected.course_id, []) if selected else []

        def class_list_student(item: SubjectEnrollment) -> dict:
            return {
                **student_brief(item.student),
                "subject_enrollment_id": item.id,
                "course_id": item.course_id,
                "course_code": item.course.code if item.course else "",
                "course_title": item.course.title if item.course else "",
                "status": "Enrolled" if item.status == "Current" else item.status,
                "source_reference": item.source_reference,
                "enrolled_at": iso(item.enrolled_at),
                "updated_at": iso(item.updated_at),
            }

        class_lists = []
        for offering_row in offering_rows:
            class_roster = roster_by_course.get(offering_row["course_id"], [])
            class_lists.append({
                "offering": offering_row,
                "students": [class_list_student(item) for item in class_roster],
                "summary": {
                    "listed": len(class_roster),
                    "active": sum(
                        1
                        for item in class_roster
                        if item.status in ACTIVE_SUBJECT_ENROLLMENT_STATUSES
                    ),
                },
            })
        return jsonify({
            "program": program_dict(program),
            "term": term_dict(term),
            "offerings": offering_rows,
            "selected_course_id": selected.course_id if selected else None,
            "selected_offering": next(
                (item for item in offering_rows if selected and item["course_id"] == selected.course_id),
                None,
            ),
            "students": [class_list_student(item) for item in roster],
            "class_lists": class_lists,
            "view": "all" if view == "all" else "single",
            "summary": {
                "offered_classes": len(offering_rows),
                "students_in_selected_class": len(roster),
                "active_students": sum(
                    1 for item in roster if item.status in ACTIVE_SUBJECT_ENROLLMENT_STATUSES
                ),
                "class_list_entries": len(all_roster),
                "unique_students": len({item.student_id for item in all_roster}),
            },
            "read_only": True,
            "source": "Enrollment and imported class-list records",
        })

    # ---- Soft-remove a student from the monitoring sheet -------------------
    @app.route("/api/students/<int:student_id>/flag-issue", methods=["POST"])
    @require_api_login("staff", "academic_coordinator")
    def flag_student_data_issue(student_id: int):
        # Exception reporting (checklist items 8, 72): official AIMS-derived values are
        # read-only. Staff report a discrepancy which is recorded in the activity trail
        # for the proper office to correct in AIMS; the official value is not changed.
        data = request.get_json(silent=True) or {}
        student = Student.query.get_or_404(student_id)
        category = (data.get("category") or "").strip()
        note = (data.get("note") or "").strip()
        target_kind = (data.get("target_kind") or "Whole record").strip() or "Whole record"
        target_label = (data.get("target_label") or "").strip() or None
        if category not in MONITORING_FLAG_CATEGORIES:
            return jsonify({"error": "Choose a valid flag category."}), 400
        if category == "AWOL policy alert":
            return jsonify({"error": "AWOL policy alerts are created automatically by the system."}), 400
        if not note:
            return jsonify({"error": "Enter the reason or observation for this flag."}), 400
        # A flag targets either the whole record or a specific subject/field.
        if target_kind not in ("Whole record", "Subject", "Field"):
            return jsonify({"error": "Choose a valid flag target."}), 400
        if target_kind != "Whole record" and not target_label:
            return jsonify({"error": "Select the subject or field this flag is about."}), 400
        target_text = target_label if target_kind != "Whole record" else "the whole record"
        account = current_account()
        actor = workflow_actor_label(account) if account else "Graduate School Staff"
        item, created = ensure_monitoring_flag(
            student,
            category,
            note,
            source="Manual",
            source_reference="Monitoring Sheet",
            target_kind=target_kind,
            target_label=target_label,
            account=account,
        )
        if not created:
            return jsonify({
                "error": f"{student.name} already has an open {category.lower()} flag on {target_text}. Resolve it before adding another."
            }), 409
        add_log(
            "aims-discrepancy",
            student.id,
            actor,
            category,
            f"{category} flagged for {student.name} ({student.student_number}) on {target_text}.",
            "Academic Coordinator",
            note + "\nThe monitoring projection remains read-only; no official source value was changed.",
            visibility="internal",
        )
        db.session.commit()
        return jsonify({
            "ok": True,
            "flag": monitoring_flag_dict(item),
            "message": "Flag recorded for Academic Coordinator follow-up.",
        })

