    @app.route("/api/students/<int:student_id>/flags/<int:flag_id>/resolve", methods=["POST"])
    @require_api_login("staff", "academic_coordinator")
    def resolve_student_monitoring_flag(student_id: int, flag_id: int):
        student = Student.query.get_or_404(student_id)
        item = StudentMonitoringFlag.query.get_or_404(flag_id)
        if item.student_id != student.id:
            return jsonify({"error": "The selected flag does not belong to this student."}), 404
        if item.status == "Resolved":
            return jsonify({"ok": True, "flag": monitoring_flag_dict(item), "message": "Flag is already resolved."})
        data = request.get_json(silent=True) or {}
        resolution_note = (data.get("resolution_note") or "").strip()
        if not resolution_note:
            return jsonify({"error": "Enter how the flag was resolved."}), 400
        account = current_account()
        item.status = "Resolved"
        item.resolved_by_user_id = account.id if account else None
        item.resolution_note = resolution_note
        item.resolved_at = now_utc()
        item.updated_at = now_utc()
        add_log(
            "aims-discrepancy",
            student.id,
            workflow_actor_label(account) if account else "Graduate School Staff",
            item.category,
            f"{item.category} resolved",
            "Academic Coordinator",
            resolution_note + "\nNo monitoring cell was manually edited.",
            previous_status="Open",
            new_status="Resolved",
            visibility="internal",
        )
        db.session.commit()
        return jsonify({
            "ok": True,
            "flag": monitoring_flag_dict(item),
            "message": "Flag resolved without editing the monitoring sheet.",
        })

    @app.route("/api/monitoring/conflicts")
    @require_api_login("staff", "academic_coordinator")
    def monitoring_conflicts():
        # Consolidated view of every open flag/conflict across students so the
        # Academic Coordinator can work through them in one place (Work Queue).
        status_filter = (request.args.get("status") or "Open").strip()
        query = StudentMonitoringFlag.query
        if status_filter and status_filter != "All":
            query = query.filter(StudentMonitoringFlag.status == status_filter)
        rows = (
            query.order_by(
                StudentMonitoringFlag.status.asc(),
                StudentMonitoringFlag.created_at.desc(),
                StudentMonitoringFlag.id.desc(),
            )
            .all()
        )
        items = []
        for flag in rows:
            student = flag.student
            record = monitoring_flag_dict(flag)
            record.update({
                "student_name": student.name if student else "",
                "student_number": student.student_number if student else "",
                "program_code": student.program.code if student and student.program else "",
                # Source-correctable categories clear automatically on a corrected
                # re-import; everything else needs coordinator supervision.
                "auto_resolvable": flag.category in SOURCE_CORRECTABLE_FLAG_CATEGORIES,
                "system_generated": (flag.source or "Manual") != "Manual",
            })
            items.append(record)
        open_items = [item for item in items if item["status"] == "Open"]
        return jsonify({
            "items": items,
            "summary": {
                "open_total": len(open_items),
                "auto_resolvable": sum(1 for item in open_items if item["auto_resolvable"]),
                "needs_action": sum(1 for item in open_items if not item["auto_resolvable"]),
            },
        })

    @app.route("/api/students/<int:student_id>/remove", methods=["POST"])
    @require_api_login("staff", "academic_coordinator")
    def monitoring_remove_student(student_id: int):
        return jsonify({
            "error": "The Monitoring Sheet is read-only. Use the applicable standing-change workflow."
        }), 409

        # Legacy branch retained temporarily for migration reference.
        # A "removal" from the monitoring sheet is a soft change: the student is
        # marked Withdrawn (kept in the database with all history) rather than
        # deleted, so records and the activity trail stay intact.
        data = request.get_json(silent=True) or {}
        student = Student.query.get_or_404(student_id)
        reason = (data.get("reason") or "").strip()
        previous = student.standing
        if student.standing == "Withdrawn" and student.enrollment_tag == "Withdrawn":
            return jsonify({"error": f"{student.name} is already marked Withdrawn."}), 400
        student.standing = "Withdrawn"
        student.enrollment_tag = "Withdrawn"
        student.updated_at = now_utc()
        cancelled_subjects = cancel_active_subject_enrollments(
            student,
            reason or "Removed via the monitoring sheet.",
        )
        account = current_account()
        actor = workflow_actor_label(account) if account else "Graduate School Staff"
        add_log(
            "withdrawal",
            student.id,
            actor,
            "Monitoring sheet removal",
            f"{student.name} marked Withdrawn and removed from active monitoring.",
            "Student",
            (
                f"{reason or 'Removed via the monitoring sheet.'} "
                f"Cancelled {cancelled_subjects} active subject enrollment(s)."
            ),
            previous_status=previous,
            new_status="Withdrawn",
        )
        recompute_risk(student)
        db.session.commit()
        return jsonify({"ok": True, "message": f"{student.name} was marked Withdrawn.", "student_id": student.id})

    # ---- Monitoring Sheet portal entry (owner decision 2026-10-01) -------
    # Staff, academic coordinators and admins write; research coordinators and the
    # dean read; a student only reads their own record (student portal route).
    def monitoring_error_response(exc: MonitoringEntryError):
        db.session.rollback()
        return jsonify({"error": str(exc), **exc.extra}), exc.status

    def monitoring_can_edit() -> bool:
        account = current_account()
        return bool(account and account.role in MONITORING_WRITE_ROLES)

