# Table 3.2 - the actions the system is defined to record in the audit trail.
AUDITABLE_ACTIONS = [
    "student-handoff", "enrollment", "course-adjustments", "research-gate",
    "panel-matching", "defense-scheduling", "practicum", "graduation",
    "leave-of-absence", "readmission", "awol", "withdrawal",
]

# Table 3.3 - the monitoring fields a student record is required to carry.
REQUIRED_MONITORING_FIELDS = [
    ("Lifecycle stage", lambda s: bool((s.current_stage or "").strip())),
    ("Completion status", lambda s: bool((s.standing or "").strip())),
    # Use the same derived accessor the screens use: the raw column may be blank
    # on legacy rows while the marker is still available from the entry year.
    ("AY / year-level markers", lambda s: bool(student_academic_year_entry(s))
                                          and bool(str(s.year_level or "").strip())),
    ("Curriculum tag", lambda s: s.id in _CURRICULUM_TAGGED),
]

_CURRICULUM_TAGGED: set[int] = set()

# Table 3.8 - the reference set the Policy Assistant's routing rule is measured
# against. Each question has one correct handling under the defined prototype
# rule; the KPI runs the rule and counts exact matches. No model call is made,
# so the measurement is deterministic and repeatable.
ASSISTANT_REFERENCE_SET = [
    ("What is the maximum leave of absence a student may file?", "policy"),
    ("What is the maximum residency period for a master's student?", "policy"),
    ("What are the requirements for the comprehensive examination?", "policy"),
    ("What is the withdrawal policy for a subject?", "policy"),
    ("Which students need attention right now?", "student_attention"),
    ("What is blocking this student's progress?", "student_progress_blockers"),
]


def policy_grounding_kpi() -> dict:
    """Table 3.8 - does the assistant route each reference question the way the
    defined rule specifies?"""
    matched, misses = 0, []
    for question, expected in ASSISTANT_REFERENCE_SET:
        try:
            actual = _assistant_intent(question)
        except Exception as exc:  # noqa: BLE001
            actual = f"error: {exc}"
        if actual == expected:
            matched += 1
        else:
            misses.append(f"“{question[:38]}…” → {actual}, expected {expected}")
    total = len(ASSISTANT_REFERENCE_SET)
    return {
        "module": "Module 6 - Policy and Case Guidance",
        "kpi": "Policy-grounded response match rate",
        "target": "100%",
        "value": _percent(matched, total),
        "unit": "%",
        "basis": f"{matched} of {total} reference questions routed as the defined rule specifies"
                 + (f"; mismatched: {'; '.join(misses)}" if misses else ""),
        "met": matched == total,
    }


def access_control_kpi() -> dict:
    """Table 3.1 - does every protected area enforce the specified roles?"""
    passed, mismatches = 0, []
    for label, endpoint, expected in ACCESS_CONTROL_SPEC:
        actual = API_ROLE_REGISTRY.get(endpoint)
        if actual is not None and set(actual) == expected:
            passed += 1
        else:
            mismatches.append(f"{label} (expected {sorted(expected)}, got "
                              f"{sorted(actual) if actual is not None else 'unregistered'})")
    total = len(ACCESS_CONTROL_SPEC)
    return {
        "module": "User and Access Management",
        "kpi": "Access control enforcement rate",
        "target": "100%",
        "value": _percent(passed, total),
        "unit": "%",
        "basis": f"{passed} of {total} role-permission cases enforce the specified roles"
                 + (f"; mismatched: {'; '.join(mismatches)}" if mismatches else ""),
        "met": passed == total,
    }


def audit_coverage_kpi(student_ids: list[int]) -> dict:
    """Table 3.2 - does every auditable action produce a timestamped log entry?"""
    covered, missing = 0, []
    for slug in AUDITABLE_ACTIONS:
        exists = (
            TransactionLog.query.filter(
                TransactionLog.transaction_slug == slug,
                TransactionLog.created_at.isnot(None),
                TransactionLog.actor_role.isnot(None),
            ).first()
            is not None
        )
        if exists:
            covered += 1
        else:
            missing.append(slug)
    total = len(AUDITABLE_ACTIONS)
    return {
        "module": "Audit Trail and Accountability",
        "kpi": "Audit event coverage",
        "target": "100%",
        "value": _percent(covered, total),
        "unit": "%",
        "basis": f"{covered} of {total} auditable actions have timestamped log entries"
                 + (f"; no entries yet for: {', '.join(missing)}" if missing else ""),
        "met": covered == total,
    }


def monitoring_field_kpi(students: list[Student]) -> dict:
    """Table 3.3 - do active records carry every required monitoring field?"""
    active = [s for s in students if (s.current_stage or "") not in TERMINAL_STAGES]
    global _CURRICULUM_TAGGED
    _CURRICULUM_TAGGED = {
        sid for (sid,) in db.session.query(StudentCurriculumTag.student_id)
        .filter(StudentCurriculumTag.active.is_(True)).distinct().all()
    }
    complete, shortfall = 0, {}
    for student in active:
        missing = [name for name, check in REQUIRED_MONITORING_FIELDS if not check(student)]
        if missing:
            for name in missing:
                shortfall[name] = shortfall.get(name, 0) + 1
        else:
            complete += 1
    worst = sorted(shortfall.items(), key=lambda kv: -kv[1])[:3]
    return {
        "module": "Module 1 - Student Progress Management",
        "kpi": "Required monitoring field completion rate",
        "target": "100%",
        "value": _percent(complete, len(active)),
        "unit": "%",
        "basis": f"{complete} of {len(active)} active records carry every required field"
                 + (f"; most often missing: {', '.join(f'{k} ({v})' for k, v in worst)}" if worst else ""),
        "met": complete == len(active) if active else None,
    }


def next_action_ownership_kpi(student_ids: list[int]) -> dict:
    """Table 3.4 - does every active case name who acts next?"""
    if not student_ids:
        return {"module": "Module 2 - Case Status and Action Tracking",
                "kpi": "Next-action ownership coverage", "target": "100%", "value": 0.0,
                "unit": "%", "basis": "No cases in scope", "met": None}
    latest: dict[tuple, TransactionLog] = {}
    for entry in (TransactionLog.query
                  .filter(TransactionLog.student_id.in_(student_ids))
                  .order_by(TransactionLog.created_at.asc(), TransactionLog.id.asc()).all()):
        latest[(entry.student_id, entry.transaction_slug)] = entry
    owned = sum(1 for e in latest.values() if (e.next_owner or "").strip())
    total = len(latest)
    return {
        "module": "Module 2 - Case Status and Action Tracking",
        "kpi": "Next-action ownership coverage",
        "target": "100%",
        "value": _percent(owned, total),
        "unit": "%",
        "basis": f"{owned} of {total} active case(s) name the role that acts next",
        "met": owned == total if total else None,
    }


def scheduling_completeness_kpi(student_ids: list[int]) -> dict:
    """Table 3.5 - do scheduling cases carry both request and outcome timestamps?"""
    if not student_ids:
        return {"module": "Module 3 - Defense Scheduling Management",
                "kpi": "Scheduling record completeness", "target": "at least 90%", "value": 0.0,
                "unit": "%", "basis": "No scheduling cases in scope", "met": None}
    rows = ScheduleRequest.query.filter(ScheduleRequest.student_id.in_(student_ids)).all()
    complete = sum(1 for r in rows if r.created_at is not None and r.confirmed_at is not None)
    total = len(rows)
    rate = _percent(complete, total)
    return {
        "module": "Module 3 - Defense Scheduling Management",
        "kpi": "Scheduling record completeness",
        "target": "at least 90%",
        "value": rate,
        "unit": "%",
        "basis": f"{complete} of {total} scheduling case(s) carry both a request and an outcome timestamp",
        "met": (rate >= 90.0) if total else None,
    }


def analytics_kpi_summary(payload: dict) -> list[dict]:
    """KPI measurements for the analytics and reporting modules, computed from
    the reports actually produced in this request rather than asserted."""
    generated = sum(1 for key, _ in ANALYTICS_REPORTS if _report_is_valid(payload.get(key)))
    total_reports = len(ANALYTICS_REPORTS)
    failed = [label for key, label in ANALYTICS_REPORTS if not _report_is_valid(payload.get(key))]
    generation_rate = _percent(generated, total_reports)

    available = generated + len(OPERATIONAL_REPORT_KEYS)
    agreed_total = total_reports + len(OPERATIONAL_REPORT_KEYS)
    availability = _percent(available, agreed_total)

    closure = payload.get("followup_closure", {}).get("totals", {})
    flagged = closure.get("flagged_cases", 0)
    closure_rate = closure.get("closure_rate", 0.0)

    return [
        {
            "module": "Module 4 - Case Monitoring and Follow-Up",
            "kpi": "Follow-up closure logging rate",
            "target": "at least 90%",
            "value": closure_rate,
            "unit": "%",
            "basis": f"{closure.get('closed', 0)} closed of {flagged} flagged case(s)"
                     if flagged else "No flagged cases in scope; rate not measurable",
            "met": (closure_rate >= 90.0) if flagged else None,
        },
        {
            "module": "Module 5 - Analytics and Decision Support",
            "kpi": "Analytics report generation rate",
            "target": "at least 90%",
            "value": generation_rate,
            "unit": "%",
            "basis": f"{generated} of {total_reports} analytics outputs computed successfully"
                     + (f"; failed: {', '.join(failed)}" if failed else ""),
            "met": generation_rate >= 90.0,
        },
        {
            "module": "Module 7 - Reporting and Dashboards",
            "kpi": "Required report availability",
            "target": "100%",
            "value": availability,
            "unit": "%",
            "basis": f"{available} of {agreed_total} agreed reports available "
                     f"({generated}/{total_reports} analytics, {len(OPERATIONAL_REPORT_KEYS)} operational)",
            "met": availability >= 100.0,
        },
    ]


def analytics_payload(filters=None) -> dict:
    filters = filters or {}
    students = filtered_students_query(filters).all()
    student_ids = [student.id for student in students]

    builders = {
        "queue_aging": lambda: queue_aging_report(student_ids),
        "stage_bottlenecks": lambda: stage_bottleneck_report(students),
        "owner_workload": lambda: owner_workload_report(student_ids),
        "residency_watchlist": lambda: residency_watchlist_report(students),
        "completion_attrition": lambda: completion_attrition_report(students),
        "scheduling_cycle_time": lambda: scheduling_cycle_report(student_ids),
        "followup_closure": lambda: followup_closure_report(student_ids),
    }

    payload = {
        "filters": normalize_filters(filters),
        "programs": [program_dict(p) for p in Program.query.order_by(Program.code).all()],
        "stages": STAGES,
        "reports": [{"id": key, "label": label} for key, label in ANALYTICS_REPORTS],
        "student_count": len(student_ids),
    }
    for key, build in builders.items():
        try:
            payload[key] = build()
        except Exception as exc:  # noqa: BLE001 - a failed report must not hide the rest
            app.logger.exception("Analytics report %s failed", key)
            payload[key] = {"count": 0, "rows": [], "columns": [], "error": str(exc)}
    # All nine KPI measurements defined in the proposal, in proposal order.
    kpis = [access_control_kpi(), audit_coverage_kpi(student_ids),
            monitoring_field_kpi(students), next_action_ownership_kpi(student_ids),
            scheduling_completeness_kpi(student_ids), policy_grounding_kpi()]
    try:
        kpis.extend(analytics_kpi_summary(payload))
    except Exception as exc:  # noqa: BLE001
        app.logger.exception("Analytics KPI summary failed")
        kpis.append({"module": "Modules 4, 5 and 7", "kpi": "Analytics KPIs", "target": "-",
                     "value": 0.0, "unit": "%", "basis": f"Could not compute: {exc}", "met": False})
    # Present them in the order the proposal defines them (Tables 3.1 to 3.9).
    order = ["User and Access", "Audit Trail", "Module 1", "Module 2", "Module 3",
             "Module 4", "Module 5", "Module 6", "Module 7"]
    kpis.sort(key=lambda k: next((i for i, name in enumerate(order)
                                  if k["module"].startswith(name)), 99))
    payload["kpis"] = kpis
    return payload


REPORT_TABS = (
    "graduation_candidates",
    "missing_requirements",
    "practicum_monitoring",
    "withdrawal_requests",
    "loa_readmission",
    "at_risk",
    "open_overdue_tasks",
    "research_completion",
)


def reports_payload(filters=None) -> dict:
    """Report tabs with real counts. Only the rows are paged, never the count.

    ``tab`` names the tab that ``page`` / ``page_size`` apply to; the other tabs return their first
    page. Every tab says how many rows exist in total (``count``) and how many pages that makes.
    """
    filters = filters or {}
    student_ids = report_student_ids(filters)
    empty = len(student_ids) == 0
    selected_tab = _filter_value(filters, "tab")
    requested_page, page_size = page_arguments(filters, default_size=100, max_size=200)

    def page_for(key: str) -> int:
        return requested_page if key == selected_tab else 1

    def section(key: str, total: int, rows: list[dict]) -> dict:
        return {
            "count": total,
            "rows": rows,
            "page": page_for(key),
            "page_size": page_size,
            "pages": max((total + page_size - 1) // page_size, 1),
        }

    def paged(key: str, query):
        """Real total for ``query`` and the rows of the requested page."""
        total = query.count()
        rows = query.offset((page_for(key) - 1) * page_size).limit(page_size).all()
        return total, rows

    def by_students(model):
        query = model.query
        return query.filter(model.student_id.in_(student_ids)) if not empty else query.filter(False)

    dashboard = dashboard_stats(filters)

    practicum_query = scoped_practicum_records_query()
    practicum_query = (
        practicum_query.filter(PracticumRecord.student_id.in_(student_ids))
        if not empty
        else practicum_query.filter(False)
    )
    total, items = paged("practicum_monitoring", practicum_query.order_by(PracticumRecord.updated_at.desc()))
    practicum_section = section("practicum_monitoring", total, [practicum_record_dict(item) for item in items])

    total, items = paged("withdrawal_requests", by_students(WithdrawalApplication).order_by(WithdrawalApplication.updated_at.desc()))
    withdrawal_section = section("withdrawal_requests", total, [withdrawal_application_dict(item) for item in items])

    total, items = paged("graduation_candidates", by_students(GraduationEndorsement).order_by(GraduationEndorsement.updated_at.desc()))
    graduation_section = section("graduation_candidates", total, [graduation_endorsement_dict(item) for item in items])

    # Missing requirements: EVERY student is evaluated; only then is the list counted and paged.
    missing_all = []
    for student in filtered_students_query(filters).order_by(Student.last_name, Student.first_name).all():
        eligibility = graduation_eligibility(student)
        if eligibility["missing_coursework"] or eligibility["missing_research_requirements"] or eligibility["missing_practicum_requirement"]:
            missing_all.append((student, eligibility))
    start = (page_for("missing_requirements") - 1) * page_size
    missing_rows = [
        {
            "student": student_brief(student),
            "coursework": eligibility["missing_coursework"][:6],
            "research": eligibility["missing_research_requirements"][:6],
            "practicum": eligibility["missing_practicum_requirement"],
            "next_owner": eligibility["next_owner"],
        }
        for student, eligibility in missing_all[start:start + page_size]
    ]
    missing_section = section("missing_requirements", len(missing_all), missing_rows)

    adopt_legacy_leave_logs(commit=True)
    leave_query = LeaveCase.query.order_by(LeaveCase.updated_at.desc(), LeaveCase.id.desc())
    leave_query = leave_query.filter(LeaveCase.student_id.in_(student_ids)) if not empty else leave_query.filter(False)
    loa_readmission_rows = []
    students_with_cases = set()
    for case in leave_query.all():
        students_with_cases.add(case.student_id)
        loa_readmission_rows.append({
            "id": case.id,
            "student": student_brief(case.student),
            "standing": case.student.standing,
            "stage": case.student.current_stage,
            "kind": case.kind,
            "kind_label": KIND_LABELS[case.kind],
            "status": case.status,
            "status_label": STATUS_BY_KEY.get(case.status, {}).get("label", case.status),
            "period_text": leave_target_label(case) if case.kind == KIND_READMISSION else leave_period_text(case),
            "owner": _lw.next_owner(case.kind, case.status),
            "submitted_at": iso(case.submitted_at),
            "decided_at": iso(case.decided_at),
            "registrar_status": case.registrar_status,
        })
    # A student marked On Leave who has no case on file still belongs on the report.
    for student in (
        filtered_students_query(filters)
        .filter(or_(Student.standing == "On Leave", Student.current_stage == "LOA"))
        .order_by(Student.last_name, Student.first_name)
        .all()
    ):
        if student.id in students_with_cases:
            continue
        loa_readmission_rows.append({
            "id": f"standing-{student.id}",
            "student": student_brief(student),
            "standing": student.standing,
            "stage": student.current_stage,
            "kind": "STANDING",
            "kind_label": "On leave (no request on file)",
            "status": "On Leave",
            "status_label": "On leave",
            "period_text": "Not recorded",
            "owner": "",
            "submitted_at": None,
            "decided_at": None,
            "registrar_status": "",
        })
    # Real total, then the requested page (same paging as the other report tabs).
    loa_total = len(loa_readmission_rows)
    loa_start = (page_for("loa_readmission") - 1) * page_size
    loa_section = section("loa_readmission", loa_total, loa_readmission_rows[loa_start:loa_start + page_size])

    at_risk_query = filtered_students_query(filters).filter(at_risk_clause()).order_by(Student.last_name, Student.first_name)
    total, items = paged("at_risk", at_risk_query)
    at_risk_rows = []
    for student in items:
        recs = student_recommendations(student)["recommendations"]
        at_risk_rows.append({
            "student": student_brief(student),
            "top_recommendation": recs[0] if recs else None,
        })
    at_risk_section = section("at_risk", total, at_risk_rows)

    task_query = by_students(Task).filter(Task.status.in_(["Pending", "Overdue"])).order_by(Task.due_at.asc(), Task.id.asc())
    total, items = paged("open_overdue_tasks", task_query)
    task_section = section("open_overdue_tasks", total, [task_dict(task) for task in items])

    total, items = paged("research_completion", by_students(ResearchCase).order_by(ResearchCase.opened_at.desc()))
    research_section = section("research_completion", total, [
        {"student": student_brief(case.student), "case": research_case_dict(case)} for case in items
    ])

    return {
        "filters": normalize_filters(filters),
        "programs": [program_dict(p) for p in Program.query.order_by(Program.code).all()],
        "stages": STAGES,
        "standings": STANDINGS,
        "summary": dashboard["kpis"],
        "dashboard": dashboard,
        "graduation_candidates": graduation_section,
        "missing_requirements": missing_section,
        "practicum_monitoring": practicum_section,
        "withdrawal_requests": withdrawal_section,
        "loa_readmission": loa_section,
        "at_risk": at_risk_section,
        "open_overdue_tasks": task_section,
        "research_completion": research_section,
    }


# ---------------------------------------------------------------------------
# Transaction context (data needed by each workflow screen)
# ---------------------------------------------------------------------------
def request_notes_value(notes: str | None, label: str) -> str:
    match = re.search(rf"{re.escape(label)}:\s*(.+?)(?:\n|$)", notes or "", re.IGNORECASE)
    return match.group(1).strip().rstrip(".") if match else ""


def latest_request_attachment(student_id: int, request_type: str) -> StudentRequestAttachment | None:
    return (
        StudentRequestAttachment.query.filter_by(student_id=student_id, request_type=request_type)
        .order_by(StudentRequestAttachment.uploaded_at.desc(), StudentRequestAttachment.id.desc())
        .first()
    )


def practicum_roster_payload() -> list[dict]:
    students = (
        Student.query.join(Program)
        .filter(practicum_program_filter())
        .order_by(Student.last_name.asc(), Student.first_name.asc())
        .all()
    )
    rows = []
    for student in students:
        eligibility = practicum_eligibility(student)
        record = latest_practicum_record(student.id)
        record_payload = practicum_record_dict(record) if record else None
        rows.append({
            "student": student_brief(student),
            "eligibility": eligibility,
            "record": record_payload,
            "has_submitted_documents": bool(
                record_payload
                and (record_payload.get("moa_attachment") or record_payload.get("completion_attachments"))
            ),
            "timeline": practicum_timeline(record, eligibility),
            "moa_status": record.moa_status if record else "Not Submitted",
            "documents_status": record.document_status if record else "Not Submitted",
            "hours_status": (
                "Complete" if record and record.required_hours and record.completed_hours >= record.required_hours
                else "Incomplete" if record else "Not Started"
            ),
            "coordinator_review_status": (
                practicum_record_dict(record, include_student=False)["coordinator_review_status"] if record else "Pending"
            ),
            "dean_report_status": (
                practicum_record_dict(record, include_student=False)["dean_report_status"] if record else "Not Sent"
            ),
            **workflow_case_meta("practicum", student.id),
        })
    return sorted(rows, key=lambda item: item["last_activity_at"] or "", reverse=True)


def withdrawal_roster_payload() -> list[dict]:
    rows = []
    for item in WithdrawalApplication.query.order_by(WithdrawalApplication.updated_at.desc()).all():
        rows.append({**withdrawal_application_dict(item), **workflow_case_meta("withdrawal", item.student_id)})
    return rows


def graduation_candidate_payload() -> list[dict]:
    students = (
        Student.query.filter(Student.standing != "Withdrawn")
        .order_by(Student.last_name.asc(), Student.first_name.asc())
        .all()
    )
    rows = []
    for student in students:
        eligibility = graduation_eligibility(student)
        endorsement = latest_graduation_endorsement(student.id)
        if not eligibility["eligible"] and (not endorsement or not endorsement.batch_name):
            continue
        case_meta = workflow_case_meta("graduation", student.id)
        endorsement_payload = graduation_endorsement_dict(endorsement) if endorsement else None
        application_submitted = bool(
            endorsement_payload
            and endorsement_payload.get("request_attachment")
        )
        rows.append({
            "student": student_brief(student),
            "eligibility": eligibility,
            "endorsement": endorsement_payload,
            "application_submitted": application_submitted,
            "application_status": (
                "Application Submitted"
                if application_submitted
                else "Awaiting Student Application"
            ),
            "has_submitted_documents": application_submitted,
            **case_meta,
            "next_action_owner": (
                case_meta["next_action_owner"]
                or ("Student" if not application_submitted else eligibility["next_owner"])
            ),
        })
    return sorted(rows, key=lambda item: item["last_activity_at"] or "", reverse=True)


def serialize_transaction_context(slug: str, selected_student_id: int | None, specialization: str = "") -> dict:
    # Context responses are read-only preparation data for workflow screens.
    # The actual record changes happen only in the transaction handlers.
    selected_student = None
    if slug != "student-handoff" and selected_student_id:
        selected_student = Student.query.get(selected_student_id)

    activity_query = TransactionLog.query if slug in {"practicum", "withdrawal", "graduation"} else human_activity_query()
    recent_logs = (
        activity_query
        .filter(TransactionLog.transaction_slug == slug)
        .order_by(TransactionLog.created_at.desc())
        .limit(30)
        .all()
    )

    context: dict = {
        "slug": slug,
        "transaction": TRANSACTION_BY_SLUG[slug],
        "selected_student": student_brief(selected_student) if selected_student else None,
        "recent_logs": [log_dict(l) for l in recent_logs],
        "message_templates": WORKFLOW_MESSAGE_TEMPLATES,
        "message_recipients": list(WORKFLOW_RECIPIENTS),
        "deployment_policy_questions": DEPLOYMENT_POLICY_QUESTIONS,
        "practicum_program_scope": practicum_program_scope(),
        "eligibility_config": practicum_eligibility_config(),
        "gate_requirements": {
            gate: required_documents_for_gate(gate)
            for gate in [
                "Form 1 - Title Defense",
                "Form 4 - Proposal Defense Readiness",
                "Final Defense",
                "Completion Evidence",
            ]
        },
        "readmission_requirements": readmission_requirements(),
        "onboarding_requirements": onboarding_requirements(),
    }

    if slug == "practicum":
        context["roster"] = practicum_roster_payload()
    elif slug == "withdrawal":
        context["roster"] = withdrawal_roster_payload()
    elif slug == "graduation":
        context["roster"] = graduation_candidate_payload()
        context["graduation_review_windows"] = graduation_school_year_options()
        context["graduation_default_review_window"] = default_graduation_school_year()
    elif slug == "awol":
        sync_automatic_awol_statuses(commit=True)
        context["roster"] = awol_residency_roster_payload()
        context["residency_reasons"] = RESIDENCY_REASONS
        context["policy_citations"] = AWOL_RESIDENCY_CITATIONS

    if slug == "student-handoff":
        context["programs"] = [program_dict(p) for p in Program.query.order_by(Program.college, Program.name).all()]
        context["terms"] = [term_dict(t) for t in AcademicTerm.query.order_by(AcademicTerm.start_date.desc()).all()]

    # LOA/Readmission are student-initiated: staff only see students who submitted.
    if slug in ("leave-of-absence", "readmission"):
        context["submitted_requests"] = submitted_request_students(slug)
        context["selected_request"] = next(
            (row for row in context["submitted_requests"] if row["id"] == selected_student_id),
            None,
        )
        if slug == "leave-of-absence" and selected_student and context["selected_request"]:
            context["loa_policy_review"] = loa_policy_review(selected_student, context["selected_request"])
        if slug == "readmission" and selected_student and context["selected_request"]:
            context["readmission_policy_review"] = readmission_policy_review(
                selected_student,
                {**context["selected_request"], "readmission_items": readmission_requirements()},
            )

    if selected_student:
        context["panel_roles"] = panel_roles_for_student(
            selected_student,
            current_panel_gate(selected_student) if slug in {"research-gate", "panel-matching", "defense-scheduling"} else None,
        )
        context["research_case_type"] = research_case_type(selected_student)
        if slug == "course-audit":
            context["course_audit"] = course_audit_dict(compute_course_audit(selected_student))
            context["courses"] = [
                {"id": c.id, "code": c.code, "title": c.title}
                for c in Course.query.filter(Course.program_id == selected_student.program_id)
                .order_by(Course.code)
                .all()
            ]
            context["offering_demand"] = [
                {"code": row["course"].code, "title": row["course"].title, "count": row["count"]}
                for row in compute_offering_demand()
            ]
        if slug == "research-gate":
            context["research_prerequisite"] = comprehensive_exam_eligibility(selected_student)
            research_case, progress = sync_research_progress(selected_student)
            context["research_case"] = research_case_dict(research_case)
            context["research_progress"] = progress
            context["research_vocabulary"] = RESEARCH_VOCABULARY
            context["current_milestone"] = progress["milestone"]
            context["form1_endorsement"] = form1_endorsement_dict(
                Form1Endorsement.query.filter_by(student_id=selected_student.id).first()
            )
            final_panel = active_panel_assignments(selected_student, progress["gate"])
            matching_profile = research_matching_profile(selected_student)
            context["panel_status"] = {
                "status": (
                    "Final panel selected"
                    if len(final_panel) >= len(panel_roles_for_student(selected_student, progress["gate"]))
                    else "Recommended panel available"
                    if matching_profile["ready"]
                    else "Not yet generated"
                ),
                "recommendations": [
                    panel_assignment_dict(item)
                    for item in final_panel
                ],
            }
            context["documents_by_gate"] = {}
            for doc in DocumentCheck.query.filter_by(student_id=selected_student.id).all():
                context["documents_by_gate"].setdefault(doc.gate, []).append(document_check_dict(doc))
        if slug == "panel-matching":
            prerequisite = comprehensive_exam_eligibility(selected_student)
            context["research_prerequisite"] = prerequisite
            matching_profile = research_matching_profile(selected_student)
            context["matching_profile"] = matching_profile
            matching_result = (
                panel_matching_result(selected_student, matching_profile)
                if prerequisite["research_allowed"] and matching_profile["ready"]
                else None
            )
            context["matching_method"] = matching_result["method"] if matching_result else None
            context["matching_method_label"] = matching_result["method_label"] if matching_result else None
            context["matching_method_note"] = matching_result["method_note"] if matching_result else ""
            context["matching_weights"] = dict(PANEL_MATCH_WEIGHTS)
            context["suggested_panel"] = matching_result["suggested_panel"] if matching_result else []
            context["panel_composition"] = matching_result["composition"] if matching_result else None
            context["excluded_faculty"] = matching_result["excluded"] if matching_result else []
            context["panel_recommendations"] = [
                {
                    "faculty_id": row["faculty"].id,
                    "faculty_name": row["faculty"].name,
                    "college": row["faculty"].college,
                    "specialization": row["faculty"].specialization,
                    "score": row["score"],
                    "note": row["note"],
                    "matched_keywords": row["matched_keywords"],
                    "availability_status": row["availability_status"],
                    "availability_windows": row["availability_windows"],
                    "workload": row["workload"],
                    "score_breakdown": row["score_breakdown"],
                    "breakdown": row["breakdown"],
                    "flags": row["flags"],
                    "method": row["method"],
                    "method_label": row["method_label"],
                }
                for row in (matching_result["rows"] if matching_result else [])
            ]
            context["assigned_panel"] = [
                panel_assignment_dict(p)
                for p in active_panel_assignments(selected_student, matching_profile["gate"])
            ]
        if slug == "defense-scheduling":
            prerequisite = comprehensive_exam_eligibility(selected_student)
            context["research_prerequisite"] = prerequisite
            research_case, progress = sync_research_progress(selected_student)
            assignments = active_panel_assignments(selected_student, progress["gate"])
            context["assigned_panel"] = [panel_assignment_dict(p) for p in assignments]
            # Full defense-eligible faculty list so staff can reassign the panel from
            # this screen (not just accept the matched panel).
            context["faculty_directory"] = defense_faculty_directory()
            context["panel_roles"] = panel_roles_for_student(selected_student, progress["gate"])
            requirements = progress["milestone"]["requirements"]
            schedule_blockers = [
                item for item in requirements
                if item["source_type"] not in SCHEDULE_SYSTEM_SOURCES
                and item["item_name"] not in POST_DEFENSE_REQUIREMENTS
            ]
            context["schedule_readiness"] = {
                "stage": progress["stage"],
                "gate": progress["gate"],
                "status": progress["status"],
                "ready": all(item["status"] == "Complete" for item in schedule_blockers),
                "requirements": requirements,
                "completed_count": sum(item["status"] == "Complete" for item in schedule_blockers),
                "pending_count": sum(item["status"] != "Complete" for item in schedule_blockers),
                "research_title": research_case.title if research_case else "Locked until comprehensive exam is passed",
                "adviser_name": (research_case.adviser_name if research_case else None) or selected_student.adviser_name,
            }
            participants = defense_participants(selected_student, assignments) if assignments else []
            today = date.today()
            stage_defense_type = RESEARCH_GATE_DEFENSE_TYPES.get(progress["gate"])
            lead_days = defense_lead_days(stage_defense_type or progress["stage"])
            window_start, lead_reference, lead_reference_label = student_earliest_defense_date(
                selected_student, stage_defense_type or progress["stage"]
            )
            window_end = window_start + timedelta(days=60)
            stage_outcome = latest_defense_outcome(selected_student, progress["gate"])
            context["defense_type"] = stage_defense_type
            context["schedulable_types"] = (
                [stage_defense_type]
                if stage_defense_type and not (stage_outcome and (stage_outcome["complete"] or stage_outcome["effect"] in REVISION_EFFECTS))
                else []
            )
            context["verdict_outcome"] = stage_outcome
            context["lead_reference"] = {"date": iso(lead_reference), "label": lead_reference_label, "days": lead_days}
            context["change_requesters"] = list(SCHEDULE_CHANGE_REQUESTERS)
            context["availability"] = defense_availability_context(
                participants,
                window_start,
                window_end,
            )
            context["availability"].update({
                "today": iso(today),
                "lead_days": lead_days,
                "earliest_schedule_date": iso(window_start),
                "now": manila_now().strftime("%Y-%m-%dT%H:%M"),
            })
            for slot in context["availability"]["possible_slots"]:
                conflicts = defense_schedule_conflicts(
                    selected_student,
                    assignments,
                    parse_date(slot["date"]),
                    parse_time(slot["start"]),
                    parse_time(slot["end"]),
                    "",
                    stage_defense_type or progress["stage"],
                )
                slot["conflicts"] = conflicts
                slot["conflict_free"] = not conflicts
            context["schedules"] = [
                schedule_request_dict(s)
                for s in ScheduleRequest.query.filter_by(student_id=selected_student.id)
                .order_by(ScheduleRequest.id.desc())
                .limit(12)
                .all()
            ]
            context["availability_requests"] = [
                availability_request_dict(item)
                for item in AvailabilityRequest.query.filter_by(student_id=selected_student.id)
                .order_by(AvailabilityRequest.created_at.desc(), AvailabilityRequest.id.desc()).limit(30).all()
            ]
            if progress["gate"] in RESEARCH_GATE_DEFENSE_TYPES:
                sync_panel_invitations(selected_student, progress["gate"], notify=False)
            context["panel_invitations"] = [
                panel_invitation_dict(item)
                for item in PanelInvitation.query.filter_by(student_id=selected_student.id, gate=progress["gate"]).all()
            ]
        if slug == "practicum":
            context["practicum_record"] = practicum_record_dict(
                latest_practicum_record(selected_student.id),
                include_student=False,
            )
            context["practicum_eligibility"] = practicum_eligibility(selected_student)
        if slug == "withdrawal":
            context["withdrawal_application"] = withdrawal_application_dict(
                latest_withdrawal_application(selected_student.id),
                include_student=False,
            )
        if slug == "graduation":
            endorsement = latest_graduation_endorsement(selected_student.id)
            context["graduation_endorsement"] = graduation_endorsement_dict(endorsement, include_student=False)
            context["graduation_eligibility"] = graduation_eligibility(selected_student)

    return context


def student_search_label(student: Student | None) -> str:
    if not student:
        return ""
    return f"{student.student_number} - {student.last_name}, {student.first_name} - {student.program.code}"


def student_directory_brief(student: Student) -> dict:
    payload = student_brief(student)
    research_case = (
        ResearchCase.query.filter_by(student_id=student.id)
        .order_by(ResearchCase.opened_at.desc())
        .first()
    )
    gate = research_case.current_gate if research_case else None
    stage_by_gate = {
        "Form 1 - Title Defense": "Title Defense",
        "Form 4 - Proposal Defense Readiness": "Proposal Defense",
        "Final Defense": "Final Defense",
        "Completion Evidence": "Completed",
    }
    payload["research_stage"] = stage_by_gate.get(gate, student.current_stage)
    payload["readiness_status"] = research_case.status if research_case else "Research Gate not started"
    return payload


def identity_text(value: str | None) -> str:
    return re.sub(r"[^a-z0-9]+", "", (value or "").lower())


def student_identity_key(first_name: str, last_name: str, program_id: int | None, entry_year: int | None) -> tuple:
    return (identity_text(last_name), identity_text(first_name), program_id, entry_year)


def possible_student_identity_match(first_name: str, last_name: str, program_id: int, entry_year: int) -> Student | None:
    first_key = identity_text(first_name)
    last_key = identity_text(last_name)
    if not first_key or not last_key:
        return None
    candidates = Student.query.filter_by(program_id=program_id, entry_year=entry_year).all()
    for student in candidates:
        if identity_text(student.first_name) == first_key and identity_text(student.last_name) == last_key:
            return student
    return None


def duplicate_student_groups(limit: int = 12) -> list[dict]:
    groups: list[dict] = []
    seen: set[tuple[int, ...]] = set()

    def add_group(reason: str, students: list[Student]) -> None:
        ids = tuple(sorted(s.id for s in students))
        if len(ids) < 2 or ids in seen:
            return
        seen.add(ids)
        groups.append({
            "reason": reason,
            "students": [student_brief(s) for s in sorted(students, key=lambda st: st.id)],
        })

    by_email: dict[str, list[Student]] = {}
    by_identity: dict[tuple, list[Student]] = {}
    for student in Student.query.order_by(Student.last_name, Student.first_name).all():
        email_key = (student.email or "").strip().lower()
        if email_key:
            by_email.setdefault(email_key, []).append(student)
        key = student_identity_key(student.first_name, student.last_name, student.program_id, student.entry_year)
        if all(key):
            by_identity.setdefault(key, []).append(student)

    for email, students in by_email.items():
        if len(students) > 1:
            add_group(f"Same email: {email}", students)
    for students in by_identity.values():
        if len(students) > 1:
            sample = students[0]
            add_group(f"Same name, program, and entry year: {sample.program.code} / {sample.entry_year}", students)

    return groups[:limit]


def status_rank(status: str | None) -> int:
    ranks = {"Completed": 6, "Current": 5, "Enrolled": 5, "Failed": 3, "Missing": 1}
    return ranks.get(status or "", 0)


def student_linked_tables() -> list:
    """Every table with a ``student_id`` column, taken from the models themselves."""
    return [table for table in db.metadata.sorted_tables if "student_id" in table.c and table.name != "student"]


def merge_student_records(target: Student, source: Student, overwrite_profile: bool = False) -> dict:
    if target.id == source.id:
        raise ValueError("Choose two different student records to merge.")

    if overwrite_profile:
        target.first_name = source.first_name
        target.last_name = source.last_name
        target.email = source.email
        target.program_id = source.program_id
        target.entry_year = source.entry_year
        target.current_stage = source.current_stage
        target.standing = source.standing
        target.risk_level = source.risk_level
        target.adviser_name = source.adviser_name
    else:
        target.adviser_name = target.adviser_name or source.adviser_name

    moved = {"course_records": 0, "related_records": 0}

    target_courses = {rec.course_id: rec for rec in CourseRecord.query.filter_by(student_id=target.id).all()}
    for rec in CourseRecord.query.filter_by(student_id=source.id).all():
        existing = target_courses.get(rec.course_id)
        if existing:
            if status_rank(rec.status) > status_rank(existing.status):
                existing.status = rec.status
                existing.term_label = rec.term_label or existing.term_label
                existing.evidence_reference = rec.evidence_reference or existing.evidence_reference
                existing.updated_at = now_utc()
            db.session.delete(rec)
        else:
            rec.student_id = target.id
            moved["course_records"] += 1

    target_terms = {e.term_id: e for e in TermEnrollment.query.filter_by(student_id=target.id).all()}
    for enrollment in TermEnrollment.query.filter_by(student_id=source.id).all():
        if enrollment.term_id in target_terms:
            db.session.delete(enrollment)
        else:
            enrollment.student_id = target.id
            moved["related_records"] += 1

    target_subject_terms = {
        (item.course_id, item.term_id): item
        for item in SubjectEnrollment.query.filter_by(student_id=target.id).all()
    }
    for enrollment in SubjectEnrollment.query.filter_by(student_id=source.id).all():
        key = (enrollment.course_id, enrollment.term_id)
        existing = target_subject_terms.get(key)
        if existing:
            if status_rank(enrollment.status) > status_rank(existing.status):
                existing.status = enrollment.status
                existing.source_reference = (
                    enrollment.source_reference or existing.source_reference
                )
                existing.conflict_override = (
                    enrollment.conflict_override or existing.conflict_override
                )
                existing.cancelled_at = enrollment.cancelled_at
                existing.updated_at = now_utc()
            db.session.delete(enrollment)
        else:
            enrollment.student_id = target.id
            moved["related_records"] += 1

    target_docs = {(d.gate, d.item_name): d for d in DocumentCheck.query.filter_by(student_id=target.id).all()}
    for doc in DocumentCheck.query.filter_by(student_id=source.id).all():
        existing = target_docs.get((doc.gate, doc.item_name))
        if existing:
            if status_rank(doc.status) > status_rank(existing.status):
                existing.status = doc.status
                existing.evidence_reference = doc.evidence_reference or existing.evidence_reference
                existing.updated_at = now_utc()
            db.session.delete(doc)
        else:
            doc.student_id = target.id
            moved["related_records"] += 1

    # Everything else that points at a student is moved by table metadata, so a table added later
    # cannot be forgotten (messages, AWOL cases, advisers, verdicts, evidence, plans ...).
    merged_by_hand = {"course_record", "term_enrollment", "subject_enrollment", "document_check", "panel_assignment"}
    for table in student_linked_tables():
        if table.name in merged_by_hand:
            continue
        if table.name == "user_account":
            target_has_login = db.session.execute(
                table.select().where(table.c.student_id == target.id)
            ).first() is not None
            if target_has_login:
                # One student, one login: the duplicate's login is switched off, never left orphaned.
                values = {"student_id": None}
                if "active" in table.c:
                    values["active"] = False
                db.session.execute(table.update().where(table.c.student_id == source.id).values(**values))
            else:
                db.session.execute(table.update().where(table.c.student_id == source.id).values(student_id=target.id))
            continue
        if table.c.student_id.unique:
            # At most one row per student: keep the target's, otherwise move the source's.
            if db.session.execute(table.select().where(table.c.student_id == target.id)).first() is not None:
                db.session.execute(table.delete().where(table.c.student_id == source.id))
                continue
        result = db.session.execute(table.update().where(table.c.student_id == source.id).values(student_id=target.id))
        moved["related_records"] += result.rowcount or 0
    # The bulk updates bypassed the ORM: drop cached collections so deleting the source below
    # cannot cascade onto rows that now belong to the target.
    db.session.expire(source)

    target_panel_keys = {(p.faculty_id, p.panel_role, p.gate): p for p in PanelAssignment.query.filter_by(student_id=target.id).all()}
    for panel in PanelAssignment.query.filter_by(student_id=source.id).all():
        existing = target_panel_keys.get((panel.faculty_id, panel.panel_role, panel.gate))
        if existing:
            existing.score = max(existing.score or 0, panel.score or 0)
            db.session.delete(panel)
        else:
            panel.student_id = target.id
            moved["related_records"] += 1

    source_label = f"{source.name} ({source.student_number})"
    db.session.delete(source)
    target.updated_at = now_utc()
    recompute_risk(target)
    add_log(
        "student-handoff",
        target.id,
        "GS Staff",
        "Duplicate review",
        f"Merged duplicate record into {target.student_number}",
        "GS Staff",
        f"Source record: {source_label}. Moved {moved['course_records']} course audit row(s) and {moved['related_records']} related record(s).",
    )
    return moved


def add_log(
    slug: str,
    student_id: int | None,
    actor: str,
    source: str,
    result: str,
    next_owner: str,
    notes: str,
    previous_status: str | None = None,
    new_status: str | None = None,
    visibility: str = "student_visible",
) -> TransactionLog:
    # Every workflow records what happened, who acted, where the evidence came
    # from, and who owns the next action.
    next_owner = normalize_owner_label(next_owner) if next_owner else next_owner
    # The log columns are 160 characters; MySQL (strict mode) refuses longer text, SQLite would not.
    source = (source or "")[:160]
    result = (result or "")[:160]
    close_finished_workflow_tasks(slug, student_id, actor, result, new_status)
    account = current_account() if has_request_context() else None
    record = (
        workflow_case_record(slug, student_id)
        if student_id and slug in {
            "practicum",
            "withdrawal",
            "graduation",
            "awol",
            "leave-of-absence",
            "readmission",
        }
        else None
    )
    log = TransactionLog(
        transaction_slug=slug,
        student_id=student_id,
        workflow_request_id=record.id if record else None,
        actor_user_id=account.id if account else None,
        action_type=workflow_transition_action(result),
        visibility=visibility if visibility in {"student_visible", "internal"} else "student_visible",
        actor_role=actor,
        source_reference=source,
        result=result,
        next_owner=next_owner,
        notes=notes,
        previous_status=previous_status,
        new_status=new_status,
    )
    db.session.add(log)
    add_student_transition_notice(
        slug,
        student_id,
        result,
        next_owner,
        previous_status,
        new_status,
    )
    return log


# Tasks that belong to each workflow, recognised by words in the title. Research-side workflows
# (research gate, panel matching, defense scheduling) and LOA/readmission close their own tasks
# elsewhere and are deliberately not listed here.
WORKFLOW_TASK_MARKERS = {
    "student-handoff": ("admission handoff", "student handoff"),
    "practicum": ("practicum",),
    "withdrawal": ("withdrawal",),
    "graduation": ("graduation",),
    "awol": ("awol", "refresher", "maximum residence", "residency"),
}
# A log entry that moves a case into one of these statuses ends the workflow for that student, so
# every task still open for it is closed whoever owns it.
WORKFLOW_FINAL_STATUSES = {
    "withdrawal": {"Denied", "Exported - Ready to Send", "Withdrawn Confirmed", "Sent to Registrar"},
    "practicum": {"Dean Reviewed"},
}
# Words in a log result that mean "only a message was sent, nothing was completed".
_MESSAGE_ONLY_RESULT_SUFFIXES = ("message sent", "forwarded with a note")


def _tasks_created_this_transaction() -> list:
    return db.session.info.setdefault("fresh_tasks", [])


def close_finished_workflow_tasks(
    slug: str,
    student_id: int | None,
    actor: str | None,
    result: str | None = None,
    new_status: str | None = None,
) -> int:
    """Close the open tasks a recorded workflow step has just completed.

    Recording a step (``add_log``) means the office that acted has done its part, so that
    office's earlier open tasks for this student in this workflow are finished. A step that ends
    the workflow closes every open task of it. Tasks created in the same transaction (the work
    this step hands on) are never closed here.
    """
    markers = WORKFLOW_TASK_MARKERS.get(slug)
    if not markers or not student_id:
        return 0
    final = new_status in WORKFLOW_FINAL_STATUSES.get(slug, ())
    actor_owner = canonical_owner_role(actor)
    message_only = (result or "").lower().endswith(_MESSAGE_ONLY_RESULT_SUFFIXES)
    if not final and (not actor_owner or message_only):
        return 0
    fresh = {id(task) for task in _tasks_created_this_transaction()}
    closed = 0
    for task in Task.query.filter(
        Task.student_id == student_id,
        Task.status.in_(["Pending", "Overdue"]),
    ).all():
        if id(task) in fresh:
            continue
        if not any(marker in task.title.lower() for marker in markers):
            continue
        if final or canonical_owner_role(task.owner_role) == actor_owner:
            task.status = "Done"
            closed += 1
    return closed


def _forget_fresh_tasks(session, *_args) -> None:
    session.info.pop("fresh_tasks", None)


event.listen(Session, "after_commit", _forget_fresh_tasks)
event.listen(Session, "after_soft_rollback", _forget_fresh_tasks)


def close_tasks_of_finished_workflows() -> int:
    """Startup clean-up: close open tasks left behind by workflows that already finished.

    Older databases kept such tasks forever, which inflated "open" and "overdue" counts.
    Only the student's latest case is looked at, so a newer active request keeps its tasks.
    """
    closed = 0
    for slug, finder, final_statuses in (
        ("withdrawal", latest_withdrawal_application, WORKFLOW_FINAL_STATUSES["withdrawal"]),
        ("practicum", latest_practicum_record, WORKFLOW_FINAL_STATUSES["practicum"]),
    ):
        markers = WORKFLOW_TASK_MARKERS[slug]
        open_by_student: dict[int, list[Task]] = {}
        for task in Task.query.filter(Task.status.in_(["Pending", "Overdue"])).all():
            if any(marker in task.title.lower() for marker in markers):
                open_by_student.setdefault(task.student_id, []).append(task)
        for student_id, tasks in open_by_student.items():
            record = finder(student_id)
            if record and record.status in final_statuses:
                for task in tasks:
                    task.status = "Done"
                    closed += 1
    if closed:
        db.session.commit()
    return closed


def add_task(student_id: int, title: str, owner: str, days: int, priority: int = 20, status: str = "Pending") -> None:
    # Tasks make workflow follow-ups visible in the Work Queue.
    task = Task(
        student_id=student_id,
        title=title,
        owner_role=normalize_owner_label(owner),
        due_at=date.today() + timedelta(days=days),
        priority=priority,
        status=status,
    )
    db.session.add(task)
    _tasks_created_this_transaction().append(task)


def ensure_task(student_id: int, title: str, owner: str, due_at: date, priority: int = 20, status: str = "Pending") -> Task:
    existing = (
        Task.query.filter(
            Task.student_id == student_id,
            Task.title == title,
            Task.owner_role == owner,
            Task.status.in_(["Pending", "Overdue"]),
        )
        .order_by(Task.due_at.asc(), Task.id.asc())
        .first()
    )
    if existing:
        existing.due_at = min(existing.due_at, due_at)
        existing.priority = max(existing.priority or 0, priority)
        if status == "Overdue" or existing.due_at < date.today():
            existing.status = "Overdue"
        return existing
    task = Task(
        student_id=student_id,
        title=title,
        owner_role=owner,
        due_at=due_at,
        priority=priority,
        status=status,
    )
    db.session.add(task)
    return task



# ---------------------------------------------------------------------------
# Student Handoff via file upload — AC Student Monitoring sheet importer
# ---------------------------------------------------------------------------
def _norm(value) -> str:
    return "" if value is None else str(value).strip()


def parse_class_list_rows(file) -> list[dict]:
    """Read CSV/XLSX class-list rows using normalized, uppercase headers."""
    import csv as _csv
    import io as _io

    name = (file.filename or "").lower()
    rows: list[dict] = []
    if name.endswith((".xlsx", ".xlsm")):
        import openpyxl

        wb = openpyxl.load_workbook(file, data_only=True, read_only=True)
        ws = wb.active
        grid = [[_norm(c.value) for c in row] for row in ws.iter_rows()]
        header_idx = next(
            (i for i, row in enumerate(grid) if any("ID" in (value or "").upper() for value in row)),
            0,
        )
        headers = [_norm(value).upper() for value in grid[header_idx]]
        for row in grid[header_idx + 1:]:
            rows.append({
                headers[index]: (row[index] if index < len(row) else "")
                for index in range(len(headers))
            })
        return rows

    text = file.read().decode("utf-8-sig", errors="replace")
    reader = _csv.DictReader(_io.StringIO(text))
    for row in reader:
        rows.append({
            (key or "").strip().upper(): (value or "").strip()
            for key, value in row.items()
        })
    return rows


def class_list_value(row: dict, *keys: str) -> str:
    for key in keys:
        normalized_key = key.replace(" ", "").replace("_", "")
        for header, value in row.items():
            if header.replace(" ", "").replace("_", "") == normalized_key:
                return (value or "").strip()
    return ""


def class_list_has_faculty_header(rows: list[dict]) -> bool:
    normalized_headers = {
        str(header or "").replace(" ", "").replace("_", "").upper()
        for row in rows
        for header in row
    }
    return bool(normalized_headers.intersection({"FACULTY", "FACULTYNAME", "INSTRUCTOR"}))


# ---- Class-list import: one evaluation shared by the preview and the import ----
CLASS_LIST_PLACEHOLDER_FACULTY = {"to be confirmed", "tbc", "tba", "to be announced", "n/a", "na", "-", "none"}
CLASS_LIST_ENROLL_STATUSES = {"", "enrolled", "current"}
CLASS_LIST_DROP_STATUSES = {"dropped", "drop"}


def _class_list_normalized_year(text: str) -> str:
    """'2025-2026', 'AY 2025-2026' or '25-26' -> '2025-2026' ('' when unreadable)."""
    match = re.search(r"(\d{2,4})\s*-\s*(\d{2,4})", text or "")
    if not match:
        return ""
    start = int(match.group(1))
    start = start + 2000 if start < 100 else start
    return f"{start}-{start + 1}"


def _class_list_file_term(year_text: str, term_text: str) -> tuple[str, str]:
    """The (academic year, semester) a class-list row claims, normalized like a term label."""
    year = _class_list_normalized_year(year_text)
    cleaned = (term_text or "").strip()
    if cleaned and not re.search(r"sem|term", cleaned, flags=re.IGNORECASE):
        cleaned = f"{cleaned} Semester"
    _, semester = split_academic_term_label(f"{year} {cleaned}") if cleaned else ("", "")
    return year, semester


def _class_list_date(text: str) -> date | None:
    value = (text or "").strip()
    if not value:
        return None
    for pattern in ("%Y-%m-%d", "%m/%d/%Y", "%d-%b-%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(value[:10] if pattern == "%Y-%m-%d" else value, pattern).date()
        except ValueError:
            continue
    raise ValueError(value)


def evaluate_class_list_row(row: dict, term: AcademicTerm, academic_year: str, semester: str, seen_faculty: dict) -> dict | None:
    """Decide what one class-list row means. Shared by the preview and the import so they
    always agree. Returns None for an empty row. `reason` names the skip counter."""
    sid = class_list_value(row, "STUDENTID", "IDNUMBER", "IDNO", "ID")
    code = class_list_value(row, "SUBJECTCODE", "CODE", "SUBJECT")
    faculty_value = class_list_value(row, "FACULTY", "FACULTYNAME", "INSTRUCTOR")
    status_value = class_list_value(row, "ENROLLMENTSTATUS", "STATUS")
    date_value = class_list_value(row, "STATUSEFFECTIVEDATE", "EFFECTIVEDATE")
    file_year = class_list_value(row, "ACADEMICYEAR", "AY", "SCHOOLYEAR")
    file_term = class_list_value(row, "TERM", "SEMESTER")
    remarks = class_list_value(row, "REMARKS", "NOTE", "NOTES")
    if not sid and not code and not faculty_value:
        return None
    result = {
        "status": "ready", "message": "Ready to import", "reason": "", "sid": sid, "code": code,
        "faculty_value": faculty_value, "first_name": class_list_value(row, "FIRSTNAME", "FIRST NAME"),
        "last_name": class_list_value(row, "LASTNAME", "LAST NAME"),
        "program": class_list_value(row, "PROGRAM", "PROGRAMCODE"),
        "student": None, "course": None, "offered": None, "faculty": None, "existing": None,
        "desired": "Enrolled", "effective_date": None, "remarks": remarks,
        "approved_faculty": None, "fill_faculty": False, "already_enrolled": False,
    }

    def fail(reason: str, message: str, status: str = "error") -> dict:
        result.update({"status": status, "reason": reason, "message": message})
        return result

    if not sid:
        return fail("no_student", "Student ID is required.")
    student = Student.query.filter_by(student_number=sid).first()
    if not student:
        return fail("not_found", "Student was not found.")
    result.update({
        "student": student, "first_name": student.first_name, "last_name": student.last_name,
        "program": student.program.code if student.program else result["program"],
    })
    # The file's own semester must be the semester it is imported into.
    if file_year or file_term:
        year, sem = _class_list_file_term(file_year, file_term)
        if (file_year and year != academic_year) or (file_term and sem != semester):
            named = " ".join(part for part in (file_year, file_term) if part)
            return fail(
                "term_mismatch",
                f"This row is for {named}, but the list is being imported into {term.label}. "
                "Choose the matching semester or correct the file.",
            )
    if not code:
        return fail("no_subject", "Subject code is required.")
    course = Course.query.filter_by(program_id=student.program_id, code=code).first()
    if not course:
        return fail("not_offered", "Subject is not in this student's program.")
    result["course"] = course
    offered = CurriculumOffering.query.filter_by(
        program_id=student.program_id, academic_year=academic_year, semester=semester, course_id=course.id,
    ).first()
    if not offered:
        return fail("not_offered", "Subject is not officially offered this semester.")
    result["offered"] = offered
    status_key = status_value.strip().lower()
    if status_key in CLASS_LIST_DROP_STATUSES:
        result["desired"] = "Dropped"
    elif status_key not in CLASS_LIST_ENROLL_STATUSES:
        return fail(
            "unsupported_status",
            f"Status '{status_value}' is not handled by the class list. A withdrawal goes through the "
            "Withdrawal workflow and completion comes from the monitoring sheet.",
        )
    try:
        effective = _class_list_date(date_value)
    except ValueError:
        return fail("bad_date", f"Status effective date '{date_value}' is not a valid date (use YYYY-MM-DD).")
    if effective and term.start_date and term.end_date and not (term.start_date <= effective <= term.end_date):
        return fail(
            "bad_date",
            f"Status effective date {effective.isoformat()} is outside {term.label} "
            f"({term.start_date.isoformat()} to {term.end_date.isoformat()}).",
        )
    result["effective_date"] = effective
    if not faculty_value:
        return fail("no_faculty", "Faculty is required.")
    faculty = None
    if faculty_value.strip().lower() not in CLASS_LIST_PLACEHOLDER_FACULTY:
        faculty = Faculty.query.filter(
            Faculty.active.is_(True),
            or_(
                func.lower(Faculty.name) == faculty_value.lower(),
                func.lower(Faculty.email) == faculty_value.lower(),
            ),
        ).first()
        if not faculty:
            return fail("invalid_faculty", "Faculty was not found or is inactive.")
        if faculty.college != student.program.college:
            return fail("invalid_faculty", f"Faculty must belong to {student.program.college}.")
        previous = seen_faculty.get(offered.id)
        if previous and previous != faculty.id:
            return fail("faculty_conflict", "Conflicting faculty for the same offered subject.")
        seen_faculty[offered.id] = faculty.id
    result["faculty"] = faculty
    record = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
    if record and record.status == "Completed":
        return fail("completed", "Already completed; review is required before import.")
    existing = SubjectEnrollment.query.filter_by(
        student_id=student.id, course_id=course.id, term_id=term.id
    ).first()
    result["existing"] = existing
    if result["desired"] == "Enrolled":
        block = student_enrollment_block_reason(student, term)
        if block:
            return fail("blocked_standing", block)
        if existing and existing.status in {"Dropped", "Withdrawn"}:
            return fail(
                "already_dropped",
                f"Already recorded {existing.status} for {term.label}; it cannot be silently re-enrolled. "
                "The Academic Coordinator re-enrolls it from the Enrollment screen if that is intended.",
            )
        other_active = SubjectEnrollment.query.filter(
            SubjectEnrollment.student_id == student.id,
            SubjectEnrollment.course_id == course.id,
            SubjectEnrollment.term_id != term.id,
            SubjectEnrollment.status.in_(ACTIVE_SUBJECT_ENROLLMENT_STATUSES),
        ).first()
        if other_active:
            return fail(
                "active_other_term",
                f"Already {other_active.status.lower()} in {other_active.term.label}; the same subject cannot "
                "be active in two semesters.",
            )
        if faculty and offered.assigned_faculty_id and offered.assigned_faculty_id != faculty.id:
            approved = db.session.get(Faculty, offered.assigned_faculty_id)
            result["approved_faculty"] = approved
            result.update({
                "status": "warning", "reason": "faculty_mismatch",
                "message": (
                    f"The list names {faculty.name}, but the approved faculty for this offering is "
                    f"{approved.name if approved else 'another faculty member'}. The student is enrolled; "
                    "the approved faculty is kept."
                ),
            })
        elif faculty and not offered.assigned_faculty_id:
            result["fill_faculty"] = True
        if existing and existing.status in ACTIVE_SUBJECT_ENROLLMENT_STATUSES:
            result["already_enrolled"] = True
            if result["status"] == "ready":
                result.update({"status": "warning", "reason": "already_enrolled",
                               "message": "Already enrolled; no duplicate will be created."})
        return result
    # Dropped row
    if existing and existing.status in {"Dropped", "Withdrawn"}:
        return fail("already_dropped", f"Already recorded {existing.status}; nothing to change.", "warning")
    effective_text = f" effective {effective.isoformat()}" if effective else ""
    result["message"] = f"Will be recorded as Dropped{effective_text}"
    return result


def apply_class_list_row(item: dict, term: AcademicTerm, filename: str, actor: str) -> str:
    """Write one evaluated class-list row. Returns 'enrolled' or 'dropped'."""
    student, course = item["student"], item["course"]
    effective = item["effective_date"]
    effective_at = datetime.combine(effective, time.min) if effective else None
    record = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
    if item["desired"] == "Dropped":
        ledger = item["existing"]
        if not ledger:
            ledger = SubjectEnrollment(student_id=student.id, course_id=course.id, term_id=term.id)
            db.session.add(ledger)
        previous = ledger.status if ledger.id else "Missing"
        changed_at = now_utc()
        ledger.status = "Dropped"
        ledger.source_reference = f"Class list import ({filename})"[:160]
        ledger.status_note = item["remarks"] or f"Dropped per class list import ({filename})."
        ledger.status_changed_at = changed_at
        ledger.cancelled_at = effective_at or changed_at
        ledger.updated_at = changed_at
        if not record:
            record = CourseRecord(student_id=student.id, course_id=course.id)
            db.session.add(record)
        record.status = "Dropped"
        record.term_label = term.label
        record.evidence_reference = f"Class list import ({filename})"
        record.remarks = "Dropped" + (f" effective {effective.isoformat()}" if effective else "") + " per class list import."
        record.updated_at = changed_at
        db.session.flush()
        remaining_active = SubjectEnrollment.query.filter(
            SubjectEnrollment.student_id == student.id,
            SubjectEnrollment.term_id == term.id,
            SubjectEnrollment.id != ledger.id,
            SubjectEnrollment.status.in_(ACTIVE_SUBJECT_ENROLLMENT_STATUSES),
        ).count()
        if not remaining_active:
            term_row = TermEnrollment.query.filter_by(student_id=student.id, term_id=term.id).first()
            if term_row:
                term_row.status = "Confirmed"
                term_row.source_reference = "Class list import"
                term_row.confirmed_at = changed_at
            if student.enrollment_tag == "Enrolled":
                student.enrollment_tag = "Not Enrolled"
        add_log("enrollment", student.id, actor, "Class list import",
                f"{course.code} recorded as Dropped for {term.label}.", "Student",
                f"From the uploaded class list. {previous} -> Dropped."
                + (f" Effective {effective.isoformat()}." if effective else ""),
                previous_status=previous, new_status="Dropped")
        return "dropped"
    previous = record.status if record else "Missing"
    if not record:
        record = CourseRecord(student_id=student.id, course_id=course.id)
        db.session.add(record)
    record.status = "Enrolled"
    record.term_label = term.label
    record.evidence_reference = f"Class list import ({filename})"
    record.updated_at = now_utc()
    ledger = sync_subject_enrollment_from_course_record(student, course, term.label, "Enrolled", "Class list import")
    if ledger is not None:
        # Keep the source file's name with the enrollment (walkthrough: retain the class list reference).
        ledger.source_reference = f"Class list import ({filename})"[:160]
        if effective_at and not item["existing"]:
            ledger.enrolled_at = effective_at
    if student.enrollment_tag != "Enrolled":
        student.enrollment_tag = "Enrolled"
    if student.current_stage == "Admission":
        student.current_stage = "Coursework"
    add_log("enrollment", student.id, actor, "Class list import",
            f"Tagged {student.name} as Enrolled in {course.code} for {term.label}.",
            "Academic Coordinator",
            f"Bulk enrollment tag from uploaded class list. {previous} -> Enrolled.",
            previous_status=previous, new_status="Enrolled")
    return "enrolled"


def _entry_year_from_ay(ay: str) -> int:
    """'23-24' -> 2023, '2023-2024' -> 2023, fallback to current year."""
    m = re.search(r"(\d{2,4})", ay or "")
    if not m:
        return date.today().year
    n = int(m.group(1))
    return n if n >= 1900 else 2000 + n


def academic_year_start(term: AcademicTerm | None = None) -> int:
    term = term or get_active_term()
    match = re.search(r"(\d{4})\s*-\s*\d{4}", term.label if term else "")
    if match:
        return int(match.group(1))
    today = date.today()
    return today.year if today.month >= 6 else today.year - 1


def academic_year_start_on(day: date) -> int:
    """The calendar year in which the academic year containing `day` began (June rollover)."""
    return day.year if day.month >= 6 else day.year - 1


def years_in_program(student: Student, as_of: date | None = None, term: AcademicTerm | None = None) -> int | None:
    """THE one count of a student's years in the program (course year and residency).

    The entry academic year is year 1, and the count steps up at the academic-year boundary
    (June), not on 1 January. It is never reduced by leave of absence: the handbook's maximum
    residence includes time on leave (rule residency.includes_loa). `term` measures up to that
    semester's academic year; otherwise up to `as_of`, which defaults to today.
    """
    entry_year = int(student.entry_year or _entry_year_from_ay(student.academic_year_entry or "") or 0)
    if not entry_year:
        return None
    start = academic_year_start(term) if term is not None else academic_year_start_on(as_of or date.today())
    return max(1, start - entry_year + 1)


def student_current_course_year(student: Student, term: AcademicTerm | None = None) -> int | None:
    return years_in_program(student, term=term or get_active_term())


def student_academic_year_entry(student: Student) -> str:
    """Return the source AY Entry label, with a legacy-safe derived fallback."""
    if (student.academic_year_entry or "").strip():
        return student.academic_year_entry.strip()
    year = int(student.entry_year or 0)
    if not year:
        return ""
    return f"{year % 100:02d}-{(year + 1) % 100:02d}"


def clean_person_name(value: str) -> str:
    """Registrar sheets often store names in ALL CAPS (e.g. 'YU', 'MA. LORIANNE').
    Normalize to a clean display case so 'MIGUEL YU' becomes 'Miguel Yu'."""
    parts = re.split(r"\s+", (value or "").strip())
    return " ".join(part[:1].upper() + part[1:].lower() if part else part for part in parts).strip()


def parse_ac_monitoring(stream) -> dict:
    """Parse an AC Student Monitoring .xlsx into a structured payload.

    Layout: A1 = 'PROGRAM: <code>'. A two-row header (row N has IDNO/COURSE/YR,
    row N+1 has AY ENTRY/SN/FN and the subject codes), then one student per row.
    """
    import openpyxl  # imported lazily so the rest of the app has no hard dependency

    wb = openpyxl.load_workbook(stream, data_only=True, read_only=True)
    ws = wb.active
    max_col = ws.max_column or 40

    grid = [[_norm(c.value) for c in row] for row in ws.iter_rows(min_row=1, max_row=ws.max_row)]

    def cell(r, c):  # 1-indexed helpers over the cached grid
        if 1 <= r <= len(grid) and 1 <= c <= len(grid[r - 1]):
            return grid[r - 1][c - 1]
        return ""

    program_code = ""
    for r in range(1, min(5, len(grid)) + 1):
        for c in range(1, min(6, max_col) + 1):
            v = cell(r, c)
            if v and "PROGRAM" in v.upper():
                program_code = v.split(":", 1)[1].strip() if ":" in v else v.upper().replace("PROGRAM", "").strip()
                break
        if program_code:
            break

    # header row = the one containing IDNO and COURSE
    hdr = None
    for r in range(1, min(15, len(grid)) + 1):
        rowvals = [cell(r, c).upper() for c in range(1, max_col + 1)]
        if "IDNO" in rowvals and "COURSE" in rowvals:
            hdr = r
            break
    if not hdr:
        raise ValueError("Could not find the header row (expected an 'IDNO' and 'COURSE' header).")
    sub = hdr + 1

    def find(row, label):
        for c in range(1, max_col + 1):
            if cell(row, c).upper() == label:
                return c
        return None

    idno_c = find(hdr, "IDNO")
    course_c = find(hdr, "COURSE")
    yr_c = find(hdr, "YR")
    note_c = find(hdr, "NOTE")
    sn_c = find(sub, "SN")
    fn_c = find(sub, "FN")
    ay_c = find(sub, "AY ENTRY") or 1
    milestone_cols = {m: find(sub, m) for m in ("TITLE", "PROPOSAL", "ETHICS", "FINAL")}
    compre_c = find(hdr, "COMPRE") or find(sub, "COMPRE")

    stop_cols = [c for c in list(milestone_cols.values()) + [note_c] if c]
    milestone_start = min(stop_cols) if stop_cols else max_col + 1

    subjects = []  # (col, code, title)
    subject_categories = {}  # code -> Basic / Major / Cognate
    subject_titles = {}  # code -> display title copied from the sheet header
    current_group = "Core"
    group_map = {"BASIC": "Basic", "MAJOR": "Major", "COGNATE": "Cognate", "COMPRE": "Comprehensive"}
    if yr_c:
        for c in range(yr_c + 1, milestone_start):
            group_label = cell(hdr, c).upper()
            if group_label in group_map:
                current_group = group_map[group_label]
            code = cell(sub, c)
            if not code or code == "-" or code.isdigit() or code.upper() in ("SN", "FN", "TOTAL"):
                continue
            if group_label == "TOTAL":
                continue
            title = code
            subjects.append((c, code, title))
            subject_categories[code] = current_group
            subject_titles[code] = title

    rows = []
    issues = []
    last_ay = None
    for r in range(sub + 1, len(grid) + 1):
        idno = cell(r, idno_c) if idno_c else ""
        ay_here = cell(r, ay_c) if ay_c else ""
        if ay_here:
            last_ay = ay_here
        last = cell(r, sn_c) if sn_c else ""
        first = cell(r, fn_c) if fn_c else ""
        if not idno and not last and not first:
            continue
        subj = {code: bool(cell(r, c)) for c, code, _title in subjects}
        milestones = {m: bool(cell(r, mc)) for m, mc in milestone_cols.items() if mc}
        rows.append({
            "row": r,
            "idno": idno,
            "last_name": last,
            "first_name": first,
            "course": cell(r, course_c) if course_c else "",
            "year": cell(r, yr_c) if yr_c else "",
            "ay_entry": ay_here or last_ay or "",
            "subjects": subj,
            "milestones": milestones,
            "comprehensive_exam_passed": bool(cell(r, compre_c)) if compre_c else False,
            "note": cell(r, note_c) if note_c else "",
        })

        missing = []
        if not idno:
            missing.append("Student ID")
        if not first:
            missing.append("First name")
        if not last:
            missing.append("Last name")
        if not (ay_here or last_ay):
            missing.append("School year / AY Entry")
        if missing:
            issues.append({
                "row": r,
                "type": "Missing required fields",
                "student_name": f"{first} {last}".strip() or idno or f"Row {r}",
                "message": f"Missing: {', '.join(missing)}.",
                "fields": missing,
            })

    if not program_code:
        program_code = "IMPORT"
    return {
        "program_code": program_code,
        "subjects": [s[1] for s in subjects],
        "subject_categories": subject_categories,
        "subject_titles": subject_titles,
        "rows": rows,
        "issues": issues,
    }


def _stage_from_sheet(milestones: dict, completed_subjects: int, comprehensive_exam_passed: bool = False) -> str:
    if not comprehensive_exam_passed:
        return "Coursework" if completed_subjects > 0 else "Admission"
    if milestones.get("FINAL"):
        return "Final Defense"
    if milestones.get("ETHICS"):
        return "Data Collection"
    if milestones.get("PROPOSAL"):
        return "Proposal Defense"
    if milestones.get("TITLE"):
        return "Proposal Development"
    if completed_subjects > 0:
        return "Coursework"
    return "Admission"


def _sheet_student_comparison(student: Student, row: dict, course_by_code: dict[str, Course]) -> dict:
    entry_year = _entry_year_from_ay(row["ay_entry"])
    differences = []
    if (student.first_name or "").strip().lower() != (row["first_name"] or "").strip().lower():
        differences.append("first name")
    if (student.last_name or "").strip().lower() != (row["last_name"] or "").strip().lower():
        differences.append("last name")
    if student.entry_year != entry_year:
        differences.append("entry year")

    existing_records = {
        rec.course_id: rec.status
        for rec in CourseRecord.query.filter_by(student_id=student.id).all()
    }
    new_completions = []
    completion_regressions = []
    subject_comparison = []
    incoming_completed = 0
    existing_completed = 0
    for code, done in row["subjects"].items():
        course = course_by_code.get(code)
        if not course:
            continue
        incoming_status = "Completed" if done else "Missing"
        existing_status = existing_records.get(course.id, "Missing")
        if incoming_status == "Completed":
            incoming_completed += 1
        if existing_status == "Completed":
            existing_completed += 1
        if done and existing_status != "Completed":
            new_completions.append(code)
        elif not done and existing_status == "Completed":
            completion_regressions.append(code)
        subject_comparison.append({
            "code": code,
            "existing": existing_status,
            "uploaded": incoming_status,
            "changed": existing_status != incoming_status,
            "regression": code in completion_regressions,
        })

    if completion_regressions:
        differences.append(
            "previously completed subject(s) missing from upload: "
            + ", ".join(completion_regressions)
        )

    category_comparison = []
    for category in ("Basic", "Major", "Cognate"):
        matching = [course for course in course_by_code.values() if course.category == category]
        existing_units = sum((course.units or 3) for course in matching if existing_records.get(course.id) == "Completed")
        incoming_units = sum((course.units or 3) for code, done in row["subjects"].items() if done and (course := course_by_code.get(code)) and course.category == category)
        category_comparison.append({"category": category, "current": existing_units, "uploaded": incoming_units})

    return {
        "conflicting": bool(differences),
        "differences": differences,
        "incoming_completed": incoming_completed,
        "existing_completed": existing_completed,
        "incoming_total": len(row["subjects"]),
        "new_completions": new_completions,
        "completion_regressions": completion_regressions,
        "subject_comparison": subject_comparison,
        "category_comparison": category_comparison,
    }


def _monitoring_uploaded_snapshot(row: dict) -> dict:
    completed = sorted(code for code, done in row.get("subjects", {}).items() if done)
    return {
        "row": row.get("row"),
        "student_number": row.get("idno", ""),
        "first_name": row.get("first_name", ""),
        "last_name": row.get("last_name", ""),
        "name": f"{row.get('first_name', '')} {row.get('last_name', '')}".strip(),
        "course": row.get("course", ""),
        "academic_year_entry": row.get("ay_entry", ""),
        "year": row.get("year", ""),
        "subjects": row.get("subjects", {}),
        "completed_subjects": completed,
        "completed_count": len(completed),
        "milestones": row.get("milestones", {}),
        "comprehensive_exam_passed": bool(row.get("comprehensive_exam_passed")),
    }


def _monitoring_existing_snapshot(student: Student | None, course_by_code: dict[str, Course]) -> dict:
    if not student:
        return {}
    statuses = {
        rec.course_id: rec.status
        for rec in CourseRecord.query.filter_by(student_id=student.id).all()
    }
    subjects = {code: statuses.get(course.id, "Missing") for code, course in course_by_code.items()}
    completed = sorted(code for code, status in subjects.items() if status == "Completed")
    return {
        "student_id": student.id,
        "student_number": student.student_number,
        "first_name": student.first_name,
        "last_name": student.last_name,
        "name": student.name,
        "program": student.program.code,
        "academic_year_entry": student_academic_year_entry(student),
        "year": student.year_level,
        "subjects": subjects,
        "completed_subjects": completed,
        "completed_count": len(completed),
    }


def _monitoring_row_discrepancies(row, program, course_by_code, id_counts=None):
    """Return every independently detectable discrepancy for one uploaded student row."""
    student_number = str(row.get("idno") or "").strip()
    student = Student.query.filter_by(student_number=student_number).first() if student_number else None
    discrepancies: list[dict] = []

    def add(issue_type: str, *messages: str) -> None:
        clean_messages = [str(message).strip() for message in messages if str(message or "").strip()]
        discrepancies.append({"type": issue_type, "messages": clean_messages})

    required = {
        "Student ID": student_number,
        "First name": row.get("first_name"),
        "Last name": row.get("last_name"),
        "School Year / AY Entry": row.get("ay_entry"),
    }
    missing_fields = [label for label, value in required.items() if not str(value or "").strip()]
    if missing_fields:
        add("Missing required fields", "Missing: " + ", ".join(missing_fields))
    if student_number and id_counts and id_counts.get(student_number, 0) > 1:
        add("Duplicate student ID in upload", f"Student ID {student_number} appears {id_counts[student_number]} times in this workbook")
    uploaded_program_code = str(row.get("course") or "").strip().upper().split("-", 1)[0]
    if uploaded_program_code and uploaded_program_code != program.code.upper():
        add("Program mismatch", f"Row course {row['course']} does not match workbook program {program.code}")

    comparison = _sheet_student_comparison(student, row, course_by_code) if student else None
    if student:
        if student.program_id != program.id:
            add("Existing ID in another program", f"Existing program is {student.program.code}; uploaded program is {program.code}")
        name_mismatch = (
            (student.first_name or "").strip().lower() != (row.get("first_name") or "").strip().lower()
            or (student.last_name or "").strip().lower() != (row.get("last_name") or "").strip().lower()
        )
        if name_mismatch:
            uploaded_name = f"{row.get('first_name', '')} {row.get('last_name', '')}".strip()
            add("Existing ID with different name", f"Existing name is {student.name}; uploaded name is {uploaded_name}")
        uploaded_ay_entry = str(row.get("ay_entry") or "").strip()
        uploaded_entry_year = _entry_year_from_ay(uploaded_ay_entry) if uploaded_ay_entry else None
        if uploaded_entry_year and student.entry_year != uploaded_entry_year:
            add("School year mismatch", f"Existing AY Entry is {student_academic_year_entry(student)}; uploaded AY Entry is {row.get('ay_entry', '')}")
        if comparison and comparison["completion_regressions"]:
            add(
                "Subject mismatch",
                "Previously completed subjects missing in upload: " + ", ".join(comparison["completion_regressions"]),
            )
        # Portal entry is allowed (2026-10-01); an upload never silently replaces it.
        portal_conflicts = _portal_edit_conflicts(student, row)
        if portal_conflicts:
            add("Portal edit conflict", *portal_conflicts)
    elif not missing_fields:
        possible_match = possible_student_identity_match(
            row.get("first_name", ""), row.get("last_name", ""), program.id,
            _entry_year_from_ay(row.get("ay_entry", "")),
        )
        if possible_match:
            student = possible_match
            add("Existing student with different ID", f"Possible existing record is {possible_match.name} ({possible_match.student_number})")

    return student, comparison, discrepancies


def _create_monitoring_validation_issue(upload, row, student, discrepancies, course_by_code):
    if not upload:
        return None
    issue_types = [item["type"] for item in discrepancies]
    details = [message for item in discrepancies for message in item.get("messages", [])]
    issue = MonitoringValidationIssue(
        upload_id=upload.id,
        row_number=row.get("row"),
        student_id=student.id if student else None,
        incoming_student_number=row.get("idno", ""),
        incoming_name=f"{row.get('first_name', '')} {row.get('last_name', '')}".strip(),
        issue_type="; ".join(dict.fromkeys(issue_types)),
        issue_summary="; ".join(dict.fromkeys(details)),
        details_json=json.dumps(discrepancies, ensure_ascii=False),
        existing_json=json.dumps(_monitoring_existing_snapshot(student, course_by_code), ensure_ascii=False),
        uploaded_json=json.dumps(_monitoring_uploaded_snapshot(row), ensure_ascii=False),
        status="Unresolved",
    )
    db.session.add(issue)
    db.session.flush()
    return issue


# NOTE-column wording -> (standing, lifecycle stage, enrollment tag). Checked in this order.
SHEET_NOTE_STANDINGS = [
    (re.compile(r"\bawol\b|absent without (official )?leave", re.IGNORECASE), ("AWOL", "AWOL", "AWOL")),
    (re.compile(r"\bloa\b|leave of absence|\bon leave\b", re.IGNORECASE), ("On Leave", "LOA", "LOA")),
    (
        re.compile(
            r"withdr\w+ from (the )?(program|school|university|graduate school)|dropped out|\btransferred\b|^\s*withdrawn\s*$",
            re.IGNORECASE,
        ),
        ("Withdrawn", "Withdrawn", "Withdrawn"),
    ),
]


def standing_from_sheet_note(note: str | None) -> tuple[str, str, str] | None:
    """The (standing, stage, tag) a monitoring-sheet NOTE says the student is in, or None."""
    text_value = (note or "").strip()
    if not text_value:
        return None
    for pattern, outcome in SHEET_NOTE_STANDINGS:
        if pattern.search(text_value):
            return outcome
    return None


def _apply_monitoring_row(row, program, course_by_code, term, *, student=None, overwrite_completed=False, upload=None):
    student_number = str(row.get("idno") or "").strip()
    first_name = clean_person_name(row.get("first_name", ""))
    last_name = clean_person_name(row.get("last_name", ""))
    ay_entry = str(row.get("ay_entry") or "").strip()
    if not student_number or not first_name or not last_name or not ay_entry:
        raise ValueError("Student ID, first name, last name, and School Year / AY Entry are required.")
    collision = Student.query.filter_by(student_number=student_number).first()
    if collision and (not student or collision.id != student.id):
        raise ValueError(f"Student ID {student_number} already belongs to {collision.name}.")

    is_new = student is None
    if is_new:
        student = Student(student_number=student_number, program_id=program.id, standing="Active")
        db.session.add(student)
    student.student_number = student_number
    student.first_name = first_name
    student.last_name = last_name
    student.program_id = program.id
    student.entry_year = _entry_year_from_ay(ay_entry)
    student.academic_year_entry = ay_entry
    course_year = years_in_program(student, term=term) or 1
    student.year_level = str(course_year or row.get("year") or "")
    if row.get("comprehensive_exam_passed"):
        student.comprehensive_exam_status = "Passed"
    if is_new or not student.email:
        student.email = unique_student_email(first_name, last_name, student_number, student.id if not is_new else None)
    completed = sum(1 for done in row.get("subjects", {}).values() if done)
    incoming_stage = _stage_from_sheet(row.get("milestones", {}), completed, bool(row.get("comprehensive_exam_passed")))
    current_index = STAGES.index(student.current_stage) if student.current_stage in STAGES else 0
    incoming_index = STAGES.index(incoming_stage) if incoming_stage in STAGES else 0
    # A student who is on leave, AWOL or withdrawn keeps the stage their own workflow set;
    # an upload only refreshes the stage of someone in good standing.
    if is_new or (student.standing == "Active" and incoming_index >= current_index):
        student.current_stage = incoming_stage
    # The NOTE column can say the student is on leave / AWOL / withdrawn. For a NEW student
    # that is the imported standing (recorded with its source text). For an existing Active
    # student it is only reported, never applied: a change of standing has its own workflow.
    note_standing = standing_from_sheet_note(row.get("note"))
    standing_imported = None
    standing_review = None
    if note_standing and is_new:
        student.standing, student.current_stage, student.enrollment_tag = note_standing
        standing_imported = {
            "student_number": student_number, "name": f"{first_name} {last_name}",
            "note": str(row.get("note") or "").strip(), "standing": note_standing[0],
        }
    elif note_standing and student.standing == "Active":
        standing_review = {
            "student_number": student_number, "name": f"{first_name} {last_name}",
            "note": str(row.get("note") or "").strip(), "suggested_standing": note_standing[0],
        }
    if is_new:
        student.monitoring_new_student = True
        student.monitoring_imported_at = now_utc()
        student.monitoring_upload_id = upload.id if upload else None
    db.session.flush()

    subject_changes = 0
    for code, done in row.get("subjects", {}).items():
        course = course_by_code.get(code)
        if not course:
            continue
        rec = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
        if not rec:
            rec = CourseRecord(student_id=student.id, course_id=course.id, status="Missing")
            db.session.add(rec)
        new_status = "Completed" if done else "Missing"
        should_apply = is_new or done or (overwrite_completed and rec.status == "Completed")
        if should_apply and rec.source == MONITORING_MANUAL_SOURCE and rec.status == new_status and not rec.removed_at:
            continue  # the portal value already agrees with the sheet; keep its provenance
        if should_apply and rec.status != new_status:
            if rec.source == MONITORING_MANUAL_SOURCE:
                # Only reachable when staff resolved a "Portal edit conflict" in favour of the
                # sheet: the overwrite of a portal value is itself recorded.
                account, actor_name = _monitoring_actor()
                _monitoring_edit(
                    student, "import_overwrite", "status",
                    "Removed" if rec.removed_at else rec.status, new_status,
                    change_id=uuid4().hex, account=account, actor_name=actor_name, course=course,
                    reason=f"Uploaded sheet applied after staff resolved a portal edit conflict (upload #{upload.id})" if upload else "Uploaded sheet applied",
                    source="Imported",
                )
            rec.status = new_status
            subject_changes += 1
        if should_apply:
            rec.term_label = ""
            rec.evidence_reference = f"AC Student Monitoring upload #{upload.id}" if upload else "AC Student Monitoring import"
            rec.updated_at = now_utc()
            if new_status != "Missing" or (rec.source == MONITORING_MANUAL_SOURCE and not rec.removed_at):
                rec.source = "Imported" if new_status != "Missing" else None
                rec.source_user = rec.source_at = rec.source_reason = None
                rec.removed_at = rec.removed_by = rec.removal_reason = rec.removed_status = None

    if is_new and term and not standing_imported:
        db.session.add(TermEnrollment(student_id=student.id, term_id=term.id, status="Confirmed", source_reference="AC Student Monitoring import"))
        for item in onboarding_requirements():
            db.session.add(DocumentCheck(student_id=student.id, gate="Admission Handoff", item_name=item, status="Complete", evidence_reference="AC Student Monitoring import"))
    account = ensure_student_account(student, student.email) if is_new else None
    if standing_imported:
        add_log(
            "student-handoff",
            student.id,
            "GS Staff",
            f"Monitoring upload #{upload.id}" if upload else "AC Student Monitoring import",
            f"Standing imported from the monitoring sheet: {standing_imported['standing']}",
            "Academic Coordinator",
            (
                f'Standing taken from the NOTE column of the uploaded sheet: "{standing_imported["note"]}". '
                "This is an imported value, not a decision made in this system; if it needs a decision, "
                "use the leave of absence, AWOL or withdrawal workflow."
            ),
            visibility="internal",
        )
    resolved_flags = resolve_source_flags_after_monitoring_upload(student, upload)
    if resolved_flags:
        add_log(
            "aims-discrepancy",
            student.id,
            "Workflow System",
            f"Monitoring upload #{upload.id}",
            f"{resolved_flags} source-correctable monitoring flag(s) resolved",
            "Academic Coordinator",
            (
                f"The refreshed source row from {upload.original_name} resolved the flagged "
                "data condition. Official values were updated only through the upload."
            ),
            visibility="internal",
        )
    recompute_risk(student)
    return {
        "student": student,
        "is_new": is_new,
        "subject_changes": subject_changes,
        "completed": completed,
        "resolved_flags": resolved_flags,
        "initial_password": getattr(account, "initial_password", None) if account else None,
        "must_change_password": bool(account.must_change_password) if account else False,
        "standing_imported": standing_imported,
        "standing_review": standing_review,
    }


def accounts_message(created_accounts: list[dict]) -> str:
    """Sentence about the student logins an import created. Passwords are never put in
    this text: in demo mode it is the shared demo password, otherwise each one-time
    password is listed in the `accounts` array of the response, shown once."""
    if not created_accounts:
        return ""
    if any(item.get("must_change_password") for item in created_accounts):
        return (
            f" {len(created_accounts)} new student portal account(s) created. Each has its own initial password, "
            "listed below and shown only now; give it to the student, who must change it at first sign-in."
        )
    hint = demo_password_hint()
    if len(created_accounts) == 1:
        return (
            f" Portal login for {created_accounts[0]['name']}: {created_accounts[0]['email']}"
            + (f" / {hint}." if hint else ".")
        )
    return f" {len(created_accounts)} new student portal account(s) created" + (f" (password: {hint})." if hint else ".")


def import_ac_monitoring(parsed: dict, upload: MonitoringSheetUpload | None = None) -> dict:
    program = Program.query.filter_by(code=parsed["program_code"]).first()
    if not program:
        program = Program(code=parsed["program_code"], name=f"{parsed['program_code']} (imported)", college="Imported")
        db.session.add(program)
        db.session.flush()

    # ensure a Course row exists for each subject code on the sheet (for this program)
    categories = parsed.get("subject_categories", {})
    titles = parsed.get("subject_titles", {})
    course_by_code: dict[str, Course] = {}
    for code in parsed["subjects"]:
        category = categories.get(code, "Core")
        title = titles.get(code) or code
        existing = Course.query.filter_by(program_id=program.id, code=code).first()
        if not existing:
            existing = Course(program_id=program.id, code=code, title=title, units=3, category=category)
            db.session.add(existing)
            db.session.flush()
        else:
            if existing.title == existing.code and title != existing.code:
                existing.title = title
            if (existing.category or "Core") == "Core" and category != "Core":
                existing.category = category
        course_by_code[code] = existing

    term = get_active_term()

    created, updated, skipped, sample, conflicts, duplicates = 0, 0, 0, [], [], []
    validation_issues: list[MonitoringValidationIssue] = []
    created_accounts = []
    standing_from_note = []
    standing_needs_review = []
    subject_changes = 0
    students_changed = 0
    id_counts = Counter(str(row.get("idno") or "").strip() for row in parsed["rows"] if row.get("idno"))
    for row in parsed["rows"]:
        student_number = str(row.get("idno") or "").strip()
        student, comparison, discrepancies = _monitoring_row_discrepancies(
            row, program, course_by_code, id_counts
        )
        if discrepancies:
            details = [message for item in discrepancies for message in item.get("messages", [])]
            issue = _create_monitoring_validation_issue(upload, row, student, discrepancies, course_by_code)
            if issue:
                validation_issues.append(issue)
            conflict = {
                "issue_id": issue.id if issue else None,
                "incoming_student_number": student_number,
                "incoming_name": f"{row.get('first_name', '')} {row.get('last_name', '')}".strip(),
                "matched_student": student_brief(student) if student else None,
                "reason": "; ".join(details),
                "differences": details,
                "status": "Unresolved",
            }
            if comparison:
                conflict.update({
                    "incoming_completed": comparison["incoming_completed"],
                    "existing_completed": comparison["existing_completed"],
                    "total_subjects": comparison["incoming_total"],
                    "category_comparison": comparison["category_comparison"],
                })
            conflicts.append(conflict)
            skipped += 1
            continue

        existing_before = _monitoring_existing_snapshot(student, course_by_code) if student else {}
        applied = _apply_monitoring_row(row, program, course_by_code, term, student=student, upload=upload)
        student = applied["student"]
        row_subject_changes = applied["subject_changes"]
        completed = applied["completed"]
        subject_changes += row_subject_changes
        if row_subject_changes:
            students_changed += 1
        if applied.get("standing_imported"):
            standing_from_note.append(applied["standing_imported"])
        if applied.get("standing_review"):
            standing_needs_review.append(applied["standing_review"])
        if applied["is_new"]:
            created += 1
            created_accounts.append({
                "name": student.name,
                "student_number": student.student_number,
                "email": student.email,
                "password": applied.get("initial_password") or demo_password_hint(),
                "must_change_password": applied.get("must_change_password", False),
            })
        elif row_subject_changes or existing_before.get("academic_year_entry") != student.academic_year_entry:
            updated += 1
        else:
            skipped += 1
            duplicates.append({
                "incoming_student_number": student_number,
                "incoming_name": student.name,
                "matched_student": student_brief(student),
                "reason": "Student is already in the system with the same cumulative monitoring data.",
            })
        if len(sample) < 10:
            sample.append({
                "id": student.id, "name": student.name, "student_number": student.student_number,
                "program_code": program.code, "stage": student.current_stage,
                "completed": completed, "total_subjects": len(row.get("subjects", {})),
            })

    sync_program_curriculum(program)
    add_log(
        "student-handoff",
        None,
        "GS Staff",
        "AC Student Monitoring import",
        f"Monitoring sheet imported: {len(parsed['rows'])} rows, {created} new, {updated} refreshed, {skipped} skipped, {len(conflicts)} conflict(s)",
        "Academic Coordinator",
        f"Program {program.code}; {len(parsed['subjects'])} subjects; {subject_changes} subject status change(s) across {students_changed} student(s).",
    )

    return {
        "ok": True,
        "program_id": program.id,
        "program": program.code,
        "subjects": len(parsed["subjects"]),
        "rows": len(parsed["rows"]),
        "created": created,
        "updated": updated,
        "skipped": skipped,
        "duplicates": duplicates,
        "duplicate_count": len(duplicates),
        "subject_changes": subject_changes,
        "issues": parsed.get("issues", []),
        "students_changed": students_changed,
        "conflicts": conflicts,
        "conflict_count": len(conflicts),
        "validation_issues": [monitoring_validation_issue_dict(item) for item in validation_issues],
        "unresolved_count": len(validation_issues),
        "sample": sample,
        "accounts": created_accounts,
        "standing_from_note": standing_from_note,
        "standing_needs_review": standing_needs_review,
        "message": f"Imported {created} new student(s) and refreshed AY/YR for {updated} student(s) "
                   f"from the {program.code} monitoring sheet ({skipped} already in system or "
                   f"needing verification, {len(conflicts)} conflict(s))."
                   + (
                       f" {len(standing_from_note)} new student(s) came in on leave, AWOL or withdrawn (from the NOTE column)."
                       if standing_from_note else ""
                   )
                   + (
                       f" {len(standing_needs_review)} existing student(s) have a NOTE that suggests a different standing; "
                       "nothing was changed, use the matching workflow if it is right."
                       if standing_needs_review else ""
                   )
                   + (
                       accounts_message(created_accounts)
                   ),
    }


def monitoring_validation_issue_dict(issue: MonitoringValidationIssue) -> dict:
    existing = json.loads(issue.existing_json or "{}")
    uploaded = json.loads(issue.uploaded_json or "{}")
    edited = json.loads(issue.edited_json or "{}") if issue.edited_json else None
    existing_subjects = existing.get("subjects", {})
    uploaded_subjects = uploaded.get("subjects", {})
    raw_details = json.loads(issue.details_json or "[]")
    if raw_details and isinstance(raw_details[0], dict):
        discrepancies = raw_details
        details = [message for item in discrepancies for message in item.get("messages", [])]
    else:
        details = [str(item) for item in raw_details]
        legacy_types = [item.strip() for item in (issue.issue_type or "").split(";") if item.strip()]
        discrepancies = [
            {"type": issue_type, "messages": [details[index]] if index < len(details) else []}
            for index, issue_type in enumerate(legacy_types)
        ]
        if discrepancies and len(details) > len(discrepancies):
            discrepancies[-1]["messages"].extend(details[len(discrepancies):])
    subject_rows = []
    for code in sorted(set(existing_subjects) | set(uploaded_subjects)):
        uploaded_complete = bool(uploaded_subjects.get(code))
        existing_status = existing_subjects.get(code, "Missing")
        subject_rows.append({
            "code": code,
            "existing": existing_status,
            "uploaded": "Completed" if uploaded_complete else "Missing",
            "different": (existing_status == "Completed") != uploaded_complete,
            "regression": existing_status == "Completed" and not uploaded_complete,
        })
    return {
        "id": issue.id,
        "upload_id": issue.upload_id,
        "row_number": issue.row_number,
        "student_id": issue.student_id,
        "student": student_brief(issue.student) if issue.student else None,
        "incoming_student_number": issue.incoming_student_number,
        "incoming_name": issue.incoming_name,
        "issue": issue.issue_type,
        "summary": issue.issue_summary,
        "details": details,
        "discrepancies": discrepancies,
        "discrepancy_count": len(discrepancies),
        "existing": existing,
        "uploaded": uploaded,
        "edited": edited,
        "subject_comparison": subject_rows,
        "status": issue.status,
        "resolution_action": issue.resolution_action,
        "resolution_upload": {
            "id": issue.resolution_upload.id,
            "original_name": issue.resolution_upload.original_name,
            "download_url": f"/api/monitoring/uploads/{issue.resolution_upload.id}/download",
        } if issue.resolution_upload else None,
        "resolved_by": issue.resolved_by.full_name if issue.resolved_by else None,
        "resolved_at": iso(issue.resolved_at),
        "created_at": iso(issue.created_at),
    }


def _monitoring_row_from_snapshot(snapshot: dict) -> dict:
    return {
        "row": snapshot.get("row"),
        "idno": str(snapshot.get("student_number") or "").strip(),
        "first_name": str(snapshot.get("first_name") or "").strip(),
        "last_name": str(snapshot.get("last_name") or "").strip(),
        "course": str(snapshot.get("course") or "").strip(),
        "year": str(snapshot.get("year") or "").strip(),
        "ay_entry": str(snapshot.get("academic_year_entry") or "").strip(),
        "subjects": {str(code): bool(done) for code, done in (snapshot.get("subjects") or {}).items()},
        "milestones": snapshot.get("milestones") or {},
        "comprehensive_exam_passed": bool(snapshot.get("comprehensive_exam_passed")),
        "note": "",
    }


def monitoring_upload_dict(upload: MonitoringSheetUpload) -> dict:
    result = json.loads(upload.result_json or "{}")
    validation_issues = [
        monitoring_validation_issue_dict(item)
        for item in MonitoringValidationIssue.query.filter_by(upload_id=upload.id)
        .order_by(MonitoringValidationIssue.status.desc(), MonitoringValidationIssue.row_number, MonitoringValidationIssue.id)
        .all()
    ]
    unresolved_count = sum(1 for item in validation_issues if item["status"] == "Unresolved")
    return {
        "id": upload.id,
        "original_name": upload.original_name,
        "program": upload.program_code,
        "rows": upload.row_count,
        "subjects": upload.subject_count,
        "uploaded_at": iso(upload.uploaded_at),
        "created": result.get("created", 0),
        "updated": result.get("updated", 0),
        "skipped": result.get("skipped", 0),
        "conflict_count": unresolved_count,
        "unresolved_count": unresolved_count,
        "resolved_count": len(validation_issues) - unresolved_count,
        "conflicts": result.get("conflicts", []),
        "issues": validation_issues,
        "download_url": f"/api/monitoring/uploads/{upload.id}/download",
    }


# ---------------------------------------------------------------------------
# Monitoring Sheet portal entry (owner decision 2026-10-01)
# ---------------------------------------------------------------------------
# Staff and coordinators add students and subject rows and change statuses
# directly in the portal; the workbook upload stays as a second way in. Rules:
#   * every portal value is stamped "Manual entry" + who + when (+ reason);
#   * every change is written to MonitoringEdit (old -> new) and the activity log;
#   * deletes are soft (row kept, marked removed);
#   * a later import never silently overwrites a portal value: it raises a
#     "Portal edit conflict" validation issue and both facts are kept until staff
#     resolve it (see _portal_edit_conflicts).
# Grades stay out of scope.
MONITORING_MANUAL_SOURCE = "Manual entry"
MONITORING_NO_ROW_STATUSES = {"", "Missing", "Not Started", "Not Taken"}
_MONITORING_IMPORT_HINTS = ("ac student monitoring", "aims", "import", "monitoring sheet upload")
MONITORING_WRITE_ROLES = {"staff", "academic_coordinator", "admin"}


class MonitoringEntryError(ValueError):
    """A portal-entry request that cannot be accepted, with the HTTP status to use."""

    def __init__(self, message: str, status: int = 400, **extra):
        super().__init__(message)
        self.status = status
        self.extra = extra


def monitoring_record_source(record: CourseRecord | None) -> str:
    """Where a subject row's value came from: Manual entry, Imported, System or ''."""
    if not record:
        return ""
    if record.source == MONITORING_MANUAL_SOURCE:
        return MONITORING_MANUAL_SOURCE
    if (record.status or "").strip() in MONITORING_NO_ROW_STATUSES:
        return ""
    if record.source == "Imported":
        return "Imported"
    reference = (record.evidence_reference or "").strip().lower()
    if not reference or any(hint in reference for hint in _MONITORING_IMPORT_HINTS):
        return "Imported"
    return "System"


@_sa_event.listens_for(CourseRecord, "before_update")
def _course_record_drops_manual_provenance(mapper, connection, record):
    """A status changed by another workflow (enrollment, withdrawal...) must not
    keep claiming to be a manual entry."""
    if getattr(record, "_monitoring_manual_write", False) or record.source != MONITORING_MANUAL_SOURCE:
        return
    if _sa_get_history(record, "status").has_changes():
        record.source = None
        record.source_user = None
        record.source_at = None
        record.source_reason = None
        if (record.status or "") not in MONITORING_NO_ROW_STATUSES:
            record.removed_at = None
            record.removed_by = None
            record.removal_reason = None
            record.removed_status = None


def _monitoring_actor() -> tuple[UserAccount | None, str]:
    account = current_account() if has_request_context() else None
    return account, (account.full_name if account else "System")


def _monitoring_clean(value, limit: int | None = None) -> str:
    text_value = re.sub(r"\s+", " ", str(value or "")).strip()
    return text_value[:limit] if limit else text_value


def _monitoring_stamp(record: CourseRecord, account: UserAccount | None, actor_name: str, reason: str) -> None:
    """Mark a subject row as a manual entry made now by this user."""
    record._monitoring_manual_write = True
    record.source = MONITORING_MANUAL_SOURCE
    record.source_user = actor_name
    record.source_at = now_utc()
    record.source_reason = reason or None
    record.evidence_reference = "Monitoring sheet portal entry"
    record.updated_at = now_utc()


def _monitoring_edit(
    student: Student,
    action: str,
    field: str,
    old,
    new,
    *,
    change_id: str,
    account: UserAccount | None,
    actor_name: str,
    course: Course | None = None,
    reason: str = "",
    source: str = MONITORING_MANUAL_SOURCE,
) -> MonitoringEdit:
    edit = MonitoringEdit(
        student_id=student.id,
        course_id=course.id if course else None,
        change_id=change_id,
        action=action,
        field=field,
        old_value=None if old is None else str(old),
        new_value=None if new is None else str(new),
        source=source,
        reason=reason or None,
        actor_user_id=account.id if account else None,
        actor_name=actor_name,
    )
    db.session.add(edit)
    return edit


def _monitoring_log(student: Student, account: UserAccount | None, summary: str, notes: str,
                    previous: str | None = None, new: str | None = None) -> None:
    add_log(
        "student-handoff",
        student.id,
        workflow_actor_label(account) if account else "Graduate School Staff",
        "Monitoring sheet (portal entry)",
        summary,
        "Academic Coordinator",
        notes,
        previous_status=previous,
        new_status=new,
        visibility="internal",
    )


def _monitoring_ay_entry(value) -> str:
    text_value = _monitoring_clean(value, 20)
    if not re.fullmatch(r"\d{2}(?:\d{2})?\s*-\s*\d{2}(?:\d{2})?", text_value):
        raise MonitoringEntryError("School Year / AY Entry must look like 26-27 (or 2026-2027).")
    return re.sub(r"\s+", "", text_value)


def _monitoring_email_free(email: str, student: Student | None = None) -> None:
    with db.session.no_autoflush:
        student_query = Student.query.filter(func.lower(Student.email) == email.lower())
        if student:
            student_query = student_query.filter(Student.id != student.id)
        account_query = UserAccount.query.filter(func.lower(UserAccount.email) == email.lower())
        if student:
            account_query = account_query.filter(
                or_(UserAccount.student_id.is_(None), UserAccount.student_id != student.id)
            )
        if student_query.first() or account_query.first():
            raise MonitoringEntryError(f"The email {email} is already used by another account.", 409)


def monitoring_portal_create_student(data: dict) -> tuple[Student, UserAccount]:
    """Create a student from the portal with the same rules the import applies."""
    account, actor_name = _monitoring_actor()
    program = None
    if data.get("program_id") not in (None, ""):
        program = db.session.get(Program, safe_int(data.get("program_id")) or 0)
    elif _monitoring_clean(data.get("program_code")):
        program = Program.query.filter(func.upper(Program.code) == _monitoring_clean(data.get("program_code")).upper()).first()
    student_number = _monitoring_clean(data.get("student_number"), 40)
    first_name = clean_person_name(_monitoring_clean(data.get("first_name"), 80))
    last_name = clean_person_name(_monitoring_clean(data.get("last_name"), 80))
    ay_raw = _monitoring_clean(data.get("academic_year_entry"), 20)
    missing = [
        label for label, value in (
            ("Student ID", student_number), ("First name", first_name),
            ("Last name", last_name), ("School Year / AY Entry", ay_raw),
        ) if not value
    ]
    if missing:
        raise MonitoringEntryError("Missing required fields: " + ", ".join(missing) + ".")
    if not program:
        raise MonitoringEntryError("Choose a valid program for this student.")
    ay_entry = _monitoring_ay_entry(ay_raw)
    collision = Student.query.filter_by(student_number=student_number).first()
    if collision:
        raise MonitoringEntryError(
            f"Student ID {student_number} already belongs to {collision.name}.", 409,
            existing_student=student_brief(collision),
        )
    entry_year = _entry_year_from_ay(ay_entry)
    if not data.get("confirm_possible_duplicate"):
        possible = possible_student_identity_match(first_name, last_name, program.id, entry_year)
        if possible:
            raise MonitoringEntryError(
                f"{possible.name} ({possible.student_number}) is already in {program.code} with the same "
                "name and entry year. Confirm to add this as a separate student.",
                409, possible_match=student_brief(possible),
            )
    enrollment_tag = _monitoring_clean(data.get("enrollment_tag")) or "Enrolled"
    if enrollment_tag not in {"Enrolled", "Not Enrolled"}:
        raise MonitoringEntryError("Only Enrolled or Not Enrolled can be set here; LOA, AWOL and withdrawal have their own workflows.")
    email = _monitoring_clean(data.get("email"), 160).lower()
    if email:
        if "@" not in email or " " in email:
            raise MonitoringEntryError("Enter a valid email address.")
        _monitoring_email_free(email)
    term = db.session.get(AcademicTerm, safe_int(data.get("term_id")) or 0) if data.get("term_id") else get_active_term()

    student = Student(
        student_number=student_number,
        first_name=first_name,
        last_name=last_name,
        email=email or unique_student_email(first_name, last_name, student_number),
        program_id=program.id,
        entry_year=entry_year,
        academic_year_entry=ay_entry,
        current_stage="Admission",
        standing="Active",
        enrollment_tag=enrollment_tag,
        adviser_name=_monitoring_clean(data.get("adviser_name"), 120) or None,
        monitoring_new_student=True,
    )
    student.year_level = str(years_in_program(student, term=term) or 1)
    db.session.add(student)
    db.session.flush()
    if term:
        db.session.add(TermEnrollment(
            student_id=student.id, term_id=term.id, status="Confirmed",
            source_reference="Monitoring sheet portal entry",
        ))
    for item in onboarding_requirements():
        db.session.add(DocumentCheck(
            student_id=student.id, gate="Admission Handoff", item_name=item,
            status="Complete", evidence_reference="Monitoring sheet portal entry",
        ))
    login = ensure_student_account(student, student.email)
    sync_student_curriculum(student)
    db.session.flush()
    recompute_risk(student)
    change_id = uuid4().hex
    _monitoring_edit(
        student, "create_student", "record", None,
        f"{student.name} ({student.student_number}) - {program.code}, AY {ay_entry}",
        change_id=change_id, account=account, actor_name=actor_name,
    )
    _monitoring_log(
        student, account, "Student added to the monitoring sheet in the portal",
        f"{student.name} ({student.student_number}) added to {program.code}, AY entry {ay_entry}; "
        "student login account created.",
    )
    return student, login


MONITORING_STUDENT_EDIT_FIELDS = ("student_number", "first_name", "last_name", "email", "academic_year_entry", "adviser_name")


def monitoring_portal_update_student(student: Student, data: dict) -> list[dict]:
    """Edit the header fields a monitoring sheet holds. Returns the recorded changes."""
    account, actor_name = _monitoring_actor()
    reason = _monitoring_clean(data.get("reason"), 500)
    incoming: dict[str, str] = {}
    for field in MONITORING_STUDENT_EDIT_FIELDS:
        if field not in data:
            continue
        value = _monitoring_clean(data.get(field), 160)
        if field in {"first_name", "last_name"}:
            value = clean_person_name(value)
        if field == "email":
            value = value.lower()
        if field == "academic_year_entry" and value:
            value = _monitoring_ay_entry(value)
        if not value and field != "adviser_name":
            raise MonitoringEntryError(f"{field.replace('_', ' ').capitalize()} cannot be blank.")
        incoming[field] = value
    current = {
        "student_number": student.student_number,
        "first_name": student.first_name,
        "last_name": student.last_name,
        "email": student.email,
        "academic_year_entry": student_academic_year_entry(student),
        "adviser_name": student.adviser_name or "",
    }
    changes = {field: value for field, value in incoming.items() if value != current[field]}
    if not changes:
        return []
    if not reason:
        raise MonitoringEntryError("Enter a reason for this correction; it is kept in the change history.")
    if "student_number" in changes:
        collision = Student.query.filter(
            Student.student_number == changes["student_number"], Student.id != student.id
        ).first()
        if collision:
            raise MonitoringEntryError(
                f"Student ID {changes['student_number']} already belongs to {collision.name}.", 409,
                existing_student=student_brief(collision),
            )
    if "email" in changes:
        if "@" not in changes["email"] or " " in changes["email"]:
            raise MonitoringEntryError("Enter a valid email address.")
        _monitoring_email_free(changes["email"], student)

    login = UserAccount.query.filter_by(student_id=student.id, role="student").first()
    change_id = uuid4().hex
    recorded = []
    for field, value in changes.items():
        recorded.append({"field": field, "old": current[field], "new": value})
        _monitoring_edit(
            student, "update_student", field, current[field], value,
            change_id=change_id, account=account, actor_name=actor_name, reason=reason,
        )
        if field == "academic_year_entry":
            student.academic_year_entry = value
            student.entry_year = _entry_year_from_ay(value)
        elif field == "adviser_name":
            record_adviser_from_name(student, value, actor_name)  # while the old adviser is still on record
            student.adviser_name = value or None
        else:
            setattr(student, field, value)
    if "academic_year_entry" in changes:
        student.year_level = str(student_current_course_year(student) or student.year_level or "")
    if login:
        login.full_name = f"{student.name} (Student)"
        if "email" in changes:
            login.email = student.email
    student.updated_at = now_utc()
    _monitoring_log(
        student, account, "Monitoring sheet header corrected in the portal",
        "; ".join(f"{item['field']}: {item['old'] or '(blank)'} → {item['new'] or '(blank)'}" for item in recorded)
        + f". Reason: {reason}",
    )
    return recorded


def _monitoring_subject_status(value) -> str:
    status = _monitoring_clean(value)
    match = next((item for item in MONITORING_MANUAL_STATUSES if item.lower() == status.lower()), None)
    if not match:
        raise MonitoringEntryError("Choose a status: " + ", ".join(MONITORING_MANUAL_STATUSES) + ".")
    return match


def _monitoring_after_subject_change(student: Student) -> None:
    db.session.flush()
    if student.current_stage == "Admission" and CourseRecord.query.filter_by(
        student_id=student.id, status="Completed"
    ).first():
        student.current_stage = "Coursework"
    student.updated_at = now_utc()
    recompute_risk(student)


def _monitoring_course_for_row(student: Student, data: dict) -> Course:
    if data.get("course_id") not in (None, ""):
        course = db.session.get(Course, safe_int(data.get("course_id")) or 0)
        if not course:
            raise MonitoringEntryError("That subject does not exist.", 404)
        if course.program_id != student.program_id:
            raise MonitoringEntryError(f"{course.code} belongs to another program; pick a subject from {student.program.code} or enter it as free-form.")
        return course
    code = _monitoring_clean(data.get("code"), 40)
    if not code:
        raise MonitoringEntryError("Pick a curriculum subject, or enter a subject code for a free-form row.")
    in_program = Course.query.filter(Course.program_id == student.program_id, func.lower(Course.code) == code.lower()).first()
    if in_program:
        return in_program
    if Course.query.filter(func.lower(Course.code) == code.lower()).first():
        raise MonitoringEntryError(f"{code} is already used by another program's subject; use a different code for a free-form row.")
    title = _monitoring_clean(data.get("title"), 160)
    units = safe_int(data.get("units"))
    if not title or not units or not 1 <= units <= 12:
        raise MonitoringEntryError("A free-form subject needs a title and units between 1 and 12.")
    course = Course(
        program_id=student.program_id, code=code, title=title, units=units,
        category=MONITORING_FREE_FORM_CATEGORY, recommended_term="",
    )
    db.session.add(course)
    db.session.flush()
    return course


def _monitoring_row_values(data: dict) -> dict:
    values = {}
    if "term_label" in data:
        term_label = _monitoring_clean(data.get("term_label"), 60)
        if len(term_label) > 40:
            raise MonitoringEntryError("Term taken is too long (40 characters at most).")
        values["term_label"] = term_label
    if "remarks" in data:
        values["remarks"] = _monitoring_clean(data.get("remarks"), 500)
    return values


def monitoring_portal_add_subject(student: Student, data: dict) -> CourseRecord:
    account, actor_name = _monitoring_actor()
    status = _monitoring_subject_status(data.get("status"))
    values = _monitoring_row_values(data)
    reason = _monitoring_clean(data.get("reason"), 500)
    course = _monitoring_course_for_row(student, data)
    record = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
    if record and not record.removed_at and (record.status or "") not in MONITORING_NO_ROW_STATUSES:
        raise MonitoringEntryError(
            f"{course.code} already has a row for this student ({record.status}); edit that row instead.", 409,
        )
    readded = bool(record and record.removed_at)
    if not record:
        record = CourseRecord(student_id=student.id, course_id=course.id, status="Missing")
        db.session.add(record)
        db.session.flush()
    old_status = record.status or "Missing"
    old_term, old_remarks = record.term_label or "", record.remarks or ""
    record.status = status
    record.term_label = values.get("term_label", record.term_label if readded else "") or None
    record.remarks = values.get("remarks", record.remarks if readded else "") or None
    record.removed_at = record.removed_by = record.removal_reason = record.removed_status = None
    _monitoring_stamp(record, account, actor_name, reason)
    change_id = uuid4().hex
    action = "add_subject"
    kwargs = dict(change_id=change_id, account=account, actor_name=actor_name, course=course, reason=reason)
    _monitoring_edit(student, action, "status", old_status, status, **kwargs)
    if (record.term_label or "") != old_term:
        _monitoring_edit(student, action, "term_label", old_term, record.term_label or "", **kwargs)
    if (record.remarks or "") != old_remarks:
        _monitoring_edit(student, action, "remarks", old_remarks, record.remarks or "", **kwargs)
    _monitoring_after_subject_change(student)
    detail = f"{course.code} status: {old_status} → {status}"
    if record.term_label:
        detail += f"; term: {record.term_label}"
    _monitoring_log(
        student, account, f"Subject row {'re-added' if readded else 'added'} in the monitoring sheet",
        detail + (f". Reason: {reason}" if reason else ""), old_status, status,
    )
    return record


def monitoring_portal_update_subject(student: Student, record: CourseRecord, data: dict) -> tuple[CourseRecord, list[dict]]:
    account, actor_name = _monitoring_actor()
    course = record.course
    if record.removed_at:
        raise MonitoringEntryError(f"{course.code} was removed from this record; add it again to restore it.", 409)
    reason = _monitoring_clean(data.get("reason"), 500)
    changes = []  # (field, old, new, apply)
    if "status" in data:
        status = _monitoring_subject_status(data.get("status"))
        if status != (record.status or "Missing"):
            changes.append(("status", record.status or "Missing", status))
    for field, new in _monitoring_row_values(data).items():
        old = getattr(record, field) or ""
        if new != old:
            changes.append((field, old, new))
    is_free_form = (course.category or "") == MONITORING_FREE_FORM_CATEGORY
    for field in ("title", "units"):
        if field in data:
            if not is_free_form:
                raise MonitoringEntryError("Title and units of a curriculum subject come from the curriculum and cannot be edited here.")
            new = _monitoring_clean(data.get(field), 160) if field == "title" else safe_int(data.get(field))
            if field == "units" and (not new or not 1 <= new <= 12):
                raise MonitoringEntryError("Units must be between 1 and 12.")
            if field == "title" and not new:
                raise MonitoringEntryError("Title cannot be blank.")
            if new != getattr(course, field):
                changes.append((field, getattr(course, field), new))
    if not changes:
        return record, []
    if monitoring_record_source(record) in {"Imported", "System"} and not reason:
        raise MonitoringEntryError(
            "This value came from an imported/system source. Enter a reason for changing it; it is kept in the change history.",
        )
    change_id = uuid4().hex
    recorded = []
    for field, old, new in changes:
        recorded.append({"field": field, "old": old, "new": new})
        _monitoring_edit(
            student, "update_subject", field, old, new, change_id=change_id, account=account,
            actor_name=actor_name, course=course, reason=reason,
        )
        if field in {"title", "units"}:
            setattr(course, field, new)
        else:
            setattr(record, field, new or None if field != "status" else new)
    _monitoring_stamp(record, account, actor_name, reason)
    _monitoring_after_subject_change(student)
    _monitoring_log(
        student, account, "Subject row changed in the monitoring sheet",
        f"{course.code} " + "; ".join(f"{item['field']}: {item['old'] or '(blank)'} → {item['new'] or '(blank)'}" for item in recorded)
        + (f". Reason: {reason}" if reason else ""),
        next((item["old"] for item in recorded if item["field"] == "status"), None),
        next((item["new"] for item in recorded if item["field"] == "status"), None),
    )
    return record, recorded


def monitoring_portal_remove_subject(student: Student, record: CourseRecord, data: dict) -> CourseRecord:
    account, actor_name = _monitoring_actor()
    reason = _monitoring_clean(data.get("reason"), 500)
    course = record.course
    if record.removed_at:
        raise MonitoringEntryError(f"{course.code} is already removed from this record.", 409)
    if (record.status or "") in MONITORING_NO_ROW_STATUSES:
        raise MonitoringEntryError(f"{course.code} has no entry to remove.", 409)
    if not reason:
        raise MonitoringEntryError("Enter a reason for removing this row; the row is kept in the change history.")
    old_status, old_term = record.status, record.term_label or ""
    record.removed_status = old_status
    record.removed_at = now_utc()
    record.removed_by = actor_name
    record.removal_reason = reason
    record.status = "Missing"
    record.term_label = None
    _monitoring_stamp(record, account, actor_name, reason)
    change_id = uuid4().hex
    kwargs = dict(change_id=change_id, account=account, actor_name=actor_name, course=course, reason=reason)
    _monitoring_edit(student, "remove_subject", "status", old_status, "Removed", **kwargs)
    if old_term:
        _monitoring_edit(student, "remove_subject", "term_label", old_term, "", **kwargs)
    _monitoring_after_subject_change(student)
    _monitoring_log(
        student, account, "Subject row removed from the monitoring sheet",
        f"{course.code} status: {old_status} → removed (row kept in history). Reason: {reason}",
        old_status, "Removed",
    )
    return record


def monitoring_portal_bulk_add_remaining(program: Program, data: dict) -> dict:
    """Add every curriculum subject a student has not taken as a Planned row."""
    account, actor_name = _monitoring_actor()
    status = _monitoring_subject_status(data.get("status") or "Planned")
    if status != "Planned":
        raise MonitoringEntryError("Only Planned can be added in bulk; set other statuses one subject at a time.")
    term_label = _monitoring_clean(data.get("term_label"), 40)
    curriculum = monitoring_curriculum_courses(program)
    if data.get("course_ids"):
        wanted = {safe_int(item) for item in data.get("course_ids")}
        curriculum = [course for course in curriculum if course.id in wanted]
    if data.get("student_ids"):
        ids = {safe_int(item) for item in data.get("student_ids")}
        students = Student.query.filter(Student.program_id == program.id, Student.id.in_(ids or {-1})).all()
        if len(students) != len(ids):
            raise MonitoringEntryError("One or more students were not found in this program.", 404)
    else:
        students = Student.query.filter(
            Student.program_id == program.id,
            Student.standing.notin_(["Withdrawn", "Graduated", "Completed"]),
        ).all()
    added = touched = skipped_removed = 0
    for student in students:
        records = {item.course_id: item for item in CourseRecord.query.filter_by(student_id=student.id)}
        change_id = uuid4().hex
        student_added = []
        for course in curriculum:
            record = records.get(course.id)
            if record and record.removed_at:
                skipped_removed += 1
                continue
            if record and (record.status or "") not in MONITORING_NO_ROW_STATUSES:
                continue
            if not record:
                record = CourseRecord(student_id=student.id, course_id=course.id, status="Missing")
                db.session.add(record)
                db.session.flush()
            old_status = record.status or "Missing"
            record.status = status
            record.term_label = term_label or None
            _monitoring_stamp(record, account, actor_name, "Bulk add of remaining curriculum subjects")
            _monitoring_edit(
                student, "bulk_add_subject", "status", old_status, status, change_id=change_id,
                account=account, actor_name=actor_name, course=course,
                reason="Bulk add of remaining curriculum subjects",
            )
            student_added.append(course.code)
        if student_added:
            added += len(student_added)
            touched += 1
            _monitoring_after_subject_change(student)
            _monitoring_log(
                student, account, "Remaining curriculum subjects added as Planned",
                f"{len(student_added)} subject(s) added as {status}: {', '.join(student_added)}.",
            )
    return {"added": added, "students": touched, "skipped_removed": skipped_removed}


def _portal_edit_conflicts(student: Student, row: dict) -> list[str]:
    """Where an uploaded sheet claims a subject completed that a person edited in the portal.

    Blank cells are not a claim, so they never conflict. A portal Completed
    agrees with the sheet. Anything else (Enrolled, INC, Dropped, a removed
    row...) is kept and reported instead of overwritten.
    """
    if not student:
        return []
    done_codes = {code for code, done in (row.get("subjects") or {}).items() if done}
    if not done_codes:
        return []
    messages = []
    for record in CourseRecord.query.filter_by(student_id=student.id, source=MONITORING_MANUAL_SOURCE).all():
        code = record.course.code if record.course else ""
        if code not in done_codes:
            continue
        if record.removed_at:
            state = f"removed in the portal ({record.removal_reason or 'no reason recorded'})"
        elif record.status == "Completed":
            continue
        else:
            state = f"{record.status} in the portal"
        who = record.source_user or "a staff member"
        when = record.source_at.strftime("%Y-%m-%d") if record.source_at else "an earlier date"
        messages.append(f"{code}: {state} (manual entry by {who} on {when}); the uploaded sheet says Completed")
    return messages


def monitoring_subject_item(record: CourseRecord | None, course: Course, *, in_curriculum: bool,
                            operational: SubjectEnrollment | None = None, for_student: bool = False) -> dict:
    manual = bool(record and record.source == MONITORING_MANUAL_SOURCE)
    return {
        "record_id": record.id if record else None,
        "course_id": course.id,
        "code": course.code,
        "title": course.title,
        "units": course.units or 3,
        "category": course.category,
        "in_curriculum": in_curriculum,
        "status": ((record.status if record else "") or "Missing"),
        "term_label": (record.term_label if record else "") or "",
        "remarks": (record.remarks if record else "") or "",
        "source": monitoring_record_source(record),
        "source_by": None if for_student or not manual else record.source_user,
        "source_at": iso(record.source_at) if manual else None,
        "source_reason": None if for_student or not manual else record.source_reason,
        "evidence_reference": (record.evidence_reference if record else "") or "",
        "removed": bool(record and record.removed_at),
        "removed_at": iso(record.removed_at) if record else None,
        "removed_by": None if for_student or not record else record.removed_by,
        "removal_reason": None if for_student or not record else record.removal_reason,
        "removed_status": record.removed_status if record else None,
        "operational_status": operational.status if operational else None,
        "updated_at": iso(record.updated_at) if record else None,
    }


def monitoring_student_header(student: Student, *, for_student: bool = False) -> dict:
    created = (
        MonitoringEdit.query.filter_by(student_id=student.id, action="create_student")
        .order_by(MonitoringEdit.id).first()
    )
    last_update = (
        MonitoringEdit.query.filter_by(student_id=student.id, action="update_student")
        .order_by(MonitoringEdit.id.desc()).first()
    )
    header = student_brief(student)
    header["source"] = {
        "label": MONITORING_MANUAL_SOURCE if created else "Imported",
        "by": None if for_student or not created else created.actor_name,
        "at": iso(created.created_at) if created else iso(student.monitoring_imported_at),
        "upload_id": student.monitoring_upload_id,
    }
    header["last_change"] = None if not last_update else {
        "by": None if for_student else last_update.actor_name,
        "at": iso(last_update.created_at),
        "reason": None if for_student else last_update.reason,
    }
    return header


def monitoring_record_payload(student: Student, *, can_edit: bool, for_student: bool = False) -> dict:
    curriculum = monitoring_curriculum_courses(student.program)
    curriculum_ids = {course.id for course in curriculum}
    records = {item.course_id: item for item in CourseRecord.query.filter_by(student_id=student.id).all()}
    term = get_active_term()
    operational = {}
    if term:
        operational = {
            item.course_id: item
            for item in SubjectEnrollment.query.filter_by(student_id=student.id, term_id=term.id).all()
        }
    subjects = [
        monitoring_subject_item(records.get(course.id), course, in_curriculum=True,
                                operational=operational.get(course.id), for_student=for_student)
        for course in curriculum
    ]
    extras = sorted(
        (item for course_id, item in records.items() if course_id not in curriculum_ids and item.course),
        key=lambda item: item.course.code,
    )
    for record in extras:
        if (record.status or "") in MONITORING_NO_ROW_STATUSES and not record.removed_at:
            continue
        subjects.append(monitoring_subject_item(
            record, record.course, in_curriculum=False,
            operational=operational.get(record.course_id), for_student=for_student,
        ))
    if for_student:
        subjects = [item for item in subjects if not item["removed"]]
    audit = compute_course_audit(student)
    return {
        "student": monitoring_student_header(student, for_student=for_student),
        "subjects": subjects,
        "summary": {
            "completed_count": len(audit["completed"]),
            "required_count": audit["required_count"],
            "completed_units": audit["completed_units"],
            "total_units": audit["total_units"],
            "manual_rows": sum(1 for item in subjects if item["source"] == MONITORING_MANUAL_SOURCE and not item["removed"]),
        },
        "statuses": MONITORING_MANUAL_STATUSES,
        "permissions": {"can_edit": can_edit},
        "history_count": MonitoringEdit.query.filter_by(student_id=student.id).count(),
        "active_term": term_dict(term) if term else None,
    }


def monitoring_edit_dict(edit: MonitoringEdit) -> dict:
    return {
        "id": edit.id,
        "change_id": edit.change_id,
        "action": edit.action,
        "field": edit.field,
        "old_value": edit.old_value,
        "new_value": edit.new_value,
        "source": edit.source,
        "reason": edit.reason,
        "actor_name": edit.actor_name,
        "created_at": iso(edit.created_at),
        "course_id": edit.course_id,
        "code": edit.course.code if edit.course else None,
        "title": edit.course.title if edit.course else None,
    }


def monitoring_export_workbook(program: Program) -> bytes:
    """AC monitoring workbook for a program, including portal-entered students and rows.

    Sheet 1 follows the AC template so it can be uploaded straight back; sheets 2
    and 3 carry every subject row (with statuses the template cannot hold and the
    provenance of each value) and the portal change history.
    """
    students = (
        Student.query.filter_by(program_id=program.id)
        .order_by(Student.entry_year, Student.last_name, Student.first_name).all()
    )
    category_rank = {name: index for index, name in enumerate(["Basic", "Major", "Cognate", "Core", "Comprehensive"])}
    courses = sorted(monitoring_curriculum_courses(program), key=lambda c: category_rank.get(c.category or "Core", 99))
    records = {
        (item.student_id, item.course_id): item
        for item in CourseRecord.query.filter(CourseRecord.student_id.in_([s.id for s in students] or [-1])).all()
    }
    header_font = Font(name="Arial", size=10, bold=True)
    fill = PatternFill("solid", fgColor="DCFCE7")

    workbook = Workbook()
    sheet = workbook.active
    sheet.title = f"{program.code} monitoring"[:31]
    sheet["A1"] = f"PROGRAM: {program.code}"
    sheet["A1"].font = Font(name="Arial", size=12, bold=True)
    first_subject = 8
    last_subject = first_subject + len(courses) - 1
    compre_col = last_subject + 1
    milestone_cols = {name: compre_col + 1 + index for index, name in enumerate(["TITLE", "PROPOSAL", "ETHICS", "FINAL"])}
    note_col = compre_col + 6
    top = {3: "NAME", 5: "IDNO", 6: "COURSE", 7: "YR", compre_col: "COMPRE", note_col: "NOTE"}
    sub = {1: "AY ENTRY", 3: "SN", 4: "FN"}
    previous = None
    for offset, course in enumerate(courses):
        column = first_subject + offset
        sub[column] = course.code
        group = (course.category or "Core").upper()
        if group != previous:
            top[column] = group
            previous = group
    for name, column in milestone_cols.items():
        sub[column] = name
    for column, label in top.items():
        cell = sheet.cell(row=3, column=column, value=label)
        cell.font, cell.fill = header_font, fill
    for column, label in sub.items():
        cell = sheet.cell(row=4, column=column, value=label)
        cell.font, cell.fill = header_font, fill
    sheet.freeze_panes = "H5"
    manual_students = {
        edit.student_id: edit for edit in
        MonitoringEdit.query.filter(MonitoringEdit.action == "create_student",
                                    MonitoringEdit.student_id.in_([s.id for s in students] or [-1])).all()
    }
    for index, student in enumerate(students, 1):
        row = 4 + index
        marks = monitoring_research_milestones(student)
        sheet.cell(row=row, column=1, value=student_academic_year_entry(student))
        sheet.cell(row=row, column=2, value=index)
        sheet.cell(row=row, column=3, value=student.last_name)
        sheet.cell(row=row, column=4, value=student.first_name)
        sheet.cell(row=row, column=5, value=student.student_number)
        sheet.cell(row=row, column=6, value=program.code)
        sheet.cell(row=row, column=7, value=student.year_level or "")
        for offset, course in enumerate(courses):
            record = records.get((student.id, course.id))
            if record and record.status in {"Completed", "Taken"}:
                sheet.cell(row=row, column=first_subject + offset, value=course.units or 3)
        if (student.comprehensive_exam_status or "").lower() == "passed":
            sheet.cell(row=row, column=compre_col, value="PASSED")
        for name, column in milestone_cols.items():
            if marks.get(name.lower()):
                sheet.cell(row=row, column=column, value="Y")
        created = manual_students.get(student.id)
        if created:
            sheet.cell(row=row, column=note_col, value=f"Added in the portal by {created.actor_name} on {created.created_at:%Y-%m-%d}")

    rows_sheet = workbook.create_sheet("Subject rows")
    columns = [
        "Student ID", "Student name", "Program", "Subject code", "Subject title", "Units", "In curriculum",
        "Term taken", "Status", "Remarks", "Source", "Entered by", "Entered at", "Reason",
        "Removed", "Removed status", "Removed reason",
    ]
    for column, label in enumerate(columns, 1):
        cell = rows_sheet.cell(row=1, column=column, value=label)
        cell.font, cell.fill = header_font, fill
    curriculum_ids = {course.id for course in courses}
    by_id = {student.id: student for student in students}
    ordered = sorted(
        (item for item in records.values()
         if (item.status or "") not in MONITORING_NO_ROW_STATUSES or item.removed_at),
        key=lambda item: (by_id[item.student_id].last_name, by_id[item.student_id].first_name, item.course.code),
    )
    for row_number, record in enumerate(ordered, 2):
        student, course = by_id[record.student_id], record.course
        manual = record.source == MONITORING_MANUAL_SOURCE
        values = [
            student.student_number, student.name, program.code, course.code, course.title, course.units or 3,
            "Yes" if course.id in curriculum_ids else "No", record.term_label or "", record.status or "",
            record.remarks or "", monitoring_record_source(record),
            record.source_user if manual else "", record.source_at.strftime("%Y-%m-%d %H:%M") if manual and record.source_at else "",
            record.source_reason if manual else "",
            "Yes" if record.removed_at else "", record.removed_status or "", record.removal_reason or "",
        ]
        for column, value in enumerate(values, 1):
            rows_sheet.cell(row=row_number, column=column, value=value)

    history = workbook.create_sheet("Change history")
    history_columns = ["When", "Student ID", "Student name", "Action", "Field", "Subject", "Old value", "New value", "Reason", "By"]
    for column, label in enumerate(history_columns, 1):
        cell = history.cell(row=1, column=column, value=label)
        cell.font, cell.fill = header_font, fill
    edits = (
        MonitoringEdit.query.filter(MonitoringEdit.student_id.in_([s.id for s in students] or [-1]))
        .order_by(MonitoringEdit.id).all()
    )
    for row_number, edit in enumerate(edits, 2):
        student = by_id[edit.student_id]
        values = [
            edit.created_at.strftime("%Y-%m-%d %H:%M") if edit.created_at else "", student.student_number, student.name,
            edit.action, edit.field, edit.course.code if edit.course else "", edit.old_value or "", edit.new_value or "",
            edit.reason or "", edit.actor_name or "",
        ]
        for column, value in enumerate(values, 1):
            history.cell(row=row_number, column=column, value=value)
    for extra in (rows_sheet, history):
        extra.freeze_panes = "A2"
        for column in range(1, extra.max_column + 1):
            extra.column_dimensions[chr(64 + column)].width = 18
    buffer = io.BytesIO()
    workbook.save(buffer)
    return buffer.getvalue()


# ---------------------------------------------------------------------------
# Transaction handlers (now accept a MultiDict payload from JSON or form)
# ---------------------------------------------------------------------------
def handle_student_handoff(data: MultiDict) -> int:
    # Intake transaction: create the monitoring record, mirror the enrollment
    # signal, compare onboarding evidence, and open a follow-up if anything is missing.
    program = Program.query.get(int(data["program_id"]))
    count = Student.query.count() + 1
    student_number = (data.get("student_number") or "").strip() or f"2026-{count:04d}"
    first_name = data["first_name"].strip()
    last_name = data["last_name"].strip()
    admission_signal = (data.get("admission_signal") or "").strip()
    transcript_status = (data.get("transcript_status") or "Not verified").strip()
    source_reference = (data.get("source_reference") or "").strip()
    # Manual handoff requirements are derived from entered evidence instead of
    # relying on a five-checkbox memory test. Keep submitted items for backwards
    # compatibility with older API clients, but the current UI does not use them.
    submitted_onboarding = set(data.getlist("onboarding_items"))
    if admission_signal in {"Admission Confirmed", "Enrollment Confirmed"}:
        submitted_onboarding.add("Admission approval")
    if source_reference:
        submitted_onboarding.add("Student profile sheet")
    if program:
        submitted_onboarding.add("Program assignment")
    if data.get("term_id") and admission_signal:
        submitted_onboarding.add("Enrollment signal")
    if transcript_status == "Received":
        submitted_onboarding.add("Official transcript")
    missing_items = [item for item in onboarding_requirements() if item not in submitted_onboarding]
    missing_items.extend(split_items(data.get("additional_missing_items", "")))
    student = Student(
        student_number=student_number,
        first_name=first_name,
        last_name=last_name,
        email=(data.get("email") or "").strip().lower() or unique_student_email(first_name, last_name, student_number),
        program_id=program.id,
        entry_year=int(data.get("entry_year") or date.today().year),
        current_stage="Admission",
        standing="Active",
        risk_level="Not Yet Assessed",
    )
    db.session.add(student)
    db.session.flush()
    account = ensure_student_account(student, student.email)
    sync_student_curriculum(student)

    term = AcademicTerm.query.get(int(data["term_id"]))
    db.session.add(
        TermEnrollment(
                student_id=student.id,
                term_id=term.id,
                status=admission_signal,
                source_reference=source_reference,
        )
    )

    for item in onboarding_requirements():
        db.session.add(
            DocumentCheck(
                student_id=student.id,
                gate="Admission Handoff",
                item_name=item,
                status="Missing" if item in missing_items else "Complete",
                evidence_reference=(
                    f"Transcript status: {transcript_status}"
                    if item == "Official transcript"
                    else source_reference
                ),
            )
        )

    if missing_items:
        for item in split_items(data.get("additional_missing_items", "")):
            db.session.add(
                DocumentCheck(
                    student_id=student.id,
                    gate="Admission Handoff",
                    item_name=item,
                    status="Missing",
                    evidence_reference=data.get("source_reference", ""),
                )
            )
        add_task(student.id, "Complete admission handoff missing items", "GS Staff", 3, 40)

    add_log(
        "student-handoff",
        student.id,
        "GS Staff",
        source_reference,
        f"Monitoring record created from {admission_signal}; {len(missing_items)} onboarding item(s) missing",
        "GS Staff",
        f"Program: {program.code}; Automatically derived {len(submitted_onboarding)} received item(s) against "
        f"{len(onboarding_requirements())} required item(s). Missing: "
        f"{', '.join(missing_items) if missing_items else 'None'}. "
        f"Student portal account: {account.email}.",
    )
    return student.id


def resolve_standing_change_tasks(student_id: int, title_fragment: str, owner: str) -> None:
    for task in Task.query.filter(
        Task.student_id == student_id,
        owner_task_clause(owner),
        Task.status.in_(["Pending", "Overdue"]),
        Task.title.contains(title_fragment),
    ).all():
        task.status = "Done"


def _leave_legacy_forward(slug: str, data: MultiDict) -> int:
    """Staff forward a student's request to the Dean (older form-post entry point)."""
    account = require_workflow_actor("staff")
    student = Student.query.get_or_404(int(data["student_id"]))
    adopt_legacy_leave_logs(student.id)
    case = (
        LeaveCase.query.filter(
            LeaveCase.student_id == student.id,
            LeaveCase.kind.in_(KINDS_FOR_SLUG[slug]),
            LeaveCase.status.in_(("Submitted", "Staff Review")),
        )
        .order_by(LeaveCase.id.desc())
        .first()
    )
    if not case:
        raise ValueError("The student must submit a new request before staff can forward it to the Dean.")
    try:
        leave_case_apply(case, "forward", account, comment=(data.get("workflow_comment") or ""), data=data)
    except LeaveError as exc:
        raise ValueError(str(exc)) from exc
    return student.id


def handle_leave_of_absence(data: MultiDict) -> int:
    # The policy checker supports staff review; it never makes the Dean's decision or
    # changes the student standing. The request's period and reason come from the case,
    # not from the staff form, so the Dean and the Registrar always read the same values.
    return _leave_legacy_forward(SLUG_LOA, data)


def handle_readmission(data: MultiDict) -> int:
    return _leave_legacy_forward(SLUG_READMISSION, data)


def handle_course_audit(data: MultiDict) -> int:
    raise ValueError(
        "Direct course-audit writes are disabled for USLS. Use Enrollment for subject tagging "
        "and the Monitoring Sheet for audited operational status updates."
    )

    # Legacy implementation retained temporarily for data-migration reference.
    # Coursework transaction: upsert one subject status, then recompute the whole
    # curriculum audit to determine risk and readiness.
    student = Student.query.get_or_404(int(data["student_id"]))
    course = Course.query.get_or_404(int(data["course_id"]))
    status = data["status"]
    existing = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
    if not existing:
        existing = CourseRecord(student_id=student.id, course_id=course.id)
        db.session.add(existing)
    existing.status = status
    existing.term_label = data.get("term_label", "")
    existing.evidence_reference = data.get("evidence_reference", "")
    existing.updated_at = now_utc()
    sync_subject_enrollment_from_course_record(
        student,
        course,
        existing.term_label,
        status,
        data.get("evidence_reference", "") or "Course audit transaction",
    )

    audit = compute_course_audit(student)
    if audit["missing_count"] > 0:
        add_task(student.id, "Resolve missing curriculum subjects", "Academic Coordinator", 7, 25)
        recompute_risk(student)
    if comprehensive_exam_eligibility(student)["eligible"] and student.current_stage in ("Admission", "Coursework"):
        student.current_stage = "Comprehensive Exam"

    add_log(
        "course-audit",
        student.id,
        "Academic Coordinator",
        data.get("evidence_reference", ""),
        f"{course.code} marked {status}; {audit['missing_count']} subject(s) missing",
        "Academic Coordinator",
        "Course audit updated from monitoring signal.",
    )
    return student.id


def handle_research_gate(data: MultiDict) -> int:
    # Research gate status is derived only from stored student uploads. Staff
    # can evaluate evidence, but cannot assert that an absent file was received.
    student = Student.query.get_or_404(int(data["student_id"]))
    require_research_prerequisite(student)
    research_case, progress = sync_research_progress(student)
    gate = progress["gate"]
    ethics_clearance_status = (data.get("ethics_clearance_status") or "").strip()
    if ethics_clearance_status:
        account = require_workflow_actor("research_coordinator")
        if gate != "Form 4 - Proposal Defense Readiness":
            raise ValueError("Ethics clearance is recorded during the Proposal Defense stage.")
        outcome = latest_defense_outcome(student, gate)
        if not (outcome and outcome["complete"]):
            raise ValueError("The ethics review opens after the proposal defense is passed and any revisions are confirmed.")
        form_5_1 = DocumentCheck.query.filter_by(student_id=student.id, gate=gate, item_name=FORM_5_1_ITEM).first()
        if not form_5_1 or not form_5_1.evidence_files:
            raise ValueError("Preview the uploaded Form 5.1 Technical Review Certificate before recording the ethics clearance.")
        allowed_statuses = {"Cleared", "Returned", "Not cleared"}
        if ethics_clearance_status not in allowed_statuses:
            raise ValueError("Choose Cleared, Returned, or Not cleared for the ethics clearance status.")
        clearance_date = (data.get("ethics_clearance_date") or "").strip()
        if ethics_clearance_status == "Cleared" and not clearance_date:
            raise ValueError("Enter the ethics clearance date before marking the form Cleared.")
        checks = ensure_research_document_checks(student.id, gate)
        clearance_doc = next((doc for doc in checks if doc.item_name == "Ethics Clearance"), None)
        record_doc = next((doc for doc in checks if doc.item_name == "Ethics clearance status and date"), None)
        if not clearance_doc or not clearance_doc.evidence_files:
            raise ValueError("Preview an uploaded Research Protocol Form 5.2 ethics clearance before recording the status.")
        label = (
            f"{ethics_clearance_status} on {clearance_date}"
            if clearance_date
            else ethics_clearance_status
        )
        clearance_doc.status = "Complete" if ethics_clearance_status == "Cleared" else ethics_clearance_status
        clearance_doc.evidence_reference = label
        clearance_doc.updated_at = now_utc()
        if record_doc:
            record_doc.status = "Complete" if ethics_clearance_status == "Cleared" else ethics_clearance_status
            record_doc.evidence_reference = label
            record_doc.updated_at = now_utc()
        next_owner = "Research Coordinator" if ethics_clearance_status == "Cleared" else "Student"
        if ethics_clearance_status != "Cleared":
            ensure_open_task(student.id, "Resolve ethics clearance form", "Student", 5, 45)
        else:
            close_research_tasks(student.id, "Resolve ethics clearance form", ETHICS_APPLICATION_TASK)
        add_log(
            "research-gate",
            student.id,
            workflow_actor_label(account),
            clearance_doc.evidence_reference,
            f"Ethics clearance {ethics_clearance_status}",
            next_owner,
            f"Research Coordinator recorded Research Protocol Form 5.2 as {label}.",
        )
        sync_research_progress(student)
        return student.id
    defense_outcome = (data.get("defense_outcome") or "").strip()
    if defense_outcome:
        raise ValueError("Defense verdicts can be submitted only by the assigned panel chair or panel lead from the Faculty Portal.")
    required_items = required_documents_for_gate(gate)
    checks = ensure_research_document_checks(student.id, gate)
    submitted_items = set()
    missing_items = []
    states = {}
    locked_items = set()
    for doc in checks:
        presentation = research_requirement_presentation(gate, doc.item_name)
        state = research_requirement_state(student, gate, doc.item_name, doc)
        states[doc.item_name] = state
        if (state.get("status_label") or "").startswith("Opens after"):
            # Form 5.1 / ethics before the proposal defense is passed: not reviewable yet, not missing either.
            locked_items.add(doc.item_name)
            continue
        present = (
            presentation["source_type"] == "staff"
            and research_student_uploads_ready(student, gate)
        ) or state["status"] == "Complete" or (
            presentation["source_type"] == "student_upload" and state["status"] == "Submitted"
        )
        if present:
            submitted_items.add(doc.item_name)
        else:
            missing_items.append(doc.item_name)
    evidence_names = [file.original_name for doc in checks for file in doc.evidence_files]
    source = ", ".join(evidence_names[:4])
    revision_required = data.get("revision_required") == "yes"

    missing_sources = {
        research_requirement_presentation(gate, item)["source_type"]
        for item in missing_items
    }
    if "student_upload" in missing_sources:
        result = "Missing Requirements"
        next_owner = "Student"
    elif "coordinator_endorsement" in missing_sources:
        result = "Pending Academic Coordinator Endorsement"
        next_owner = "Academic Coordinator"
    elif missing_items:
        result = "Pending Staff Action"
        next_owner = "Research Coordinator"
    elif revision_required:
        result = "Revisions Required"
        next_owner = "Adviser"
    elif gate == "Completion Evidence":
        result = "Verified Complete"
        next_owner = "GS Staff"
    else:
        result = "Ready"
        next_owner = "Research Coordinator"

    research_case.status = result
    close_research_tasks(
        student.id,
        f"Review student {gate} application",
        *[f"Review submitted {item}" for item in required_items],
    )

    for item in required_items:
        if item in locked_items:
            continue
        status = "Missing" if item in missing_items else "Complete"
        existing = next(doc for doc in checks if doc.item_name == item)
        if item == "Ethics Clearance" and item not in missing_items:
            ethics_record = next((doc for doc in checks if doc.item_name == "Ethics clearance status and date"), None)
            if not ethics_record or ethics_record.status != "Complete":
                status = existing.status if existing.status in {"Returned", "Not cleared"} else "Submitted"
        existing.status = status
        if existing.evidence_files and item != "Ethics Clearance":
            existing.evidence_reference = ", ".join(file.original_name for file in existing.evidence_files)
        existing.updated_at = now_utc()

    if result in ["Missing Requirements", "Revisions Required", "Returned", "Pending Staff Action", "Pending Academic Coordinator Endorsement"]:
        ensure_open_task(student.id, f"Resolve {gate} requirements", next_owner, 5, 45)
    sync_research_progress(student)
    recompute_risk(student)

    add_log(
        "research-gate",
        student.id,
        "Research Coordinator",
        source,
        f"{gate}: {result}",
        next_owner,
        f"Compared stored PDF evidence against {len(required_items)} required item(s). Received: "
        f"{', '.join(sorted(submitted_items)) if submitted_items else 'None'}. Missing: "
        f"{', '.join(missing_items) if missing_items else 'None'}",
    )
    return student.id


SCHEDULING_ROLES = ("staff", "research_coordinator", "admin")
PANEL_NOMINATION_ROLES = ("staff", "research_coordinator")
SCHEDULE_SYSTEM_SOURCES = {
    "system_title_schedule", "system_proposal_schedule", "system_final_schedule", "system_defense_result",
}
SCHEDULE_CHANGE_REQUESTERS = (
    "Student", "Research adviser", "Panel chair", "Panel member", "GS Office", "Research Coordinator", "Other",
)


def require_active_standing(student: Student) -> None:
    if (student.standing or "") != "Active":
        raise ValueError(
            "Only active students can move through panel matching and defense scheduling; "
            f"this student's standing is {student.standing or 'not recorded'}."
        )


def student_adviser_faculty_ids(student: Student) -> set[int]:
    return set(adviser_faculty_ids_for_student(student))


def validate_panel_selection(student: Student, gate: str, faculty_ids: list[int], reason: str = "") -> list[Faculty]:
    """Protocol checks for a panel about to be saved. Returns the chosen faculty in role order.

    The adviser can never be chair or member of their own advisee's panel; the size
    follows the paper type and stage; replacing an existing panel needs a reason.
    """
    roles = panel_roles_for_student(student, gate)
    if len(faculty_ids) != len(roles) or len(set(faculty_ids)) != len(faculty_ids):
        raise ValueError(f"Select {len(roles)} different faculty members for the defense panel.")
    adviser_ids = student_adviser_faculty_ids(student)
    chosen = []
    for faculty_id in faculty_ids:
        faculty = Faculty.query.filter_by(id=faculty_id, active=True).first()
        if not faculty:
            raise ValueError("One of the selected faculty members is no longer active.")
        if faculty.id in adviser_ids:
            raise ValueError(
                f"{faculty.name} is this student's research adviser and cannot also be a panel chair or member "
                "for the same student."
            )
        if not UserAccount.query.filter_by(faculty_id=faculty.id, role="faculty", active=True).first():
            raise ValueError(f"{faculty.name} does not have an active faculty login account yet.")
        chosen.append(faculty)
    existing = active_panel_assignments(student, gate)
    if existing:
        previous = {assignment.panel_role: assignment.faculty_id for assignment in existing}
        proposed = {roles[index]: chosen[index].id for index in range(len(roles))}
        if previous != proposed and not (reason or "").strip():
            raise ValueError(
                "Give the reason for changing the panel; it is recorded with the change "
                "(the same panel carries from proposal to final unless a reason is recorded)."
            )
    return chosen


def panel_snapshot_for(panel: list[PanelAssignment]) -> list[dict]:
    return [
        {
            "faculty_id": assignment.faculty_id,
            "name": assignment.faculty.name,
            "role": assignment.panel_role,
            "department": assignment.faculty.college,
            "specialization": assignment.faculty.specialization,
        }
        for assignment in panel
        if assignment.faculty
    ]


def slot_availability(participants: list[dict], day: date, start: time, end: time) -> tuple[int, list[str], list[str]]:
    """How many participants are free for the whole slot, who is not, and who has entered nothing.

    A participant who has not entered availability is neither free nor unavailable: they are
    reported separately so the scheduler can warn instead of guessing.
    """
    context = defense_availability_context(participants, day, day)
    free = 0
    unavailable = []
    not_entered = []
    for participant in context["participants"]:
        if not participant["availability_entered"]:
            not_entered.append(participant["name"])
            continue
        covered = any(
            slot["date"] == day.isoformat()
            and parse_time(slot["start"]) <= start
            and parse_time(slot["end"]) >= end
            for slot in participant["slots"]
        ) and not any(
            busy["date"] == day.isoformat()
            and parse_time(busy["start"]) < end
            and parse_time(busy["end"]) > start
            for busy in participant.get("google_busy", [])
        )
        if covered:
            free += 1
        else:
            unavailable.append(participant["name"])
    return free, unavailable, not_entered


def schedule_slot_problems(student: Student, schedule: ScheduleRequest, panel: list[PanelAssignment]) -> list[str]:
    """Re-run the availability and conflict checks for an existing booking and its current panel."""
    if not schedule.start_time or not schedule.end_time:
        return ["The booking has no start and end time."]
    participants = defense_participants(student, panel)
    _free, unavailable, _not_entered = slot_availability(participants, schedule.preferred_date, schedule.start_time, schedule.end_time)
    problems = [
        f"{name} is not available {schedule.start_time.strftime('%H:%M')}-{schedule.end_time.strftime('%H:%M')} on {schedule.preferred_date.isoformat()}"
        for name in unavailable
    ]
    problems.extend(
        defense_schedule_conflicts(
            student, panel, schedule.preferred_date, schedule.start_time, schedule.end_time,
            schedule.venue or "", schedule.defense_type,
        )
    )
    return problems


def flag_schedule_after_panel_change(student: Student, gate: str, actor: str, reason: str) -> ScheduleRequest | None:
    """A panel change after booking invalidates the booking until it is re-confirmed."""
    defense_type = RESEARCH_GATE_DEFENSE_TYPES.get(gate)
    schedule = (
        ScheduleRequest.query.filter(
            ScheduleRequest.student_id == student.id,
            ScheduleRequest.defense_type == defense_type,
            ScheduleRequest.status.in_(ACTIVE_DEFENSE_STATUSES),
        )
        .order_by(ScheduleRequest.id.desc())
        .first()
    )
    if not schedule:
        return None
    panel = active_panel_assignments(student, gate)
    schedule.panel_snapshot = json.dumps(panel_snapshot_for(panel))
    problems = schedule_slot_problems(student, schedule, panel)
    schedule.status = RECONFIRM_DEFENSE_STATUS
    recheck = "; ".join(problems) if problems else "the new panel is free at the booked time"
    schedule.conflict_reason = (
        f"Panel changed by {actor} on {date.today().isoformat()}: {reason or 'no reason recorded'}. "
        f"Availability recheck: {recheck}. Re-confirm the schedule or reschedule it."
    )
    ensure_open_task(student.id, f"Re-confirm {defense_type} schedule after panel change", "Research Coordinator", 2, 50)
    add_log(
        "defense-scheduling", student.id, actor, gate,
        f"{defense_type} panel changed; schedule #{schedule.id} needs re-confirmation", "Research Coordinator",
        schedule.conflict_reason,
    )
    notify_schedule_people(
        schedule, "panel_changed", f"The panel of the {defense_type} of {student.name} changed",
        f"The booking {defense_slot_text(schedule.preferred_date, schedule.start_time, schedule.end_time)} is on hold until "
        f"the Graduate School re-confirms it. Reason: {reason or 'not recorded'}.",
        "panel_changed",
    )
    return schedule


def carry_panel_forward(student: Student, gate: str) -> int:
    """Protocol: the same panel that heard the proposal sits in the closed-door final defense."""
    if gate != RESEARCH_GATE_FINAL:
        return 0
    if PanelAssignment.query.filter_by(student_id=student.id, gate=RESEARCH_GATE_FINAL).first():
        return 0
    proposal_panel = PanelAssignment.query.filter_by(student_id=student.id, gate=RESEARCH_GATE_PROPOSAL).all()
    for assignment in proposal_panel:
        db.session.add(PanelAssignment(
            student_id=student.id, faculty_id=assignment.faculty_id, gate=RESEARCH_GATE_FINAL,
            panel_role=assignment.panel_role, score=assignment.score,
            eligibility_note="Carried over from the proposal defense panel (same panel at the final defense)",
        ))
    return len(proposal_panel)


def handle_panel_matching(data: MultiDict) -> int:
    # Finalization is the Research Coordinator's nomination (GS staff may also do it).
    # The system supplies the ranked shortlist, while the submitted faculty ids
    # preserve any adjustments.
    student = Student.query.get_or_404(int(data["student_id"]))
    account = require_workflow_actor(*PANEL_NOMINATION_ROLES)
    require_research_prerequisite(student)
    require_active_standing(student)
    gate = current_panel_gate(student)
    if gate == RESEARCH_GATE_TITLE:
        endorsement = Form1Endorsement.query.filter_by(student_id=student.id).first()
        if not (endorsement and endorsement.status == "Endorsed" and concept_paper_package_ready(student.id)):
            raise ValueError(
                "Panel matching opens only after the Academic Coordinator has endorsed Form 1 and the three concept "
                "papers."
            )
    matching_profile = research_matching_profile(student)
    if not matching_profile["ready"]:
        raise ValueError(matching_profile.get("blocked_reason") or "Panel matching requires readable research manuscript body text.")
    matching_result = panel_matching_result(student, matching_profile)
    recommendations = matching_result["rows"]
    required_roles = panel_roles_for_student(student, matching_profile["gate"])
    adviser_ids = student_adviser_faculty_ids(student)
    selected_ids = []
    for value in data.getlist("faculty_ids"):
        try:
            faculty_id = int(value)
        except (TypeError, ValueError):
            continue
        if faculty_id not in selected_ids:
            selected_ids.append(faculty_id)
    adviser_conflicts = student_advisers(student)
    for faculty_id in selected_ids:
        if faculty_id in adviser_conflicts:
            info = adviser_conflicts[faculty_id]
            raise ValueError(
                f"{info['faculty'].name} is the student's {info['role'].lower()} and cannot be assigned to the panel."
            )
    if not selected_ids:
        # Default: the suggested panel, seated by role (best methods profile on the Method seat),
        # never the student's own adviser.
        seats = {
            seat["role"]: seat["faculty_id"]
            for seat in matching_result["suggested_panel"]
            if seat["faculty_id"] not in adviser_ids
        }
        selected_ids = [seats[role] for role in required_roles if role in seats]
    if len(selected_ids) != len(required_roles):
        raise ValueError(f"Select {len(required_roles)} different faculty members before finalizing the panel.")

    recommendation_by_id = {row["faculty"].id: row for row in recommendations}
    selected_rows = []
    for faculty_id in selected_ids:
        row = recommendation_by_id.get(faculty_id)
        if not row:
            raise ValueError("One of the selected faculty members is no longer eligible for panel assignment.")
        selected_rows.append(row)
    composition = panel_composition_report(
        student, [(required_roles[index], row["faculty"]) for index, row in enumerate(selected_rows)], matching_profile["gate"]
    )
    failed_rules = [check["message"] for check in composition["checks"] if not check["ok"] and check["severity"] == "required"]
    if failed_rules:
        raise ValueError("The panel does not satisfy the Research Protocol: " + " ".join(failed_rules))

    change_reason = (data.get("panel_change_reason") or "").strip()
    validate_panel_selection(student, matching_profile["gate"], selected_ids, change_reason)
    had_panel = bool(active_panel_assignments(student, matching_profile["gate"]))
    clear_panel_for_research_gate(student, matching_profile["gate"])
    for index, row in enumerate(selected_rows):
        # Panel selection grants access through the assignment and reuses the
        # faculty's already-created general login.
        db.session.add(
            PanelAssignment(
                student_id=student.id,
                faculty_id=row["faculty"].id,
                gate=matching_profile["gate"],
                panel_role=required_roles[index],
                score=int(round(row["score"])),
                eligibility_note=(
                    f"{row['method_label']}: {row['note']}" + (f" Changed: {change_reason}" if had_panel and change_reason else "")
                )[:220],
            )
        )

    add_log(
        "panel-matching",
        student.id,
        workflow_actor_label(account),
        data.get("source_reference", ""),
        f"{len(required_roles)}-member {research_case_type(student)} panel matched from uploaded {matching_profile['source_label']}",
        "Research Coordinator",
        "; ".join(
            [
                f"{required_roles[index]}: {row['faculty'].name} ({row['score']})"
                for index, row in enumerate(selected_rows)
            ]
        ) + f". Method: {matching_result['method_label']}.",
    )
    defense_type = RESEARCH_GATE_DEFENSE_TYPES.get(matching_profile["gate"], "defense")
    ensure_open_task(student.id, f"Confirm assigned panel acceptance ({defense_type})", "Research Coordinator", 3, 30)
    sync_panel_invitations(student, matching_profile["gate"])
    if had_panel:
        flag_schedule_after_panel_change(student, matching_profile["gate"], workflow_actor_label(account), change_reason)
    sync_research_progress(student)
    return student.id


def handle_defense_scheduling(data: MultiDict) -> int:
    # GS staff / the Research Coordinator book the schedule. The system enforces the
    # protocol (stage, panel, lead times, no past slots); a warning can be overridden
    # only with a recorded reason.
    student = Student.query.get_or_404(int(data["student_id"]))
    account = require_workflow_actor(*SCHEDULING_ROLES)
    require_research_prerequisite(student)
    require_active_standing(student)

    # Optional panel reassignment from the Defense Scheduling screen: staff may pick
    # faculty from the full directory (not just the matched panel). This reassigns the
    # student's official gate panel before scheduling against it.
    reassign_ids = []
    for value in data.getlist("panel_faculty_ids"):
        try:
            fid = int(value)
        except (TypeError, ValueError):
            continue
        if fid not in reassign_ids:
            reassign_ids.append(fid)
    if reassign_ids:
        _, reassign_progress = sync_research_progress(student)
        reassign_gate = reassign_progress["gate"]
        reassign_roles = panel_roles_for_student(student, reassign_gate)
        change_reason = (data.get("panel_change_reason") or data.get("reason") or "").strip()
        chosen_faculty = validate_panel_selection(student, reassign_gate, reassign_ids, change_reason)
        prior_scores = {a.faculty_id: a.score for a in active_panel_assignments(student, reassign_gate)}
        had_panel = bool(prior_scores)
        clear_panel_for_research_gate(student, reassign_gate)
        for index, faculty in enumerate(chosen_faculty):
            db.session.add(PanelAssignment(
                student_id=student.id, faculty_id=faculty.id, gate=reassign_gate,
                panel_role=reassign_roles[index], score=prior_scores.get(faculty.id, 0),
                eligibility_note=(f"Reassigned via Defense Scheduling. {change_reason}".strip())[:220]))
        add_log(
            "panel-matching", student.id, workflow_actor_label(account),
            data.get("source_reference", ""),
            f"Defense panel reassigned to {len(chosen_faculty)} member(s) from Defense Scheduling",
            "Research Coordinator",
            "; ".join(f"{reassign_roles[i]}: {f.name}" for i, f in enumerate(chosen_faculty))
            + (f". Reason: {change_reason}" if change_reason else ""),
        )
        db.session.flush()
        sync_panel_invitations(student, reassign_gate)
        if had_panel:
            flag_schedule_after_panel_change(student, reassign_gate, workflow_actor_label(account), change_reason)
        sync_research_progress(student)
        if str(data.get("reassign_only", "")).lower() in {"1", "true", "yes", "on"}:
            return student.id

    book_defense_schedule(student, data, account)
    return student.id


def evaluate_schedule_slot(
    student: Student,
    panel: list[PanelAssignment],
    defense_type: str,
    day: date,
    start: time,
    end: time,
    venue: str,
    manuscript_received_on: date | None = None,
    participants: list[dict] | None = None,
) -> dict:
    """Every warning for one candidate slot, split into hard (blocks) and soft (needs a reason).

    hard: slot in the past, a participant who entered hours that do not cover the slot or marked
    the date unavailable, a panelist / adviser / student double-booked, the room already booked.
    soft: before the protocol lead time, a participant who has not entered any availability.
    """
    participants = participants if participants is not None else defense_participants(student, panel)
    hard: list[str] = []
    soft: list[str] = []
    if datetime.combine(day, start) <= manila_now():
        hard.append("That date and time is already in the past.")
    earliest, _reference, reference_label = student_earliest_defense_date(student, defense_type, manuscript_received_on)
    lead_days = defense_lead_days(defense_type)
    if day < earliest:
        soft.append(
            f"{defense_type} needs at least {lead_days} days after {reference_label}; "
            f"the earliest date is {earliest.isoformat()}"
        )
    matched_count, unavailable, not_entered = slot_availability(participants, day, start, end) if participants else (0, [], [])
    for name in unavailable:
        hard.append(f"{name} is not available {start.strftime('%H:%M')}-{end.strftime('%H:%M')} on {day.isoformat()}")
    if not_entered:
        soft.append(
            f"{', '.join(not_entered)} {'has' if len(not_entered) == 1 else 'have'} not entered availability, "
            "so it cannot be checked"
        )
    hard.extend(declined_invitation_problems(student, panel))
    conflicts = defense_schedule_conflicts(student, panel, day, start, end, venue, defense_type)
    hard_conflicts = [item for item in conflicts if has_hard_schedule_conflict([item])]
    hard.extend(hard_conflicts)
    soft.extend(item for item in conflicts if item not in hard_conflicts)
    return {
        "hard": hard,
        "soft": soft,
        "ok": not hard,
        "matched_count": matched_count,
        "participant_count": len(participants),
        "unavailable": unavailable,
        "not_entered": not_entered,
        "earliest_date": iso(earliest),
        "lead_days": lead_days,
    }


def book_defense_schedule(
    student: Student,
    data: MultiDict,
    account: UserAccount,
    replaces: ScheduleRequest | None = None,
) -> ScheduleRequest:
    """Create a booking (or a reschedule of `replaces`) after every protocol check."""
    research_case, progress = sync_research_progress(student)
    gate = progress["gate"]
    expected_type = RESEARCH_GATE_DEFENSE_TYPES.get(gate)
    defense_type = (data.get("defense_type") or expected_type or "").strip()
    if defense_type == "Public Final Defense":
        raise ValueError(
            "Public Final Defense cannot be booked here: it has no panel or verdict step in this system yet. "
            "Book the Title, Proposal or Final Defense."
        )
    if defense_type not in SCHEDULABLE_DEFENSE_TYPES:
        raise ValueError("Choose the Title, Proposal or Final Defense.")
    if not expected_type:
        raise ValueError("All of this student's research defenses are complete; there is no defense left to schedule.")
    if defense_type != expected_type:
        raise ValueError(
            f"This student is at the {progress['stage']} stage, so only a {expected_type} can be scheduled "
            f"({defense_type} does not match the research stage)."
        )
    outcome = latest_defense_outcome(student, gate)
    if outcome and outcome["complete"]:
        raise ValueError(f"The {defense_type} already has a passing result; there is nothing more to schedule at this stage.")
    if outcome and outcome["effect"] in REVISION_EFFECTS:
        raise ValueError(
            f"The panel asked for revisions after the {defense_type}; they are confirmed by the "
            f"{'panel chair' if outcome['effect'] == 'panel_revise' else 'research adviser'}, not by a new defense."
        )

    preferred_date = parse_date(data["preferred_date"])
    preferred_end_date = parse_date(data.get("preferred_end_date") or data["preferred_date"])
    mode = data["mode"]
    venue = data.get("venue", "")
    selected_start = parse_time(data.get("selected_start"))
    selected_end = parse_time(data.get("selected_end"))
    if not selected_start or not selected_end:
        raise ValueError("Select a start and end time from the shared availability.")
    if selected_end <= selected_start:
        raise ValueError("Defense end time must be later than the start time.")
    if preferred_end_date < preferred_date:
        raise ValueError("Preferred date window end cannot be before the selected defense date.")
    if datetime.combine(preferred_date, selected_start) <= manila_now():
        raise ValueError("That date and time is already in the past. Choose a future slot.")

    override_requirements = str(data.get("override_requirements", "")).lower() in {"1", "true", "yes", "on"}
    override_conflicts = str(data.get("override_conflicts", "")).lower() in {"1", "true", "yes", "on"}
    override_reason = (data.get("override_reason") or "").strip()

    blocking = [
        item
        for item in progress["milestone"]["requirements"]
        if item["status"] != "Complete"
        and item["source_type"] not in SCHEDULE_SYSTEM_SOURCES
        and item["source_type"] != "system_panel"
        and item["item_name"] not in POST_DEFENSE_REQUIREMENTS
    ]
    if any(item["source_type"] == "coordinator_endorsement" for item in blocking):
        raise ValueError(
            "The Academic Coordinator must endorse Form 1 and the three concept papers before a title defense "
            "can be scheduled. This cannot be overridden."
        )
    missing_requirements = [item["label"] for item in blocking]
    if missing_requirements and not override_requirements:
        raise ValueError(
            "Research Gate requirements are still pending: "
            + ", ".join(missing_requirements)
            + ". Review them or confirm the staff override."
        )
    panel = active_panel_assignments(student, gate)
    if not panel:
        raise ValueError("Complete Panel Matching before creating a defense schedule.")
    required_panel_count = len(panel_roles_for_student(student, gate))
    if len(panel) < required_panel_count:
        raise ValueError(
            f"Panel Matching is incomplete: {len(panel)} of {required_panel_count} required panelists are selected."
        )
    adviser_ids = student_adviser_faculty_ids(student)
    if any(assignment.faculty_id in adviser_ids for assignment in panel):
        raise ValueError("The student's research adviser cannot also sit on the panel. Change the panel first.")
    existing = (
        ScheduleRequest.query.filter(
            ScheduleRequest.student_id == student.id,
            ScheduleRequest.defense_type == defense_type,
            ScheduleRequest.status.in_(SLOT_HOLDING_DEFENSE_STATUSES),
        )
        .order_by(ScheduleRequest.id.desc())
        .first()
    )
    if existing and not replaces:
        raise ValueError(
            f"A {defense_type} is already booked for {existing.preferred_date.isoformat()}. "
            "Use Reschedule (with a reason) to move it, or Cancel it first."
        )
    participants = defense_participants(student, panel)

    received_raw = (data.get("manuscript_received_on") or "").strip() if isinstance(data.get("manuscript_received_on"), str) else ""
    received_on = parse_date(received_raw) if received_raw else None
    if received_on and received_on > date.today():
        raise ValueError("The date the panel received the manuscript cannot be in the future.")
    if defense_type == "Title Defense":
        received_on = None
    evaluation = evaluate_schedule_slot(
        student, panel, defense_type, preferred_date, selected_start, selected_end, venue,
        received_on, participants=participants,
    )
    matched_count = evaluation["matched_count"]
    status_reason = evaluation["soft"]
    if evaluation["hard"]:
        raise ValueError(
            "Schedule unavailable: "
            + " ".join(evaluation["hard"])
            + " Choose a conflict-free time where all assigned panelists are available."
        )
    if status_reason and not override_conflicts:
        raise ValueError(
            "Schedule warning: " + "; ".join(status_reason) + ". Confirm the schedule override to finalize anyway."
        )
    if (status_reason or missing_requirements) and not override_reason:
        raise ValueError("Record the reason for the staff override before continuing.")

    time_label = f"{selected_start.strftime('%I:%M %p')}-{selected_end.strftime('%I:%M %p')}"
    requested_by = (data.get("requested_by") or "").strip() or ("GS Office" if replaces else None)
    change_reason = (data.get("reason") or "").strip() if replaces else ""
    link_to = replaces or (
        ScheduleRequest.query.filter_by(student_id=student.id, defense_type=defense_type, status=DEFERRED_DEFENSE_STATUS)
        .order_by(ScheduleRequest.id.desc())
        .first()
    )
    action_label = "Rescheduled" if replaces else "Scheduled"
    if replaces and replaces.status in SLOT_HOLDING_DEFENSE_STATUSES:
        replaces.status = RESCHEDULED_DEFENSE_STATUS
        replaces.conflict_reason = f"Replaced by a rescheduled booking on {date.today().isoformat()}: {change_reason}"
    schedule = ScheduleRequest(
        student_id=student.id,
        preferred_date=preferred_date,
        preferred_end_date=preferred_end_date,
        start_time=selected_start,
        end_time=selected_end,
        defense_type=defense_type,
        mode=mode,
        venue=venue,
        status="Scheduled",
        matched_count=matched_count,
        panel_snapshot=json.dumps(panel_snapshot_for(panel)),
        required_forms_status="Complete" if not missing_requirements else "Staff override",
        conflict_reason="; ".join(status_reason) if status_reason else None,
        notes=(
            f"{action_label}; {defense_type}; {time_label}; "
            f"{'; '.join(status_reason) if status_reason else 'all scheduling checks passed'}; "
            f"{data.get('constraints', '')}"
        )[:260],
        confirmed_at=now_utc(),
        rescheduled_from_id=link_to.id if link_to else None,
        change_reason=change_reason or None,
        requested_by=requested_by,
        override_reason=override_reason or None,
        manuscript_received_on=received_on,
    )
    db.session.add(schedule)
    db.session.flush()
    close_research_tasks(
        student.id,
        f"Review student {defense_type} schedule request",
        f"Reschedule deferred {defense_type}",
        f"Reschedule cancelled {defense_type}",
        f"Re-confirm {defense_type} schedule after panel change",
    )
    add_log(
        "defense-scheduling",
        student.id,
        workflow_actor_label(account),
        data.get("source_reference", ""),
        f"{defense_type} schedule {action_label}; {matched_count}/{len(participants)} participant match(es)",
        "Panel Chair",
        f"{preferred_date.isoformat()} {time_label}; {mode}; {venue}; "
        f"{'; '.join(status_reason) if status_reason else 'lead time and availability passed'}"
        + (f"; requested by {requested_by}: {change_reason}" if replaces else "")
        + (f"; override reason: {override_reason}" if override_reason else ""),
    )
    close_research_tasks(student.id, prefix=f"Reschedule {defense_type}:")
    notify_defense_booked(schedule, replaces, change_reason, requested_by)
    sync_research_progress(student)
    return schedule


def cancel_defense_schedule(schedule: ScheduleRequest, account: UserAccount, reason: str, requested_by: str) -> None:
    student = schedule.student
    schedule.status = CANCELLED_DEFENSE_STATUS
    schedule.cancelled_at = now_utc()
    schedule.change_reason = reason
    schedule.requested_by = requested_by or schedule.requested_by
    schedule.conflict_reason = f"Cancelled on {date.today().isoformat()}: {reason}"
    ensure_open_task(student.id, f"Reschedule cancelled {schedule.defense_type}", "Research Coordinator", 3, 50)
    add_log(
        "defense-scheduling", student.id, workflow_actor_label(account), schedule.defense_type or "",
        f"{schedule.defense_type} schedule #{schedule.id} cancelled", "Research Coordinator",
        f"Requested by {requested_by or 'not recorded'}. Reason: {reason}",
    )
    notify_defense_cancelled(schedule, reason, requested_by)


# ===========================================================================
# Calendar, availability, adviser appointments, invitations, reminders, private feed.
# Ground truth: the Graduate School research protocol and the audit
# `.planning/audit/research-workflows.md` (R01-R05, R15, R17-R19, R26-R27, R38, R40).
# Times are naive local Asia/Manila, exactly as the rest of the app stores them.
# ===========================================================================
CALENDAR_TIMEZONE = "Asia/Manila"


def json_body() -> dict:
    body = request.get_json(silent=True)
    return body if isinstance(body, dict) else {}


# ---- in-app notifications (core) ------------------------------------------------------------
def notify_account(
    account: UserAccount | None,
    kind: str,
    title: str,
    body: str = "",
    link: str | None = None,
    related_type: str | None = None,
    related_id: int | None = None,
    due_on: date | None = None,
    dedupe_key: str | None = None,
) -> Notification | None:
    """Add one notification for one person. Idempotent: the same dedupe key is never added twice."""
    if not account or not account.active:
        return None
    key = (dedupe_key or f"{kind}:{related_type}:{related_id}:{iso(due_on)}")[:160]
    if Notification.query.filter_by(account_id=account.id, dedupe_key=key).first():
        return None
    note = Notification(
        account_id=account.id, kind=kind, title=title[:180], body=body, link=link,
        related_type=related_type, related_id=related_id, due_on=due_on, dedupe_key=key,
    )
    db.session.add(note)
    return note


def accounts_for_student(student_id: int | None) -> list[UserAccount]:
    if not student_id:
        return []
    return UserAccount.query.filter_by(student_id=student_id, role="student", active=True).all()


def accounts_for_faculty(faculty_id: int | None) -> list[UserAccount]:
    if not faculty_id:
        return []
    return UserAccount.query.filter_by(faculty_id=faculty_id, role="faculty", active=True).all()


def accounts_for_roles(*roles: str) -> list[UserAccount]:
    return UserAccount.query.filter(UserAccount.role.in_(roles), UserAccount.active.is_(True)).all()


def notify_many(accounts: list[UserAccount], kind: str, title: str, body: str = "", **kwargs) -> int:
    sent = 0
    for account in accounts:
        if notify_account(account, kind, title, body, **kwargs):
            sent += 1
    return sent


# ---- availability requests --------------------------------------------------------------------
def availability_request_dict(item: AvailabilityRequest) -> dict:
    faculty = item.faculty
    return {
        "id": item.id,
        "faculty_id": item.faculty_id,
        "faculty_name": faculty.name if faculty else None,
        "student_id": item.student_id,
        "student_name": item.student.name if item.student else None,
        "requested_by": item.requested_by,
        "window_start": iso(item.window_start),
        "window_end": iso(item.window_end),
        "message": item.message,
        "status": item.status,
        "created_at": iso(item.created_at),
        "answered_at": iso(item.answered_at),
        "availability_entered": faculty_availability_entered(faculty) if faculty else False,
        "availability_updated_at": iso(faculty.availability_updated_at) if faculty else None,
    }


def request_panel_availability(
    student: Student, faculty_ids: list[int] | None, window_start: date, window_end: date, message: str, actor: str,
) -> list[AvailabilityRequest]:
    """Ask each panelist (and the adviser) to enter availability. One open request per person and student."""
    if not faculty_ids:
        gate = current_panel_gate(student)
        faculty_ids = [item["faculty"].id for item in defense_participants(student, active_panel_assignments(student, gate))]
    if not faculty_ids:
        raise ValueError("This student has no panel or adviser yet, so there is nobody to ask.")
    rows = []
    for faculty_id in dict.fromkeys(faculty_ids):
        faculty = Faculty.query.filter_by(id=faculty_id, active=True).first()
        if not faculty:
            continue
        row = AvailabilityRequest.query.filter_by(faculty_id=faculty.id, student_id=student.id, status="Open").first()
        if not row:
            row = AvailabilityRequest(faculty_id=faculty.id, student_id=student.id, status="Open")
            db.session.add(row)
        row.requested_by = actor
        row.window_start, row.window_end = window_start, window_end
        row.message = message
        rows.append(row)
        db.session.flush()
        window = f"{window_start.isoformat()} to {window_end.isoformat()}"
        notify_many(
            accounts_for_faculty(faculty.id), "availability_requested",
            f"Please enter your availability for {student.name}'s defense",
            f"{actor} asked for your available dates between {window}. {message}".strip(),
            link="/faculty-portal/availability", related_type="availability_request", related_id=row.id,
            dedupe_key=f"availability_requested:{row.id}:{row.created_at.date().isoformat() if row.created_at else ''}",
        )
    return rows


# ---- panel invitations (declined seats block a booking) --------------------------------------
def declined_invitation_problems(student: Student, panel: list[PanelAssignment]) -> list[str]:
    ids = {assignment.faculty_id for assignment in panel}
    if not ids:
        return []
    gate = panel[0].gate
    rows = PanelInvitation.query.filter(
        PanelInvitation.student_id == student.id,
        PanelInvitation.gate == gate,
        PanelInvitation.faculty_id.in_(ids),
        PanelInvitation.status == "Declined",
    ).all()
    return [
        f"{row.faculty.name} declined the panel invitation ({row.reason or 'no reason given'}); "
        "replace them on the panel or ask them to accept."
        for row in rows if row.faculty
    ]


# ---- adviser appointment ---------------------------------------------------------------------
def adviser_max_advisees() -> int:
    return int(rule_value("faculty.max_advisees", 5))


def adviser_contract_days() -> int:
    return int(rule_value("research.adviser_contract_days", 5))


def adviser_change_limit() -> int:
    return int(rule_value("research.adviser_change_max", 1))


def adviser_active_count(faculty_id: int, exclude_id: int | None = None, include_pending: bool = False) -> int:
    """Advisees a faculty member currently has: accepted appointments, plus (optionally) issued-but-unanswered ones."""
    statuses = [ADVISER_STATUS_ACCEPTED] + ([ADVISER_STATUS_APPOINTED] if include_pending else [])
    query = AdviserAppointment.query.filter(
        AdviserAppointment.faculty_id == faculty_id,
        AdviserAppointment.status.in_(statuses),
        AdviserAppointment.ended_at.is_(None),
    )
    if exclude_id:
        query = query.filter(AdviserAppointment.id != exclude_id)
    return query.count()


def student_active_appointments(student_id: int) -> list[AdviserAppointment]:
    return (
        AdviserAppointment.query.filter(
            AdviserAppointment.student_id == student_id,
            AdviserAppointment.status == ADVISER_STATUS_ACCEPTED,
            AdviserAppointment.ended_at.is_(None),
        ).order_by(AdviserAppointment.id.desc()).all()
    )


def legacy_adviser_faculty_ids(student: Student) -> set[int]:
    """The adviser as older data recorded it: an active AdviserAssignment or the free-text name."""
    ids = {
        row.faculty_id
        for row in AdviserAssignment.query.filter_by(student_id=student.id, status="Active").all()
    }
    if student.adviser_name:
        ids.update(faculty.id for faculty in Faculty.query.filter_by(name=student.adviser_name).all())
    return ids


def adviser_faculty_ids_for_student(student: Student) -> set[int]:
    """Who the student's adviser is. The approved (Accepted, not ended) appointment decides; the old
    free-text name and AdviserAssignment are consulted only for a student with no appointment record."""
    rows = AdviserAppointment.query.filter_by(student_id=student.id).all()
    if rows:
        return {row.faculty_id for row in rows if row.status == ADVISER_STATUS_ACCEPTED and row.ended_at is None}
    return legacy_adviser_faculty_ids(student)


def student_adviser_faculty(student: Student) -> list[Faculty]:
    ids = adviser_faculty_ids_for_student(student)
    if not ids:
        return []
    found = Faculty.query.filter(Faculty.id.in_(ids), Faculty.active.is_(True)).order_by(Faculty.id).all()
    # An adviser by name comes first so the legacy single-adviser display stays stable.
    return sorted(found, key=lambda item: (item.name != student.adviser_name, item.id))


def migrate_student_adviser(student: Student) -> int:
    """Turn the free-text adviser / AdviserAssignment of one student into an appointment record, once."""
    if AdviserAppointment.query.filter_by(student_id=student.id).first():
        return 0
    created = 0
    seen = set()
    for assignment in AdviserAssignment.query.filter_by(student_id=student.id, status="Active").order_by(AdviserAssignment.id).all():
        if assignment.faculty_id in seen or not db.session.get(Faculty, assignment.faculty_id):
            continue
        seen.add(assignment.faculty_id)
        db.session.add(AdviserAppointment(
            student_id=student.id, faculty_id=assignment.faculty_id, kind="Recorded", status=ADVISER_STATUS_ACCEPTED,
            adviser_response="Accepted", applied_at=assignment.assigned_at or now_utc(),
            adviser_responded_at=assignment.assigned_at, source="Migrated from the existing adviser record",
        ))
        created += 1
    if not created and student.adviser_name:
        active_faculty = Faculty.query.all()
        by_key = {_panel_name_key(item.name): item for item in active_faculty}
        for part in re.split(r"\s*(?:;|/|&|\band\b)\s*", student.adviser_name):
            faculty = by_key.get(_panel_name_key(part)) if part.strip() else None
            if faculty and faculty.id not in seen:
                seen.add(faculty.id)
                db.session.add(AdviserAppointment(
                    student_id=student.id, faculty_id=faculty.id, kind="Recorded", status=ADVISER_STATUS_ACCEPTED,
                    adviser_response="Accepted", source="Migrated from the existing adviser record",
                ))
                created += 1
    if created:
        db.session.flush()
    return created


def migrate_adviser_appointments() -> int:
    """Startup migration: every student who has an adviser on record gets an appointment row. Idempotent."""
    created = 0
    candidate_ids = {
        student_id for (student_id,) in db.session.query(AdviserAssignment.student_id).filter_by(status="Active").all()
    }
    candidate_ids.update(
        student_id for (student_id,) in db.session.query(Student.id).filter(Student.adviser_name.isnot(None), Student.adviser_name != "").all()
    )
    for student_id in sorted(candidate_ids):
        student = db.session.get(Student, student_id)
        if student:
            created += migrate_student_adviser(student)
    db.session.commit()
    return created


def sync_student_adviser(student: Student) -> None:
    """Write the approved appointment through to the legacy fields so every older read path agrees."""
    active = student_active_appointments(student.id)
    keep = {row.faculty_id for row in active}
    for assignment in AdviserAssignment.query.filter_by(student_id=student.id).all():
        if assignment.faculty_id in keep and assignment.status != "Active":
            assignment.status = "Active"
        elif assignment.faculty_id not in keep and assignment.status == "Active":
            assignment.status = "Ended"
    for faculty_id in keep:
        if not AdviserAssignment.query.filter_by(student_id=student.id, faculty_id=faculty_id, status="Active").first():
            db.session.add(AdviserAssignment(student_id=student.id, faculty_id=faculty_id, status="Active"))
    primary = db.session.get(Faculty, active[0].faculty_id) if active else None
    student.adviser_name = primary.name if primary else None
    research_case = ResearchCase.query.filter_by(student_id=student.id).order_by(ResearchCase.opened_at.desc()).first()
    if research_case:
        research_case.adviser_name = student.adviser_name


def record_adviser_from_name(student: Student, name: str | None, actor: str) -> AdviserAppointment | None:
    """The adviser was typed on the monitoring sheet: keep a proper appointment record of it."""
    name = (name or "").strip()
    migrate_student_adviser(student)
    current = student_active_appointments(student.id)
    faculty = None
    if name:
        faculty = Faculty.query.filter_by(name=name).first() or {
            _panel_name_key(item.name): item for item in Faculty.query.all()
        }.get(_panel_name_key(name))
    if faculty and any(row.faculty_id == faculty.id for row in current):
        return None
    for row in current:
        row.status = ADVISER_STATUS_ENDED
        row.ended_at = now_utc()
        row.end_reason = f"Adviser changed on the monitoring sheet by {actor}"
    appointment = None
    if faculty:
        appointment = AdviserAppointment(
            student_id=student.id, faculty_id=faculty.id, kind="Recorded", status=ADVISER_STATUS_ACCEPTED,
            adviser_response="Accepted", adviser_responded_at=now_utc(), source=f"Recorded on the monitoring sheet by {actor}",
        )
        db.session.add(appointment)
    db.session.flush()
    if appointment or current:
        sync_student_adviser(student)
        if not faculty and name:
            student.adviser_name = name  # a name that is not a faculty record stays as typed
    return appointment


def adviser_contract_info(row: AdviserAppointment) -> dict:
    if row.status != ADVISER_STATUS_ACCEPTED or not row.contract_due_on:
        return {"status": "Not applicable", "due_on": None, "submitted_at": None, "received_at": None, "days_left": None}
    if row.contract_received_at:
        status = "Received"
    elif row.contract_submitted_at:
        status = "Submitted"
    elif row.contract_due_on < date.today():
        status = "Overdue"
    else:
        status = "Pending"
    return {
        "status": status,
        "due_on": iso(row.contract_due_on),
        "submitted_at": iso(row.contract_submitted_at),
        "received_at": iso(row.contract_received_at),
        "received_by": row.contract_received_by,
        "note": row.contract_note,
        "days_left": (row.contract_due_on - date.today()).days,
    }


def adviser_eligibility_warnings(student: Student, faculty: Faculty) -> list[str]:
    """Protocol checks the system cannot prove from its data: shown as warnings, never as a block."""
    warnings = []
    degrees = [
        record.text.lower() for record in FacultyExpertise.query.filter_by(faculty_id=faculty.id, kind="degree").all()
    ]
    has_doctorate = any(re.search(r"ph\.?\s?d|doctor", text_value) for text_value in degrees)
    if not has_doctorate:
        if research_case_type(student) == "Dissertation":
            warnings.append(f"No PhD degree is recorded for {faculty.name}; the protocol requires a PhD for PhD students.")
        else:
            warnings.append(
                f"No PhD degree or PhD units are recorded for {faculty.name}; the protocol requires at least PhD units "
                "for master's advisees."
            )
    if "Faculty Adviser" not in faculty_eligible_roles(faculty):
        warnings.append(f"{faculty.name} is not marked as a Faculty Adviser in their profile; check that they may advise.")
    count = adviser_active_count(faculty.id)
    if count >= adviser_max_advisees():
        warnings.append(f"{faculty.name} already has {count} active advisees (the limit is {adviser_max_advisees()}).")
    return warnings


def adviser_steps(row: AdviserAppointment) -> list[dict]:
    """The tracker the student sees: each protocol step, done or not."""
    if row.kind == "Change":
        consent_done = row.current_adviser_consent == "Consented"
        steps = [
            {"key": "applied", "label": "Form 3.1.1 submitted", "done": True, "at": iso(row.applied_at)},
            {"key": "current_consent", "label": "Current adviser agrees", "done": consent_done, "at": iso(row.current_adviser_consent_at)},
            {"key": "new_adviser", "label": "New adviser agrees", "done": row.adviser_response == "Accepted", "at": iso(row.adviser_responded_at)},
            {"key": "deliberation", "label": "Research Coordinator sends it to the Dean", "done": row.status in (ADVISER_STATUS_DELIBERATION, ADVISER_STATUS_ACCEPTED, ADVISER_STATUS_ENDED) or bool(row.forwarded_at), "at": iso(row.forwarded_at)},
            {"key": "decision", "label": "Dean approves the change (new Form 3.1)", "done": row.status == ADVISER_STATUS_ACCEPTED, "at": iso(row.decided_at)},
        ]
    else:
        steps = [
            {"key": "applied", "label": "Form 3 submitted", "done": True, "at": iso(row.applied_at)},
            {"key": "noted", "label": "Academic Coordinator notes the application", "done": bool(row.ac_noted_at), "at": iso(row.ac_noted_at)},
            {"key": "deliberation", "label": "Research Coordinator sends it to the Dean", "done": bool(row.forwarded_at), "at": iso(row.forwarded_at)},
            {"key": "decision", "label": "Dean, Associate Dean and Research Coordinator approve (Form 3.1 issued)", "done": bool(row.form31_issued_on), "at": iso(row.decided_at)},
            {"key": "accepted", "label": "Adviser accepts Form 3.1", "done": row.adviser_response == "Accepted" and row.status == ADVISER_STATUS_ACCEPTED, "at": iso(row.adviser_responded_at)},
        ]
    if row.status == ADVISER_STATUS_ACCEPTED and row.contract_due_on:
        contract = adviser_contract_info(row)
        steps.append({
            "key": "contract", "label": f"Forms 3.2 and 3.3 sent to the Research Coordinator (due {iso(row.contract_due_on)})",
            "done": contract["status"] in ("Submitted", "Received"), "at": iso(row.contract_submitted_at),
        })
    first_open = next((step for step in steps if not step["done"]), None)
    for step in steps:
        step["current"] = step is first_open and row.status in ADVISER_OPEN_STATUSES + (ADVISER_STATUS_ACCEPTED,)
    return steps


def adviser_actions_for(row: AdviserAppointment, role: str) -> list[str]:
    actions = []
    is_admin = role == "admin"
    if (role == "academic_coordinator" or is_admin) and row.kind != "Change" and row.status == ADVISER_STATUS_APPLIED:
        actions.append("note")
    if role in ("staff", "research_coordinator") or is_admin:
        if row.kind != "Change" and row.status == ADVISER_STATUS_NOTED:
            actions.append("forward")
        if row.kind == "Change" and row.status == ADVISER_STATUS_APPLIED and change_consents_complete(row):
            actions.append("forward")
        if row.status == ADVISER_STATUS_ACCEPTED and row.contract_submitted_at and not row.contract_received_at:
            actions.append("contract-received")
    if role == "dean" or is_admin:
        if row.status == ADVISER_STATUS_DELIBERATION:
            actions += ["appoint", "return"]
    return actions


def change_consents_complete(row: AdviserAppointment) -> bool:
    return row.kind == "Change" and row.current_adviser_consent == "Consented" and row.adviser_response == "Accepted"


def adviser_appointment_dict(row: AdviserAppointment, role: str | None = None) -> dict:
    student = row.student
    faculty = row.faculty
    replaced = db.session.get(AdviserAppointment, row.replaces_id) if row.replaces_id else None
    payload = {
        "id": row.id,
        "student_id": row.student_id,
        "student_name": student.name if student else None,
        "student_number": student.student_number if student else None,
        "program_code": student.program.code if student and student.program else None,
        "research_type": research_case_type(student) if student and student.program else None,
        "faculty_id": row.faculty_id,
        "faculty_name": faculty.name if faculty else None,
        "faculty_college": faculty.college if faculty else None,
        "kind": row.kind,
        "status": row.status,
        "replaces_id": row.replaces_id,
        "current_adviser_name": replaced.faculty.name if replaced and replaced.faculty else None,
        "reason": row.reason,
        "student_note": row.student_note,
        "applied_at": iso(row.applied_at),
        "ac_note": row.ac_note,
        "ac_noted_by": row.ac_noted_by,
        "ac_noted_at": iso(row.ac_noted_at),
        "forwarded_by": row.forwarded_by,
        "forwarded_at": iso(row.forwarded_at),
        "decided_by": row.decided_by,
        "decided_at": iso(row.decided_at),
        "decision_note": row.decision_note,
        "associate_dean_name": row.associate_dean_name,
        "cap_exception": bool(row.cap_exception),
        "form31_issued_on": iso(row.form31_issued_on),
        "adviser_response": row.adviser_response,
        "adviser_responded_at": iso(row.adviser_responded_at),
        "adviser_response_reason": row.adviser_response_reason,
        "current_adviser_consent": row.current_adviser_consent,
        "current_adviser_consent_at": iso(row.current_adviser_consent_at),
        "current_adviser_consent_reason": row.current_adviser_consent_reason,
        "contract": adviser_contract_info(row),
        "ended_at": iso(row.ended_at),
        "end_reason": row.end_reason,
        "source": row.source,
        "steps": adviser_steps(row),
        "advisees": adviser_active_count(row.faculty_id),
        "max_advisees": adviser_max_advisees(),
        "warnings": adviser_eligibility_warnings(student, faculty) if student and faculty and row.status in ADVISER_OPEN_STATUSES else [],
    }
    if role:
        payload["actions"] = adviser_actions_for(row, role)
    return payload


def adviser_actor_label(account: UserAccount) -> str:
    return f"{account.full_name} ({ROLE_LABELS.get(account.role, account.role)})"


def adviser_log(row: AdviserAppointment, actor: str, result: str, next_owner: str, notes: str = "") -> None:
    add_log(
        "adviser-appointment", row.student_id, actor, f"Adviser appointment #{row.id}", result, next_owner,
        notes or f"{row.faculty.name if row.faculty else 'Adviser'} ({row.kind.lower()} appointment).",
    )


def student_past_proposal_defense(student: Student) -> bool:
    """Protocol: a change of adviser is allowed only before the proposal defense."""
    held = ScheduleRequest.query.filter(
        ScheduleRequest.student_id == student.id,
        ScheduleRequest.defense_type.in_(["Proposal Defense", "Final Defense"]),
        ScheduleRequest.status == HELD_DEFENSE_STATUS,
    ).first()
    verdict = DefenseVerdict.query.filter(
        DefenseVerdict.student_id == student.id,
        DefenseVerdict.gate.in_([RESEARCH_GATE_PROPOSAL, RESEARCH_GATE_FINAL]),
    ).first()
    return bool(held or verdict)


def adviser_candidate_list() -> list[dict]:
    rows = []
    for faculty in Faculty.query.filter_by(active=True).order_by(Faculty.name).all():
        if not UserAccount.query.filter_by(faculty_id=faculty.id, role="faculty", active=True).first():
            continue
        count = adviser_active_count(faculty.id)
        rows.append({
            "id": faculty.id, "name": faculty.name, "college": faculty.college, "specialization": faculty.specialization,
            "advisees": count, "max_advisees": adviser_max_advisees(), "available": count < adviser_max_advisees(),
        })
    return rows


def adviser_tracker_payload(student: Student) -> dict:
    """Everything the student's 'My research adviser' page shows."""
    migrate_student_adviser(student)
    rows = AdviserAppointment.query.filter_by(student_id=student.id).order_by(AdviserAppointment.id.desc()).all()
    active = student_active_appointments(student.id)
    open_row = next((row for row in rows if row.status in ADVISER_OPEN_STATUSES), None)
    change_rows = [
        row for row in rows
        if row.kind == "Change" and row.status not in (ADVISER_STATUS_DECLINED, ADVISER_STATUS_NOT_APPROVED, ADVISER_STATUS_WITHDRAWN)
    ]
    blocked = None
    if not active:
        blocked = "A change of adviser needs a current adviser."
    elif open_row:
        blocked = "Finish or withdraw the open application first."
    elif len(change_rows) >= adviser_change_limit():
        blocked = "A change of research adviser is allowed only once (protocol)."
    elif student_past_proposal_defense(student):
        blocked = "A change of research adviser must be done before the proposal defense (protocol)."
    return {
        "current": adviser_appointment_dict(active[0], "student") if active else None,
        "open": adviser_appointment_dict(open_row, "student") if open_row else None,
        "history": [adviser_appointment_dict(row, "student") for row in rows],
        "candidates": adviser_candidate_list(),
        "can_apply": not active and not open_row,
        "can_request_change": blocked is None,
        "change_blocked_reason": blocked,
        "rules": {
            "max_advisees": adviser_max_advisees(),
            "contract_days": adviser_contract_days(),
            "change_max": adviser_change_limit(),
            "forms": {"application": "Form 3", "appointment": "Form 3.1", "timetable": "Form 3.2", "contract": "Form 3.3", "change": "Form 3.1.1"},
        },
        "timezone": CALENDAR_TIMEZONE,
    }


def start_adviser_application(student: Student, faculty: Faculty, kind: str, note: str, reason: str = "") -> AdviserAppointment:
    row = AdviserAppointment(
        student_id=student.id, faculty_id=faculty.id, kind=kind, status=ADVISER_STATUS_APPLIED,
        student_note=note, reason=reason or None, source="Student application in the portal",
    )
    if kind == "Change":
        current = student_active_appointments(student.id)[0]
        row.replaces_id = current.id
        row.current_adviser_consent = "Pending"
    db.session.add(row)
    db.session.flush()
    if kind == "Change":
        add_task(student.id, "Current and new adviser sign Form 3.1.1", "Student", 7, 40)
        notify_many(
            accounts_for_faculty(row.faculty_id), "adviser_consent_requested",
            f"{student.name} asks you to be their research adviser (change of adviser)",
            "Open Advisees to agree to the change (Form 3.1.1).", link="/faculty-portal/advisees",
            related_type="adviser_appointment", related_id=row.id, dedupe_key=f"adviser_change_new:{row.id}",
        )
        notify_many(
            accounts_for_faculty(current.faculty_id), "adviser_consent_requested",
            f"{student.name} asks to change research adviser",
            "Open Advisees to agree or decline releasing the advisee (Form 3.1.1).", link="/faculty-portal/advisees",
            related_type="adviser_appointment", related_id=row.id, dedupe_key=f"adviser_change_current:{row.id}",
        )
    else:
        add_task(student.id, "Note the adviser application (Form 3)", "Academic Coordinator", 3, 40)
        notify_many(
            accounts_for_roles("academic_coordinator"), "adviser_application",
            f"{student.name} applied for a research adviser",
            f"Nominated adviser: {faculty.name}. Note the application for the Research Coordinator.",
            link="/adviser-appointments", related_type="adviser_appointment", related_id=row.id,
            dedupe_key=f"adviser_application:{row.id}",
        )
    return row


def student_active_advisee_rows(faculty_id: int) -> list[dict]:
    """The faculty member's current advisees with their contract (Forms 3.2 / 3.3) status."""
    rows = []
    for row in (
        AdviserAppointment.query.filter(
            AdviserAppointment.faculty_id == faculty_id,
            AdviserAppointment.status == ADVISER_STATUS_ACCEPTED,
            AdviserAppointment.ended_at.is_(None),
        ).order_by(AdviserAppointment.id).all()
    ):
        student = row.student
        if not student:
            continue
        rows.append({
            "id": row.id,
            "student_id": student.id,
            "student_name": student.name,
            "student_number": student.student_number,
            "program_code": student.program.code if student.program else None,
            "stage": student.current_stage,
            "appointed_on": iso(row.form31_issued_on or row.adviser_responded_at),
            "kind": row.kind,
            "contract": adviser_contract_info(row),
        })
    return rows


def advisee_student_ids(faculty: Faculty) -> set[int]:
    """Students this faculty member advises: approved appointments, plus legacy records of
    students who have no appointment row yet."""
    ids = {
        row.student_id for row in AdviserAppointment.query.filter(
            AdviserAppointment.faculty_id == faculty.id,
            AdviserAppointment.status == ADVISER_STATUS_ACCEPTED,
            AdviserAppointment.ended_at.is_(None),
        ).all()
    }
    legacy = {
        row.student_id for row in AdviserAssignment.query.filter_by(faculty_id=faculty.id, status="Active").all()
    }
    legacy.update(student_id for (student_id,) in Student.query.with_entities(Student.id).filter_by(adviser_name=faculty.name).all())
    if legacy:
        with_rows = {
            student_id for (student_id,) in db.session.query(AdviserAppointment.student_id)
            .filter(AdviserAppointment.student_id.in_(legacy)).distinct().all()
        }
        ids.update(legacy - with_rows)
    return ids


# ---- calendar: events, deadlines, availability layer, .ics ---------------------------------------
CALENDAR_LAYERS = {"deadlines", "availability", "busy"}
CALENDAR_DEFAULT_SPAN_DAYS = 62


def next_working_day(day: date) -> date:
    """The first working day after `day` (Monday-Friday; the app keeps no holiday calendar)."""
    following = day + timedelta(days=1)
    while following.weekday() >= 5:
        following += timedelta(days=1)
    return following


def calendar_scope(account: UserAccount) -> dict:
    """What a signed-in person may see on the calendar."""
    return {"role": account.role, "student_id": account.student_id, "faculty_id": account.faculty_id}


def schedule_in_scope(scope: dict, schedule: ScheduleRequest) -> bool:
    if scope["role"] == "student":
        return bool(scope["student_id"]) and schedule.student_id == scope["student_id"]
    if scope["role"] == "faculty":
        return bool(scope["faculty_id"]) and scope["faculty_id"] in schedule_panel_ids(schedule)
    return True


def parse_calendar_range(args) -> tuple[date, date]:
    today = date.today()
    try:
        start = parse_date(args.get("start")) if args.get("start") else today - timedelta(days=7)
        end = parse_date(args.get("end")) if args.get("end") else start + timedelta(days=CALENDAR_DEFAULT_SPAN_DAYS)
    except ValueError:
        raise ValueError("Enter dates as YYYY-MM-DD.")
    if end < start:
        raise ValueError("The end date cannot be before the start date.")
    if (end - start).days > 400:
        raise ValueError("Ask for at most about a year at a time.")
    return start, end


def defense_seat_role(schedule: ScheduleRequest, faculty_id: int | None) -> str | None:
    if not faculty_id:
        return None
    try:
        snapshot = json.loads(schedule.panel_snapshot or "[]")
    except (TypeError, json.JSONDecodeError):
        snapshot = []
    for seat in snapshot:
        if seat.get("faculty_id") == faculty_id:
            return seat.get("role")
    if schedule.student and faculty_id in adviser_faculty_ids_for_student(schedule.student):
        return "Research Adviser"
    return None


def defense_attention(schedule: ScheduleRequest) -> list[str]:
    notes = []
    if schedule.status == RECONFIRM_DEFENSE_STATUS:
        notes.append("Needs re-confirmation: the panel changed after booking.")
    gate = RESEARCH_DEFENSE_TYPES_TO_GATES.get(schedule.defense_type or "")
    if gate and schedule.status in SLOT_HOLDING_DEFENSE_STATUSES:
        seated = schedule_panel_ids(schedule)
        for row in PanelInvitation.query.filter_by(student_id=schedule.student_id, gate=gate, status="Declined").all():
            if row.faculty and row.faculty_id in seated:
                notes.append(f"{row.faculty.name} cannot attend: {row.reason or 'no reason given'}.")
    return notes


def calendar_defense_event(schedule: ScheduleRequest, scope: dict, verdict_ids: set[int]) -> dict:
    student = schedule.student
    try:
        panel = [
            {"faculty_id": seat.get("faculty_id"), "name": seat.get("name"), "role": seat.get("role")}
            for seat in json.loads(schedule.panel_snapshot or "[]")
        ]
    except (TypeError, json.JSONDecodeError):
        panel = []
    status = "Scheduled" if schedule.status == "Confirmed" else schedule.status
    start_time = schedule.start_time or time(9, 0)
    end_time = schedule.end_time or (datetime.combine(schedule.preferred_date, start_time) + timedelta(hours=2)).time()
    has_verdict = schedule.id in verdict_ids
    overdue = bool(
        schedule.status in ACTIVE_DEFENSE_STATUSES and not has_verdict
        and date.today() > next_working_day(schedule.preferred_date)
    )
    return {
        "id": f"defense-{schedule.id}",
        "kind": "defense",
        "schedule_id": schedule.id,
        "title": f"{schedule.defense_type or 'Defense'} - {student.name}" if student else (schedule.defense_type or "Defense"),
        "student_id": schedule.student_id,
        "student_name": student.name if student else None,
        "student_number": student.student_number if student else None,
        "program_id": student.program_id if student else None,
        "program_code": student.program.code if student and student.program else None,
        "defense_type": schedule.defense_type,
        "status": status,
        "date": iso(schedule.preferred_date),
        "start": datetime.combine(schedule.preferred_date, start_time).isoformat(timespec="seconds"),
        "end": datetime.combine(schedule.preferred_date, end_time).isoformat(timespec="seconds"),
        "venue": schedule.venue,
        "mode": schedule.mode,
        "panel": panel,
        "adviser": ", ".join(item.name for item in student_adviser_faculty(student)) if student else None,
        "my_role": defense_seat_role(schedule, scope.get("faculty_id")) if scope["role"] == "faculty" else None,
        "has_verdict": has_verdict,
        "verdict_overdue": overdue,
        "attention": defense_attention(schedule),
        "rescheduled_from_id": schedule.rescheduled_from_id,
        "change_reason": schedule.change_reason,
        "ics_url": f"/api/defense-schedules/{schedule.id}/event.ics",
    }


def calendar_events(scope: dict, start: date, end: date, filters: dict) -> list[dict]:
    query = ScheduleRequest.query.filter(
        ScheduleRequest.preferred_date >= start, ScheduleRequest.preferred_date <= end,
    ).order_by(ScheduleRequest.preferred_date, ScheduleRequest.start_time)
    if scope["role"] == "student":
        query = query.filter(ScheduleRequest.student_id == (scope["student_id"] or -1))
    status_filter = (filters.get("status") or "").strip()
    if status_filter and status_filter != "all":
        query = query.filter(ScheduleRequest.status == status_filter)
    elif not status_filter:
        query = query.filter(ScheduleRequest.status.notin_(CALENDAR_HIDDEN_STATUSES))
    if filters.get("defense_type"):
        query = query.filter(ScheduleRequest.defense_type == filters["defense_type"])
    if filters.get("venue"):
        query = query.filter(ScheduleRequest.venue.ilike(f"%{filters['venue']}%"))
    rows = query.all()
    verdict_ids = {
        schedule_id for (schedule_id,) in db.session.query(DefenseVerdict.schedule_request_id)
        .filter(DefenseVerdict.schedule_request_id.in_([row.id for row in rows] or [-1])).all()
    }
    events = []
    needle = (filters.get("q") or "").strip().lower()
    for schedule in rows:
        student = schedule.student
        if not schedule_in_scope(scope, schedule):
            continue
        if filters.get("program_id") and (not student or student.program_id != filters["program_id"]):
            continue
        if filters.get("faculty_id") and filters["faculty_id"] not in schedule_panel_ids(schedule):
            continue
        if needle and not (student and (needle in student.name.lower() or needle in (student.student_number or "").lower())):
            continue
        events.append(calendar_defense_event(schedule, scope, verdict_ids))
    return events


def deadline_urgency(due: date, done: bool) -> str:
    if done:
        return "done"
    days = (due - date.today()).days
    return "overdue" if days < 0 else "soon" if days <= 3 else "later"


def deadline_item(kind: str, label: str, due: date, student: Student | None, *, done: bool, **extra) -> dict:
    return {
        "id": f"{kind}-{extra.get('schedule_id') or extra.get('appointment_id')}",
        "kind": kind,
        "label": label,
        "date": iso(due),
        "student_id": student.id if student else None,
        "student_name": student.name if student else None,
        "done": done,
        "urgency": deadline_urgency(due, done),
        **extra,
    }


def schedule_deadlines(schedule: ScheduleRequest) -> list[dict]:
    """Protocol deadlines that hang on one booked or held defense."""
    student = schedule.student
    day = schedule.preferred_date
    has_verdict = DefenseVerdict.query.filter_by(schedule_request_id=schedule.id).first() is not None
    items = []
    meta = {"schedule_id": schedule.id, "defense_type": schedule.defense_type}
    if schedule.status in SLOT_HOLDING_DEFENSE_STATUSES or schedule.status == HELD_DEFENSE_STATUS:
        if schedule.defense_type == "Title Defense":
            endorsement = Form1Endorsement.query.filter_by(student_id=schedule.student_id, status="Endorsed").first()
            due = day - timedelta(days=defense_lead_days("Title Defense"))
            done = bool(endorsement and endorsement.endorsed_at and endorsement.endorsed_at.date() <= due)
            items.append(deadline_item(
                "form1_due", "Form 1 and three concept papers endorsed (14 days before the title defense)", due, student, done=done, **meta))
        else:
            due = day - timedelta(days=defense_lead_days(schedule.defense_type or "Proposal Defense"))
            done = bool(schedule.manuscript_received_on and schedule.manuscript_received_on <= due) or schedule.status == HELD_DEFENSE_STATUS
            items.append(deadline_item(
                "manuscript_to_panel", "Manuscript and Form 4 with the panel (14-Day Rule)", due, student, done=done, **meta))
        after = next_working_day(day)
        items.append(deadline_item(
            "verdict_due", "Verdict and comment sheets (Forms 2 / 5 / 6 / 7) due", after, student, done=has_verdict, **meta))
        if not has_verdict and schedule.status != HELD_DEFENSE_STATUS:
            items.append(deadline_item(
                "fee_receipt_due", "Panel fee receipt emailed to the GS Office", after, student, done=False, **meta))
    if schedule.defense_type == "Proposal Defense" and schedule.status == HELD_DEFENSE_STATUS and student:
        due = day + timedelta(days=ETHICS_APPLICATION_WINDOW_DAYS)
        items.append(deadline_item(
            "ethics_due", "Ethics review application (Form 5.2) within one month of the proposal defense",
            due, student, done=student_ethics_cleared(student), **meta))
    return items


def calendar_deadlines(scope: dict, start: date, end: date) -> list[dict]:
    query = ScheduleRequest.query.filter(
        ScheduleRequest.preferred_date >= start - timedelta(days=40),
        ScheduleRequest.preferred_date <= end + timedelta(days=20),
        ScheduleRequest.status.notin_(CALENDAR_HIDDEN_STATUSES + (DEFERRED_DEFENSE_STATUS,)),
    )
    if scope["role"] == "student":
        query = query.filter(ScheduleRequest.student_id == (scope["student_id"] or -1))
    items = []
    for schedule in query.all():
        if not schedule_in_scope(scope, schedule):
            continue
        items.extend(item for item in schedule_deadlines(schedule) if start <= parse_date(item["date"]) <= end)
    contracts = AdviserAppointment.query.filter(
        AdviserAppointment.status == ADVISER_STATUS_ACCEPTED,
        AdviserAppointment.ended_at.is_(None),
        AdviserAppointment.contract_due_on.isnot(None),
        AdviserAppointment.contract_due_on >= start,
        AdviserAppointment.contract_due_on <= end,
    ).all()
    for row in contracts:
        if scope["role"] == "student" and row.student_id != scope["student_id"]:
            continue
        if scope["role"] == "faculty" and row.faculty_id != scope["faculty_id"]:
            continue
        items.append(deadline_item(
            "adviser_contract_due", "Forms 3.2 and 3.3 (research timetable and advising contract) due",
            row.contract_due_on, row.student, done=bool(row.contract_submitted_at), appointment_id=row.id,
        ))
    return sorted(items, key=lambda item: (item["date"], item["kind"]))


def calendar_availability_layer(faculty: Faculty, start: date, end: date) -> list[dict]:
    bundle = faculty_availability_bundle(faculty)
    layer = []
    day = start
    while day <= end and len(layer) < 120:
        state = faculty_day_availability(faculty, day, bundle)
        layer.append({
            "date": iso(day),
            "entered": state["entered"],
            "windows": [{"start": a.strftime("%H:%M"), "end": b.strftime("%H:%M")} for a, b in state["windows"]],
            "blocked": [
                {"start": item["start"].strftime("%H:%M") if item["start"] else None,
                 "end": item["end"].strftime("%H:%M") if item["end"] else None,
                 "all_day": item["all_day"], "note": item["note"]}
                for item in state["blocked"]
            ],
        })
        day += timedelta(days=1)
    return layer


def calendar_filter_options() -> dict:
    return {
        "programs": [{"id": p.id, "code": p.code, "name": p.name} for p in Program.query.order_by(Program.code).all()],
        "defense_types": list(SCHEDULABLE_DEFENSE_TYPES),
        "statuses": list(CALENDAR_STATUS_OPTIONS),
        "venues": sorted({v for (v,) in db.session.query(ScheduleRequest.venue).distinct().all() if v}),
        "faculty": [{"id": f.id, "name": f.name} for f in Faculty.query.filter_by(active=True).order_by(Faculty.name).all()],
    }


def calendar_payload(account: UserAccount, args) -> dict:
    """The one calendar API every role's page reads: events, deadline overlay, availability layer."""
    start, end = parse_calendar_range(args)
    scope = calendar_scope(account)
    layers = {item.strip() for item in (args.get("layers") or "").split(",")} & CALENDAR_LAYERS
    filters = {
        "program_id": args.get("program_id", type=int) if hasattr(args, "get") else None,
        "defense_type": (args.get("defense_type") or "").strip(),
        "status": (args.get("status") or "").strip(),
        "faculty_id": args.get("faculty_id", type=int),
        "venue": (args.get("venue") or "").strip(),
        "q": (args.get("q") or "").strip(),
    }
    payload = {
        "timezone": CALENDAR_TIMEZONE,
        "scope": account.role,
        "range": {"start": iso(start), "end": iso(end)},
        "events": calendar_events(scope, start, end, filters),
        "deadlines": calendar_deadlines(scope, start, end) if "deadlines" in layers else [],
        "availability": [],
        "busy": [],
        "busy_status": None,
        "filters": calendar_filter_options() if account.role not in ("student",) else {},
    }
    faculty = db.session.get(Faculty, account.faculty_id) if account.role == "faculty" and account.faculty_id else None
    if faculty and "availability" in layers:
        payload["availability"] = calendar_availability_layer(faculty, start, end)
    if faculty and "busy" in layers and google_calendar_configured(faculty):
        result = google_freebusy_lookup(faculty, start, end)
        payload["busy_status"] = result.get("error") or "Google Calendar busy periods loaded"
        payload["busy"] = [
            {"date": iso(day), **busy}
            for offset in range((end - start).days + 1)
            for day in [start + timedelta(days=offset)]
            for busy in google_busy_payload_for_day(result.get("busy", []), day)
        ]
    return payload


# ---- .ics -------------------------------------------------------------------------------------
ICS_TIMEZONE_BLOCK = [
    "BEGIN:VTIMEZONE",
    f"TZID:{CALENDAR_TIMEZONE}",
    "BEGIN:STANDARD",
    "DTSTART:19700101T000000",
    "TZOFFSETFROM:+0800",
    "TZOFFSETTO:+0800",
    "TZNAME:PST",
    "END:STANDARD",
    "END:VTIMEZONE",
]


def ics_fold(line: str) -> list[str]:
    """RFC 5545: lines longer than 75 octets are folded with a leading space."""
    raw = line.encode("utf-8")
    if len(raw) <= 75:
        return [line]
    parts, current = [], b""
    for char in line:
        encoded = char.encode("utf-8")
        limit = 75 if not parts else 74
        if len(current) + len(encoded) > limit:
            parts.append(current.decode("utf-8"))
            current = b""
        current += encoded
    parts.append(current.decode("utf-8"))
    return [parts[0]] + [f" {part}" for part in parts[1:]]


def ics_defense_event(event: dict, uid_suffix: str = "usls-gs", alarms: bool = True) -> list[str]:
    start = datetime.fromisoformat(event["start"])
    end = datetime.fromisoformat(event["end"])
    panel = "; ".join(f"{seat['name']} ({seat['role']})" for seat in event.get("panel", []) if seat.get("name"))
    description = f"{event['defense_type']} of {event['student_name']}. Mode: {event.get('mode') or 'not stated'}."
    if panel:
        description += f" Panel: {panel}."
    if event.get("adviser"):
        description += f" Adviser: {event['adviser']}."
    lines = [
        "BEGIN:VEVENT",
        f"UID:defense-{event['schedule_id']}@{uid_suffix}",
        f"DTSTAMP:{datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')}",
        f"DTSTART;TZID={CALENDAR_TIMEZONE}:{start.strftime('%Y%m%dT%H%M%S')}",
        f"DTEND;TZID={CALENDAR_TIMEZONE}:{end.strftime('%Y%m%dT%H%M%S')}",
        f"SUMMARY:{calendar_text(event['defense_type'] + ' - ' + (event['student_name'] or ''))}",
        f"LOCATION:{calendar_text(event.get('venue') or '')}",
        f"DESCRIPTION:{calendar_text(description)}",
        f"STATUS:{'CANCELLED' if event['status'] in CALENDAR_HIDDEN_STATUSES else 'CONFIRMED'}",
    ]
    if alarms:
        for label, trigger in (("one day before", "-P1D"), ("one hour before", "-PT1H")):
            lines += [
                "BEGIN:VALARM", "ACTION:DISPLAY", f"DESCRIPTION:{calendar_text(event['defense_type'] + ' ' + label)}",
                f"TRIGGER:{trigger}", "END:VALARM",
            ]
    lines.append("END:VEVENT")
    return lines


def ics_deadline_event(item: dict, uid_suffix: str = "usls-gs") -> list[str]:
    day = parse_date(item["date"])
    who = f" ({item['student_name']})" if item.get("student_name") else ""
    return [
        "BEGIN:VEVENT",
        f"UID:{item['id']}@{uid_suffix}",
        f"DTSTAMP:{datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')}",
        f"DTSTART;VALUE=DATE:{day.strftime('%Y%m%d')}",
        f"DTEND;VALUE=DATE:{(day + timedelta(days=1)).strftime('%Y%m%d')}",
        f"SUMMARY:{calendar_text('Due: ' + item['label'] + who)}",
        "TRANSP:TRANSPARENT",
        "END:VEVENT",
    ]


def build_ics(name: str, description: str, event_lines: list[list[str]]) -> str:
    lines = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//USLS Graduate School//Defense Calendar//EN",
        "CALSCALE:GREGORIAN",
        "METHOD:PUBLISH",
        f"X-WR-CALNAME:{calendar_text(name)}",
        f"X-WR-CALDESC:{calendar_text(description)}",
        f"X-WR-TIMEZONE:{CALENDAR_TIMEZONE}",
        *ICS_TIMEZONE_BLOCK,
    ]
    for block in event_lines:
        lines.extend(block)
    lines.append("END:VCALENDAR")
    folded = [piece for line in lines for piece in ics_fold(line)]
    return "\r\n".join(folded) + "\r\n"


def next_defense_event(scope: dict) -> dict | None:
    now = manila_now()
    rows = ScheduleRequest.query.filter(
        ScheduleRequest.status.in_(SLOT_HOLDING_DEFENSE_STATUSES),
        ScheduleRequest.preferred_date >= now.date(),
    ).order_by(ScheduleRequest.preferred_date, ScheduleRequest.start_time).all()
    for schedule in rows:
        if schedule_in_scope(scope, schedule) and defense_start_datetime(schedule) >= now - timedelta(hours=3):
            return calendar_defense_event(schedule, scope, set())
    return None


# ---- panel invitations ------------------------------------------------------------------------
def panel_invitation_dict(row: PanelInvitation, include_schedule: bool = False) -> dict:
    payload = {
        "id": row.id,
        "student": student_brief(row.student) if row.student else None,
        "faculty_id": row.faculty_id,
        "faculty_name": row.faculty.name if row.faculty else None,
        "gate": row.gate,
        "defense_type": RESEARCH_GATE_DEFENSE_TYPES.get(row.gate),
        "panel_role": row.panel_role,
        "status": row.status,
        "invited_at": iso(row.invited_at),
        "responded_at": iso(row.responded_at),
        "reason": row.reason,
    }
    if include_schedule:
        defense_type = RESEARCH_GATE_DEFENSE_TYPES.get(row.gate)
        schedule = (
            ScheduleRequest.query.filter(
                ScheduleRequest.student_id == row.student_id,
                ScheduleRequest.defense_type == defense_type,
                ScheduleRequest.status.in_(SLOT_HOLDING_DEFENSE_STATUSES),
            ).order_by(ScheduleRequest.id.desc()).first()
        )
        payload["schedule"] = schedule_request_dict(schedule) if schedule else None
        payload["other_members"] = [
            {"name": item.faculty.name, "role": item.panel_role}
            for item in PanelAssignment.query.filter_by(student_id=row.student_id, gate=row.gate).all()
            if item.faculty and item.faculty_id != row.faculty_id
        ]
    return payload


def sync_panel_invitations(student: Student, gate: str, notify: bool = True) -> int:
    """Make sure every seat on the current panel has an invitation; tell new members once."""
    panel = active_panel_assignments(student, gate)
    seated = {item.faculty_id for item in panel}
    created = 0
    for assignment in panel:
        invitation = PanelInvitation.query.filter_by(student_id=student.id, faculty_id=assignment.faculty_id, gate=gate).first()
        if invitation:
            invitation.panel_role = assignment.panel_role
            continue
        carried = None
        if gate == RESEARCH_GATE_FINAL:
            carried = PanelInvitation.query.filter_by(
                student_id=student.id, faculty_id=assignment.faculty_id, gate=RESEARCH_GATE_PROPOSAL, status="Accepted",
            ).first()
        invitation = PanelInvitation(
            student_id=student.id, faculty_id=assignment.faculty_id, gate=gate, panel_role=assignment.panel_role,
            status="Accepted" if carried else "Invited",
            responded_at=now_utc() if carried else None,
            reason="Carried over from the proposal defense panel" if carried else None,
        )
        db.session.add(invitation)
        db.session.flush()
        created += 1
        if notify and not carried:
            notify_many(
                accounts_for_faculty(assignment.faculty_id), "panel_invited",
                f"You are invited to the {RESEARCH_GATE_DEFENSE_TYPES.get(gate, 'defense')} panel of {student.name}",
                f"Role: {assignment.panel_role}. Accept or decline in Panel Invitations.",
                link="/faculty-portal/invitations", related_type="panel_invitation", related_id=invitation.id,
                dedupe_key=f"panel_invited:{invitation.id}",
            )
    for invitation in PanelInvitation.query.filter_by(student_id=student.id, gate=gate, status="Declined").all():
        if invitation.faculty_id not in seated and invitation.faculty:
            close_research_tasks(student.id, prefix=f"Replace declined panelist: {invitation.faculty.name}")
    return created


def ensure_invitations_for_faculty(faculty: Faculty) -> None:
    """Create the invitations a faculty member should have for seats on a student's current panel."""
    for assignment in PanelAssignment.query.filter_by(faculty_id=faculty.id).all():
        student = assignment.student
        if not student:
            continue
        gate = current_panel_gate(student)
        if assignment.gate == gate:
            sync_panel_invitations(student, gate, notify=False)


# ---- notifications about schedule changes -----------------------------------------------------
def defense_slot_text(day: date, start: time | None, end: time | None) -> str:
    return f"{day.isoformat()} {start.strftime('%H:%M') if start else '--:--'}-{end.strftime('%H:%M') if end else '--:--'} ({CALENDAR_TIMEZONE})"


def schedule_people_accounts(schedule: ScheduleRequest) -> list[UserAccount]:
    accounts = list(accounts_for_student(schedule.student_id))
    for faculty_id in sorted(schedule_panel_ids(schedule)):
        accounts.extend(accounts_for_faculty(faculty_id))
    unique = {account.id: account for account in accounts}
    return list(unique.values())


def notify_schedule_people(schedule: ScheduleRequest, kind: str, title: str, body: str, dedupe: str, link_student: str = "/student/calendar") -> None:
    for account in schedule_people_accounts(schedule):
        link = link_student if account.role == "student" else "/faculty-portal/calendar"
        notify_account(
            account, kind, title, body, link=link, related_type="schedule_request", related_id=schedule.id,
            dedupe_key=f"{dedupe}:{schedule.id}",
        )


def notify_defense_booked(schedule: ScheduleRequest, replaced: ScheduleRequest | None, reason: str, requested_by: str | None) -> None:
    slot = defense_slot_text(schedule.preferred_date, schedule.start_time, schedule.end_time)
    where = f"{schedule.venue} ({schedule.mode})" if schedule.venue else schedule.mode
    student = schedule.student
    if replaced:
        old = defense_slot_text(replaced.preferred_date, replaced.start_time, replaced.end_time)
        notify_schedule_people(
            schedule, "defense_rescheduled", f"{schedule.defense_type} of {student.name} was rescheduled",
            f"Moved from {old} to {slot}. Venue: {where}. Reason: {reason or 'not recorded'}"
            + (f" (asked by {requested_by})." if requested_by else "."),
            "defense_rescheduled",
        )
    else:
        notify_schedule_people(
            schedule, "defense_scheduled", f"{schedule.defense_type} of {student.name} is scheduled",
            f"{slot}. Venue: {where}.", "defense_scheduled",
        )


def notify_defense_cancelled(schedule: ScheduleRequest, reason: str, requested_by: str | None) -> None:
    slot = defense_slot_text(schedule.preferred_date, schedule.start_time, schedule.end_time)
    notify_schedule_people(
        schedule, "defense_cancelled", f"{schedule.defense_type} of {schedule.student.name} was cancelled",
        f"The defense planned for {slot} was cancelled. Reason: {reason}"
        + (f" (asked by {requested_by})." if requested_by else ".") + " A new date will be set.",
        "defense_cancelled",
    )


# ---- reminders ----------------------------------------------------------------------------------
def defense_reminder_thresholds() -> list[int]:
    raw = str(rule_value("defense.reminder_days", "14,7,2,1"))
    values = sorted({int(item) for item in re.findall(r"\d+", raw)})
    return values or [1, 2, 7, 14]


def generate_reminders(account: UserAccount | None = None, today: date | None = None) -> int:
    """Create every reminder that is due. Idempotent (each notification has a dedupe key), so it can run
    whenever someone opens the bell. With `account` only that person's reminders are made."""
    today = today or manila_now().date()
    thresholds = defense_reminder_thresholds()
    created = 0

    def wanted(target: UserAccount) -> bool:
        return account is None or account.id == target.id

    def add(target: UserAccount, *args, **kwargs) -> None:
        nonlocal created
        if wanted(target) and notify_account(target, *args, **kwargs):
            created += 1

    upcoming = ScheduleRequest.query.filter(
        ScheduleRequest.status.in_(SLOT_HOLDING_DEFENSE_STATUSES),
        ScheduleRequest.preferred_date >= today,
        ScheduleRequest.preferred_date <= today + timedelta(days=max(thresholds)),
    ).all()
    for schedule in upcoming:
        if account is not None and account.role in ("student", "faculty") and not schedule_in_scope(calendar_scope(account), schedule):
            continue
        days_left = (schedule.preferred_date - today).days
        bracket = min((t for t in thresholds if days_left <= t), default=None)
        if bracket is None:
            continue
        slot = defense_slot_text(schedule.preferred_date, schedule.start_time, schedule.end_time)
        when = "today" if days_left == 0 else "tomorrow" if days_left == 1 else f"in {days_left} days"
        for person in schedule_people_accounts(schedule):
            note = (
                f"Panel and adviser: the manuscript must already be with the panel (14-Day Rule). {slot}. Venue: {schedule.venue}."
                if bracket == max(thresholds) and person.role == "faculty"
                else f"{slot}. Venue: {schedule.venue}."
            )
            add(
                person, "defense_reminder", f"Defense {when} ({bracket}-day reminder): {schedule.defense_type} of {schedule.student.name}",
                note, link="/student/calendar" if person.role == "student" else "/faculty-portal/calendar",
                related_type="schedule_request", related_id=schedule.id, due_on=schedule.preferred_date,
                dedupe_key=f"defense_reminder:{schedule.id}:{bracket}",
            )
    # staff: what is on today
    todays = [
        item for item in ScheduleRequest.query.filter(
            ScheduleRequest.status.in_(SLOT_HOLDING_DEFENSE_STATUSES), ScheduleRequest.preferred_date == today,
        ).order_by(ScheduleRequest.start_time).all()
    ]
    if todays:
        for person in accounts_for_roles("staff", "research_coordinator"):
            add(
                person, "defenses_today", f"{len(todays)} defense{'s' if len(todays) != 1 else ''} today",
                "; ".join(f"{item.start_time.strftime('%H:%M') if item.start_time else ''} {item.defense_type} - {item.student.name} ({item.venue})" for item in todays),
                link="/calendar", related_type="schedule_request", dedupe_key=f"defenses_today:{today.isoformat()}", due_on=today,
            )
    # verdicts: the chair is reminded on the day; staff when it is overdue
    started = ScheduleRequest.query.filter(
        ScheduleRequest.status.in_(ACTIVE_DEFENSE_STATUSES), ScheduleRequest.preferred_date <= today,
        ScheduleRequest.preferred_date >= today - timedelta(days=60),
    ).all()
    verdict_ids = {
        sid for (sid,) in db.session.query(DefenseVerdict.schedule_request_id)
        .filter(DefenseVerdict.schedule_request_id.in_([item.id for item in started] or [-1])).all()
    }
    for schedule in started:
        if schedule.id in verdict_ids:
            continue
        due = next_working_day(schedule.preferred_date)
        try:
            seats = json.loads(schedule.panel_snapshot or "[]")
        except (TypeError, json.JSONDecodeError):
            seats = []
        for seat in seats:
            if (seat.get("role") or "").lower() in {"panel chair", "panel lead"}:
                for person in accounts_for_faculty(seat.get("faculty_id")):
                    add(
                        person, "verdict_due", f"Verdict due by {due.isoformat()}: {schedule.defense_type} of {schedule.student.name}",
                        "Submit the verdict and the consolidated comments within the first working day after the defense.",
                        link="/faculty-portal/verdicts", related_type="schedule_request", related_id=schedule.id, due_on=due,
                        dedupe_key=f"verdict_due:{schedule.id}",
                    )
        if today > due:
            for person in accounts_for_roles("staff", "research_coordinator"):
                add(
                    person, "verdict_overdue", f"Verdict overdue: {schedule.defense_type} of {schedule.student.name}",
                    f"The defense was on {schedule.preferred_date.isoformat()}; the verdict was due {due.isoformat()}.",
                    link="/calendar", related_type="schedule_request", related_id=schedule.id,
                    dedupe_key=f"verdict_overdue:{schedule.id}",
                )
    # faculty: availability not entered while seated on a panel, overdue requests, signatures waiting
    for person in (accounts_for_roles("faculty") if account is None else ([account] if account.role == "faculty" else [])):
        faculty = db.session.get(Faculty, person.faculty_id) if person.faculty_id else None
        if not faculty:
            continue
        seats = PanelAssignment.query.filter_by(faculty_id=faculty.id).count() + len(advisee_student_ids(faculty))
        if seats and not faculty_availability_entered(faculty):
            add(
                person, "availability_missing", "Please enter your availability",
                "You sit on panels or advise students, but no availability is entered, so the Graduate School cannot check your time.",
                link="/faculty-portal/availability", related_type="faculty", related_id=faculty.id,
                dedupe_key=f"availability_missing:{faculty.id}",
            )
        overdue_days = int(rule_value("defense.availability_reminder_days", 3))
        for request_row in AvailabilityRequest.query.filter_by(faculty_id=faculty.id, status="Open").all():
            if request_row.created_at and (today - request_row.created_at.date()).days >= overdue_days:
                add(
                    person, "availability_request_overdue", "An availability request is still waiting for you",
                    request_row.message or "Staff asked for your available dates for a defense.",
                    link="/faculty-portal/availability", related_type="availability_request", related_id=request_row.id,
                    dedupe_key=f"availability_request_overdue:{request_row.id}",
                )
        waiting_days = int(rule_value("research.signature_reminder_days", 3))
        for student_id in advisee_student_ids(faculty):
            for check in DocumentCheck.query.filter(
                DocumentCheck.student_id == student_id, DocumentCheck.item_name.in_(ADVISER_APPROVAL_DOCUMENTS),
            ).all():
                files = sorted(check.evidence_files, key=lambda item: item.uploaded_at or now_utc())
                latest = files[-1] if files else None
                if not latest or not latest.uploaded_at or (today - latest.uploaded_at.date()).days < waiting_days:
                    continue
                if AdviserDocumentApproval.query.filter_by(evidence_file_id=latest.id).first():
                    continue
                student = db.session.get(Student, student_id)
                add(
                    person, "signature_waiting", f"Signature waiting: {check.item_name} of {student.name if student else 'a student'}",
                    f"Uploaded {latest.uploaded_at.date().isoformat()}; it has been waiting {(today - latest.uploaded_at.date()).days} days.",
                    link="/faculty-portal/signatures", related_type="evidence_file", related_id=latest.id,
                    dedupe_key=f"signature_waiting:{latest.id}",
                )
    # students: ethics application and advising-contract deadlines
    for student_account in (accounts_for_roles("student") if account is None else ([account] if account.role == "student" else [])):
        if not student_account.student_id:
            continue
        scope = calendar_scope(student_account)
        for item in calendar_deadlines(scope, today, today + timedelta(days=7)):
            if item["done"] or item["kind"] not in ("ethics_due", "adviser_contract_due", "manuscript_to_panel"):
                continue
            add(
                student_account, "deadline_soon", f"Due {item['date']}: {item['label']}", "",
                link="/student/calendar", related_type=item["kind"], dedupe_key=f"deadline_soon:{item['id']}", due_on=parse_date(item["date"]),
            )
    return created


def notification_dict(row: Notification) -> dict:
    return {
        "id": row.id, "kind": row.kind, "title": row.title, "body": row.body, "link": row.link,
        "related_type": row.related_type, "related_id": row.related_id, "due_on": iso(row.due_on),
        "created_at": iso(row.created_at), "read_at": iso(row.read_at),
    }


# ---- private calendar feed ---------------------------------------------------------------------
def active_calendar_token(account: UserAccount) -> CalendarToken | None:
    return CalendarToken.query.filter_by(account_id=account.id, revoked_at=None).order_by(CalendarToken.id.desc()).first()


def calendar_feed_dict(row: CalendarToken | None) -> dict | None:
    if not row:
        return None
    path = f"/api/calendar/feed/{row.token}.ics"
    return {
        "url": path,
        "absolute_url": f"{request.url_root.rstrip('/')}{path}" if has_request_context() else path,
        "created_at": iso(row.created_at),
        "last_used_at": iso(row.last_used_at),
    }


def calendar_feed_for_account(account: UserAccount) -> str:
    """Defenses and deadlines for one person, exactly what their calendar page shows."""
    scope = calendar_scope(account)
    today = date.today()
    events = calendar_events(scope, today - timedelta(days=30), today + timedelta(days=200), {})
    deadlines = [
        item for item in calendar_deadlines(scope, today - timedelta(days=3), today + timedelta(days=200)) if not item["done"]
    ]
    blocks = [ics_defense_event(event) for event in events if event["kind"] == "defense"]
    blocks += [ics_deadline_event(item) for item in deadlines]
    return build_ics(
        f"USLS Graduate School - {account.full_name}",
        "Defenses and deadlines from the Graduate School platform. Private link: do not share it.",
        blocks,
    )


def faculty_adviser_inbox(faculty: Faculty) -> tuple[list[AdviserAppointment], list[AdviserAppointment]]:
    """(appointments waiting for this faculty member's answer, change requests waiting for their consent)."""
    inbox = [
        row for row in AdviserAppointment.query.filter_by(faculty_id=faculty.id, adviser_response="Pending")
        .order_by(AdviserAppointment.id.desc()).all()
        if (row.kind != "Change" and row.status == ADVISER_STATUS_APPOINTED)
        or (row.kind == "Change" and row.status == ADVISER_STATUS_APPLIED)
    ]
    consents = []
    for row in AdviserAppointment.query.filter_by(kind="Change", status=ADVISER_STATUS_APPLIED, current_adviser_consent="Pending").all():
        previous = db.session.get(AdviserAppointment, row.replaces_id) if row.replaces_id else None
        if previous and previous.faculty_id == faculty.id:
            consents.append(row)
    return inbox, consents


def faculty_open_invitations(faculty: Faculty) -> list[PanelInvitation]:
    """Invitations on a student's current panel that this faculty member has not answered yet."""
    ensure_invitations_for_faculty(faculty)
    rows = []
    for row in PanelInvitation.query.filter_by(faculty_id=faculty.id, status="Invited").all():
        student = row.student
        if student and row.gate == current_panel_gate(student) and PanelAssignment.query.filter_by(
            student_id=row.student_id, faculty_id=faculty.id, gate=row.gate,
        ).first():
            rows.append(row)
    return rows


