def _email_slug(value: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", ".", (value or "").strip().lower()).strip(".")
    return slug or "student"


def default_student_email(first_name: str, last_name: str, student_number: str = "") -> str:
    first = _email_slug(first_name)
    last = _email_slug(last_name)
    local = f"{first}.{last}" if first != "student" or last != "student" else _email_slug(student_number)
    return f"{local}@{STUDENT_EMAIL_DOMAIN}"


def unique_student_email(first_name: str, last_name: str, student_number: str = "", current_student_id: int | None = None) -> str:
    base = default_student_email(first_name, last_name, student_number)
    local, _, domain = base.partition("@")
    candidate = base
    suffix = 2
    while True:
        with db.session.no_autoflush:
            student_query = Student.query.filter(func.lower(Student.email) == candidate.lower())
            if current_student_id:
                student_query = student_query.filter(Student.id != current_student_id)
            student_exists = student_query.first() is not None
            account_exists = UserAccount.query.filter(func.lower(UserAccount.email) == candidate.lower()).first() is not None
        if not student_exists and not account_exists:
            return candidate
        candidate = f"{local}{suffix}@{domain}"
        suffix += 1


def new_student_initial_password() -> tuple[str, bool]:
    """(initial password, must change it at first sign-in) for a newly created student login.

    DEMO_MODE on: the shared demo password, so the presenter's demo keeps working.
    DEMO_MODE off: a random password nobody else knows; the staff member who created the
    account is shown it once and the student must replace it at first sign-in.
    """
    if demo_mode_enabled():
        return SIM_STUDENT_PASSWORD, False
    import secrets
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
    return "".join(secrets.choice(alphabet) for _ in range(12)), True


def ensure_student_account(student: Student, email: str, password: str | None = None) -> UserAccount:
    # Idempotently link (or create) a student-portal account so a handed-off student
    # can sign in to upload concept papers and file LOA / withdrawal requests.
    # A NEW account gets new_student_initial_password() unless a password is passed; its
    # plain value is left on `account.initial_password` (in memory only) so the caller can
    # show it once. Existing accounts keep whatever password they have.
    email = (email or student.email or "").strip().lower()
    account = UserAccount.query.filter_by(email=email).first()
    if not account:
        must_change = False
        if password is None:
            password, must_change = new_student_initial_password()
        account = UserAccount(
            email=email,
            full_name=f"{student.name} (Student)",
            password_hash=generate_password_hash(password),
            role="student",
            active=True,
            must_change_password=must_change,
        )
        account.initial_password = password
        if has_request_context():
            # Whoever created the account is shown this once, in this response only.
            credentials = getattr(_flask_g, "new_student_credentials", None)
            if credentials is None:
                credentials = _flask_g.new_student_credentials = []
            credentials.append({"email": email, "password": password, "must_change_password": must_change})
        db.session.add(account)
    account.student_id = student.id
    account.full_name = f"{student.name} (Student)"
    account.active = True
    return account


def workflow_demo_config_for_student(student: Student | None) -> tuple[str, dict] | tuple[None, None]:
    if not student:
        return None, None
    for demo_key, config in WORKFLOW_DEMO_STUDENTS.items():
        if student.student_number == config["student_number"]:
            return demo_key, config
    return None, None


DEMO_LEAVE_PERIODS = {
    # (leave starts, leave ends) for the two readmission demo students.
    "GS-2026-READ-01": ("AY 2026-2027 1st Semester", "AY 2026-2027 1st Semester"),
    "GS-2026-READ-02": ("AY 2026-2027 1st Semester", "AY 2026-2027 2nd Semester"),
}


def ensure_demo_leave_case(student: Student, demo_config: dict | None) -> LeaveCase:
    """The approved leave a readmission demo student is on (created once, reset on demand)."""
    start_label, end_label = DEMO_LEAVE_PERIODS.get(student.student_number, (
        "AY 2026-2027 1st Semester", "AY 2026-2027 1st Semester",
    ))
    start_term, end_term = leave_term(start_label), leave_term(end_label)
    case = (
        LeaveCase.query.filter_by(student_id=student.id, kind=KIND_LOA, source="demo")
        .order_by(LeaveCase.id.desc()).first()
    )
    if case is None:
        case = LeaveCase(
            student_id=student.id, kind=KIND_LOA, source="demo", status="On Leave",
            reason_category="Medical / health", reason_text="Approved leave for the readmission demonstration.",
            submitted_at=now_utc() - timedelta(days=60), forwarded_at=now_utc() - timedelta(days=58),
            decided_at=now_utc() - timedelta(days=55), started_at=now_utc() - timedelta(days=50),
            prior_stage="Coursework", prior_enrollment_tag="Enrolled", registrar_status="Acknowledged",
        )
        db.session.add(case)
        db.session.flush()
        for from_status, to_status, action in (
            (None, "Submitted", "submit"), ("Submitted", "Dean Review", "forward"),
            ("Dean Review", "On Leave", "approve"),
        ):
            db.session.add(LeaveCaseEvent(
                case_id=case.id, from_status=from_status, to_status=to_status, action=action,
                actor_role="Demo Data", actor_name="Demo Data",
            ))
    case.status = "On Leave"
    case.closed_at = case.closed_reason = case.awol_proposed_at = case.return_reminded_at = None
    case.start_term_id, case.end_term_id = (start_term.id if start_term else None), (end_term.id if end_term else None)
    case.start_label, case.end_label = start_label, end_label
    student.standing = "On Leave"
    student.current_stage = "LOA"
    student.enrollment_tag = "LOA"
    student.risk_level = "On Track"
    db.session.flush()
    for term in leave_covered_terms(case):
        ensure_term_enrollment(student, term, "LOA", LEAVE_TERM_SOURCE)
    return case


def ensure_workflow_demo_student_baseline(student: Student, workflow: str) -> None:
    """Keep upstream requirements complete without resetting the active demo case."""
    _, demo_config = workflow_demo_config_for_student(student)
    program_code = (demo_config or {}).get("program_code", "MAED")
    program = Program.query.filter(func.upper(Program.code) == program_code.upper()).first()
    if not program:
        raise ValueError(f"The {program_code} demo curriculum is not available.")

    is_withdrawal_demo = workflow == "withdrawal"
    is_research_demo = workflow == "research"
    is_enrollment_demo = workflow == "enrollment"
    is_adjustments_demo = workflow == "course-adjustments"
    is_loa_demo = workflow == "leave-of-absence"
    is_awol_demo = workflow == "awol"
    is_handoff_demo = workflow == "student-handoff"
    is_readmission_demo = workflow == "readmission"
    # A demo student who already has a leave case keeps the standing that case gave them;
    # the baseline only builds the starting state (first login, or after a reset).
    has_leave_case = bool(
        (is_loa_demo or is_readmission_demo)
        and LeaveCase.query.filter_by(student_id=student.id).first() is not None
    )
    is_new_demo = (
        is_enrollment_demo
        or is_adjustments_demo
        or is_loa_demo
        or is_awol_demo
        or is_handoff_demo
        or is_readmission_demo
    )
    withdrawal_application = latest_withdrawal_application(student.id) if is_withdrawal_demo else None
    withdrawal_complete = bool(
        withdrawal_application
        and (
            withdrawal_application.status in {
                "Subject Tagged - Registrar Preparation",
                "Exported - Ready to Send",
                "Sent to Registrar",
                "Withdrawn Confirmed",
            }
            or (
                withdrawal_application.subject_enrollment
                and withdrawal_application.subject_enrollment.status == "Withdrawn"
            )
        )
    )
    student.program_id = program.id
    student.entry_year = student.entry_year if is_research_demo else 2026 if (is_withdrawal_demo or is_new_demo) else 2024
    student.academic_year_entry = student.academic_year_entry if is_research_demo else "2026-2027" if (is_withdrawal_demo or is_new_demo) else "2024-2025"
    student.year_level = "Year 1" if (is_withdrawal_demo or is_new_demo) else "Completed Coursework"
    leave_snapshot = (student.standing, student.enrollment_tag, student.current_stage, student.risk_level)
    student.standing = "Active"
    student.enrollment_tag = (
        "Completed" if workflow == "graduation"
        else "LOA" if is_readmission_demo
        else "Not Enrolled" if (
            is_enrollment_demo
            or is_adjustments_demo
            or is_handoff_demo
            or (is_awol_demo and demo_config.get("scenario") == "residency")
        )
        else "Enrolled"
    )
    student.current_stage = (
        "Completed" if workflow == "graduation"
        else "Admission" if is_handoff_demo
        else "LOA" if is_readmission_demo
        else "Coursework" if (is_withdrawal_demo or is_enrollment_demo or is_adjustments_demo or is_loa_demo)
        else "Writing" if is_awol_demo and demo_config.get("scenario") == "residency"
        else "AWOL" if is_awol_demo
        else "Proposal Development" if is_research_demo
        else "Final Defense"
    )
    student.comprehensive_exam_status = "Not Taken" if (is_withdrawal_demo or is_enrollment_demo or is_adjustments_demo or is_loa_demo) else "Passed"
    student.risk_level = "Not Yet Assessed"
    student.adviser_name = student.adviser_name or "Dr. Liwayway Bautista"
    student.updated_at = now_utc()
    if has_leave_case:
        student.standing, student.enrollment_tag, student.current_stage, student.risk_level = leave_snapshot

    if workflow == "practicum":
        # Practicum demo identities changed from the retired MAED fixtures to
        # their confirmed MAPSY/MSGC tracks. Remove only their obsolete
        # cross-program course projections so the student portal stays coherent.
        for record in (
            CourseRecord.query.join(Course)
            .filter(
                CourseRecord.student_id == student.id,
                Course.program_id != program.id,
            )
            .all()
        ):
            db.session.delete(record)

    active_course_code = (demo_config or {}).get("active_course_code", "")
    active_course_codes = set(
        (demo_config or {}).get("active_course_codes")
        or ([active_course_code] if active_course_code else [])
    )
    withdrawn_course_id = (
        withdrawal_application.subject_enrollment.course_id
        if withdrawal_complete
        and withdrawal_application
        and withdrawal_application.subject_enrollment
        else None
    )
    current_course_codes = set((demo_config or {}).get("current_course_codes", []))
    active_term = get_active_term() if is_withdrawal_demo else None
    demo_courses = monitoring_curriculum_courses(program)
    for course_index, course in enumerate(demo_courses):
        record = CourseRecord.query.filter_by(student_id=student.id, course_id=course.id).first()
        if not record:
            # Some workflow fixtures look up the active term before assigning
            # their final status. Give new records a valid interim value so
            # SQLAlchemy's query-triggered autoflush cannot violate NOT NULL.
            record = CourseRecord(
                student_id=student.id,
                course_id=course.id,
                status="Not Started",
            )
            db.session.add(record)
        if has_leave_case and course.code in current_course_codes:
            continue  # the leave already decided what this subject looks like
        if course.code in current_course_codes:
            active_term = active_term or get_active_term()
            record.status = "Enrolled"
            record.grade_status = "No Grade"
            record.grade_value = None
            record.term_label = active_term.label if active_term else None
            record.evidence_reference = "Requested MAED demo enrollment"
            record.resolved_at = None
        elif is_withdrawal_demo:
            is_active_course = course.code in active_course_codes
            is_withdrawn_course = is_active_course and course.id == withdrawn_course_id
            record.status = "Withdrawn" if is_withdrawn_course else "Current" if is_active_course else "Not Started"
            record.grade_status = "No Grade"
            record.grade_value = None
            record.term_label = active_term.label if is_active_course and active_term else None
            record.evidence_reference = (
                "Approved subject withdrawal."
                if is_withdrawn_course
                else "Withdrawal demo active enrollment"
                if is_active_course
                else None
            )
            record.resolved_at = None
        elif is_new_demo:
            completed_count = 0
            if is_adjustments_demo:
                completed_count = max(len(demo_courses) - 2, 0) if student.student_number.endswith("02") else min(2, len(demo_courses))
            elif is_enrollment_demo and student.student_number.endswith("02"):
                completed_count = min(2, len(demo_courses))
            elif is_loa_demo or is_readmission_demo:
                completed_count = min(3, len(demo_courses))
            elif is_awol_demo:
                completed_count = min(4, len(demo_courses))
            completed = course_index < completed_count
            record.status = "Completed" if completed else "Not Started"
            record.grade_status = "Passed" if completed else "No Grade"
            record.grade_value = "1.50" if completed else None
            record.term_label = "AY 2025-2026 2nd Semester" if completed else None
            record.evidence_reference = "Demo prerequisite baseline" if completed else None
            record.resolved_at = now_utc() if completed else None
        else:
            record.status = "Completed"
            record.grade_status = "Passed"
            record.grade_value = record.grade_value or "1.50"
            record.term_label = record.term_label or "AY 2025-2026 2nd Semester"
            record.evidence_reference = "Workflow demo prerequisite baseline"
            record.resolved_at = record.resolved_at or now_utc()
        record.updated_at = now_utc()

    # Subject withdrawal begins while the student is active in several classes.
    # The student chooses one class, and completing the request preserves every
    # other active subject and the student's enrolled program standing.
    if is_withdrawal_demo:
        active_courses = (
            Course.query.filter(
                Course.program_id == program.id,
                Course.code.in_(active_course_codes),
            )
            .order_by(Course.id.asc())
            .all()
        )
        default_enrollment = None
        if active_courses and active_term:
            academic_year, semester = split_academic_term_label(active_term.label)
            for active_course in active_courses:
                if academic_year and semester and not CurriculumOffering.query.filter_by(
                    program_id=program.id,
                    academic_year=academic_year,
                    semester=semester,
                    course_id=active_course.id,
                ).first():
                    db.session.add(CurriculumOffering(
                        program_id=program.id,
                        academic_year=academic_year,
                        semester=semester,
                        course_id=active_course.id,
                        added_by="Workflow demo baseline",
                    ))
                enrollment = SubjectEnrollment.query.filter_by(
                    student_id=student.id,
                    course_id=active_course.id,
                    term_id=active_term.id,
                ).first()
                if not enrollment:
                    enrollment = SubjectEnrollment(
                        student_id=student.id,
                        course_id=active_course.id,
                        term_id=active_term.id,
                        source_reference="Withdrawal demo active enrollment",
                    )
                    db.session.add(enrollment)
                is_withdrawn_course = active_course.id == withdrawn_course_id
                enrollment.status = "Withdrawn" if is_withdrawn_course else "Enrolled"
                enrollment.status_note = (
                    "Approved subject withdrawal."
                    if is_withdrawn_course
                    else None
                )
                enrollment.cancelled_at = (
                    withdrawal_application.completed_at
                    if is_withdrawn_course and withdrawal_application
                    else None
                )
                enrollment.updated_at = now_utc()
                if active_course.code == active_course_code:
                    default_enrollment = enrollment
            ensure_term_enrollment(
                student,
                active_term,
                "Enrolled",
                "Withdrawal demo active enrollment",
            )
            if withdrawal_application and not withdrawal_application.subject_enrollment_id and default_enrollment:
                db.session.flush()
                withdrawal_application.subject_enrollment_id = default_enrollment.id
                withdrawal_application.withdrawal_scope = "Subject"
                withdrawal_application.effective_term = active_term.label
        return

    if is_new_demo:
        active_term = get_active_term()
        if current_course_codes and active_term and not has_leave_case:
            academic_year, semester = split_academic_term_label(active_term.label)
            for course_code in current_course_codes:
                course = Course.query.filter_by(program_id=program.id, code=course_code).first()
                if not course:
                    continue
                if academic_year and semester and not CurriculumOffering.query.filter_by(
                    program_id=program.id,
                    academic_year=academic_year,
                    semester=semester,
                    course_id=course.id,
                ).first():
                    db.session.add(CurriculumOffering(
                        program_id=program.id,
                        academic_year=academic_year,
                        semester=semester,
                        course_id=course.id,
                        added_by="Requested MAED demo enrollment",
                    ))
                enrollment = SubjectEnrollment.query.filter_by(
                    student_id=student.id,
                    course_id=course.id,
                    term_id=active_term.id,
                ).first()
                if not enrollment:
                    enrollment = SubjectEnrollment(
                        student_id=student.id,
                        course_id=course.id,
                        term_id=active_term.id,
                        source_reference="Requested MAED demo enrollment",
                    )
                    db.session.add(enrollment)
                enrollment.status = "Enrolled"
                enrollment.cancelled_at = None
                enrollment.updated_at = now_utc()
            ensure_term_enrollment(
                student,
                active_term,
                "Enrolled",
                "Requested MAED demo enrollment",
            )
            student.enrollment_tag = "Enrolled"
        if is_loa_demo and active_term and not has_leave_case:
            ensure_term_enrollment(student, active_term, "Enrolled", "LOA demo active standing")
        if is_readmission_demo:
            ensure_demo_leave_case(student, demo_config)
        if is_handoff_demo:
            student.standing = "Active"
            student.current_stage = "Admission"
            student.enrollment_tag = "Not Enrolled"
            for index, requirement in enumerate(onboarding_requirements()):
                check = DocumentCheck.query.filter_by(
                    student_id=student.id,
                    gate="Admission Handoff",
                    item_name=requirement,
                ).first()
                if not check:
                    check = DocumentCheck(
                        student_id=student.id,
                        gate="Admission Handoff",
                        item_name=requirement,
                    )
                    db.session.add(check)
                needs_follow_up = (
                    demo_config.get("scenario") == "follow-up"
                    and index == len(onboarding_requirements()) - 1
                )
                check.status = "Missing" if needs_follow_up else "Complete"
                check.evidence_reference = (
                    "Awaiting admissions source confirmation"
                    if needs_follow_up
                    else "Admissions handoff demo baseline"
                )
                check.updated_at = now_utc()
        if is_awol_demo and demo_config.get("scenario") == "return":
            student.standing = "AWOL"
            student.current_stage = "AWOL"
            student.enrollment_tag = "AWOL"
            student.risk_level = "Delayed"
            item = (
                AwolCase.query.filter_by(student_id=student.id)
                .order_by(AwolCase.id.desc())
                .first()
            )
            if not item:
                item = AwolCase(student_id=student.id)
                db.session.add(item)
            item.status = "AWOL Declared"
            item.awol_effective_date = date.today() - timedelta(days=120)
            item.last_enrolled_term = "AY 2025-2026 2nd Semester"
            item.policy_classification = "Awaiting return intent"
            item.dean_decision = "Not Submitted"
            item.detection_source = "Demo imported AWOL standing"
            item.automatically_flagged_at = item.automatically_flagged_at or now_utc()
            item.updated_at = now_utc()
        return

    # Research starts at Title Defense with only its prerequisites complete.
    # Existing progress is derived back from Miguel's current evidence, so a
    # normal login never wipes an in-progress walkthrough; only Reset does.
    if is_research_demo:
        sync_research_progress(student)
        return

    # Practicum and Graduation demos have completed every academic and research gate that
    # precedes their selected workflow. Keeping an explicit verified case means
    # Practicum eligibility is backed by source records as well as stage order.
    research_case = (
        ResearchCase.query.filter_by(student_id=student.id)
        .order_by(ResearchCase.opened_at.desc(), ResearchCase.id.desc())
        .first()
    )
    if not research_case:
        research_case = ResearchCase(
            student_id=student.id,
            case_type="Thesis",
            title=f"Completed research portfolio of {student.name}",
            current_gate="Completion Evidence",
            status="Verified Complete",
            adviser_name=student.adviser_name,
        )
        db.session.add(research_case)
    else:
        research_case.current_gate = "Completion Evidence"
        research_case.status = "Verified Complete"
        research_case.adviser_name = student.adviser_name

    if workflow != "graduation":
        return

    practicum = latest_practicum_record(student.id)
    if not practicum:
        practicum = PracticumRecord(student_id=student.id)
        db.session.add(practicum)
    practicum.moa_status = "Approved"
    practicum.moa_uploaded = True
    practicum.practicum_site = practicum.practicum_site or "USLS Partner Institution"
    practicum.supervisor_name = practicum.supervisor_name or "Demo Practicum Supervisor"
    practicum.required_hours = 200
    practicum.completed_hours = 200
    practicum.document_status = "Verified"
    practicum.completion_status = "Completed"
    practicum.status = "Dean Reviewed"
    practicum.report_sent_at = practicum.report_sent_at or now_utc()
    practicum.dean_reviewed_at = practicum.dean_reviewed_at or now_utc()
    practicum.updated_at = now_utc()


def ensure_workflow_demo_students() -> list[Student]:
    students = []
    for config in WORKFLOW_DEMO_STUDENTS.values():
        program = Program.query.filter(
            func.upper(Program.code) == config.get("program_code", "MAED").upper()
        ).first()
        if not program:
            continue
        student = Student.query.filter_by(student_number=config["student_number"]).first()
        if not student:
            student = Student(
                student_number=config["student_number"],
                first_name=config["first_name"],
                last_name=config["last_name"],
                email=config["email"],
                program_id=program.id,
                entry_year=2024,
                academic_year_entry="2024-2025",
                year_level="Completed Coursework",
            )
            db.session.add(student)
            db.session.flush()
        student.first_name = config["first_name"]
        student.last_name = config["last_name"]
        # Keep existing demo identities aligned with their configured program.
        # This also migrates practicum personas created by older seeds where
        # both Andrea and Paolo were still attached to MAED.
        student.program_id = program.id
        if not config.get("preserve_student_email"):
            student.email = config["email"]
        existing_account = UserAccount.query.filter_by(
            student_id=student.id,
            role="student",
        ).first()
        target_account = UserAccount.query.filter(
            func.lower(UserAccount.email) == config["email"].lower(),
        ).first()
        if existing_account and not target_account:
            existing_account.email = config["email"].lower()
        ensure_workflow_demo_student_baseline(student, config["workflow"])
        account = ensure_student_account(student, config["email"], SIM_STUDENT_PASSWORD)
        account.password_hash = generate_password_hash(SIM_STUDENT_PASSWORD)
        workflow_title = config.get("title") or config["workflow"].title()
        account.full_name = f"{student.name} · {workflow_title} Demo"
        students.append(student)
    return students


